body:
[Lemma 10 of arXiv:2511.07350, 'Decoupling of clusters in independent sets in a percolated hypercube'] There exists a universal constant $\gamma > 0$ such that for $p > \fr{1}{2}-\gamma$,
there is a constant $\alpha_p > \fr{(2-p)^2}{2}$ such that, for all $\eps = \eps_d > \poly(d)^{-1}$,
there is a function $f(d) > \poly(d)^{-1}$ (which may depend on $\eps_d$) such that  the following event
(determined by the percolation configuration) holds with probability tending to $1$.
\begin{equation}
    \left\{ \text{For all choices of } a,b,\ell,\sigma, \text{ we have }
    \pi\Box{\scrC(a,b;\ell;\sigma;S) > \eps \cdot 2^{a+b}} \leq \Exp{- f(d) \cdot \alpha_p^d}
    \right\}.
\end{equation}

[Proposition 25 of arXiv:2606.22964, 'Signature McKean--Vlasov stochastic differential equations'] Let $p\in(2,3)$. For every $t\in[0,T]$,
    \begin{equation*}
        \begin{aligned}
            &\mathbb{E}\left[\sup_D\sum_{i=0}^{n-1} \Big\lVert \augpr{X}^{\mu,1}_{t_i,t_{i+1}}-\augpr{Y}^{\nu,1}_{t_i,t_{i+1}} \Big\rVert^p_{\mathbb{R}^{d+1}}\right]\\
            &=\mathbb{E}\left[\sup_D\sum_{i=0}^{n-1} \Big\lVert\left(X^{\mu}_{t_{i+1}}-X^{\mu}_{t_i}\right)-\left(Y^{\nu}_{t_{i+1}}-Y^{\nu}_{t_i}\right)\Big\rVert^p_{\mathbb{R}^d}\right]\\
            &\leq \widetilde{C}\int_0^t\left(\mathbb{E}\left[\big\lVert\augpr{X}^{\mu}-\augpr{Y}^{\nu}\big\rVert_{\textup{$p$-var};[0,s]}^p\right] + \int_{\widehat{G\Omega}_p(\mathbb{R}^{d+1})\times \widehat{G\Omega}_p(\mathbb{R}^{d+1})}C_s\lVert x-y \rVert_{\textup{$p$-var};[0,s]}^p\pi(dx,dy)\right)ds,
        \end{aligned}
    \end{equation*}
    where $D=D_{[0,t]}$ is a partition of $[0,t]$, $\widetilde{C}=\widetilde{C}(p,T,L)$, $C_s=C_s(d,p,N,T,\alpha_\infty,\Gamma_s)$, $\alpha_\infty:=\max_{0\leq |I|\leq N}|\alpha_I|$ where $\alpha_I$ are the coefficients in \eqref{eq:linear_comb_in_sig_MKV_SDE}, $\Gamma_s:=\max\{\lVert x\rVert_{\textup{$p$-var};[0,s]},\lVert y\rVert_{\textup{$p$-var};[0,s]}\}$, and $\pi\in\Pi(\mu,\nu)$ is an arbitrary coupling of $\mu$ and $\nu$.

[Proposition 2 of arXiv:2607.11608, '2607.11608'] Let $p > 2$ if $d=1,2 $, or  $2 < p < \frac{2 d}{d - 2 }$ if $d \ge 3$. Then, 
