[Definition of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Let $p\in[-d,\infty)$. Suppose that $\Phi$ is a locally square-integrable invariant random complex measure, i.e., $\BE[|\Phi(B_1)|^2]<\infty$. If
\begin{equation}
    \frac{\hat\beta_\Phi(B_\varepsilon)}{\varepsilon^d} = O(\varepsilon^p)
\end{equation}
as $\varepsilon\to 0$, then $\Phi$ is called $p$\textit{-uniform}.
Similarly, if
\begin{equation}
    \frac{\hat\beta_\Phi(B_\varepsilon)}{\varepsilon^d} = o(\varepsilon^p)
\end{equation}
as $\varepsilon\to 0$, then $\Phi$ is called \textit{beyond} $p$\textit{-uniform}.
Further, if $\hat\beta_\Phi(B_\varepsilon)=0$ for some $\varepsilon>0$, then $\Phi$ is called $\infty$\textit{-uniform with radius} $\varepsilon$. Note that $B_\varepsilon:=\{x\in\R^d:\|x\|<\varepsilon\}$ is the open ball of radius $\varepsilon$ around $0$.

For $p<\infty$, if $\Phi$ is $p$-uniform but not beyond $p$-uniform, then it is called \textit{solely} $p$\textit{-uniform}. Moreover, if $\Phi$ is $\infty$-uniform with radius $\varepsilon$ but not $\infty$-uniform with radius $\vartheta$ for any $\vartheta>\varepsilon$, then it is called $\infty$\textit{-uniform} \textit{with maximal radius} $\varepsilon$. 

Finally, a tensor-valued random complex measure is called (beyond) $p$-uniform (with radius $\varepsilon$) if all of its components are.

[Theorem thm:heat_content of arXiv:2609.04045, 'Heat content and spectrum for subordinated sub-Laplacians'] Let $\Omega$ be a bounded set in $\mathbb{G}$ whose $C^\infty$ boundary $\partial \Omega$ does contain no characteristic points. Then,  the following holds.
     \begin{enumerate}[leftmargin=*]
     \item For $1<\alpha< 2$,
     \begin{align*}
         \lim_{t\to 0} \frac{\operatorname{Vol}(\Omega) - H^{(\alpha)}_\Omega(t)}{t^{\frac{1}{\alpha}}}=\frac{1}{\pi}\Gamma\left(1-\frac{1}{\alpha}\right)\operatorname{Per}_\mathcal{H}(\Omega).
     \end{align*}
     \item When $\alpha=1$,
     \begin{align*}
         \lim_{t\to 0} \frac{\operatorname{Vol}(\Omega) - H^{(\alpha)}_\Omega(t)}{t\log(1/t)}=\frac{1}{\pi}\operatorname{Per}_\mathcal{H}(\Omega).
     \end{align*}
     \end{enumerate}
    For $0<\alpha<1$ and for any bounded open set $\Omega$ satisfying $\operatorname{Per}^{(\alpha)}_{\mathcal H}(\Omega)<\infty$ we have
    \begin{align*}
        \lim_{t\to 0} \frac{\operatorname{Vol}(\Omega) - H^{(\alpha)}_\Omega(t)}{t}=\operatorname{Per}^{(\alpha)}_{\mathcal H}(\Omega).
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 12 of arXiv:2609.01166, 'Nonparametric inference for density-dependent McKean--Vlasov diffusions'] Under the same assumptions as in Lemma~\ref{lem:primitive-kl}, there exists a constant \(C_\mathrm{risk}\) depending on \(I,J,\beta,H,\kappa,K,\xi_\star,d\) and \(V\), but not on \(n\), such that
\begin{equation}
  \inf_{\wh\Xi_n}
  \sup_{\xi\in\mathfrak X_\beta(J)}
  \E_\xi\norm{\wh\Xi_n-\xi}_{L^2(I)}^2
  \geq C_\mathrm{risk} n^{-2\beta/(2\beta+3)}.
\end{equation}
Moreover, for constants 
\(C_\mathrm{sep}>0\) and \(p\in(0,1)\)
depending on the same variables as \(C_\mathrm{risk}\),
\begin{equation}
  \inf_{\wh\Xi_n}
  \sup_{\xi\in\mathfrak X_\beta(J)}
  \Pi_\xi^{\otimes n}\!\biggl(
    \norm{\wh\Xi_n-\xi}_{L^2(I)}
    \geq C_\mathrm{sep} n^{-\beta/(2\beta+3)}
  \biggr)
  \geq p.
\end{equation}
The infimum is over all measurable estimators based on \(X_1,\ldots,X_n\sim \Pi_\xi\). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 7 (Sobolev estimates) of arXiv:2609.03558, 'Local well-posedness of the higher-order nonlinear Schr\"{o}dinger equation on the half-li'] Let $b\in \{0,1\}$. Then, the unique solution of \eqref{cauchy2} satisfies the space estimate
	\begin{equation}
		\sup_{t\in[0,T]}\left\| z(\cdot,t) \right\|_{H_x^{s}(\mathbb{R})}\leq \left\|F\right\|_{L_t^1((0,T); H_x^{s}(\mathbb{R}))}, \quad s\in \mathbb{R}.
	\end{equation}

	Moreover, if  $-1+b\leq s \leq 2+b$ with $s\neq \frac 12+b$, then
	the following time estimate holds
\begin{equation}
\sup_{x\in\mathbb{R}}\left\| \partial_x^bz(x,\cdot) \right\|_{H_t^{\frac{s+1-b}{3}}(0,T)}\leq c \, 
\|F\|_{L_t^2((0,T); H_x^{s}(\mathbb{R}))}
	\end{equation}

	for some constant
    $c = c(s, T, \alpha, \beta, \delta) \geq 0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 11 of arXiv:2609.02050, '2609.02050'] Let $D$ be a diagram that avoids the configurations in Figure~\ref{fig-upper} and let $C^{(1)},\ldots,C^{(m)}$ be all the diagrams $C=(C_1,C_2,\ldots,C_n)$ with $|C_j|=|D_j|$ for $j\in[n]$ and ${\bf x}^{C}={\bf x}^a$, where ${\bf x}^a$ is a monomial in $\chi_{D}({\bf x})$. For simplicity, write ${\bf y}^{(a)}={y}^{F_{led}^{C^{(a)}}}$  Then we have the following results:
		\begin{enumerate}
			\item[(a)] For $1\leq a \leq m$, the leading monomial ${\bf y}^{(a)}$ appears in the polynomial $\det\left(Y_D^{C^{(a)}}\right)$.

			\item[(b)] The leading monomials $\{{\bf y}^{(a)}\}$ are distinct.
		\end{enumerate}

[Lemma 17 of arXiv:2506.10817, 'On the Weak Error for Local Stochastic Volatility Models'] Assume the setting of Theorem \ref{thm_condExp_err} and recall $\hE^\eps_\delta$ from Definition \ref{Def_hEepsdelta}. 
    Then for any $p\ge 1$ it holds that 

    \begin{align*}
        \Bigl\| \hE_\delta^\eps\bigl[\xi_{jh}^2| \hX_{jh}^{h,\eps,\delta} \bigr]-\hE^\eps\bigl[\xi_{jh}^2| \hX_{jh}^{h,\eps,\delta} \bigr] \Bigr\|_{L^p} \lesssim 
        \Bigl(\delta \sqrt{-\log(\delta)}\Bigr)^{\frac1p}.
    \end{align*}

