[Lemma 19 of arXiv:2604.19924, 'Fluctuation theory for spectrally negative Lévy processes killed by additive functionals'] For $q\geq0$, and $x\in(c,b)$,
					\begin{align}
						\lim_{n\to\infty}\E_x\bigg[e^{-q\tau_b^+-\int_{\R}L^y_{\tau_b^+}\nu_{n}(dy)};\tau_b^+<\tau_c^-\bigg]=\E_x\bigg[e^{-q\tau_b^+-\int_{\R}L^y_{\tau_b^+}{\nu_A}(dy)};\tau_b^+<\tau_c^-\bigg].
					\end{align}
					\begin{align}
						\lim_{n\to\infty}\E_x\bigg[e^{-q\tau_c^--\int_{\R}L^y_{\tau_c^-}\nu_{n}(dy)};\tau_c^-<\tau_b^+\bigg]=\E_x\bigg[e^{-q\tau_c^--\int_{\R}L^y_{\tau_c^-}{\nu_A}(dy)};\tau_c^-<\tau_b^+\bigg].
					\end{align}
					Additionally, for any bounded measurable function $f:\R\to\R$, we have
					\begin{align}
						\lim_{n\to\infty}\E_x\bigg[e^{-\int_{\R}L^y_{t}\nu_{n}(dy)}f(X_t)1_{\{
							t<\tau_c^-\wedge\tau_b^+\}}\bigg]=\E_x\bigg[e^{-\int_{\R}L^y_{t}{\nu_A}(dy)}f(X_t)1_{\{
							t<\tau_c^-\wedge\tau_b^+\}}\bigg].
					\end{align}

