[Proposition prop:small_lambda_asym of arXiv:2509.15446, 'On the pair correlation function of the $\Sineb$ process'] For $\lambda$ near 0, we have 
       \begin{align}
        \rho_{\beta,n}^{(1)}(\lambda) =\frac{1}{2\pi} 
      \binom{2n}{n}^{-1}\frac{\left(\tfrac{\beta}{2}\right)^{2n}}{\left(1+\frac{\beta}{2}\right)^{\uparrow 2n}}   \lambda^{2n}  

        + \mathcal{O}(\lambda^{2n+2}).
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 18 of arXiv:2608.17493, 'Integrals of some compound processes'] Let $N$ be a renewal process with waiting times $X\sim F$ and $\{A_n\}_{n\ge1}$ be a sequence of real random variables independent of $N$ (and its waiting times),
	\begin{itemize}
		\item[($i$)] with $\gamma\in\mathbb{R}$,
		\begin{equation}
			\mathbb{E} \exp\Biggl( i\gamma \sum_{k=1}^{N(t)} X_k A_k \Biggr) = \sum_{n\ge0}\mathbb{E} \Biggl[\conv_{k=1}^n \Big( e^{i\gamma A_k\sbullet} F(\sbullet) \Big)\ast 1 (t)- \conv_{k=1}^{n} \Big( e^{i\gamma A_k\sbullet}F(\sbullet) \Big)\ast F \ast 1 (t) \Biggr],
		\end{equation}
		where $hF\ast g (t)= \int_0^t g(t-x)h(x)F(\dif x)$ for suitable functions $h,g$ and distribution $F$.
		\item[($ii$)] If $X$ is absolutely continuous with density $f$ and $\mu>0$,
		\begin{equation}
			\mathcal{L} \left\{ \mathbb{E} \exp\Biggl( i\gamma \sum_{k=1}^{N(t)} X_k A_k \Biggr) \right\} (\mu) = \frac{1-\mathcal{L}f(\mu)}{\mu}\sum_{n\ge0}\mathbb{E} \prod_{k=1}^n \mathcal{L}f(\mu+i\gamma A_k).
		\end{equation}
	\end{itemize}

[Definition 14 (Four-moment replacement path) of arXiv:2608.07820, 'Linear Spectral Statistics for Entrywise-Transformed Spiked Wigner Matrices under Shifted '] For $0\le r\le M_N$, define the centered hybrid $H_N^{(r)}$ by
\begin{equation}
 H_N^{(r)}(e_q)
 :=N^{-1/2}
 \begin{cases}
 Y_{e_q},&q\le r,\\
 \widehat Y_{e_q},&q>r,
 \end{cases}
\end{equation}
and set
\begin{equation}
 M_N^{(r)}:=A_N+H_N^{(r)}.
\end{equation}
For the replacement of edge $e_r=(a,b)$, let
$\mathring H_N^{(r,e_r)}$ be the centered hybrid with the $(a,b)$ and
$(b,a)$ entries set to zero.  Put
\begin{equation}
 M_N^{(r,e_r)}(u)
 :=A_N+\mathring H_N^{(r,e_r)}+N^{-1/2}uV_{e_r},
 \qquad
 V_{e_r}:=E_{ab}+E_{ba}.
\end{equation}
The open-edge matrix is independent of both candidate variables
$Y_{e_r}$ and $\widehat Y_{e_r}$.

[Theorem 20 of arXiv:2606.07096, 'Non-Selection of Lagrangian Trajectories in the Zero-Noise Limit for a Class of Stochastic'] For any $\alpha \in (0,1)$ and $\eps \in (0,1)$ there exist a divergence-free $u \in C^\alpha (\T^3)$, a set $\bar A \subset \T^3$ with $|\bar A| \geq 1 - \eps $, a subsequence $\{ \kappa_q \}_{q}$ and a constant $c_\eps >0$ such that the following holds true: for  every $\bar x\in\bar A$, it holds that
    \begin{equation*}
        \bar\P\left( \bar\omega\in\bar\Omega: \liminf_{q\to\infty} \dist (\bar X_1^{\kappa_{2q}}(\bar x,\bar \omega),\bar X_1^{\kappa_{2q+1}}(\bar x,\bar \omega))\geq c_\eps> 0\right) =1.
    \end{equation*}
    Furthermore, for any $x \in \bar A$ there exist a subsequence $\{\kappa_q\}_q$, points $y, y' \in \T^3$ such that for a.e. $\omega$ it holds that
    $$ \bar X_1^{\kappa_{2q}} (\bar x, \bar \omega) \rightarrow y \neq y' \leftarrow \bar X_1^{\kappa_{2q+1}} (\bar x, \bar\omega).$$

