[Definition def:error_profiles of arXiv:2608.24963, 'Why and When Neural Networks Improve Local Approximation in Optimization'] Given $x\in\mathbb{R}^n$ and radius $\Delta>0$, define
\begin{equation}
e_f(x,\Delta):=\sup_{u\in\Ball{x}{\Delta}}\left\lvert f(u)-m(u) \right\rvert,\qquad
e_g(x,\Delta):=\sup_{u\in\Ball{x}{\Delta}}\left\lVert \nabla f(u)-\nabla m(u) \right\rVert_2.
\end{equation}

[Definition of arXiv:2411.18775, 'Limit Theorems for the Dynamical Foundation of the Fractional Brownian Motion and Related '] Let $(\Omega,\mathcal{F},\mathbb{P})$ be a probability space.  Let $\mathcal{X}$  be a separable metrizable topological space endowed with its Borel $\sigma$-field $\mathcal{B}(\mathcal{X})$. Let $\mathcal{G}\subset\mathcal{F}$ be a sub-$\sigma$-field. A sequence $(\xi_N)_{N\in\mathbb{N}}$ of $(\mathcal{X},\mathcal{B}(\mathcal{X}))$-valued random elements is said to \emph{converge $\mathcal{G}$-mixing} to a (random element with) probability distribution $\nu$ on $\mathcal{X}$, if the conditional distributions $\mathcal{P}_{\xi_N|\mathcal{G}}$ converge weakly to $\nu$ as $N\to\infty$, i.e., if for every $f\in L^1(\Omega,\mathcal{F},\mathbb{P})$ and every bounded continuous function $h$ on $\mathcal{X}$
		\begin{align*}
			\lim_{N\to\infty}\mathbb{E}\left[ f\mathbb{E}\left[h(\xi_N)|\mathcal{G}  \right] \right] =\mathbb{E}[f]\int_\mathcal{X} h d\nu.
		\end{align*}

[Proposition 2 (Weak expansion) of arXiv:2604.04100, '\LARGE Learning Equilibrium Fluctuation Expansions from Overdamped Langevin Dynamics'] Let  $\varepsilon\in (0,1)$, and let $X_\varepsilon$,  $(\bar{X}_m)_{0\leq m\leq n}$ be as in Proposition \ref{thm-dyna-exp-intro}.
    Suppose $F \in C^{n+1}(\mathbb{R}^d)$ satisfies a polynomial growth condition, i.e., there exists $q > 0$ such that \begin{equation}
    \max_{0\le i \le n+1} \|D^i F(x)\| \leq C(1+|x|^q), \quad\text{for all } x \in \mathbb{R}^d.
    \end{equation}
We define $a_0(t,F):=\mathbb{E}\big[F(\bar X_0(t))\big]$, and for each $1 \leq m \leq n$,
	\begin{equation}
		a_m(t,F):=\mathbb{E}\Bigg[\sum_{i=1}^{m}\frac{1}{i!}	\sum_{(j_1,\dots,j_i)\in\mathcal{D}_i^{m}}
		D^iF\big(\bar X_0(t)\big)\big(\bar X_{j_1}(t),\dots,\bar X_{j_i}(t)\big)
		\Bigg],
	\end{equation}
    where $\mathcal{D}_i^{m}$ is defined in \eqref{D-ni}.
Then for each $t>0$, there exists a constant $C(t,n,F)>0$, independent of $\varepsilon$, such that for all $m=0,1,\cdots,n$,
	\begin{equation*}
		\left|\frac{\mathbb{E}\big[F(X_\varepsilon(t))\big]
		-\sum_{k=0}^m\varepsilon^{k/2}a_k(t,F)}{\varepsilon^{m/2}}\right|\leq C(t, n, F) \varepsilon^{1/2}.
	\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor 9 of arXiv:2605.15501, 'Well-posedness of the obstacle problem for generalized Dean--Kawasaki equation\thanks{ The'] Let Assumption \ref{assu:assum for F} and Assumption \ref{assu:assu for unique} hold for two initial functions $u_{1,\mathrm{init}}$ and $u_{2,\mathrm{init}}$.
Let $(u_{1},\nu_{1})$ and $(u_{2},\nu_{2})$ be stochastic kinetic solutions of the obstacle problem for \eqref{eq:main} in the
sense of Definition \ref{def:def of stochastic kinetic solution} with initial data $u_{1,\mathrm{init}}$ and $u_{2,\mathrm{init}}$, respectively.
Let $\chi_{1}$ and $\chi_{2}$ be the kinetic functions of $u_{1}$ and $u_{2}$.

Then, we have, almost surely, for almost every $t\in(0,T)$,
\begin{align}
\|u_1(t)-u_{2}(t)\|_{L^1(\mathbb{T}^d)}
\leq\|u_{1,\mathrm{init}}-u_{2,\mathrm{init}}\|_{L^1(\mathbb{T}^d)}.
\end{align}

[Lemma eq:sph-grad of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[lemma]{lem:spherical-derivatives}
For \(v,w\in T_\sigma\mathbb S_N\),
\begin{align}
 \nabla_SF(\sigma)&=P_\sigma\nabla F(\sigma),\\
 \operatorname{Hess}_SF(\sigma)[v,w]
 &=D^2F(\sigma)[v,w]
 -\frac{\ip{\nabla F(\sigma)}{\sigma}}N\ip vw.
\end{align}
If \(F\) is homogeneous of degree \(p\), then
\begin{equation}
 \operatorname{Hess}_SF(\sigma)[v,w]
 =D^2F(\sigma)[v,w]-\frac{pF(\sigma)}N\ip vw.
\end{equation}

[Definition 188 of arXiv:2601.16377, '2601.16377'] For each left trapezoid $\mathcal{T}_q$, we define the map $z^{(q)} : \pounds_q \rightarrow \Sigma^{(q)}$ as the unique solution in the \emph{upper} half-plane of \eqref{eq_critical_equation_rescaled}, that is
\begin{equation}
 \frac{-x}{y - z^{(q)}} = e^{-G^{(q)}(z^{(q)})} - 1,
\end{equation}
where $G^{(q)}$ is the function \eqref{eq_x296} for the $q$-th trapezoid. We denote this solution $z^{(q)}$ and treat it as a point in $\Sigma^{(q)}$. For each right trapezoid $\mathcal{T}_q$, we map its liquid region $\pounds_q$ into a unique solution of \eqref{eq_critical_equation_rescaled2} in the \emph{lower} half-plane. We again denote this solution $z^{(q)}$ and treat it as a point in $\Sigma^{(q)}$.

[Lemma 26 of arXiv:2607.23791, 'Precise cover times for branching random walks on Hamming graphs: (iterated) logarithmic c'] Let $N_y(t)$ be the number of particles at $y$ at time $t$ and denote by 
$\alpha=d_{\rm H}(x,y)/d$.  With $q=e^{-2t/d}$,
\begin{equation}
 \mu:=\E_x[N_y(t)]
 =e^{\lambda t}2^{-d}(1+q)^{(1-\alpha)d}(1-q)^{\alpha d}.
\end{equation}
For $0\le h\le-\log q$, we have
\begin{equation}
 \frac{\E_x[N_y(t)^2]}{\mu^2}
 =\frac1\mu+2\lambda\int_0^t
 \exp\!\left(dG_\alpha\!\left(e^{-2(t-s)/d},q\right)\right)\dd s,
\end{equation}
where
\begin{align}
    G_\alpha(e^{-h},q)={}&-\frac{\lambda h}{2}
 +(1-\alpha)\log\!\left(
 1+\frac{q^2}{(1+q)^2}(e^{2h}-1)\right)+\alpha\log\!\left(
 1+\frac{q^2}{(1-q)^2}(e^{2h}-1)\right).
\end{align}

