[Lemma lem:cubic-expansion of arXiv:2608.26745, 'Moderate Deviations for the Largest Eigenvalue of a Randomly Deformed Gaussian Unitary Ens'] There are constants $c_0,c,C>0$ such that, on $\mathcal G_N$ and uniformly for
$|r|\le N^{c_0}$,
\begin{equation}
 \bigg|\Phi_N(r;\bm\xi)-\frac{r^3}{3}\bigg|
 \le CN^{-c}(1+|r|^4).
\end{equation}
The first two derivatives satisfy
\begin{align}
 \left|\Phi_N'(r;\bm\xi)-r^2\right|
 &\le CN^{-c}(1+|r|^3),                                 \\
 \left|\Phi_N''(r;\bm\xi)-2r\right|
 &\le CN^{-c}(1+|r|^2).                                 
\end{align}

[Theorem prop:mix_prod of arXiv:2604.20215, '\bf Edge Universality for Inhomogeneous Random Matrices II: Markov Chain Comparison and Cr'] For   polynomials $P_i(X)$ defined via Chebyshev polynomials of  second kind
\begin{equation}
P_i(X) :=
\begin{cases}
\displaystyle \Bigl(\frac{1}{n_i+1}\, U_{n_i}\bigl(\tfrac{X}{2}\bigr)\Bigr)^{\!m}, & i = 1,\ldots, q, \\[8pt]
\displaystyle \Bigl(\frac{1}{n_i+1}\, U_{n_i}\bigl(\tfrac{X}{2}\bigr)\Bigr)^{\!m-1} \frac{1}{n_i+2}\, U_{n_i+1}\bigl(\tfrac{X}{2}\bigr), & i = q+1,\ldots, s,
\end{cases}
\end{equation} we define $\tau(I)$ recursively  for any subset $I \subset [s]$ by
\begin{equation}
\tau(I) := \mathbb{E}\!\Big[\,\prod_{i \in I} \operatorname{Tr} P_i(X)\Big] \;-\; \sum_{\Pi \in \mathscr{P}(I)} \prod_{\pi \in \Pi} \tau(\pi),
\end{equation}
where the sum runs over all \emph{proper} partitions of $I$.
\begin{enumerate}
    \item[(i)] {\bf Even case:}  If   $\displaystyle S(I) := \sum_{i \in I \cap [q]} m n_i \;+\!\! \sum_{i \in I \setminus [q]} (m n_i + 1)$ is even, and $t_i \in (0,\infty)$ for $i=1,\dots,s$ such that
    \begin{itemize}
    \item Supercritical regime: $n_i \sim t_i N^{1/3}$;
    \item Subcritical/Critical regimes: $n_i \sim t_i W^{\alpha/(3\alpha-1)}$.
    \end{itemize}
    Then
    \begin{equation}
    \tau(I) = \bigl(1+o(1)\bigr) \sum_{\Gamma \in \mathcal{T}_{s}}
    \int_{\xi_1}\! \cdots\! \int_{\xi_s}
    \Bigl[\,\prod_{i \in I} \mathcal{Q}_m(\xi_i)\Bigr]\,
    \mathcal{L}_\Gamma\bigl(\{\xi_i t_i\}_{i\in I}; (W,N)\bigr)
    \,d\xi_1 \cdots d\xi_{s},
    \end{equation}
     where
     \begin{equation}
        \mathcal{Q}_m(\xi) := \xi \, \mathcal{P}_m(\xi), \quad \mathcal{P}_m(\xi) = \frac{1}{2^{m-1}(m-2)!} \sum_{j=0}^{m} (-1)^j \binom{m}{j} \left( m - 2j - \xi \right)_+^{m-2}.
    \end{equation}

    \item[(ii)] {\bf Odd case:} If $S(I)$ is odd, then
    $
    \tau(I) = 0.$
\end{enumerate}

