\begin{equation}
    \bigl( U_{n_i}(x) \bigr)^{m} = \sum_{k \ge 0} c_m(n_i; k) \, U_k(x).
\end{equation}

Hence, we obtain
\begin{equation}
    \mathbb{E}\!\Big[\prod_{i=1}^s\operatorname{Tr} P_i(X)\Big]
= \sum_{k_1,\dots,k_s} \,\prod_{i=1}^s \frac{c_m(n_i; k_i)}{(n_i+1)^m}
\; \mathbb{E}\!\Big[\prod_{i=1}^s\frac{1}{k_i+1}U_{k_i}(X)\Big].
