[Thm 70 of arXiv:2507.08909, 'Annealed almost periodic entropy'] Fix $\tau$ and $\phi$ as above.
\begin{enumerate}
\item[a.] For any $h > \log \Delta \phi_{\rm{ac}}$, there are a positive integer $d_0$, a neighbourhood $V$ of $\tau$, and a neighbourhood $O$ of $\phi$ such that the following holds:
\begin{quote}
If $\pi$ is a $d$-dimensional representation of $\A$ satisfying
\[d\ge d_0 \quad \hbox{and} \quad \tr_d\circ \pi \in V,\]
then
\[\frac{\vol_{2kd}\X(\pi,O)}{v(d)^k} \le e^{hd}.\]
\end{quote}
\item[b.] If $\log \Delta \phi_{\rm{ac}} > h > \infty$, and if $O$ is any neighbourhood of $\phi$, then there are a positive integer $d_0$, a neighbourhood $V$ of $\tau$, and another neighbourhood $O'$ of $\phi$ such that the following holds:
\begin{quote}
If $\pi$ is a $d$-dimensional representation of $\A$ satisfying
\[d\ge d_0, \quad  \tr_d\circ \pi \in V, \quad \hbox{and} \quad \X(\pi,O')\ne \emptyset,\]
then
\[\frac{\vol_{2kd}\X(\pi,O)}{v(d)^k} \ge e^{hd}.\]
\end{quote}
\end{enumerate}

[Lemma drift_convergence of arXiv:2609.03858, 'High-Dimensional Learning Dynamics of \\ Attention-Indexed Models'] Fix $C_*>0$ and $\rho>C_*^2$. Let
\begin{equation}
\mathcal A_d(C_*):=\left\{
(S_1,\ldots,S_K):S_k=W_kW_k^T,\ \max_{1\le k\le K}\|W_k\|_{\mathrm{op}}\le C_*\right\}.
\end{equation}
For $\mathbf S\in\mathcal A_d(C_*)$, let $\mu(\mathbf S)$ denote its associated moment sequence. Then
\begin{equation}
\sup_{\mathbf S\in\mathcal A_d(C_*)}
\left\|V_d(\mu(\mathbf S))-V(\mu(\mathbf S))
\right\|_\rho\longrightarrow0
\qquad
\text{as }d\to\infty.
\end{equation}
Consequently, on the spectral-bound event $\mathcal{E}_d(T)$,
\begin{equation}
\sup_{t\in[0,T]}
\left\|V_d(\tilde\mu^{(d)}(t))-V(\tilde\mu^{(d)}(t))\right\|_\rho
\xrightarrow{\mathbb P}0.
\end{equation}

