[Lemma S42L of arXiv:2410.23899, 'Tightness for interlacing geometric random walk bridges'] Fix $p, \epsilon, \eta, M^{\mathsf{bot}}, M^{\mathsf{side}}, A^{\mathsf{sep}}, A^{\mathsf{gap}}\in (0, \infty)$, $\Delta^{\mathsf{gap}}  \in (0,1/2)$, $k \in \mathbb{N}$, $\sigma = \sqrt{p(1+p)}$. There exist $N_6 \in \mathbb{N}$ and $\delta > 0 $, depending on $p, \epsilon, \eta, M^{\mathsf{bot}}, M^{\mathsf{side}}, A^{\mathsf{sep}}, A^{\mathsf{gap}}, \Delta^{\mathsf{gap}}, k$, such that the following holds for all $n \geq N_6$. If we assume:
\begin{itemize}
\item $\vec{x}, \vec{y}\in \mathfrak{W}_k$ as in ((DefSig of the paper)), and $|x_i| \leq M^{\mathsf{side}} \cdot n^{1/2}$, $|y_i - pn| \leq M^{\mathsf{side}} \cdot n^{1/2}$ for $i \in \llbracket 1, k \rrbracket$;
\item $x_i - x_{i+1} \geq A^{\mathsf{sep}} \cdot n^{1/2}$ and $y_i - y_{i+1} \geq A^{\mathsf{sep}} \cdot n^{1/2}$ for $i \in \llbracket 1, k -1 \rrbracket$;
\item $g: \llbracket 0, n \rrbracket \rightarrow [-\infty, \infty)$ is such that $g(s) - ps\leq  M^{\mathsf{bot}} \cdot n^{1/2} $ for all $s \in \llbracket 0, n \rrbracket$;
\item $x_k \geq g(s) - ps + A^{\mathsf{gap}} \cdot n^{1/2} $ for all $s \in \llbracket 0, n\rrbracket$ with $s \leq \Delta^{\mathsf{gap}} \cdot n$;
\item $y_k -pn \geq g(s) - ps + A^{\mathsf{gap}} \cdot n^{1/2} $ for all $s \in \llbracket 0, n\rrbracket$ with $s \geq n - \Delta^{\mathsf{gap}} \cdot n$;
\item the set $\Omega_{\mathsf{Inter}}(0,n,\vec{x},\vec{y}, \infty, g)$ is non-empty;
\item for $Q_i \in \Omega(0,n, x,y)$, we set $\mathcal{Q}_i(t)= \sigma^{-1}n^{-1/2}(Q_i(tn) - ptn)$ for $t \in [0,1]$;
\end{itemize}
then the following inequality holds for each $i \in \llbracket 1, k \rrbracket$
\begin{equation}
\mathbb{P}_{\mathsf{Inter}, \operatorname{Geom}}^{0, n, \vec{x}, \vec{y}, \infty, g}\left( w(\mathcal{Q}_i, \delta) > \epsilon \right) < \eta.
\end{equation}
We recall that $w(f,\delta)$ is the modulus of continuity from ((S33E1 of the paper)). (Proof in the paper; no proof environment follows the statement in the TeX.)

