body:
[Defi def:cLSI of arXiv:2602.17579, 'Non-equilibrium functional inequalities for finite Markov chains'] The \emph{log-Sobolev inequality (LSI)} is satisfied if there exists a constant $\alpha > 0$ such that 
\begin{equation}
\forall \varphi\in \mathcal D_\pi(\ensuremath{\mathbb{Z}}): \ \ \mathscr{H}_\pi(\varphi)\leq  \frac{1}{\alpha} \mathscr{R}_\pi(\varphi,M).
\end{equation}
The supremum over all possible choices of $\alpha$ is called the \emph{log-Sobolev constant}. We denote it by
\begin{equation}
    \alpha_{\LSI}(M) \coloneqq \inf_{\substack{\varphi\in \mathcal D_\pi(\ensuremath{\mathbb{Z}})\\\varphi\neq \1}}\frac{\mathscr{R}_\pi(\varphi,M)}{\mathscr{H}_\pi(\varphi)}.
\end{equation}

[Prop PropISDEGL of arXiv:2605.06429, '\large \bf $\mathsf{GL}_N(\mathbb{C})$ BROWNIAN MOTION AND STOCHASTIC PDE ON ENTIRE FUNCTI'] For any $\gamma\ge \sum_{i=1}^\infty x_i$, whenever $(x_i)_{i\in \mathbb{N}}\in \mathbf{W}_{\infty;+}^\circ$, the projection of $\mathbf{X}_{GL}^\bullet$ on the $(\mathsf{x}_i(\bullet))_{i\in \mathbb{N}}$ solves the infinite system of SDE
\begin{equation*}
\mathsf{x}_i(t)= x_i+\int_0^t\mathsf{x}_i(s)\mathrm{d}\mathsf{w}_i(s) + \frac{\theta}{2}\int_0^t\mathsf{x}_i(s)\mathrm{d}s
 +\int_0^t\sum_{j=1,j\neq i}^{\infty}\frac{\mathsf{x}_i(s)\mathsf{x}_j(s)}{\mathsf{x}_i(s)-\mathsf{x}_j(s)}\mathrm{d}s, \  \forall t\ge 0 , \   i \in \mathbb{N},
 \end{equation*}
with independent standard Brownian motions $(\mathsf{w}_i)_{i\in \mathbb{N}}$.

