[Lemma 25 of arXiv:2609.00183, '2609.00183'] Let $u$ be a harmonic map to an $N$-dimensional conical DM-complex $Y_C$ with splitting $u=(V,v):B_{\sigma_j}(0) \to (\mathbb{R}^j \times Y_C^{N-j},d_G)$ satisfying $\Ord_{\phi,v}(0,R_0)\leq \Lambda$ and $\sup_{B_{\sigma_j}(0)}|\nabla u| \leq M$, then there exists $\eta_1>0$ and $\calA\geq 1$, depending only on $\Lambda$, $n$, $M$, and the constant in \cite[(29)--(33)]{dm}, such that for $\sigma\in (0,\eta_1]$ and $\eta\in (0,\eta_1]$, if for $x\in B_{R_0/64}(0)$ there exists a homogeneous Lipschitz map $h:B_{\sigma}(x)\to Y_C$ such that
     \begin{equation*}
         \sup_{B_{\sigma}(x)}d(v,h)\leq \eta\paren{\sigma^{1-n}I_{\phi,v}(x,\sigma)}^{1/2},
     \end{equation*}
     then $\alpha\leq \calA$, where $\alpha$ is the degree of $h$.

[Theorem 8 of arXiv:2606.15178, 'The distribution of the de Moivre experiment'] Let $X\sim\mathcal{B}^{(s)}(n,p)$ and let $x_i=\sum_{l=1}^{s}l^ip^lq^{s-l}=E(X_1^i)$. Then, for every $r\geq1$,
	\begin{equation}
		\kappa_r(X)=n\sum_{k=1}^{r}(-1)^{k-1}(k-1)!\,B_{r,k}\big(x_1,x_2,\ldots,x_{r-k+1}\big), \quad \text{ for } p\neq q, 
	\end{equation}
	and
	\begin{equation}
		\kappa_r(X)=n\sum_{k=1}^{r}(-1)^{k-1}(k-1)!\,p^{ks}\,B_{r,k}\Big(\sum_{l=1}^{s}l,\sum_{l=1}^{s}l^2,\ldots,\sum_{l=1}^{s}l^{r-k+1}\Big), \quad \text{ for } p=q.
	\end{equation}

