\begin{equation}

\forall h_1,h_2 \in [H] \qquad \mathcal{F}_{h_1,h_2}(z_1,z_2) =
\Op_{h_1}\left[\frac{\sqrt{(* - \alpha_{h_2})(* - \beta_{h_2})}}{2(*- z_2)^2}\boldsymbol{e}^{(h_2)}\,;\,\boldsymbol{\kappa} = \boldsymbol{0}\right](z_1),
