body:
[Proposition 8 of arXiv:2604.19308, '\textbf{On McKean--Vlasov SDEs with polynomial drifts for SIS epidemic models}'] In the setting of Example~\ref{ex:a representative SIS epidemic model} let~\eqref{a.1} and~\eqref{a.2} hold and suppose that if $\eta_{0} = \frac{1}{2}$, then $g_{1,1} = 0$ or $g_{1,2} = 0$. Further, let $u_{1}\in\R$ be such that
\begin{equation}
\limsup_{t\uparrow\infty} (\beta + \beta_{1}^{+})(t) - \frac{1}{2}(g_{1,2}^{2} + g_{2,1}^{2})(t)\mathbbm{1}_{\{\frac{1}{2}\}}(\eta_{0}) \leq u_{1}
\end{equation}
and $c_{1,2,\infty},c_{2,1,\infty},c_{2,2,\infty},u_{2},u_{3}\in\R$ satisfy the following four conditions:
\begin{enumerate}[(i)]
\item $\lim_{t\uparrow\infty} c_{i,j}(t) = c_{i,j,\infty}$ for any $(i,j)\in\{(2,1),(1,2),(2,2)\}$.

\item $\lim_{t\uparrow\infty} (\beta_{1}^{-} - \beta)(t) + \frac{1}{2}(g_{1,2}(t)^{2} + g_{2,1}(t)^{2})\mathbbm{1}_{\{\frac{1}{2}\}}(\eta_{0}) = u_{2}$.

\item $\lim_{t\uparrow\infty} \big(g_{1,1}(t) + g_{1,2}(t)\mathbbm{1}_{\{1\}}(\eta_{0})\big)^{2} + g_{2,1}(t)^{2}\mathbbm{1}_{\{1\}}(\eta_{0}) = u_{3}$.

\item $u_{4} := c_{1,2,\infty} + c_{2,1,\infty} + c_{2,2,\infty}N_{\infty} + \frac{1}{2}u_{3}$ is positive.
\end{enumerate}
For a positive solution $I$ to~\eqref{eq:SIS epidemic model} set $u := -(\mu_{\infty} + \gamma_{\infty})$, if $u_{2} \geq (2c_{1,2,\infty} + c_{2,1,\infty})N_{\infty}$ $ +\, c_{2,2,\infty}N_{\infty}^{2}$, and
\begin{align*}
u &:= - (\mu_{\infty} + \gamma_{\infty} + u_{I}) + u_{1}N_{\infty} + \bigg(c_{1,2,\infty} - \frac{1}{2}u_{3}\bigg)N_{\infty}^{2}\\
&\quad + \frac{1}{4} \frac{\big((u_{2} + (c_{2,1,\infty} + u_{3})N_{\infty} + c_{2,2,\infty}N_{\infty}^{2})^{+}\big)^{2}}{u_{4}},
\end{align*}
otherwise, with the non-negative constant $u_{I} := \liminf_{t\uparrow\infty} \beta_{1}^{+}(t)N(t) - \beta_{1}(t)\E\big[I_{t}\big]$. Then $I$ becomes exponentially extinct if $u < 0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 3 (Riemann--Liouville fractional integral) of arXiv:2608.25164, 'A time-fractional Kalman filter'] For $\alpha>0$, the fractional integral of a locally integrable function $f$
is
\begin{align}
(I^\alpha f)(t)
=\frac{1}{\Gamma(\alpha)}\int_0^t(t-s)^{\alpha-1}f(s)ds.
\end{align}

[Proposition eq:sslongrange of arXiv:2606.01866, 'Phase Transition of a Semiflexible Membrane in Two Dimensions'] \label[proposition]{thm:sslongrange}
    Let $\lambda\in[0,2]$ and $\delta\in (0,1)$ be fixed. For any $x,y\in V_N^\delta$, if $\|x-y\|\gtrsim N^{\lambda/2}$, then 
    \begin{equation}
        \bar{G}_N(x,y)=G^0_N(x,y)+O(1),
    \end{equation}
    uniformly in $x,y\in V_N^\delta$. Moreover, the $O(1)$ error term improves to $o(1)$ if $\|x-y\|\gg N^{\lambda/2}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition eq:martdecomp of arXiv:2606.01937, 'Stationary fluctuations for an exclusion process with mass and energy conservation'] For any $i\in \{1,2\}$, any test function $\varphi\in \mathscr{S}(\mathbb{R} )$ and any $t\in [0,T]$, the martingale $\mathcal{M}^{N,i}$ decomposes as
    \begin{equation}
        \mathcal{M}_t^{N,i}(\varphi ) = \mathcal{Z}_t^{N,i}(\varphi )-\mathcal{Z}_0^{N,i}(\varphi ) - \mathcal{I}_t^{N,i}(\varphi ) - \Lambda_t^{N,i} (\varphi ) + E^{N,i}_t(\varphi)
    \end{equation}
    where
    \begin{align}
        & \mathcal{I}_t^{N,i}(\varphi ) = (\kappa -1)N^{a-2}\int_0^t \mathcal{Z}_s^{N,i}(\Delta_N\varphi )\,\mathrm{d} s, \\
        & \Lambda_t^{N,i} (\varphi ) = N^{a-\gamma -\frac32} \int_0^t \sum_{x\in\mathbb{Z}} \big( \mathfrak{c}_i\tilde{h}_x^p(s)+\tilde{h}_x^e(s)\big) \nabla_NT_{v_iN^{a-1}s}\varphi\Big( \frac xN\Big)\,\mathrm{d} s, 
    \end{align}
    and $E_t^{N,i}(\varphi )$ is the remainder term coming from the replacement of the discrete gradient by its continuous counterpart, whose $L^2$-norm is of order $O(N^{2a-2\gamma -4})$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop p.gmc.coupling of arXiv:2507.16056, 'Conditional GMC within the stochastic heat flow'] There exists a coupling of the family $(M^{\theta}_{[s,t]})_{ \theta\in\mathbb{R}}$ such that, with $\mathscr{H}_{\theta}:=\sigma(M^{\phi}_{[s,t]}\,|\,\phi\leq\theta)$ denoting its canonical filtration,
\begin{align}

\begin{split}
    \text{the law of } &(M^{\theta}_{[s,t]})_{\theta\geq\theta_0}
    \text{ conditioned on } \mathscr{H}_{\theta_0}
\\
    &\text{ is equal to the law of }
\big(\mathcal{G}\big[M^{\theta}_{[s,t]},Y_{\star\,[s,t]}^{\theta},\xi(\theta_0,\theta)\big]\big)_{\theta\geq\theta_0}\ .
\end{split}
\end{align}
In particular, $M^{\theta}_{[s,t]}$ is a Markovian martingale in $\theta$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 18 (Small-time expansion of the coordinate profile) of arXiv:2605.11451, '2605.11451'] Let $1\le p<2$ and $n\ge2$, and let $Z\sim N(0,1)$. As $t\downarrow0$,
\begin{equation}
 h_{p,n,t,e_1}(0)
 =
 C_{p,n}\left(1-\frac{n-1}{p}\,\E|Z|^p\,t^{p/2}+O_{p,n}(t)\right),
\end{equation}
and therefore
\begin{equation}
 \Phi_{p,n}(t)
 =
 C_{p,n}\sqrt{v_{p,n}}\left(1-\frac{n-1}{p}\,\E|Z|^p\,t^{p/2}+O_{p,n}(t)\right).
\end{equation}
Moreover,
\begin{equation}
 \Phi_{p,n}'(t)
 =
 -C_{p,n}\sqrt{v_{p,n}}\,\frac{n-1}{2}\,\E|Z|^p\,t^{p/2-1}
 +O_{p,n}(1).
\end{equation}
In particular, $\Phi_{p,n}'(t)<0$ for all sufficiently small $t>0$.

[Lemma le:integrate-one-spin of arXiv:2411.06195, 'Restrictions of some reinforced processes to subgraphs'] Let $1\in\Lambda$ and set $1^c=\Lambda\setminus\{1\}$.
  One has
  \begin{align}

    \int_{H^{2|2}}\mathcal{D}\sigma_1\, e^{\sum_{i\in 1^c}W_{1i}\left\langle{\sigma_1,\sigma_i}\right\rangle}
    =e^{-\|\sum_{i\in 1^c}W_{1i}\sigma_i\|},
  \end{align}
  and consequently, 
\begin{align}

  \int_{H^{2|2}}\mathcal{D}\sigma_1\,
    e^{\frac12\sum_{i,j\in\Lambda}W_{ij}(1+\left\langle{\sigma_i,\sigma_j}\right\rangle)}
      =& e^{\frac12\sum_{i,j\in 1^c}W_{ij}(1+\left\langle{\sigma_i,\sigma_j}\right\rangle)
    +\sum_{i\in 1^c}W_{1i}-\|\sum_{i\in 1^c}W_{1i}\sigma_i\|}.
\end{align}

