body:
[Proposition 3 (Conditional-KL Representation of the Sinkhorn Ambiguity Set) of arXiv:2608.22746, 'Generative Neural Networks for Sinkhorn Distributionally Robust Hypothesis Testing'] The ambiguity sets based on Sinkhorn discrepancy with $\epsilon > 0$ are equivalent to 
    \begin{equation} 
        \mathbb{B}_{\bar{\rho}_k}(\mathbb{P}_k^{\epsilon}) := \left\{ \mathbb{Q}: \inf_{\gamma\in\Gamma(\widehat{ \mathbb{P}}_k, \mathbb{Q})} \, \,  \mathbb{E}_{\boldsymbol{x} \sim \widehat{\mathbb{P}}_k} \Big [ \mathcal{D}_{\mathrm{KL}} (\gamma_{\boldsymbol{x}}\| \mathcal{K}_{\boldsymbol{x}, \epsilon})\Big ] \le \bar{\rho}_k/\Reg \right\}, \quad \forall k \in \mathbb{K}, 
    \end{equation}
    where $\bar{\rho}_k := \rho_k +\Reg \mathbb{E}_{\boldsymbol{x}\sim \widehat{\mathbb{P}}_k}\Big [ \log\, \int_{\mathbb{R}^d}e^{-c(\boldsymbol{x}, \boldsymbol{z})/ \Reg} \diff \boldsymbol{z} \Big]$, probability density $\mathrm{d} \mathbb{P}_k^{\epsilon}(\boldsymbol{z}) := \mathbb{E}_{\boldsymbol{x} \sim \widehat{\mathbb{P}}_k}\left[ \diff \mathcal{K}_{\boldsymbol{x}, \epsilon}(\boldsymbol{z}) \right]$, 
    \begin{equation*}
        \diff \mathcal{K}_{\boldsymbol{x}, \epsilon}(\boldsymbol{z}) := \frac{e^{-c(\boldsymbol{x}, \boldsymbol{z}) / \epsilon}  }{\int_{\mathbb{R}^d} e^{-c(\boldsymbol{x}, \boldsymbol{u}) / \epsilon} \cdot \diff \boldsymbol{u}} \cdot \mathrm{d} v(\boldsymbol{z}). 
    \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor statequiv-annulus-bound of arXiv:2605.08052, 'Rapid phase ordering of Ising dynamics on $\mathbb Z^2$'] For any $B \in \mathscr{B}_k$ and any $R \in \mathscr{R}_{k-1}(B)$, 
    \begin{align*}
        \mathbb P\big(\exists t\in [T_{k-1},T_k] : V_t^{R,\pi}(E_{+2}(R) \setminus E_{+1}(R)) \ne V_t^{B\setminus R,\pi}(E_{+2}(R)\setminus E_{+1}(R)\big)\le \frac{1}{(2\ell_{k})^{d+1}}  \frac{q_{k+1}}{10}\,.
    \end{align*}

[Theorem 1 of arXiv:2511.14379, 'Stability of storage processes with general release rates'] Assume $\textbf{(C1)-(C2)}$ (or $\textbf{(\={C}1)-(\={C}2)}$ in the case when $\bar\upnu(0)<\infty$), that $\process{X}$ is  $\uppsi$-irreducible and aperiodic, and that every compact set is petite for $\process{X}$. 
	\begin{itemize} 
		\item[(i)] The process $\process{X}$ is transient if either of the two conditions hold:
		\begin{enumerate}
			\item[(a)]  $\displaystyle\limsup_{u\to\infty} r(u)<m_\upnu$.
			\item[(b)]  $\displaystyle\liminf_{u\to\infty} \frac{u}{r(u)}\int_0^\infty \frac{1}{1+v^2}\bar\upnu(uv)\D v > 1$.
		\end{enumerate}
	\item[(ii)] If, for some $u_0\in(0,\infty)$, $r(u) = m_\upnu$ for all $u\geq u_0$, the process  $\process{X}$ is null recurrent.
			\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

