body:
[Theorem 5 of arXiv:2607.10356, '2607.10356'] Let $\{\CW_n:n\ge 1\}$ be a sequence of independent $\Bb$-valued random variables with mean zero and is \emph{tight} $($\emph{i.e.} satisfies \eqref{m1}, \eqref{m2}$)$.
Suppose $\{\CW_n:n\ge 1\}$ is uniformly integrable, \emph{i.e.}
\begin{equation}
\textstyle\lim_{t\rightarrow\infty}\Bigl[ \sup_{n\ge 1}\E\bigl[\nrm{\CW_{n}}\Ind_{\{\nrm{\CW_{n}}\ge t\}}\bigr]\Bigr]=0.
 \end{equation}
Then for all $\epsilon>0$ there exists $t\ge 1$, $\{\xa_j: 1\le j\le t\}\subseteq\Bb$, a sequence $\{ \CY_{n}:n\ge 1\}$ of $\Bb$-valued independent random variables, a constant $C<\infty$ and for $1\le j\le t$, a sequence $\{\xi_{n,j}: n\ge 1\}$ of $[-1,1]$-valued independent random variables such that for all $n\ge 1$
\begin{align}
\CW_n=\CY_n+&\textstyle\sum_{j=1}^t \xa_j\xi_{n,j},\\

\E[\xi_{n,j}]&=0,\;\;\;\;\forall\,1\le j\le t,\\
\E[\nrm{\CY_n}]&\le \epsilon\\

\nrm{\CY_n-\CW_n}&\le C.
\end{align}
Further, if $\{\CW_n:n\ge 1\}$ are i.i.d. then $\{\CY_n:n\ge 1\}$ are i.i.d. and for each $1\le j\le t$, $\{\xi_{n,j}: n\ge 1\}$ are also i.i.d.

[Lemma lem:pushforward of arXiv:2608.07842, 'Resolution of a Conjecture on Shifted R\'enyi Divergence'] For $\beta\in[0,1)$ with $\mu_D(\beta)$ as above, $\mu'_\beta$ is Gaussian with
$$\langle u,\cdot\rangle\text{-marginal }=N\big(m-\mu_D(\beta),\,(1-\beta)^2\sigma^2\big),$$
and with all marginals orthogonal to $u$ equal to those of $\mu$, namely $N(0,\sigma^2)$. Hence, writing $\sigma_q^2(\beta):=q\sigma^2-(q-1)(1-\beta)^2\sigma^2$ and $\mu_1(\beta):=m-\mu_D(\beta)$,
\begin{equation}
J(\beta):=R_q(\mu'_\beta\|\nu)=\frac{q\,\mu_1(\beta)^2}{2\sigma_q^2(\beta)}+\frac{1}{1-q}\log\frac{\sigma_q(\beta)}{\big((1-\beta)\sigma\big)^{1-q}\sigma^{q}}.
\end{equation}

[Teo 1 of arXiv:2605.11264, 'Uniform sampling of multitype continuous-time Bienaym\'e-Galton-Watson trees'] For any $k\geq 1$, $T\in \re_+$,  $r\in [d]$, we have
\begin{equation}
	\begin{split}
\mathbb{P}^{(k)}_{unif,T,r}&\paren{\Delta_T(n)}\\
&= \frac{1}{(k-1)!}\frac{1}{\mathbb{P}_{r}\paren{\ N_T\geq k}}\int_0^\infty(e^\phi-1)^{k-1}\Q^{(k),\phi\vec{1}}_{T,r}(\Delta_T(n))\E_{r}\left[N^{\floor{k}}_Te^{-\phi\vec{1}\cdot \bo Z_T}\right]{\rm d}\phi,
\end{split}
\end{equation}
where
\[
\begin{split}
\Q^{(k),\phi\vec{1}}_{T,r}(\Delta_T(n))&= \prod_{h=1}^n\prod_{m=1}^d\E_{m}\left[e^{-\phi\vec{1} \cdot \bo Z_{T-t_h}}\right]^{\ell_{h,m} -g_{h,m}}p_{i_h}(\bm \ell_{h})\bm \ell_{h}^{\floor{\bo g_h}}\\
		&\hspace{-1.5cm}  \times 
		\prod_{h=0}^{n-1}\prod_{m=1}^d\prod_{\substack{ q\leq g_{h,m}:\\ k_{v(h,m,q)}\geq 2}}\E_{m}\left[Z^{(c(v(h,m,q)))}_{t_{v(h,m,q)}-t_h} \prod_{j=1}^d\E_{j}\left[e^{-\phi\vec{1}\cdot \bo Z_{T-t_{v(h,m,q)}}}\right]^{ Z^{(j)}_{t_{v(h,m,q)}-t_h}-\delta_{c(v(h,m,q)),j}}\right]\\
	& \hspace{1.5cm} \times
	\frac{\prod_{h=1}^{n}\prod_{m=1}^{d}\E_{m}\left[N_{T-t_{h}}e^{-\phi\vec{1} \cdot \bo Z_{T-t_{h}}}\right]
		^{\#\{ q\leq g_{h,m}:k_{v(h,m,q)}=1\}}
	}{\E_{r}\left[N_T(N_T-1)\cdots(N_T-k+1)e^{-\phi\vec{1}\cdot \bo Z_{T}}\right]} \prod_{h=1}^n\alpha_{i_{h}} {\rm d}t_h,
	\end{split}
\]
 $t_{v(h,m,q)}$ and $c(v(h,m,q))$ are the spine splitting times  and type associated to the vertex $v(h,m,q)$.  When  $h=0$, we observe that $v(0)=\emptyset$, $g_{0,m}=\delta_{r,m}$ and $v(0, r, 1)=v(1)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 6 (\cite{Chen2013}*{Lemma~5}) of arXiv:2608.10515, 'Limiting Law of Local Fields for the Mean Field Ghatak-Sherrington Model'] Fix an integer $m\ge1$. Let $\psi$ be continuous on $[0,1]$ and differentiable on $(0,1)$. For a binary word $\mathbf s=(s_1,\ldots,s_n)\in\{0,1\}^n$, let $\psi_{\mathbf s}$ be continuous on $[0,1]$ and differentiable on $(0,1)$. Suppose that all the expressions below are integrable at zero, that $\psi(0)=0$, and that
\begin{equation}
  \psi'(t)=\frac12\psi_{(0)}(t)+\frac1{2\sqrt t}\psi_{(1)}(t),
  \qquad
  \psi_{\mathbf s}'(t)=\frac12\psi_{(\mathbf s,0)}(t)
  +\frac1{2\sqrt t}\psi_{(\mathbf s,1)}(t)
\end{equation}
for $t\in(0,1)$ and $1\le |\mathbf s|\le m$. If
\[
  \psi_{\mathbf s}(0)=0,\qquad 1\le |\mathbf s|<m,
\]
then, writing
\[
  \Delta_n(t):=\{(t_1,\ldots,t_n):0<t_n<\cdots<t_1<t\},
\]
we have
\begin{align}
\psi(t)
={}&\frac1{2^m}\sum_{\mathbf s\in\{0,1\}^m}
\int_{\Delta_m(t)}
\left(\prod_{j=1}^m t_j^{-s_j/2}\right)\psi_{\mathbf s}(0)\,d\mathbf t \\
&+\frac1{2^{m+1}}\sum_{\mathbf s\in\{0,1\}^{m+1}}
\int_{\Delta_{m+1}(t)}
\left(\prod_{j=1}^{m+1}t_j^{-s_j/2}\right)
\psi_{\mathbf s}(t_{m+1})\,d\mathbf t.\notag
\end{align}

[Definition 7 (First-order corrector) of arXiv:2604.21143, 'Quantitative homogenization for the critical long-range random conductance model'] Given a slope $p \in \Rd$, a bounded Lipschitz domain $U \subseteq \Rd$, and $\eps \in (0, 1)$, we define
		\begin{equation}

			\nu(U^\eps, p)
			\coloneqq -\inf_{\substack{w \colon \eps\Zd \to \R \\ w = 0 \text{ on } \eps\Zd \setminus U^\eps}}
			\frac{\eps^{2d}}{2\kappa_\eps}
			\sum_{\substack{x, z \in \eps\Zd, z \ne 0 \\ x \in U^\eps \text{ or } x+z \in U^\eps}}
			\a\left(\frac{x}{\eps}, \frac{x+z}{\eps}\right) J(z)
			\Bigl[\bigl(p \cdot z + w(x{+}z) - w(x)\bigr)^2 - |p \cdot z|^2\Bigr].
		\end{equation}
		The factor $1/2$ ensures that each unordered edge touching $U^\eps$ is counted exactly once.
		We define the first-order corrector $\phi_p^\eps$ to be the unique minimizer of this functional; it is equivalently the unique solution to
		\begin{equation} 
			\begin{cases}
				\mathcal{L}^\eps(\ell_p + \phi_p^\eps) = 0 & \text{in } U^\eps\,,\\
				\phi_p^\eps = 0 & \text{on } \eps\Zd \setminus U^\eps\,.
			\end{cases}
		\end{equation}

