[Lemma eq:sphere-easy-1 of arXiv:2607.18011, 'From local giants to locality in long-range percolation'] \thlabel{lem:sphere_calculus}
    Let $G$ be a transitive graph of polynomial growth with $d \geq 1$.

    Let $f$ be a non-negative regularly varying function with index $\gamma\in \mathbf{R}$. 

    Then there exist $c = c(\gamma, G) > 0$ and $C = C(\gamma, G) > 0$ such that
    for all $r_0,r_1 \in \mathbf{N} \cup \{\infty\}$ with $r_0 < r_1$, 
    \begin{equation}

        c
        \int_{r_0}^{r_1}
        t^{d-1}
        f(t)
        dt
        \leq 
        \sum_{s = r_0}^{r_1}
        \# 
        S(s)
        f(s)
        \leq 
        C
        \int_{r_0}^{r_1}
        t^{d-1}
        f(t)
        dt.
    \end{equation}


    Let $A>1$ be fixed. 

    Then there exists $c = c(\gamma,G) > 0$ such that for all $r_1 \in \mathbf{N}$ 
    \begin{equation}

        \sum_{r_1/A \leq s \leq r_1}
        \# 
        S(s)
        f(r_1-s)
        \geq 
        c
        r_1^{d-1}
        \int_{1}^{r_1}
        f(t)
        dt.
    \end{equation}

    Let $k \in \mathbf{N}$ and let $\varepsilon>0$.

    Then there exists $C = C(G,A, \gamma) > 0$ such that at least a $(1-\varepsilon)$ proportion of the radii $r \in [A^{k-1},A^k)$ satisfy 

    \begin{equation}

        \sum_{r/A \leq s \leq r}
        \# 
        S(s)
        f(r-s)
        \leq 
        \frac{C}{\varepsilon} 
        r^{d-1}
        \int_{1}^{r}
        f(t) 
        dt.
    \end{equation}

