[Definition 19 of arXiv:2507.06186, '2507.06186'] For any $\ka,\eps,t>0$, we let $\mc K_{\ka,\eps}(t)$ denote the integral operator on $L^2(D)$ with kernel
\begin{align}

\mc K_{\ka,\eps}(t;x,y)=p_t(x-y)\mbf E_B\left[\mbf 1_{\{\tau_D(B^{x,y}_t)>t\}}\exp\left(-\ka\int_0^t\xi_\eps\big(B^{x,y}_t(r)\big)\d r\right)\right],\qquad x,y\in D,
\end{align}
where we assume that $B^{x,y}_t$ and $\xi_\eps$ are independent, and we use $\mbf E_B$ to
denote the (conditional) expectation with respect to the randomness in $B$ only.

[Corollary coro_crdata of arXiv:2609.00645, 'Global persistence of nearly radial concentrated vortices in a bounded domain'] Under the assumptions of (thm:main of the paper), suppose in addition that
\[
  \mathbf a_\varepsilon=\mathbf a_*,
  \qquad
  \omega_{\varepsilon,0}(\mathbf x)
  =\omega_{\varepsilon,0}^*(\mathbf x-\mathbf a_*).
\]
Then, for all sufficiently small $\varepsilon>0$,
\begin{equation}
  \sup_{t\in\mathbb R}\left\{
  \mathcal D(\omega_{\varepsilon,t})
  +\kappa^2\sup_{\mathbf b\in\mathsf C(\omega_{\varepsilon,t})}
  [H(\mathbf b)-H(\mathbf a_*)]\right\}
  \leq C\varepsilon,
\end{equation}
and
\begin{equation}
  \sup_{t\in\mathbb R}\mathcal A(\omega_{\varepsilon,t})
  \leq C\varepsilon^{1/2}.
\end{equation}
If $D^2H(\mathbf a_*)$ is positive definite, then, after possibly decreasing
$\rho$,
\begin{equation}
  \sup_{t\in\mathbb R}\ \sup_{\mathbf b\in\mathsf C(\omega_{\varepsilon,t})}
  |\mathbf b-\mathbf a_*|
  \leq C\varepsilon^{1/2}.
\end{equation}
Here $C>0$ depends only on
$D,\mathbf a_*,\rho,\kappa,M$, and $R$.

[Lemma eq:biskup_level_0_bad of arXiv:2607.18011, 'From local giants to locality in long-range percolation'] \thlabel{lem:biskup_induction_base}
    Let $G$ be a transitive graph of polynomial growth with $d \geq 1$ and suppose that $J : V \times V \to \mathbf{R}_+$ is a transitive kernel satisfying $J(x,y) = \Omega (d_G(x,y)^{-d \alpha})$ with $\alpha \in (0,2)$.

    Let $\beta > \beta_c$.

    Let $((\Tile{i}{j})_{j \geq 0})_{i \geq 0}$ be the renormalisation scheme in \thref{def:renorm_scheme_2}. 

    For all $c > 0$ we can choose $r_0$ sufficiently large such that for any tile $\Tile{0}{j}$

    \begin{equation}

        \mathbf{P}(\Tile{0}{j} \text{ is bad})
        \leq 
        \exp(-c).
    \end{equation}

