[Theorem 2 ($L$-fold, coupled spherical integration for $\mathrm{rank}(D_l D_l^\dagger)=1$) of arXiv:2608.03273, 'On the Asymptotic of Coupled Spherical Integrals: An Operator-Valued Extension of the Free'] Let $L=O(1)$, $M(N)=1$, and $D_l=O_l\Sigma_l V^\dagger$ be the singular-value decomposition of $D_l$ for all $l$, i.e. $D_l$ has a single non-zero singular value $\sqrt{\theta_l}$ at index $(1,1)$ of $\Sigma_l$, and the right unitary/orthogonal matrix $V^\dagger$ of the SVD of $D_l$ is identical for all $l$.
Define $Z_N$ as in Definition~\ref{def:operator_valued_convergence} with $E_{lk}\in\mathbb A^{N\times N}$, and $E_{lk}=E_{kl}^\dagger$.
If $Z_N$ converges to $Z$ where all moments of $Z$ are finite, $Z$ is R-cyclic, the spectral norm $||E_{lk}||_\infty<\infty$ is bounded for all $(l,k)$ as $N\uparrow\infty$, and all $\theta_l$ are small enough such that
\begin{align}
    -P=-\mathrm{diag}\left\{\frac{2\theta_1}{\beta},\ldots,\frac{2\theta_L}{\beta}\right\}
    \in \left\{\left.G^{\mathcal{D}_L}_Z(S) \right| S\in\mathcal S^Z_{\{-\}^L}\right\},
\end{align}
then
\begin{align}
    \lim_{N\uparrow\infty}
    \frac{1}{N}\log I_N^{(\beta)}(\{D_l\},\{E_{lk}\}) 
    = 
    \frac{\beta}{2}
    \int_{0}^1
        \mathrm{tr}\left(
            R_Z^{\mathcal{D}_L}(Pw)P
        \right)
        \mathrm d w
    = I_{Z}^{(\beta)}(\{\theta_l\}),
\end{align}
where $G_Z^{\mathcal D_L}$ and $R_Z^{\mathcal D_L}$ are the Stieltjes and R-transform of $Z$ on the operator-valued probability space $(\mathcal A, \mathcal E_{\mathcal D}, \mathcal D_L)$, respectively, and $\mathcal S^Z_{\{-\}^L}$ is the domain on which $G_{Z}^{\mathcal D_L}(S)$ exists on the real plane and is negative definite as defined in Properties~\ref{prop:2conditional_stieltjes_transform_on_real_plane} and \ref{prop:Lconditional_stieltjes_transform_on_real_plane}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition e:orderinghyp of arXiv:2510.00748, '\bf On irreducible central limit theorems'] Let the above assumptions prevail, and fix integers $1\leq m\leq N$. Consider a collection $B_1,...,B_m$ of nonempty disjoint subsets of $V$, and assume that
\begin{equation}
\varphi(B_1)\le \varphi(B_2)\le \cdots \le \varphi(B_m). 
\end{equation}
Then, for all $k=1,...,m$,
\begin{equation}
 \mu_k \leq \frac{2 \big(r({\ensuremath{\mathcal G}} )-1\big)^2}{ cr({\ensuremath{\mathcal G}} )-1}\, \frac{\sum_{i=k}^m \mathrm{vol} (B_i) \, \varphi(B_i)}{\sum_{i=k}^m \mathrm{vol}(B_i)}  . 
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm hop-count-asymptotics of arXiv:2609.00110, 'Phase Transition and Fluctuation Results for First-Passage Percolation on Spread-Out Cycle'] Assume that the edge weights satisfy Assumption~(ass:weight of the paper).
\begin{enumeratea}
\item  \textup{(Mesoscopic law of large numbers)}
Assume that $1 \ll \ell \ll n/\log n$. Let $H_n^{(\ell)}(0,\mathsf{u}_n)$ denote the number of edges in the a.s.\ unique geodesic realising $T_n^{(\ell)}(0,\mathsf{u}_n)$. Then, for fixed $\mathsf{u}\in(0,1/2)$, we have
\begin{align}
 \frac{\ell}{\mathsf{u}_n} H_n^{(\ell)}(0,\mathsf{u}_n) \stackrel{\pr}{\to} \frac{\beta_{\mathsf{c}}}{\theta}
 \text{ and }
 \frac{\ell}{\mathsf{u}_n} \E H_n^{(\ell)}(0,\mathsf{u}_n)
 \to \frac{\beta_{\mathsf{c}}}{\theta} \text{ as } n\to\infty,
\end{align}
where $\beta_{\mathsf{c}}$ is the constant defined in~(equation eq:beta_c of the paper).

\item  \textup{(Macroscopic law of large numbers)}
Assume that $\ell/n\to\gl\in(0,1/2)$. Let $U_n$ be chosen uniformly from $\mathds{T}_n\setminus\{0\}$ and let $H_n^{(\ell)}(0,U_n)$ be the number of edges in the geodesic from $0$ to $U_n$. Then
\begin{align}
 \frac{H_n^{(\ell)}(0,U_n)}{\log n}
 \stackrel{\pr}{\to}\frac1\theta ,
 \text{ and }
 \frac{\E H_n^{(\ell)}(0,U_n)}{\log n} \to \frac{1}{\theta} \text{ as } n\to\infty.
\end{align}
\end{enumeratea} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm hypergraphr of arXiv:2412.00610, 'Joint Poisson Convergence of Monochromatic Hyperedges in Multiplex Hypergraphs'] Fix an integer $r \geq 2$ and consider a sequence $\bm H_n = (H_n^{(1)}, H_n^{(2)})$ of 2-hypermultiplexes, where both $H_n^{(1)}$ and $H_n^{(2)}$ are $r$-uniform. Suppose the vertices of $\bm H_n$ are colored uniformly at random with $c_n$ colors, such that the following hold: 
\begin{align} 
\lim_{n \rightarrow \infty} \bE [ \bm T(\bm H_n) ] = \begin{pmatrix}
  \lambda_1 \\ 
  \lambda_2
  \end{pmatrix} \quad \text{ and } \quad \lim_{n \rightarrow \infty} \mathrm{Var}[ \bm T(\bm H_n) ] = \begin{pmatrix}
  \lambda_1 & \lambda_{1, 2} \\ 
  \lambda_{1, 2} & \lambda_2
  \end{pmatrix} , 
    \end{align}
   for constants $\lambda_1, \lambda_2, \lambda_{1,2} \geq 0$ with $\lambda_{1,2} \le \lambda_1$ and $\lambda_{1,2} \le \lambda_2$. Then
  $$ \bm T(\bm H_n) \dto \left(\begin{array}{l}
          Z_1 + Z_{1,2} \\
          Z_2 + Z_{1,2}
          \end{array}\right) , $$
  where $Z_1 \sim \Pois(\lambda_1 - \lambda_{1,2})$, $Z_2 \sim \Pois(\lambda_2 - \lambda_{1,2})$, and $Z_{1,2} \sim \Pois(\lambda_{1,2})$ are independent. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 7 (Exact descent decomposition) of arXiv:2609.01882, '\textbf{Coxeter Descents and Parabolic Homotopy Colimits}\\[2mm] \large A Hochster-type de'] There is a based chain isomorphism
\begin{equation}
  \BK_{\mathcal K}(W)
  \cong
  \bigoplus_{w\in W}
  \Sigma^{2\ell(w)}C_*(A_{\mathcal K},L_{\mathcal K,\DesR(w)};\Z).
\end{equation}
Under this isomorphism $[w;I_0<\cdots<I_q]$ corresponds to the relative simplex $[I_0<\cdots<I_q]$ in the $w$-summand.

[Lemme 47 of arXiv:2604.00635, 'Large deviations of the periodic Toda chain'] Assume that hypothesis \ref{potentialh2} holds. 
Let $\tilde{I} : \mathcal{M}_1(\mathbb{R}) \longrightarrow  \intof{-\infty}{+\infty}$ be defined by

$$ \tilde{I}[\mu]\overset{\mathrm{def}}{=}\Int{\mathbb{R}}{} V(x) \, \mathrm{d}\mu(x) -

\Int{\mathbb{R}}{} \ln \max\Big\{ 0 ,  1+ \frac{2}{\ell} \Int{\mathbb{R}}{} \ln|x-y| \, \mathrm{d}\mu(y) \Big\} \, \mathrm{d}\mu(x)$$

and likewise,  for $\eta_1, \eta_2 , M_1, M_2 > 0$, let $\bs{\mf{p}} = ( \eta_1, \eta_2 , M_1, M_2 ) $ and

\begin{align*}

&\tilde{I}_{\bs{\mf{p}}}[\mu] \overset{\mathrm{def}}{=} (1-2\eta_1) \Int{\mathbb{R}}{} \min\big\{ V(x) , M_1 \big\} \, \mathrm{d}\mu(x) \\

    &- \Int{\mathbb{R}}{} \ln_{\eta_2^{-1}}\Big\{   1+ \frac{2}{\ell} \Int{\mathbb{R}}{} \max\big\{ \ln|x-y| - \eta_1\eta_2 V(x) - \eta_1\eta_2 V(y), -M_2 \big\}

\, \mathrm{d}\mu(y) \Big\}

\, \mathrm{d}\mu(x) \, .

\end{align*}

with $\ln_{M}$ as introduced in \eqref{definition ln M regularise}.
Then, one has

\begin{equation}

\tilde{I}[\mu] = \sup_{\bs{\mf{p}} \in (\R^+)^4 } \tilde{I}_{\bs{\mf{p}}}[\mu] \, .

\end{equation}

[Proposition pro: zero probability sum for JSQ of arXiv:2603.14163, '\LARGE \bf Tail Bounds for Queues with Abandonment: Constant, Moderate, Large Deviations, '] \textnormal{(Probability Mass at Zero)}

    Under heavily overloaded assumption (ass:heavy_overload of the paper), the probability mass at zero for JSQ model is bounded as
    \begin{align*}
        \sum_{i=1}^{n} \mathbb{P}(\mathbf{q}_{i} = 0) &\leq \exp\left( -\frac{C}{2n\lambda} \cdot\frac{\lambda-\mu}{\sqrt{\gamma}} \right) \\
        \exp\left( -\frac{\lambda}{\gamma} \right) \leq \mathbb{P}(\sum_{i=1}^{n} \mathbf{q}_{i} = 0) &\leq C_{\lambda,\mu}' \sqrt{\gamma/\mu} \exp\left( -\frac{1}{\gamma/\mu} (\lambda/\mu - 1 - \ln (\lambda/\mu)) \right) 
    \end{align*}
    $C_{\lambda,\mu}'$ is the same as in Lemma (lem: tight bound on P(q_infty = 0) of the paper), $C$ is from the heavily overloaded assumption (ass:heavy_overload of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:883 of arXiv:2411.14921, 'A boundary Harnack principle and its application to analyticity of 3D Brownian intersectio'] For all $0<u\le 1$, there exists $K_1(u)>0$ such that the following holds. Consider the collection of spheres $\mathscr{S}:=\bigcup_{t\in\mathbb Z}\{\partial\mathcal B_{t/p}\}$ with a real parameter $p\geq1$. Then, for all $n\geq 1$ and $z\in\mathbb R^3$ with $|z|\ge2^{-n}$, we have
    \begin{equation*}
        \mathbb{P}_{z}\Big(\tau_{\mathscr{S}}^{[K_1np^2]}<L_{B(0,2)}\Big)<u^n.
    \end{equation*}

