[Thmd 6 of arXiv:2606.08115, '2606.08115'] Let $K = \mathbb{R}^{+} \times \mathbb{R}^{+}$, a two-dimensional random walk $\left\{\ov{S}_n\right\}$ satisfies the condition (C). Let $\tau(\ov{x})$ be the exit time of a random walk from the cone $K$ with starting point $\ov{x} \in K$, as defined in (\ref{tauDef}). Then the following statements hold.
\begin{enumerate}
\item Uniformly in $\ov{x} \in K$ such that $\left|\ov{x}\right| \le \sqrt{n}/\ln n$
\begin{equation}

\pr \left( \tau(\ov{x}) > n \right) \sim \frac{\varkappa V\left(M\ov{x}\right)}{n^{p/2}}, \;\; n \to \infty,
\end{equation}
where $\varkappa$ is some real positive number which does not depend on $\ov{x}$.
\item There exists a real positive number $C$ and a vector $\ov{x}_0 \in MK$ such that for every $\ov{x} \in K$, we have inequality
\begin{equation}

\pr \left( \tau(\ov{x}) > n \right) \le C \frac{u \left( M\ov{x} + \ov{x}_0\right)}{n^{p/2}}.
\end{equation}
\end{enumerate}
In this case the function $V$ for every $\ov{x} \in K$ defined as follows
\begin{equation}

V\left(M\ov{x}\right):= \lim_{n \to \infty} \ex u\left(M\left(\ov{x} + \ov{S}_n\right)\right) I\left\{ \tau(\ov{x}) > n\right\}.
\end{equation}
Moreover:
\begin{itemize}
\item for every vector $\ov{x} \in K$ and every natural number $n$
\begin{equation}

V\left(M\ov{x}\right)= \ex V\left(M\left(\ov{x} + \ov{S}_n\right)\right) I\left\{ \tau(\ov{x}) > n\right\};
\end{equation}
\item the following asymptotic relation holds
\begin{equation}

V(M\ov{x}) \sim u(M\ov{x}), \;\; \mathrm{dist}\left( \ov{x}, \partial K\right) \to \infty.
\end{equation}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition pr:coupling of arXiv:2504.11107, 'An Invariance Principle for some\\% Reaction-Diffusion Equations with a Multiplicative Ran'] There exists a number
	$A=A(f\,,g)>1$ such that
	\begin{align*}
		&\mathrm{P}\left\{ u(s)\neq v(s)\text{ for all $s\in(0\,,t]$}\right\}\\
		&\hskip.5in\leqslant A\, \left( \frac{\|u_0 - v_0\|_{C(\mathbb{T})}}{
			\alpha t \min\left( \inf_{z\in \mathbb{T}} u_0(z)  \,, \inf_{z\in \mathbb{T}} v_0(z) \right)}\right)^{1/2}
			+ A\, \exp\left( -\frac{1}{A\sqrt{t}}\right),
	\end{align*}
	uniformly for all $t>0$ and all bounded, measurable, and non-zero 
	respective initial profiles $u_0,v_0:\mathbb{T}\to\mathbb{R}_+$. (Proof in the paper; no proof environment follows the statement in the TeX.)

