[Corollary 11 (First two descent moments) of arXiv:2606.18047, 'Analysis of the asymmetric shelf shuffle'] Let $n,m\geq 1$, let $\pi\sim\nu_{n,m}^{(p)}$, and let $D_n=\des(\pi)$. Put $\dd=2p-1$. Then
\begin{equation}

\E[D_n]
=
\frac{n-1}{2}
+
\dd\left(
 m-\frac{n+1}{2}
 -\frac{n+1}{m^n}S_n(m)
\right).
\end{equation}
Moreover,
\begin{align}

\E[D_n(D_n+1)]
&=
\frac{n(n+1)}{4}-\frac{m}{2}
+\frac{(n+1)mS_n(m)-(n+2)S_{n+1}(m)}{m^n} \notag\\
&
+\dd\left(
 nm-\frac{n(n+1)}{2}
 -\frac{n(n+1)}{m^n}S_n(m)
\right) \notag\\
&
+\dd^2\left(
 m^2-\left(n+\frac12\right)m+\frac{n(n+1)}{4}\right. \notag\\
&\qquad\left.
 +\frac{(n^2-1)mS_n(m)-n(n+2)S_{n+1}(m)}{m^n}
\right).
\end{align}

[Proposition prop:collision-eigenfunction of arXiv:2605.16244, 'Analysis of a twisted Bose--Einstein Markov chain with applications to sampling Catalan st'] Assume $n,k\ge2$. 
Let $K$ and $\pi$ be the transition kernel and stationary distribution of the twisted Bose--Einstein Markov chain on $[k]^n$. 
Then
\begin{equation}
 K F_{r,s}=\rho F_{r,s},
\end{equation}
and, for every $x\in[k]^n$ and $t\ge0$,
\begin{equation}
 \mathbb P_x(X_t(r)=X_t(s))
 =c+\rho^tF_{r,s}(x).
\end{equation}
Moreover,
\[
 \pi(x_r=x_s)=c,
\]
and
\begin{equation}
 \left\|K^t(x,\cdot)-\pi\right\|_{\mathrm{TV}}
 \ge
 \rho^t
 \left|H_{r,s}(x)-c\right|.
\end{equation}
If $x_{\mathrm{const}}$ is any constant word, then
\begin{equation}
 \left\|K^t(x_{\mathrm{const}},\cdot)-\pi\right\|_{\mathrm{TV}}
 \ge
 \frac{\theta(k-1)}{k\theta+1}\rho^t.
\end{equation}
Consequently,
\begin{equation}
 d(t)
 \ge
 \frac{\max\{\theta+1,\theta(k-1)\}}
 {k\theta+1}\rho^t.
\end{equation}
For the lumped chain,
\begin{equation}
 \overline K(J-c)=\rho(J-c),
\end{equation}
and
\begin{equation}
 \overline d(t)
 \ge
 \frac{\theta(k-1)}{k\theta+1}\rho^t.
\end{equation}

[Proposition 142 of arXiv:2601.16377, '2601.16377'] Consider a discrete ensemble satisfying Assumptions~\ref{Assumptions_Theta}, \ref{Assumptions_basic}, \ref{Assumptions_offcrit}, \ref{Assumptions_analyticity} and the additional Assumption~\ref{Assumptions_extra}. For any tuple of compact sets $\amsmathbb{K}_h\subset \amsmathbb C\setminus \amsmathbb{A}_h^{\mathfrak{m}}$ indexed by $h \in [H]$, there exists a $\N$-independent sequence of positive constants $(C_n)_{n \geq 1}$ depending on these compacts and the constants in the assumptions, such that, for any $n \in \amsmathbb{Z}_{> 0}$, $h_1,\ldots,h_n \in [H]$ and $(z_1,\ldots,z_n) \in \prod_{i = 1}^{n} \amsmathbb{K}_{h_i}$ we have
\begin{equation}

 \E\Bigg[\bigg| \prod_{i=1}^n \Delta G_{h_i}(z_i) \bigg|\Bigg] \leq C_n.
