[Lemma 131 (Double-null differential operator pointwise estimates) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] The following estimates hold on $\characteristicdiamondtwoarg{[\leftubar,\ubarboot)}{[\moreinterestingu_1,\moreinterestingu_2]}$. 
	For $\muX$ and any scalar function $\varphi$, we have:
		\begin{align}
			|\muX \varphi| & \le |\newuL \varphi| + C \upmu |L \varphi| + C \auxbootsmall \upmu |\angrmd \varphi|_{\gtorus}. 
		\end{align}
	For any scalar function, $\varphi$, let $\angrmd \varphi$ be the $\ell_{t,u}$-tangent one-form from \eqref{E:ANGULARDIFFERENTIAL} and let $\nullangrmD \varphi$ be the $\doublenulltoritwoarg{\ubar}{u}$-tangent one-form given by Def.\,\ref{D:DOUBLENULLORTHOGONALPROJECTIONANDTANGENCY}. Then we have: 
		\begin{subequations}
			\begin{align}
				|\angrmd \varphi |_{\gtorus} & \le (1 + \mathcal{O}(\auxbootsmall)) |\nullangrmD \varphi |_{\gnulltori} + \mathcal{O}(\auxbootsmall)|L\varphi|,   \\
				|\nullangrmD \varphi |_{\gnulltori} & \le (1 + \mathcal{O}(\auxbootsmall))|\angrmd \varphi |_{\gtorus} + \mathcal{O}(\auxbootsmall)|L\varphi| 
			\end{align} 
		\end{subequations}

	In addition, we have the following for $A = 2,3$:
		\begin{align} 
			\left|\nullgeop{x^A} \varphi\right| \le \left(1 + \mathcal{O}(\mr \upalpha^{1/2}) + \mathcal{O}(\auxbootsmall)\right) \left|\nullangrmD \varphi \right|_{\gnulltori}.
		\end{align}

	Moreover, for an arbitrary string of commutator vectorfields, we have the following two estimates for $\comdersmall^{[1,N+1];1} \varphi$:
		\begin{subequations}
			\begin{align}
				\begin{split}
					\left|\comdersmall^{[1,N+1];1} \varphi\right|  & \lesssim \left|\muX \tander^{[1,N]} \varphi\right| + \left|\tander^{[1,N]} \varphi\right| + \auxbootsmall \left|\comdersmall^{[1,N];1} \controlvars \right| + \auxbootsmall \left| \tandersmall^{[1,N]} \badcontrolvars \right|.
				\end{split} \\
				\begin{split}  
					\left|\comdersmall^{[1,N+1];1} \varphi \right| &  \lesssim \left|\newuL \tander^{[1,N]} \varphi \right| + \upmu \left| \nullangrmD \tander^{[1,N]} \varphi \right|_{\gnulltori}  + \upmu \left| \tander^{[1,N+1]} \varphi \right|  \\
					& \ \ + \left|\tander^{[1,N]}\varphi \right| + \auxbootsmall \left|\comdersmall^{[1,N];1} \controlvars \right| + \auxbootsmall \left| \tandersmall^{[1,N]} \badcontrolvars \right|,
				\end{split} 
		\end{align}
	\end{subequations}

[Prop PropConsistency of arXiv:2605.06429, '\large \bf $\mathsf{GL}_N(\mathbb{C})$ BROWNIAN MOTION AND STOCHASTIC PDE ON ENTIRE FUNCTI'] Let $\theta \in \mathbb{R}$. Then, we have the intertwining,
\begin{equation}
\mathsf{P}_{t;N+1}\boldsymbol{\Lambda}_N^{N+1}=\boldsymbol{\Lambda}_N^{N+1}\mathsf{P}_{t;N}, \ \forall t \ge 0, \ \forall N \in \mathbb{N}.
\end{equation}

[Lemma lem:drift-heat of arXiv:2608.20537, 'Persistent anisotropy in multi-dimensional\\ branching Brownian motion'] Let $v(s, y; t)$ solve 
  \begin{equation*}
    \begin{cases}
      \partial_s v + \partial_y^2  v + \dot{g} \partial_y  v = 0, & s \in (1,t), y > 0,\\
      v(s = t, y) = y,\\
      v(s,0) = 0.
    \end{cases}
  \end{equation*}
  Then there exists $\underline{s}(d) > 0$ such that 
  \begin{equation}

    y \leq v(s, y; t) \leq 2y \quad \text{for all } s \in [\underline{s}, t], y \geq 0.
  \end{equation}

