[Lemma lem:pretil of arXiv:2609.00889, 'Dominant-Degree Conditions for Ramsey--Tur\'an Factors of Non-Directed Cycle Orientations'] The digraph $D$ has a $\widetilde C$-tiling $\mathcal F_E$ satisfying
\begin{enumerate}[label=\rm(\roman*)]
\item every copy in $\mathcal F_E$ contains exactly one vertex of $E_{\rm bad}$ and $E_{\rm bad}\subseteq V(\mathcal F_E)$;
\item $|V(\mathcal F_E)|=\ell|E_{\rm bad}|\le2\ell\varepsilon n\le\sqrt\varepsilon n$;
\item {for every $i\in[k]$, $|V(\mathcal F_E)\cap V_i|\le 3\sqrt\varepsilon\,m$ for sufficiently large $n$.}
\end{enumerate}

[Lem finite-direc-one-side-speed of arXiv:2609.00110, 'Phase Transition and Fluctuation Results for First-Passage Percolation on Spread-Out Cycle'] Let
\begin{align*}
 \mathsf{M}_t^{(\ell),+}
 :=
 \max\left\{
 \mathsf{p}_\ell(v):
 v\in\mathcal{N}_t^{(\ell)},\
 \mathsf{p}_\ell(v|_j)\geqslant0 \text{ for all }0\leqslant j\leqslant |v|
 \right\}.
\end{align*}
If $h_\ell\to\infty$ and $h_\ell=o(\log\ell)$, then, for every $\varepsilon>0$,
\begin{align*}
 \pr\left(
 \mathsf{M}_{(1/\mathsf{v}^\star+\varepsilon)h_\ell}^{(\ell),+}\geqslant h_\ell
 \right)
 \to 1.
\end{align*}
Moreover, the hitting particle may be chosen as the first particle on its ancestral line entering
$[h_\ell,h_\ell+1]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

