[Lem resampling_is_positive of arXiv:2604.14122, 'The scaling limit of random walk and\\ the intrinsic metric on planar critical percolation'] There exists a constant $g=g(p',R,M_0,c,\xi)>0$ such that for all percolation configurations $\omega$ on $B(x,n^{-1}R^{\kappa-f+1})$
\begin{equation}
    \mathbf{P}(E_\textrm{res} \, | \, \omega)\cdot \mathbf{1}_F(\omega)\geq g \cdot \mathbf{1}_F(\omega),
\end{equation}
whenever $\xi cR^{-f}n\geq R.$

[Lemma 16 of arXiv:2608.17509, '2608.17509'] Let \(a>1\). The limiting log-moment generating function \(\Lambda_a\) belongs to \(C^\infty(\mathbb{R})\), with
\[
\Lambda_a'(\theta)
=
\frac{1}{2\pi}
\int_0^{\infty}
\frac{e^{\theta}r_a(\xi)}
{1+(e^{\theta}-1)r_a(\xi)}
\,\mathrm{d}\xi,
\]
\[
\Lambda_a''(\theta)
=
\frac{1}{2\pi}
\int_0^{\infty}
\frac{e^{\theta}r_a(\xi)(1-r_a(\xi))}
{\left(1+(e^{\theta}-1)r_a(\xi)\right)^2}
\,\mathrm{d}\xi .
\]
Moreover, \(\Lambda_a\) is strictly increasing and strictly convex on \(\mathbb{R}\), and
\begin{equation}

\lim_{\theta\to-\infty}\Lambda_a'(\theta)=0,
\qquad
\lim_{\theta\to+\infty}\Lambda_a'(\theta)=+\infty.
\end{equation}
Consequently, the Legendre--Fenchel transform 
\(
\widetilde{J}_a(x):=\sup_{\theta\in\mathbb{R}}\{\theta x-\Lambda_a(\theta)\}
\)
is finite precisely on \([0,\infty)\), and \(J_a:=\widetilde{J}_a|_{[0,\infty)}\) is a good rate function on \([0,\infty)\).

[Proposition prop:bridge_subg_tail of arXiv:2512.17747, 'On exponentially height-penalized random trees'] Let $(B^{(n),x}_t;0\leq t \leq n)$ be a \textcolor{green!50!black}{uniform bridge} of length $n$ ending at $x$, and for fixed $C>0$, define the functional
    \begin{align*}
        Y_n(C,x):=L_{n}(B^{(n),x})\ind{-C\sqrt{n}\leq B^{(n),x}_t \leq C \sqrt{n}\;\forall\;t\in[0,n]}.
    \end{align*}
    Then uniformly over $x \in [-C\sqrt{n},C\sqrt{n}]$, for all sufficiently large $T>0$, we have
    \begin{align*}
        \Prob{\frac{Y_n(C,x)}{\sqrt{n}}>T}\leq R_1\exp{(-R_2T^2)},
    \end{align*}
    where $R_1,R_2>0$ are constants depending only on $C$.

