Let us write 
\begin{align} 
    \Prob{Y_n(C,x)>T\sqrt{n}}&=\Prob{L_n(B^{(n),x})>T\sqrt{n},-C\sqrt{n}\leq B^{(n),x}_t \leq C \sqrt{n}\;\forall\;t\in[0,n]}\\
    &\leq \Prob{L_n(B^{(n),x})>T\sqrt{n}} \, .
