[Prop continuity of arXiv:2605.11785, 'Regularization of a mean-field SDE by an additive common noise: the conditional expectatio'] For any $\epsilon\in (0,\frac 12)$, there exists a constant $C_\epsilon>0$, depending on $\epsilon$, $\sigma^0$, $b$ and $T$ only, such that, for any $M>0$ and any $\mu_0, \widehat \mu_0\in \mathcal P_1(\mathbb{R}^d)$, 
\begin{equation}
d_{\rm B_ML}(P^{\mu_0},P^{\widehat\mu_0})\leq C_\epsilon \left(W_1(\mu_0,\widehat \mu_0)^{1/2}+ W_1(\mu_0,\widehat \mu_0)^{1/2-\epsilon}\right) (W_1(\mu_0,\widehat \mu_0)^{1/2} +M).
\end{equation}  
More generally, if we  denote (with a slight abuse of notation) by $P^{\mu_0}(d\bm{x}|\bm{x}^0)$ the conditional distribution of the $X$ component given that $X^0=\bm{x} ^0$ under $P^{\mu_0}$, then, for all $M>0$ and for all $\mu_0, \widehat \mu_0\in \mathcal P_1(\mathbb{R}^d)$,
\begin{align}
& d_{{\rm B}_M{\rm L}}\left(Q^{\mu_0}(d\bm{x}^0)\prod_{i=1}^kP^{\mu_0}(d\bm{x}^i|\bm{x}^0),Q^{\widehat\mu_0}(d\bm{x}^0)\prod_{i=1}^kP^{\widehat\mu_0}(d\bm{x}^i|\bm{x}^0)\right) \notag\\
& \qquad\qquad\qquad\qquad  \leq C_\epsilon \left(W_1(\mu_0,\widehat \mu_0)^{1/2}+ W_1(\mu_0,\widehat \mu_0)^{1/2-\epsilon}\right)  \left(k W_1(\mu_0,\widehat \mu_0)^{1/2}+ M\right).
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 5 (Finite 2D $\rho$-variation) of arXiv:2512.04646, '\textbf{Canonical Rough Path over Tempered Fractional Brownian Motion: Existence, Construc'] Let $H > 1/4$ and $\rho = 1/(2H)$. Then
\begin{equation}

V_\rho(R_{H,\lambda})
\le C(H,\lambda,T)
:= V_\rho(R_H)
  + K_1(H)\,\lambda^{2H\rho}\,T^{2\rho-2}
  + \frac{K_2(H,\lambda)}{\lambda^{2H\rho}}
< \infty,
\end{equation}
where $K_1(H)$ and $K_2(H,\lambda)$ are explicit constants, and
$C(H,\lambda,T) \to C_{\rm fBm}(H,T)$ as $\lambda \to 0^+$.

[Lem 22 of arXiv:2604.06122, 'REM universality for linear random energy'] We have
\been{

\lim_{n\to \infty}\res A^{-}_n(h)=\lim_{n\to \infty}\res A^{+}_n(h)=\lim_{n\to \infty}\res \( A^{-}_n(h)+x\)=\lim_{n\to \infty}\res \( A^{+}_n(h)+x\)=\hat{a}(c),\quad \gas ,
}
for any fixed $x\in \R$.

Moreover, given any $N> N_{\e}$, for $\Gae$ $h\in \bar{\mathfrak{L}}^{\e}_N$ and any fixed $x\in \bar{\mathfrak{R}}_{N,\lambda^*}(h)$, 
\been{

\lim_{n\to \infty}\res \tilde A_n(h)=\hat{a}(c),\qquad \lim_{n\to \infty}\tilde \Lambda_n(h)=\lim_{n\to \infty}\tilde \Lambda^{x}_n(h)=\hat{\lambda}(\hat{a}(c)).
}

