[Lemma lem:expDumbbell of arXiv:2411.07157, 'Rough differential equations in the flow approach'] For $\text{${\boldsymbol{\tau}}$}=\big((\raisebox{-0.5ex}{\includegraphics[scale=1.2]{figures/XiX.pdf}},0,u)\big)$ and $c>0$ small enough, uniformly in ${\eps,\mu}\in(0,1]$, we have
   \begin{equs}   \nnorm{\text{{\Large $\kappa$}}_{\eps,\mu}^{{\boldsymbol{\tau}}}}_{2}\lesssim \eps^{u({\boldsymbol{\tau}})(-1+c)}\mu^{|{\boldsymbol{\tau}}|-u({\boldsymbol{\tau}})c-r({\boldsymbol{\tau}})}\,.
    \end{equs}

