[Lemma 4 (\citeauthor{F10}, \citeyear{F10}, Eq.~(5.101)) of arXiv:2606.06739, 'The relationship between the transition functions of the labeled and unlabeled versions of'] For $\bm m=(m_1,\ldots,m_k)$ with $m_1\ge\cdots\ge m_k\ge1$, $\bm n=(n_1,\ldots,n_l)$ with $n_1\ge\cdots\ge n_l\ge1$, $k,l\in{\bf N}$, $m=|\bm m|$, and $n=|\bm n|$,
\begin{align}
\frac{\int_{\overline{\nabla}_\infty}P_{\bm m}P_{\bm n}\,d\text{PD}_\theta}{\int_{\overline{\nabla}_\infty}P_{\bm n}\,d\text{PD}_\theta}
&=C(\bm m)\sum_{r=0}^{k\wedge l}\bigg[\sum_{\substack{I\subset\{1,\ldots,k\}:\\ |I|=r}}\;\sum_{\substack{\gamma:I\mapsto\{1,\ldots,l\}\\ \text{\rm one-to-one}}}\nonumber\\
&\quad\;{}\dfrac{\prod_{i\in I}(m_i+n_{\gamma(i)}-1)!\,\prod_{i\in I^c}(m_i-1)!}{\prod_{i\in I}(n_{\gamma(i)}-1)!}\bigg]\frac{\theta^{k-r}}{(n+\theta)_{(m)}},
\end{align}
where $I^c:=\{1,\ldots,k\}-I$.

