body:
[Lemma 6 (Stationary moment identities) of arXiv:2607.20823, 'Fluctuation impossibility results for stochastic burst networks'] For every $i\in\{1,\dots,N\}$,
\begin{equation}
        \frac{\E_\pi[X_i]}{\tau_i}
        =
        \kappa_i\mu_i
        =
        \kappa_i\E_\pi[f_i(X_{-i})].

\end{equation}
Moreover, defining
\begin{equation}
        B_i
        :=
        \frac{\E[K_i^2]+\E[K_i]}{2\E[K_i]}
        =
        \frac{\E[K_i^2]+\kappa_i}{2\kappa_i},

\end{equation}
we have
\begin{equation}
        F_{X_i}-B_i
        =
        \frac{\Cov_\pi(f_i(X_{-i}),X_i)}{\mu_i}.

\end{equation}

[Theorem 19 of arXiv:2608.19065, 'Boundedly exchangeable graphs'] Let $\xi$ be a boundedly exchangeable graph process on $S$ directed by $\nu$. For every $B \in \widehat{\Bcal}(S)$ where $\pbb(\nu(B) = 0) < 1$ there exists an infinite jointly exchangeable matrix $A^B \in \rbb^{\nbb \times \nbb}$ such that the adjacency matrix $(A, N)$ of any i.i.d.\ representation of $\xi\vert_B$ satisfies for all $n \geq 1$:
    \begin{equation} 
        A \mid (N = n) \overset{d}{=} A^B[n]
    \end{equation}
    Moreover, the distribution of $A^B$ is unique.

[Lemma 19 (Hodge a priori estimates: null-form rhs) of arXiv:2609.01093, 'Ideal MHD below the classical well-posedness threshold'] Let $\Ufield,\Vfield$ be as above, recall $\sigma=s-1>(n-1)/2$, and let
$F[\Ufield]$ be the canonical Hodge representative \eqref{eq:FU}.  Then $F[\Ufield]\in C(I;L^4)$, with
\begin{equation}
 \|F[\Ufield]\|_{L^\infty(I;L^4)}\le C_\delta R^2 ,
\end{equation}
and, for every $\rpar\in[0,1]$ such that
$\Ufield\in H^{\sigma,1+\rpar}_{\breg}$,
\begin{equation}
 \|dF[\Ufield]\|_{L^2(I;Y^{\sigma,\rpar})}
 \le C_{\delta,\rpar} 
 \|\Ufield\|_{H^{\sigma,1}_{\breg}} 
 \|\Ufield\|_{H^{\sigma,1+\rpar}_{\breg}} .
\end{equation}
In particular at $\rpar=0$,
\begin{equation}
 \|dF[\Ufield]\|_{L^2(I;H^\sigma)}\le C_\delta R^2 .
\end{equation}
Finally,
\begin{equation}
 \|dF[\Ufield]-dF[\Vfield]\|_{L^2(I;H^\sigma)}
 \le C_\delta R(1+R) D .
\end{equation}

[Definition 1 (Tempered fractional Brownian motion
\cite{MeerschaertSabzikar2013}) of arXiv:2512.04646, '\textbf{Canonical Rough Path over Tempered Fractional Brownian Motion: Existence, Construc'] For $H \in (0,1)$ and $\lambda > 0$, the \emph{tempered fractional
Brownian motion} (tfBm)
$B_{H,\lambda} = (B_{H,\lambda}(t))_{t \ge 0}$ is the centred
Gaussian process defined by
\begin{equation}

B_{H,\lambda}(t) = \frac{1}{\Gamma(H+\frac{1}{2})} \int_{\mathbb{R}}
\Bigl[ e^{-\lambda(t-s)_+}(t-s)_+^{H-\frac{1}{2}}
      - e^{-\lambda(-s)_+}(-s)_+^{H-\frac{1}{2}} \Bigr] \, dW(s),
\end{equation}
where $W$ is a standard two-sided Brownian motion and
$x_+ = \max(x,0)$.

[Theorem 3 (Reduction; conditional on Hypothesis~\ref{hyp:red}) of arXiv:2608.15987, 'Threshold cascades of interacting diffusions on unimodular random trees: a conditional bra'] Under Hypothesis~\ref{hyp:red}, the failed cluster of the root converges in distribution (as a random rooted tree) to the family tree of the multitype Galton--Watson process on type set $D$ with mean matrix
\begin{equation}
M_{d,d'}=m_*\,q(d')\,p_{d,d'},\qquad d,d'\in D,
\end{equation}
where $p_{d,d'}$ is the transmission probability \eqref{eq:wald}. In particular the survival probability of the cascade is positive iff $\rho(M)>1$, and zero iff $\rho(M)\le1$, where $\rho(M)$ is the Perron root of the nonnegative matrix $M$.

[Lem setup2 of arXiv:2412.09535, 'Local limit theorem for joint subgraph counts'] Let $H\in \mathcal{H}$ be connected and let $\eps \leq \alpha \leq 1$ be real. We get $\abs{\sete[e^{if}]} = n^{-\omega_{\lambda,\ell,\eps}(1)}$ as long as
\begin{cond}
    \item  $n^{-\alpha+\eps} \leq \Delta_H^2 \leq 1.1\pi^2 (p(1-p))^{e(H)}$;
    \item  For any graph $H' \succ H$, we have $n^{v(H')} \Delta_{H'}^2 < n^{v(H)- \alpha - \eps}$.
\end{cond}

