[Defi $K$-fuzz structure of arXiv:2607.28817, 'Limiting spectral distribution for the adjacency matrix of the Watts--Strogatz random grap'] We need a few definitions to be able to formally introduce the full $K$-fuzz graph model, denoted $F(K,p)$. See Figure~(fig:fullkfuzz of the paper) for an illustration.
    \begin{itemize}
        \item \textbf{Full $K$-path.} A full $K$-path is the infinite rooted graph with vertex set $\mathbb{Z}$ in which each vertex is adjacent to its $K/2$ nearest neighbors on either side.\\
        \item \textbf{Reduced $K$-path.} A reduced $K$-path is a rooted full $K$-path from which one of the $K/2$ edges connecting the root to its rightmost neighbors chosen uniformly at random is removed.\\
        \item \textbf{Full $K$-fuzz and reduced $K$-fuzz.} A full $K$-fuzz is obtained by starting from a full $K$-path and, for each node, independently rewiring each of its rightmost edges with probability $p$. Each rewired edge becomes a shortcut to a new full $K$-fuzz, producing an independent recursive copy. In addition, each node receives $\poisson(\frac{pK}{2})$ incoming shortcuts, each connecting to the root of a reduced $K$-fuzz. The reduced $K$-fuzz is defined analogously but starts from a reduced $K$-path.
    \end{itemize}

[Lemma spacetimeaverageagain of arXiv:2507.10545, 'KPZ equation from a class of nonlinear SPDEs in infinite volume'] \fsp Fix any {\small$\mathfrak{q}_{\n_{2}}$} in (equation eq:qnformI2 of the paper). We have the following (with notation to be explained afterwards):

\begin{align}
N\grad^{\mathbf{X}}_{\mathfrak{l}_{0}}[\mathscr{S}^{N}\star\mathfrak{q}_{\n_{2}}[\tau_{\cdot}\bphi_{\t}]\mathbf{Z}^{N}_{\t,\cdot}]_{\x}&=\sum_{\substack{{m}=0,\ldots,\mathrm{M}\\0<|\mathfrak{l}_{1}|,\ldots,|\mathfrak{l}_{{m}}|\leq\mathfrak{n}_{\mathbf{Av}}}}\tfrac{1}{|\mathfrak{l}_{1}|\ldots|\mathfrak{l}_{{m}}|}\mathrm{b}'_{N,{m},\mathfrak{l}_{1},\ldots,\mathfrak{l}_{{m}}}\grad^{\mathbf{X}}_{\mathfrak{l}_{1}}\ldots\grad^{\mathbf{X}}_{\mathfrak{l}_{{m}}}[\mathscr{S}^{N}\star(\mathbf{Av}^{\mathbf{T},\mathbf{X},\mathfrak{q}_{\n_{2}}}_{\t,\cdot}\cdot\mathbf{R}^{N}_{\t,\cdot}\mathbf{S}^{N}_{\t,\cdot})]_{\x}\\
&+\sum_{\substack{{m}=0,\ldots,\mathrm{M}\\0<|\mathfrak{l}_{1}|,\ldots,|\mathfrak{l}_{{m}}|\leq\mathfrak{n}_{\mathbf{Av}}}}\tfrac{1}{|\mathfrak{l}_{1}|\ldots|\mathfrak{l}_{{m}}|}\mathrm{b}'_{N,{m},\mathfrak{l}_{1},\ldots,\mathfrak{l}_{{m}}}\grad^{\mathbf{T},\mathrm{av}}_{\mathfrak{t}_{\mathbf{Av}}}\grad^{\mathbf{X}}_{\mathfrak{l}_{1}}\ldots\grad^{\mathbf{X}}_{\mathfrak{l}_{{m}}}[\mathscr{S}^{N}\star(\mathbf{Av}^{\mathbf{T},\mathbf{X},\mathfrak{q}_{\n_{2}}}_{\t,\cdot}\cdot\mathbf{R}^{N}_{\t,\cdot}\mathbf{S}^{N}_{\t,\cdot})]_{\x}\\
&+\mathrm{Err}_{2}[\mathbf{R}^{N}_{\t,\cdot}\mathbf{S}^{N}_{\t,\cdot}]_{\x}.
\end{align}

\begin{itemize}
\item The parameter {\small$\mathrm{M}=\mathrm{O}(1)$} is a positive integer.
\item The {\small$\mathrm{b}'_{N,{m},\mathfrak{l}_{1},\ldots,\mathfrak{l}_{{m}}}$} are deterministic and {\small$\mathrm{O}(N)$}. Moreover, {\small$\mathrm{b}'_{N,{m},\mathfrak{l}_{1},\ldots,\mathfrak{l}_{{m}}}=0$} if {\small$\min\{|\mathfrak{l}_{1}|,\ldots,|\mathfrak{l}_{{m}}|\}\geq2$}.
\item The term {\small$\mathrm{Err}_{2}[\mathbf{R}^{N}\mathbf{S}^{N}]_{\t,\x}$} is a linear operator in {\small$\mathbf{S}^{N}$} evaluated at {\small$(\t,\x)$}, and it satisfies the deterministic estimate below as long as {\small$\mathrm{C}=\mathrm{O}(1)$} is sufficiently large:

\begin{align}
|\mathrm{Err}_{2}[\mathbf{R}^{N}_{\t,\cdot}\mathbf{S}^{N}_{\t,\cdot}]_{\x}|\lesssim N^{-\frac32}\cdot N^{-1+\delta_{\mathbf{S}}}\sum_{|\w|\lesssim N^{1-\delta_{\mathbf{S}}}}\Big(1+\sum_{|\z|\lesssim1}|\bphi_{\t,\x+\w+\z}|^{\mathrm{C}}\Big)\cdot|\mathbf{R}^{N}_{\t,\x+\w}|\cdot|\mathbf{S}^{N}_{\t,\x+\w}|.
\end{align}

\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

