[Lemma 18 (TV bound via the shifted construction) of arXiv:2605.24937, '2605.24937'] Assume~\eqref{eq:reg-framework} and~\eqref{eq:tv-local-error}, and let
$d_n^{\,2}:=\E\|\widetilde X_n-Y_n'\|^{2}$. Writing
$\overline C_{\mathrm{TV}}:=\sup_{0\le n<N}\|C_{\mathrm{TV}}(x)\|_{L^2(\widetilde\mu_n)}$,
\begin{equation}
  TV\!\bigl(\widetilde\mu_N,\nu_N\bigr)
  \;\le\;
  \overline C_{\mathrm{TV}}\,\lambda
  +\sqrt{\tfrac{c}{2}}\,d_{N-1}
  +\sqrt{\tfrac{c}{2}\,\sum_{n=0}^{N-2}\eta_n^{2}\,d_n^{\,2}}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:surface_tension of arXiv:2506.12171, 'The multinomial dimer model'] The \textit{surface tension} $\sigma: \mathcal{N}(\Lambda)\to \mathbb{R}_+$ is given by
    \begin{equation}
    \sigma(s) := -\lim_{n\to \infty} \lim_{N\to \infty} \frac{1}{N n^d} \log \frac{Z_{n,N}^s}{(N!)^{n^d}}.
\end{equation}
It is straightforward to check that $\log (Z_{n,N}^s/(N!)^{n^d})$ forms as subadditive sequence in $n,N$, so $\sigma(s)$ exists for any fixed $s\in \mathcal{N}(\Lambda)$.

[Thm 17 of arXiv:2609.00598, 'Supercritical mean--field limit for magnetized Hamiltonian dynamics'] Let the assumptions of {\rm Theorem \ref{main thm renormalized}} hold, 
and let $\mathcal{E}_{\varepsilon,N}(t)$ be given by \eqref{magnetized renormalized modulated energy}. Then, for all $t\in \mathbb{R}_{+}$, 
\begin{align}
\frac{\dd}{\dd t}\mathcal{E}_{\varepsilon,N}(t)=& -\frac{1}{N}\sum_{i=1}^{N}\big(v(t,x_i(t))-\xi_i(t)\big)^{\otimes2}:D_xv(t,x_i(t))
\notag\\
&+\frac{1}{2\varepsilon}\iint_{\Delta^{c}}(v(t,x)-v(t,y))\cdot \nabla_{x} V(x-y)\left(\rho_{\varepsilon,N}-1-\varepsilon \mathfrak{U}\right)^{\otimes 2}(t,\dd x\dd y) \notag \notag\\
&-\int_{\mathbb{T}^{2}} \mathrm{div}_{x} (-\Delta_{x})^{-1}(v\mathfrak{U})(t,x)\left(\rho_{\varepsilon,N}-1-\varepsilon\mathfrak{U}\right)(t,\dd x) \notag\\
&-\int_{\mathbb{T}^{2}}\partial_{t}p(t,x)\left(\rho_{\varepsilon,N}-1-\varepsilon\mathfrak{U}\right)(t,\dd x).  
\end{align}
Consequently, it follows that 
\begin{align*}
\underset{t\in [0,T]}{\sup}\mathcal{E}_{\varepsilon,N}(t)\underset{N\rightarrow \infty}{\longrightarrow}0\ \qquad 
\mbox{provided}\ \mathcal{E}_{\varepsilon,N}(0)\underset{N\rightarrow \infty}{\longrightarrow}0\ \mbox{and}\ \frac{\log N}{\varepsilon N}\underset{N\rightarrow \infty}{\longrightarrow} 0.  \end{align*}

[Proposition prop:martingale_control of arXiv:2602.00988, 'Wealth exchange under ceiling and flooring constraints: a modified Bennati–Dragulescu–Yako'] Let $M(t)$ (equation eq:M of the paper) be the compensated process of the empirical measure ${\bf p}_{\mathrm{emp}}(t)$. There exists some universal constant $C > 0 $ such that
\begin{equation}
\mathbb{E}\left[\|M(t)\|_{\ell^1}\right] \leq \frac{C\,t\,\sqrt{\log N}}{\sqrt{N}}~~\text{for all $t\geq 0$.}
\end{equation}

