body:
[Theorem thm:mp-mbi of arXiv:2411.09516, 'Sharp Matrix Empirical Bernstein Inequalities\footnote{NeurIPS 2025 Poster}'] Let $n \geqslant 2$ be even and $ \mathbf{X} _1,\dots,  \mathbf{X} _n$ be $\mathcal{S}_d^{[0,1]}$-valued independent random matrices with common mean $ \mathbf{M} $ and variance $ \mathbf{V} $. We denote by $\overline{ \mathbf{X} }_n$ their sample average and by $    \mathbf{V} ^*_n$ their paired variance estimator defined in (equation eqn:paired of the paper).
    Then, for any $\alpha \in (0,1)$,
    \begin{equation} 
     \mathbb P \left( \lambda_{\max} \left( \overline \mathbf{X} _n - \mathbf{M}  \right) \geqslant   D_n^{\mathsf{meb1}} \right) \leqslant \alpha,
\end{equation}
where
\begin{equation}
    D_n^{\mathsf{meb1}} = \frac{ \log\frac{nd}{(n-1)\alpha}   }{3n} + \sqrt{  \frac{2  \|  \mathbf{V} ^*_n \| \log\frac{nd}{(n-1)\alpha}  }{n}} + \left( \sqrt{\frac{5}{3}} + 1 \right) \frac{\sqrt{\left(\log\frac{nd}{(n-1)\alpha}\right)\left( \log \frac{2nd}{\alpha}\right) } }{n}.
\end{equation}
Further, if $ \mathbf{X} _1,\dots,  \mathbf{X} _n$ are i.i.d.,
\begin{equation}
    \lim_{n\to\infty} \sqrt{n}   D_n^{\mathsf{meb1}} = \sqrt{2\log(d/\alpha) \| \mathbf{V} \| }, \quad \text{almost surely}.
\end{equation}

