[Definition 22 (Prediction Variance~\citep{hamman2024quantifying,watson2023predictive}) of arXiv:2609.01397, 'Measuring consistency via ensemble margin and local prediction variability: Auditing decis'] The prediction variance of $\emprashomonset$ is the variance of model outputs for a given test instance $x$, and is defined as
    \begin{align}
        \predvar(x) = \frac{1}{\abs{\emprashomonset}}\sum_{f_k \in  \emprashomonset}(f_{k}(x) - \frac{1}{\abs{\emprashomonset}}\sum_{f_k \in  \emprashomonset}f_{k}(x))^{2}.
    \end{align}

[Defn eq:rip of arXiv:2608.29018, 'Sharp Restricted Isometry Thresholds for\\ Global Minima of Rank-Restricted Matrix LASSO'] For $\delta\ge0$ and an integer $k\ge1$, we write $\mathcal{A}\in\operatorname{RIP}(\delta,k)$
if 
\begin{equation}
(1-\delta)\normF E^{2}\le\normtwo{\mathcal{A}(E)}^{2}\le(1+\delta)\normF E^{2}
\end{equation}
holds for every $E$ with $\operatorname{rank}(E)\le k$.

[Lemma 34 of arXiv:2606.16164, 'A Low-Regularity Semigroup Sewing Lemma via Quotient Structures'] For every dyadic parent interval $[a,c]$ with midpoint $b$, the residuals produced by the dyadic recursion satisfy
\begin{equation}

R^{\mathsf s}_{ca}=R^{\mathsf s}_{cb}+S_{c-b}R^{\mathsf s}_{ba}+H_{cba}.
\end{equation}
Consequently, $\hdd R^{\mathsf s}=H$ on dyadic triples.

[Proposition 13 of arXiv:2604.24392, 'Numerical approximation of Markovian BSDEs in infinite horizon and elliptic PDEs'] Let us assume that $X^x=x+W$ and let us consider $\meas(dx)=\frac{c}{(1+|x|)^{pr+d+1}}\dx$ where $c$ is such that $\meas$ is a density measure on $\bR^d$.
  Then \eqref{eq:condition:stability:rho} is satisfied for
  \begin{align*}
  c_{p,\eqref{eq:condition:stability:rho}}^p &:= \int_0^{+\infty} (t\vee 1)^{\frac{pr+d+1}{2}} \theta e^{-\theta t} \dt \int_{\bR^{d}} \left( 1+|y| \right)^{pr+d+1} \frac{1}{(2\pi)^{d/2}}e^{-\frac{|y|^2}{2}}  \dy<+\infty,\\
  \tilde{c}_{p,\eqref{eq:condition:stability:rho}}^p &:= \int_0^{+\infty} \frac{(t\vee 1)^{\frac{pr+d+1}{2}}}{\sqrt{t}} \frac{\sqrt{\ttheta}}{\sqrt{\pi}} e^{-\ttheta t} \dt \int_{\bR^{d}} \left( 1+|y| \right)^{pr+d+1} \frac{1}{(2\pi)^{d/2}}e^{-\frac{|y|^2}{2}}  \dy<+\infty.
  \end{align*}

