body:
[Proposition 9 (Non-collapsing) of arXiv:2609.01098, 'Gaussian upper bounds for averaged heat semigroups on graphs'] Let $x\in X$,  $R \ge 4R_1{\ge 4S}$, 
$n>2$ and $C>0$ constants. Assume  that for all $f\in \cC_{c}(B_x(R))$ we have 
\[
\Vert f\Vert_{\frac{2n}{n-2}}^2\leq C\left(\cE(f)+\frac{1}{R^2}\Vert f\Vert_2^2\right).
\]
Then we have for all {$r\in[2S,R]$}
{
\[
 2^{-{3}n^2}\left(\frac{1}{ C}\right)^{\frac{n}{2}}
\left[1\wedge C^{\frac{n}{2}}\frac{m(B_x(R_1))}{r^{n}}\right]^{2^{2}\sqrt[n]{{S}/{r}}}
\leq \frac{m(B_x(r))}{r^{n}}.
\]}

[Proposition 17 (Finite-horizon stability and modulus) of arXiv:2608.30261, 'Estimating Population-Risk Curves Along Nonconvex Gradient Flows from the Training Sample'] \label[proposition]{prop:gf-stability}
Under the neighboring-flow conditions in
\cref{app:gf-neighboring-flow-conditions},
\begin{equation}
 \beta_N\leq\frac{2K_{\rm ev}G_{\rm tr}}{N}\mathfrak A_{N,T}.
\end{equation}
If, in addition,
$\overline H_{\mathsf s_N,\mathsf s_N',\lambda}(t)
\succeq\underline\mu I$ for a deterministic
$\underline\mu\in\mathbb R$, uniformly over neighboring
$\mathsf s_N,\mathsf s_N'\in\mathsf Z^N$, $\lambda\in\Lambda$, and
$t\in[0,T]$, then
\begin{equation}
 \mathfrak A_{N,T}\leq\int_0^T e^{-\underline\mu s}\,\dd s.
\end{equation}
Under the candidate-index conditions in
\cref{app:gf-candidate-index-conditions}, the hyperparameter-Lipschitz
constant satisfies
\begin{equation}
 L_N^{\rm hyp}\leq C_{{\rm mod},T}.
\end{equation}
When $N=n-1$, the modulus condition \eqref{eq:hyper-modulus} holds with
\begin{equation}
 \omega_{n-1}(r)=C_{{\rm mod},T}r,
 \qquad r\geq0.
\end{equation}

[Lemma lemma-joint-convergence of arXiv:2606.13147, 'Scaling limits of the single-curve interface and outermost loops in the planar random fiel'] $(W_{\delta}^{h}, \tilde{\mathcal{Z}}_{\delta}^{\pm,\lambda,h}, \theta_L(\delta)S_{L}^{h}(\delta), \theta_{R}(\delta)S_{R}^{h}(\delta))_{\delta}$ under ${\mathbb{P}} \otimes \mu_{\delta}^{\pm}$ jointly converge in finite dimensional distribution to $(W,\mathcal{Z}_{D}^{\pm,W,\lambda},S_{L}^{W}, S_{R}^{W})$ under ${\mathbb{P}} \otimes \nu_{\operatorname{SLE}_{3}}^{(D,a,b)}$. Here, $W$ is a two-dimensional white noise, $\mathcal{Z}_{D}^{\pm,W,\lambda}$ is the limiting partition function of Theorem (theorem-cvg-RFIM-partition-function of the paper) and $S_{L}^{W}$ and $S_{R}^{W}$ are defined as
        \begin{align*}
            &S_{L}^{W}:= \sum_{k \geq 0} \frac{C_{\sigma}^k}{k!} \int_{D_{L}^k} f_{D_{L}}^{(+,k)}(z_1,\dots,z_k) \prod_{n=1}^{k} \lambda(z_j)W(dz_j), \\
            &S_{R}^{W}:= \sum_{k \geq 0} \frac{C_{\sigma}^k}{k!} \int_{D_{R}^k} f_{D_{R}}^{(-,k)}(z_1,\dots,z_k) \prod_{n=1}^{k}\lambda(z_j) W(dz_j).
        \end{align*}
        Above, $D_{L}$, respectively $D_{R}$, is the connected component on the left, respectively right, of $\gamma$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 39 ({\cite[Definition 6.2) of arXiv:2604.26549, 'Existence and uniqueness results of a stochastic nonlinear heat equation with a constraint'] {ZB+GD-21}}]
				Let $(\Omega^i,\Fn^i,\Fb^i,\Pr^i,W^i,u^i),$ for $ i=1, 2$ be the martingale solutions of the problem \eqref{eqn-main-prob-Ito} with $u^i(0) =u_0$, $i=1, 2$. Then, we say that the solutions are \emph{unique in law} if
				\begin{equation*}
					\bL_{\Pr_1}(u^1)=\bL_{\Pr_2}(u^2) \ \text{ on }\  C([0,T];\Vp)\cap L^2(0,T;D(A))\cap L^{2p-2}(0,T;L^{2p-2}(\bO)),
				\end{equation*}
				where $\bL_{\Pr_i}(u^i),$ $ i=1, 2$ represents the law of the random variable $u_i$ which takes values in $C([0,T];\Vp)\cap L^2(0,T;D(A))\cap L^{2p-2}(0,T;L^{2p-2}(\bO))$.

[Lemma {Implementation of~\ref{eq:rm-ulmc}} of arXiv:2506.23062, 'Shifted Composition IV\@: \\ Toward Ballistic Acceleration for Log-Concave Sampling'] Let $0 \leqslant s\leqslant t \leqslant h$. Consider the random variables defined in~(equation eq:rmulmc-brownian of the paper). Then,
    \begin{align*}
        \var(\xi_{nh, h}^{(2)}) &= (1-e^{-2\gamma h})\,I\,, \\
        \cov(\xi_{nh, s}^{(1)},\, \xi_{nh, t}^{(1)}) &= \frac{2}{\gamma}\,\Bigl(s - \frac{1-e^{-\gamma s} +e^{-\gamma (t-s)} - e^{-\gamma t}}{\gamma} + \frac{e^{-\gamma(t-s)} - e^{-\gamma(t+s)}}{2\gamma} \Bigr) \,I\,, \\[0.25em]
        \cov(\xi_{nh, t}^{(1)},\, \xi_{nh, h}^{(2)}) &= \frac{1}{\gamma}\, (e^{-\gamma (h-t)} - 2e^{-\gamma h} + e^{-\gamma(h+t)})\, I \,.
    \end{align*}

[Lem 14 of arXiv:2608.05185, '\large\bf ON THE HEAT FLOW CONJECTURE FOR RANDOM MATRICES'] For \(z\in\C\) and \(0\leq\ell\leq1\),
\begin{equation}
 \sum_{k=0}^{\infty}\ell^k\frac{N^k}{k!}
 \left|h_{k,c,N}(z)\right|^2
 =
 \frac{1}{\sqrt{1-\left|c\right|^2\ell^2}}
 \exp\!\left[
 N\ell\,
 \frac{\left|z\right|^2
       -\ell\Re(\overline{c}z^2)}
      {1-\left|c\right|^2\ell^2}
 \right],
 \qquad 0\leq\ell\leq1.
\end{equation}

[Lemma Lemma many to one of arXiv:2608.23202, 'Locally finite Fixed points of Branching Brownian Motion'] Let $F: \mathbb R \to \mathbb R$ be a bounded measurable function. Then, 
    \begin{equation}
        \mathbb E[\sum_{k \le n(t)} F(\chi_k(t))]=e^t \mathbb E[F(B_t)],
    \end{equation}
    where $B$ is a standard one dimensional Brownian motion. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 8 (Charge completion and combinatorial cancellation) of arXiv:2605.31374, 'Multi-point functions of a full-plane two-state\\ fuzzy $4$-Potts model'] Let $n\in 2\N$. If $\pa\notin\mathfrak{P}_+$ (see~\eqref{e.frakP_+=}), then
\begin{align}
    \sum_{\tau\in 4\Z\cap[-n,n]}\ \sum_{\xi\in\Xi_\tau}a(\xi,\pa)=0.
\end{align}

