where $\nullangpartial_\alpha \eqdef \nulltorusproject \cdot \partial_\alpha$.\footnote{Note that $\nullangpartial_{A} = \nullgeop{x^A}$ for $A = 2,3$.}

[Prop correlation of arXiv:2606.08325, 'Digit Mixing under Polynomial Maps'] Let \(M>0\). If the exponent $\Gamma$ in (equation eq:sharp of the paper) is sufficiently large in terms of degree $d$ and $M$, then for every  base $b\ge2$ and every nonzero integer \(h\in\mathbb Z\setminus\{0\}\),
			\begin{equation}
				\left| \mathbb E e\!\left(h(b^n-b^m)P(X)\right)
				\right| \ll_{P,b,h,M} (\log n)^{-M}
			\end{equation}
			uniformly for $0\le m<n$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 9 (Cutoff and symbol estimates) of arXiv:2609.01403, '2609.01403'] \quad
\begin{enumerate}
\item Suppose that \(a\in C^\infty(\mathbb R^n)\) vanishes near the
origin and that, for some \(\mu\in\mathbb R\) and every multi-index \(\rho\),
\begin{equation}
    |\partial_\xi^\rho a(\xi)|
    \leq C_\rho|\xi|^{-\mu-|\rho|}
    \qquad\text{for any }|\xi|\geq1.

\end{equation}
Then \(K=\mathcal F^{-1}a\) is smooth on
\(\mathbb R^n\setminus\{0\}\), is rapidly decreasing at infinity, and
for every multi-index \(\gamma\) and \(0<|x|\leq1\),
\begin{equation}
    |\partial_x^\gamma K(x)|
    \leq
    \begin{cases}
        C_\gamma|x|^{\mu-n-|\gamma|},&\mu<n+|\gamma|,\\
        C_\gamma(1+|\log|x||),&\mu=n+|\gamma|,\\
        C_\gamma,&\mu>n+|\gamma|.
    \end{cases}

\end{equation}
If, in addition, \(a\) is radial, \(\mu>n\), and
\begin{equation}
    0<\beta<\min\{\mu-n,2\},

\end{equation}
then
\begin{equation}
    K(x)=K(0)+o(|x|^\beta),
    \qquad
    \nabla K(x)=o(|x|^{\beta-1}),
    \qquad\text{as }|x|\to0.

\end{equation}

\item Suppose that \(b\) is compactly supported, smooth on
\(\mathbb R^n\setminus\{0\}\), and that, for some \(\nu>-n\) and every multi-index \(\rho\),
\begin{equation*}
    |\partial_\xi^\rho b(\xi)|
    \leq C_\rho|\xi|^{\nu-|\rho|}
    \qquad\text{for any }0<|\xi|\leq2.
\end{equation*}
Then, for every multi-index \(\gamma\) and \(|x|\geq1\),
\begin{equation}
    |\partial_x^\gamma\mathcal F^{-1}b(x)|
    \leq C_\gamma|x|^{-n-\nu-|\gamma|}.

\end{equation}
\end{enumerate}

