body:
[Lemma lem:width_from_contour of arXiv:2512.17747, 'On exponentially height-penalized random trees'] For any tree $T$ of size $n$, if we let $C^{(T)}=(C^{(T)}_t:0\leq t \leq 2n-1)$ be its contour walk, $w(T)$ its width, then 
\begin{align*}
    \frac{L_{2n-1}(C^{(T)})}{2}\leq w(t) \leq  L_{2n-1}(C^{(T)}).
\end{align*}

[Definition def-weak-strong-uniqueness-infty of arXiv:2411.04500, '\LARGE Probabilistic Approaches to The Energy Equality in Forced Surface Quasi-Geostrophic'] We say that
	$\mathcal{C}_0 \subset \mathbb{X}^\infty_{\alpha,\beta}$ is a weak-strong uniqueness class of (equation PDE-infty of the paper)  if for every control $g\in L^2_{loc}([0,\infty);H)$, the following holds:   for arbitrary two weak solutions $\theta_1,\theta_2$ of the skeleton equation (equation PDE-infty of the paper) in the sense of Definition (def-sol-infinity of the paper)  with the same initial data $\theta_1(0)=\theta_2(0)$ and the same control $ g $, we have $\theta_1=\theta_2$ in  $ \mathbb{X}_{\alpha,\beta}^\infty$ as long as $\theta_1\in\mathcal{C}_0$ and  $\theta_2$ satisfies the $ H^{\alpha-2\beta}$-energy inequality: for every $ t>0 $,
	\begin{equation}
		\frac{1}{2}\|\theta_2(t)\|_{H^{\alpha-2\beta}(\mathbb{T}^2)}^2+\int_0^t\|\theta_2(s)\|_{H^{2\alpha-2\beta}(\mathbb{T}^2)}^2 \,\mathrm{d}s \leqslant \frac{1}{2}\left\|\theta_2(0)\right\|_{H^{\alpha-2\beta}(\mathbb{T}^2)}^2+\int_0^t\langle\Lambda^{2\alpha-2\beta} \theta_2, g\rangle \,\mathrm{d}s.
	\end{equation}

[Theorem 10 of arXiv:2609.01166, 'Nonparametric inference for density-dependent McKean--Vlasov diffusions'] Suppose that the assumptions of Theorem~\ref{thm:oracle} hold. Fix \(I=[r_-,r_+]\Subset(0,a_0)\) and suppose that Assumption~\ref{ass:regular-interior} holds on \(I\) for \(\xi_\circ=\Xi_0\). Let \(\mathfrak R_{n,m,\delta,M_n}\) denote the right-hand side of the KL-bound in~\eqref{eq:oracle}. There exists \(C_\mathrm{mode}=C(I,a_0,d,V,K)>0\) such that the inequality 
\(
\mathfrak R_{n,m,\delta,M_n}
\leq C_\mathrm{mode}
\) implies
\begin{equation}
 \Vert \widehat\Xi_n-\Xi_0\Vert_{L^2(I)} \leq C_\mathrm{inv} \mathfrak R_{n,m,\delta,M_n}^{\beta/(2(\beta+1))}
\end{equation}
for some constant 
\(
C_\mathrm{inv}:=C(I,a_0,V,\kappa,K,\beta,H,H_1)
\)
with probability at least \((1-\delta)(1-\tau_0(M_n))^n\).
Optimizing in $m$ gives
\begin{equation}
 \Vert\widehat\Xi_n-\Xi_0\Vert_{L^2(I)} = O_{\Prob}\left( (b_n\log n/n)^{\beta/(2\beta+3)} \right).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:discrete-cmt of arXiv:2607.01946, 'Second-order fluctuations for a phase transition in random partitions'] We have
\begin{equation}
\pp{\mathcal Z_n(t)}_{t\in{\mathbb R}}\stackrel{a.s.w.}\to\pp{\mathcal Z(t)}_{t\in{\mathbb R}}
\end{equation}
with respect to ${\mathcal P}$ in $D(\mathbb R,\mathcal M_{p,f}(\mathbb R))$ with the local $J_1$ topology.
Moreover,
\begin{equation}
\left(C_{j_n}(\floor{s_n(t)})\right)_{t\in\mathbb R}\stackrel{a.s.w.}\to({\mathcal C}_{\alpha,r}(t))_{t\in{\mathbb R}}
\end{equation}
with respect to ${\mathcal P}$ in $D(\mathbb R)$ with the local $J_1$ topology. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 15 (Uniform data along the hybrid path) of arXiv:2608.07820, 'Linear Spectral Statistics for Entrywise-Transformed Spiked Wigner Matrices under Shifted '] Every hybrid has the same deterministic mean matrix, the same variance
profile, and the same edgewise third and fourth cumulants.  Under W5 and
$\max_e|s_{e,N}|\to0$,
\begin{equation}
 \sup_{0\le r\le M_N}
 \frac1{M_N}\sum_{e=1}^{M_N}
 \E\left[
 |X_e^{(r)}|^4
 \one_{\{|X_e^{(r)}|>\varepsilon\sqrt N\}}
 \right]\longrightarrow0,
\end{equation}
where $X_e^{(r)}$ denotes the centered scalar used at edge $e$ in
$H_N^{(r)}$.

[Proposition 9 of arXiv:2604.18871, 'Quantitative approximation of the Vlasov(--Fokker--Planck)--Navier--Stokes system by stoch'] Let Assumptions~\ref{assump-PDE}\ref{inivel} and \ref{momenthigh} hold.
Let $(u, F)$ be any bounded weak solution of system \eqref{eq:PDE}. Then the following holds:
\begin{enumerate}[label=(\alph*)]
\item $u\in \mathcal{C}( [0,T];  H^\gamma_p(\T^d)^d)$;

\item $\sup_{t\in (0,T]} t^{\frac{1}{2}} \lVert \nabla u_{t} \rVert_{\gamma,p} <\infty$.

\end{enumerate}

