body:
[Lemma lem:g0-forcing-removal of arXiv:2609.00556, 'Higgs--Demailly System and Positivity of Higgs Bundles'] There exists a constant $c_*>1$, depending only on the fixed background
data, such that, for every $\tau\in[0,1]$, the equation
\begin{equation}
 \sqrt{-1}\Lambda_\omega R^0_{D_{g_\tau h_{\rm ref}}}
 +c_*\log g_\tau
 =(1-\tau)\mathscr S_{g_\tau}\Psi,
 \qquad \det g_\tau=1,
\end{equation}
admits a unique smooth positive $h_{\rm ref}$-Hermitian solution $g_\tau$.
 In particular, at $\tau=1$ there  exists a unique smooth positive
determinant-one endomorphism $g_*$ satisfying
\begin{equation}
 \sqrt{-1}\Lambda_\omega R^0_{D_{g_*h_{\rm ref}}}
 +c_*\log g_*=0.
\end{equation}

[Theorem 2 of arXiv:2609.03634, 'Joint Laws of Maximum Drawdown and Maximum Drawup for Spectrally Negative L\'{e}vy Process'] Conditionally on $I_T=a$, the pre-$H_I$ and post-$H_I$ processes are independent.

\begin{enumerate}[label=\textup{(\roman*)}]
\item The law of the pre-$H_I$ process is the Doob $h$-transform of the spectrally negative L\'{e}vy process killed at $\tau_a\wedge T$, with
\[
h(x)=\frac{\gamma}{\Phi(\gamma)}W^{(\gamma)\prime}(x-a)-\gamma W^{(\gamma)}(x-a),\qquad x\geq a.
\]
Moreover,
\begin{align*}
\mathbb{P}_0\left\{S_{H_I}<b\mid I_T=a\right\}
&=1-\frac{\frac{\gamma}{\Phi(\gamma)}W^{(\gamma)\prime}(b-a)-\gamma W^{(\gamma)}(b-a)}
{\frac{\gamma}{\Phi(\gamma)}W^{(\gamma)\prime}(-a)-\gamma W^{(\gamma)}(-a)}
\frac{W^{(\gamma)}(-a)}{W^{(\gamma)}(b-a)},
\qquad b\geq0,
\end{align*}
and
\begin{align*}
\mathbb{P}\left\{M_{0,H_I}^{-}<d\mid I_T=a\right\}
&=1-\frac{\frac{\gamma}{\Phi(\gamma)}W^{(\gamma)\prime}(d)-\gamma W^{(\gamma)}(d)}
{\frac{\gamma}{\Phi(\gamma)}W^{(\gamma)\prime}(-a)-\gamma W^{(\gamma)}(-a)}
\frac{W^{(\gamma)}(-a)}{W^{(\gamma)}(d)},
\qquad d\geq0.
\end{align*}
For $u>0$,
\begin{align*}
\mathbb{P}\left\{M_{0,H_I}^{+}\leq u \mid I_T=a\right\}
=\frac{\frac{\gamma W^{(\gamma)}(u)}{\Phi(\gamma)}\mathcal{L}_{\theta \rightarrow -a}^{-1}\left\{\frac{1}{Z_\gamma(u, \theta)}\right\}}{\frac{\gamma}{\Phi(\gamma)} W^{(\gamma)^{\prime}}(-a)-\gamma W^{(\gamma)}(-a)}
\end{align*}
where $\mathcal{L}^{-1}$ is the inverse Laplace transform and  $Z_\gamma(u, \theta)$ denotes the generalized/two-parameter scale function.
\item The law of the post-$H_I$ process is the Doob $h$-transform of the spectrally negative L\'{e}vy process killed at $T\wedge\tau_a^-$, with
\[
h(x)=1-Z^{(\gamma)}(x-a)+\frac{\gamma}{\Phi(\gamma)}W^{(\gamma)}(x-a).
\]
Moreover,
\[
\mathbb{P}\left\{S_{H_I,T}<b\mid I_T=a\right\}
=\frac{\Phi(\gamma)\bigl(Z^{(\gamma)}(b-a)-1\bigr)}{\gamma W^{(\gamma)}(b-a)},
\qquad b>a,
\]
\begin{align*}
\mathbb{P}\left\{M_{H_I,T}^{-}>d\mid I_T=a\right\}
&=1-\Phi(\gamma)\frac{W^{(\gamma)}(d)}{W^{(\gamma)\prime}(d)},
\qquad d\geq0,
\end{align*}
and, for $u>0$,
\begin{align*}
\mathbb{P}\left\{M_{H_I,T}^{+}< u\mid I_T=a\right\}
=\frac{\Phi(\gamma)\bigl(Z^{(\gamma)}(u)-1\bigr)}{\gamma W^{(\gamma)}(u)}.
\end{align*}
\end{enumerate}

[Proposition 4 (Minimum-gcd Fourier layer) of arXiv:2609.01570, 'A Proof of Fraenkel's Conjecture'] Let \((\B_i)_{i=1}^m\) be a primitive rational Beatty partition with
pairwise distinct moduli and common-denominator data \(p_i,q\).  Suppose that
\(3p_i<q\) for every \(i\).  The minimum layer
\(A=\{a_1,\ldots,a_r\}\subset\U\) satisfies
\begin{equation}
 3a<Q\quad(a\in A),\qquad \sum_{a\in A}a\le Q.
\end{equation}
Moreover, every \(a_k\in A\) satisfies the necessary row inequality
\begin{equation}
 1\le M_k:=\sum_{i\ne k}
 K_Q\!\left(\normQ{a_ka_i^{-1}}\right).
\end{equation}

[Proposition 5 of arXiv:2512.02922, 'Asymptotics for additive functionals of particle systems via Stein's method'] The Wasserstein distance between $\rho_r$ and the standard Gaussian distribution $\gamma$ satisfies
\[
d_W(\rho_r,\gamma) \;\leq\; C (r^{-3H/4}\Indi{\{d=1\}}
+r^{-3H/2} \log(r)^{-1/2}\Indi{\{d=2\}} 
+ r^{-H(2d-1)/2}\Indi{\{d\geq 3\}}).
\]
for some constant $C>0.$ (Proof in the paper; no proof environment follows the statement in the TeX.)

