[Definition def:kernelholojs of arXiv:2411.04238, 'Holomorphic jump-diffusions'] The jump kernel $K$ is said to have holomorphic jump size if it is of the form
   \begin{align*}
    K(\cdot,A)=\lambda(\cdot)\int_E 1_{A\setminus\{0\}} ( j(\cdot,y))F(dy),
\end{align*}
where,
\begin{enumerate}
\item $F$ is a non-negative measure on a measurable space $E$;
    \item $\lambda\in \mathcal{O}(S)$ and its restriction to $S$ is positive real valued;
    \item $j:S\times E \rightarrow \mathbb{R}^d$ such that $ j=j_\varepsilon|_{S\times E}$ for some $\varepsilon>0$ and some measurable function $$j_\varepsilon:P^d_{R(S)+\varepsilon}(0)\times E \rightarrow \mathbb{C}^d$$ with $j_\varepsilon(\cdot,y)\in H(P^d_{R(S)+\varepsilon}(0),\mathbb C^d)$ for each $y \in E$.
\end{enumerate}

[Theorem 10 of arXiv:2609.03634, 'Joint Laws of Maximum Drawdown and Maximum Drawup for Spectrally Negative L\'{e}vy Process'] For $d>0$ and every bounded measurable function $\varphi:\mathbb{R}_+\to\mathbb{R}_+$,
\begin{align}
&\mathbb{E}\!\left(\varphi(M_T^{+});\,M_T^{-}<d,\,H_I<H_S\right)\nonumber\\
&\quad=
\int_0^d
\varphi(r)
\frac{
\left[
\gamma W^{(\gamma)}(r)
-
\bigl(Z^{(\gamma)}(r)-1\bigr)
\dfrac{W^{(\gamma)\prime}(r)}{W^{(\gamma)}(r)}
\right]^2
}{
\gamma W^{(\gamma)}(r)
}
\,dr
\nonumber\\
&\qquad+
\frac{
\left[
\gamma W^{(\gamma)}(d)
-
\bigl(Z^{(\gamma)}(d)-1\bigr)
\dfrac{W^{(\gamma)\prime}(d)}{W^{(\gamma)}(d)}
\right]^2
}{
\gamma W^{(\gamma)}(d)
}
\int_d^{\infty}
\varphi(r)
\exp\left\{
-(r-d)
\frac{W^{(\gamma)\prime}(d)}{W^{(\gamma)}(d)}
\right\}\,dr.

\end{align}

