[Theorem t:main theorem stealthy markov inversion of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Suppose that $\Psi$ is an invariant locally absolutely square-integrable random measure of intensity $\gamma$ which is $\infty$-uniform. Then there exist invariant transport kernels $K,L$ such that $K,L$ are probability kernels, $\Psi = \gamma K\lambda_d$, $\lambda_d=L\lambda_d$, and
\begin{align}
    \BE\bigg[\int \|x\|^q\, (K_0+L_0)(dx)\bigg] &<\infty,\\
    \int x^{\otimes q}\, (K_0-L_0)(dx) &= 0,\quad q\in\N.
\end{align}
We can even choose $L$ to be deterministic, which implies that $\int x^q\, K_0(dx), q\in\N$ is also deterministic. Hence, $d_{p}(\Phi, \gamma\lambda_d)\leq 2\tilde{d}_{p}(\Phi, \gamma\lambda_d)<\infty$ for all $p\in[1,\infty)$.
\begin{proof}
Let $\varepsilon>0$ such that $\Phi$ is $\infty$-uniform with radius $\varepsilon$. Further, we can assume that $\gamma>0$, as the case $\gamma=0$ is trivial.
First, we choose $g:\R^d\to\C$ such that $\hat{g}\in\cC^\infty$ and $\hat{g}(k)=0$ for $k\in\R^d$ with $\|k\|\geq \frac{\varepsilon}{2}$. Then we chose $f:= \lambda_d(|g|^2)^{-1}|g|^2$, where we note that the Paley-Wiener theorem implies that $\lambda_d(|g|^2)<\infty$; see, e.g.,~[Stein_Weiss_1971]. By construction, $f$ is nonnegative and satisfies $\hat{f}\in\cC^\infty$ with $\hat{f}(k)=0$ for $k\in\R^d$ with $\|k\|\geq \varepsilon$, and $\lambda_d(f)=1$. 
Now we can define the transport kernels $K,L$ by
\begin{align}
    K(x,B) &:= \gamma^{-1} \int_B f(x-y) \, \Psi(dy), \\
    L(x,B) &:= \int_B f(x-y) \, dy, \quad x\in\R^d, B\in\cB^d.
\end{align}
We can see that $K$ is invariant, as
\begin{align*}
    K(\theta_z,x,B) &= \gamma^{-1} \int_B f(x-y) \, \Psi(\theta_z,dy) \nonumber\\
    &= \gamma^{-1} \int_{B+z} f(x+z-y) \, \Psi(dy) \nonumber\\
    &= K(x+z,B+z),\quad x,z\in\R^d, B\in\cB^d.
\end{align*}
The invariance of $L$ follows in the same way. Further, we can calculate that
\begin{equation*}
    \BE\bigg[\int \|x\|^q\, K_0(dx)\bigg]= \gamma^{-1} \BE\bigg[\int\|x\|^q f(x)\, \Psi(dx)\bigg] = \int\|x\|^q f(x)\, dx < \infty,
\end{equation*}
where we used that $f(x)$ decays faster than any polynomial as $\|x\|\to\infty$ by the Paley-wiener theorem; see, e.g.,~[Stein_Weiss_1971]. The same holds for $L_0$ instead of $K_0$. Additionally, we have that
\begin{equation*}
    \BV\bigg[\int x^{\otimes q}\, K_0(dx)\bigg] =\gamma^{-2} \BV\bigg[\int \underbrace{x^{\otimes q} f(x)}_{f_{q}(x):=}\, \Psi(dx)\bigg] = \gamma^{-2}\int |\hat{f}_{q}(k)|^2\, \hat\beta_\Psi(dk)
    =0,
\end{equation*}
for $q\in\N_0$,where we used that $\hat{f}_{q}=(\hat{f})^{(q)}$, and that $\hat{f}(k)=0$ for $k\in\R^d$ with $\|k\|\geq \varepsilon$. Combined with the fact that 
\begin{equation*}
    \BE\bigg[\int x^{\otimes q}\, K_0(dx)\bigg] =\gamma^{-1} \BE\bigg[\int x^{\otimes q} f(x)\, \Psi(dx)\bigg]= \int x^{\otimes q} f(x)\, dx = \int x^{\otimes q}\, L_0(dx),
\end{equation*}
for $q\in\N_0$,
this equation yields that
\begin{equation*}
    \int x^{\otimes q}\, K_0(dx) = \int x^{\otimes q}\, L_0(dx),\quad q\in\N_0,
\end{equation*}
where both sides are deterministic and for $q=0$ also equal to $1$.
Finally, Fubini's theorem yields
\begin{equation*}
    \gamma K\lambda_d(B) = \iint_B f(y-x) \, \Psi(dy)\, dx = \Psi(B),
\end{equation*}
and in the same way $\lambda_d=L\lambda_d$, which concludes the proof.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 26 of arXiv:2606.09904, 'Non-explosion principles for branched rough differential equations with unbounded coeffici'] Let \((V, \|\cdot\|)\) be a finite-dimensional normed vector space and \(U\) be a closed connected subset of \(V\).
  Suppose \(a, b \in C(U; \mathbb{R})\) for which
  \(\sup_{x \in U: \|x\| \le R} b(x) < \infty\) for all \(R > 0\) and
  \(c \in C(\mathbb{R}_+, \mathbb{R}_+)\) is monotone and \(c(0) = 0\). Then, denoting 
  \[R^* = \sup \{\|x\| \in \mathbb{R}_+ : x \in U, a(x) \le 0\}\]
  and
  \begin{equation}
    \CA =
      \left\{(X_\epsilon) \in C([0, 1], U) \;\middle|\;
        \begin{aligned}
          & \forall s < t,\ \|X_s\| \le \|X_t\|,\\
          & \forall \epsilon \in (0, 1),\ a(X_\epsilon) \le c(\epsilon) b(X_\epsilon)
        \end{aligned}
      \right\},
  \end{equation}
  for any \(r > 0\), if \(\epsilon^* > 0\) is such that, for all \(\epsilon < \epsilon^*\) 
  \[a(x) - c(\epsilon)b(x) > 0, \qquad \forall\ \|x\| = R^* + r,\] 
  then \(\sup_{X \in \CA} \|X_{\epsilon^*}\| \le R^* + r\).

[Theorem thm:0 of arXiv:2603.27906, 'Marked GUE-corners process in doubly periodic dimer models'] Let~$K_{\operatorname{Int}}$ be the correlation kernel of $(u_{s}^t)_{1\leq s\leq t\leq 2\ell N}$ and suppose~$\nu:\mathbb{Z}_{>0}\times \{0,1\} \rightarrow \mathbb{R}$ is given by
\begin{equation}
 \nu(t,j)=
\begin{cases}
 \frac{1}{1+\alpha_{\ell+1-t}\beta_{\ell-t}^{-1}} \quad \text{if } j=0, \\
 \frac{\alpha_{\ell+1-t}\beta_{\ell-t}^{-1}}{1+\alpha_{\ell+1-t}\beta_{\ell-t}^{-1}} \quad \text{if } j=1,
\end{cases} 
\end{equation}
where $\alpha_{\ell-t}$ and $\beta_{\ell-t}$ are the edge weights of the model (see Figure~(fig:Aztec_diamond_graph_4 of the paper) and later (equation eqn:edge_weights of the paper)).
Let the gauge function~$g:\{0,1,\ldots, 2\ell N\}^2\rightarrow \mathbb{R}$ be defined by~(equation eq:gauge_function of the paper) and let~$\tau, \sigma>0$ be (explicitly) given by~(equation eq:turning_point of the paper) and~(equation eq:sigma_square of the paper) below.

Set~$\ell x_k+i_k=2\ell N-t_k$ and~$y_k=\lfloor N\tau +\sqrt{N}\mu_k\rfloor$, for $k=1,2$. Then, for $\mu_1\neq \mu_2$,
\begin{multline}
\lim_{N\to \infty}\frac{g(\ell x_1+i_1,2y_1+j_1)}{g(\ell x_2+i_2,2y_2+j_2)}N^{\frac{1}{2}}K_{\operatorname{Int}}\left(\ell x_1+i_1,2y_1+j_1;\ell x_2+i_2,2y_2+j_2\right) \\
=\nu(t_2,j_2)\sigma^{-1}K_{\operatorname{GUE}}(t_1,\sigma^{-1}\mu_1;t_2,\sigma^{-1}\mu_2), 
\end{multline}

where
\begin{equation}
K_{\operatorname{GUE}}(t_1,\mu_1;t_2,\mu_2)=\frac{1}{(2\pi\mathrm{i})^2}\int_{\gamma_s'}\int_{\gamma_l'}\mathrm{e}^{\frac{1}{2}(z_2^2-z_1^2)}\mathrm{e}^{\mu_1 z_1-\mu_2z_2}\frac{z_2^{t_2}}{z_1^{t_1}}\frac{\,\mathrm{d} z_1\,\mathrm{d} z_2}{z_2-z_1},
\end{equation}
 is the correlation kernel of the GUE-corners process. The sequence on the left-hand side is uniformly bounded in $N$
 on compact subsets of 
$\Lambda_{\{0,1\}}^2$ with respect to the embedding given by $(t_p, \mu_p, j_p)\in \Lambda_{\{0,1\}}$, for $p=1,2$. See Theorem~(thm:limit_correlation_function of the paper) for a definition of the curves~$\gamma_s'$ and~$\gamma_{\ell}'$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:normalform of arXiv:2608.26564, 'Real ideal points, Conway spheres, and left-orderable Dehn fillings'] A four-longitude decomposition is in \emph{parabolic normal form along $B$} if, after independent $SL_2(\mathbb{R})$-changes of basis in the two tangle sides adapted to the pair of fixed lines $(\mathcal P_i, \mathcal L_i)$, one has
\begin{equation*}
	\rho_1^B(\ell_1) = \mathrm{red}(A_1) = \epsilon_1\begin{pmatrix}1 & 0 \\ a_1 & 1\end{pmatrix} \ \ \ \ \ \rho_2^B(\ell_2) = \mathrm{red}(B_2) = \epsilon_2\begin{pmatrix}1 & 0 \\ a_2 & 1\end{pmatrix}
\end{equation*}
\begin{equation*}
	\rho_1^B(\ell_3) = \mathrm{red}(A_3) = \epsilon_3\begin{pmatrix}1 & b_1 \\ 0 & 1\end{pmatrix} \ \ \ \ \ \rho_2^B(\ell_4) = \mathrm{red}(B_4) = \epsilon_4\begin{pmatrix}1 & b_2 \\ 0 & 1\end{pmatrix}
\end{equation*}
where $a_1, a_2, b_1, b_2 \in \mathbb R^\times$ and $\epsilon_j \in \{\pm 1\}$. It is in \emph{positive parabolic normal form} if, in addition, $a_1a_2 < 0$.

[Definition 17 (\cite{mingoFreeProbabilityRandom2017}) of arXiv:2606.31528, 'Well-posedness and stationary distribution of free stochastic differential equations'] Let $\mu$ be a probability measure on $\mathbb{R}.$ Its Cauchy transform is given by 
\begin{equation}
G_\mu (z) : = \int_\mathbb{R} \frac{1}{z-t} \, \mu ({\rm d}t)
\end{equation}
for any $z \in \mathbb{C} \backslash \mathbb{R}.$

