[Theorem thm:tailrl-harmonic-decomposition of arXiv:2609.02987, 'Tail Likelihood Reinforcement Learning'] If $J_{\mathrm{TailRL{}}}(\theta;x)>-\infty$, then
\begin{equation}
J_{\mathrm{TailRL{}}}(\theta;x)
=
\sum_{k=1}^{\infty}
\frac{\text{Best-of-}k(\theta;x)-1}{k}.

\end{equation}
Under the regularity conditions of (lem:tailrl-regularity of the paper),
\begin{equation}
\nabla_\theta J_{\mathrm{TailRL{}}}(\theta;x)
=
\sum_{k=1}^{\infty}
\frac{1}{k}
\nabla_\theta\text{Best-of-}k(\theta;x).

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:char_velo of arXiv:2411.14818, 'Scaling limits of solitons in the Box-Ball system'] Suppose that $\mathbf{q} \in \mathcal{Q}$ and $q_{k} > 0$ for some $k \in {\mathbb{N}}$. Then, we have
                \begin{align}
                    v^{\mathrm{eff}}_{k}\left(\mathbf{q}\right) = k v^{\mathrm{eff}}_{1}\left(\theta^{k-1}\mathbf{q}\right) + 2 \sum_{\ell = 1}^{k - 1} \ell \alpha_{\ell}\left(\mathbf{q} \right) v^{\mathrm{eff}}_{k-\ell}\left(\theta^{\ell} \mathbf{q} \right), 
                \end{align}
            and 
                \begin{align}
                    v^{\mathrm{eff}}_{1}\left(\theta^{k-1}\mathbf{q}\right) = \bar{r}_{k}\left(\mathbf{q}\right).
                \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition eq:ctyp-LB of arXiv:2608.19050, 'Online Permutation Embedding: \\ Optimal Stopping and Scaling Laws'] \begin{equation}
    c_\mathrm{typ} = \sup_{k \in \NN} \Big(\frac{2}{(k+1)(k+2)} \sum_{j=1}^k \sqrt{\beta_j^\mathrm{typ}}\Big)^2 \geq \sup_{k \in \NN} \Big(\frac{2}{(k+1)(k+2)} \sum_{j=1}^k \sqrt{\beta_j^-}\Big)^2.
\end{equation}

[Prop 12 of arXiv:2609.03713, 'A Sharp Mass Threshold for Boundedness in a Critical Quasilinear Chemotaxis Model with Ind'] Let $a>0$, $M=a|\mathbb{B}_R|$ and consider a sequence $(u_l)_{l\ge 1}$ in $\Sigma_a$. For $l\ge 1$, we set $\lambda_l:=\|u_l\|_\infty^{1/d}$, 
\begin{equation}
	P_l(x):=\frac{1}{\lambda_l^d}u_l\left(\frac{x}{\lambda_l}\right)\,,\quad x\in \bar{\mathbb{B}}_{\lambda_l R}\,,
\end{equation} 
and
\begin{equation}
	\varphi_l(x):=\frac{1}{\lambda_l^{d-2}}\phi'\left(u_l\right)\left(\frac{x}{\lambda_l}\right)\,,\quad x\in \bar{\mathbb{B}}_{\lambda_l R}\,.
\end{equation}
Then there are $P\in C(\mathbb{R}^d)$ and $\varphi\in C^2(\mathbb{R}^d)$ such that, up to a subsequence, 
\begin{equation*}
	P_l\rightarrow P \ \text{ in }\ C(\mathbb{R}^d)\,,\qquad \varphi_l\rightarrow \varphi \ \text{ in }\ C^2(\mathbb{R}^d)\,.
\end{equation*}
Assume in addition that $\|u_l\|_\infty\to\infty$ as $l\to\infty$. Then both $P$  and $\varphi$ are non-increasing with respect to $r=|x|$ with $P(0)=1$, and $P$ has compact support $\bar{\mathbb{B}}_{\rho_0}$ for some $\rho_0\in (0,\infty)$. Furthermore, $\varphi$ satisfies
\begin{equation}
	-\Delta \varphi=\left(\frac{m-1}{m}\right)^{1/(m-1)}\varphi_+^{1/(m-1)}\ \text{ in }\ \mathbb{R}^d
\end{equation}
with $\varphi_+=\max\{\varphi,0\}$, 
\begin{subequations}
\begin{equation}
	P^{m-1} = \dfrac{m-1}{m} \varphi_+ \;\;\text{ in }\;\; \mathbb{R}^d\,, 
\end{equation} 
and
\begin{equation}
 	\varphi(x)=\left\{\begin{array}{ll}
	\dfrac{m}{m-1} \rho_0^{2-d} \zeta\left(\dfrac{x}{\rho_0}\right)\,, & x\in \bar{\mathbb{B}}_{\rho_0}\,,\\[20pt]
	\dfrac{M_c}{\sigma_d}\dfrac{|x|^{2-d}-\rho_0^{2-d}}{d-2} \,, & x\in \R^d\setminus\bar{\mathbb{B}}_{\rho_0}\,.
\end{array}\right.
\end{equation}
\end{subequations}
Finally, it holds that $M\ge M_c$, the critical mass $M_c$ being defined in~\eqref{Mc}.

