[Lemma 3 of arXiv:2606.00945, 'Ising model and percolation: from hexagonal lattice to 3-12 lattice'] Let $z^{\diamond}$ be a midpoint of an edge in $\Omega_{\312}^\delta$ separating two dodecagons, we have 
\begin{align}
    \IO_{\312}^\delta(x;z^\diamond)=\IO_6^\delta\left(\frac{x^3+x^2}{x^3+1};z^\diamond\right).
\end{align}

[Definition 6 of arXiv:2608.18834, 'The Parabolic Anderson Model's Total Mass at Small Times: Geometry, Fluctuations, and Reno'] Let $B$ be a standard Brownian motion on $\mbb R^d$ (which is started at
the origin). For every $x\in\mbb R^d$, we define
\begin{align}

B^x=x+B.
\end{align}
For any stochastic process $Z$ (e.g., $B^x$), we denote the hitting time
\[\tau_D(Z)=\inf\{s\geq0:Z(s)\not\in D\}.\]
Then, we define the total mass of $u_{\ka,\eps}$ (which we denote $\msf M_{\ka,\eps}(t)$) as
\begin{align}

\int_Du_{\ka,\eps}(t,x)\d x:=\msf M_{\ka,\eps}(t)=\int_D\mbf E_B\left[\mbf 1_{\{\tau_D(B^x)>t\}}\mr e^{\ka\int_0^t\xi_\eps(t-u,B^x(u))\d u}\right]\d x
\end{align}
for every $\eps,t>0$, where we assume that $\xi$ and $B$ are independent,
and $\mbf E_B$ means that we are only taking the expectation with respect to $B$---i.e., conditional on $\xi$.
(This is clearly well-defined since $\xi_\eps$ is continuous.)

[Theorem of arXiv:2608.10415, 'Continuous random variables'] The basic random matrices $Z\in M_N(L^\infty(X))$ are as follows:
\begin{enumerate}
\item In the case $N=1$ the random matrix is a usual random variable, $f\in L^\infty(X)$, automatically normal, and its law as defined above is the usual law.

\item In the case $X=\{.\}$ the random matrix is a usual scalar matrix, $A\in M_N(\mathbb C)$, and in the normal case, the law is $\mu=\frac{1}{N}\left(\delta_{\lambda_1}+\ldots+\delta_{\lambda_N}\right)$.
\end{enumerate}

[Lemma 19 of arXiv:2604.08127, 'Asymptotics of Brownian occupation measures \\ with unusually large intersections'] Let $W_t$ be a Brownian motion in $\mathbb{R}^d$. For any $0 \le \theta \le d$ and $x, y \in \mathbb{R}^d$,
        \begin{equation}

            \mathbb{E} \delta(W_t -x) |W_t - y|^{-\theta} \le C |t|^{-(d-\theta)/2} |x - y|^{-\theta} |x|^{-\theta}.
        \end{equation}
        Similarly, for any $0 < k < d$ and $0 \le \theta \le k/2$,
        \begin{align}

        \mathbb{E} |W_t -x|^{-k} |W_t - y|^{-k} &\le C |t|^{-k/2} |x-y|^{-k}, \\

            \mathbb{E} |W_t -x|^{-k} |W_t - y|^{-\theta} &\le C |t|^{-(k-\theta)/2} |x|^{-\theta}|x-y|^{-\theta}.
        \end{align}
        Here, $C$ may depend on $d$ and $k$ but not on $t$, $x$, $y$, or $\theta$.

[Theorem 35 (Young--L\'{o}eve's inequality) of arXiv:2606.22964, 'Signature McKean--Vlasov stochastic differential equations'] Given $x\in C^{\textup{$p$-var}}([0,T],\mathbb{R}^d)$ and $y\in C^{\textup{$q$-var}}([0,T];L(\mathbb{R}^d,\mathbb{R}^e))$, where $L(\mathbb{R}^d,\mathbb{R}^e)$ denotes the space of linear functional from $\mathbb{R}^d$ to $\mathbb{R}^e$, there exists a unique (indefinite) Young integral of $y$ against $x$ denoted by $\int_0^\cdot ydx$. Moreover, the indefinite Young integral has finite $p$-variation and
    \begin{equation*}
        \Bigg|\int_0^\cdot ydx\Bigg|_{p-\textup{var};[s,t]} \leq C|x|_{p-\textup{var};[s,t]}\left(|y|_{p-\textup{var};[s,t]} + |y_0|\right),
    \end{equation*}
    where $C=C(p,q)$.

[Lemma lem:integrationbytails of arXiv:2602.11129, 'Information-Theoretic Thresholds for Bipartite Latent-Space Graphs Under Noisy Observation'] Let $f$ be a polynomial of degree $\ell \ge 2$ in $i.i.d.$ standard Gaussian inputs $\mathbf{x}$ with $\Expectedsub{\mathbf{x}}{f(\mathbf{x})} = 0$ and variance $\sigma \coloneqq \sqrt{ \mathrm{Var}{f(\mathbf{x})}}$. Let further $c$ be the constant in the exponent of the tail bound from (prop:hypercontractivity of the paper) and assume that $|f(\mathbf{x})| \le U$ for all $\mathbf{x} \in S$ where $S$ is some measurable set. Assume $U\sigma^{\frac{2}{\ell-2}} \le \frac{c^2}{4}$ if $\ell \ge 3$, and that $\sigma \le \frac{c}{2}$ if $\ell = 2$. Note that in case $\ell = 2$, we allow $U = \infty$. Then, there is a constant $C > 0$ independent of $f$ such that \begin{align*}
        \Expectedsub{\mathbf{x}}{ \mathds{1}( \mathbf{x} \in S) \exp(f(\mathbf{x})) } \le 1 + (C \ell)^{\frac{\ell + 2}{2}} \sigma.
    \end{align*}

[Lemma lem:finite-time-w1 of arXiv:2607.00149, '\bf Uniform-in-time Propagation-of-Chaos for\\ Stein Variational Gradient Descent'] Let Assumption~(ass:w1-normalized-matern of the paper) hold.  Then there exist constants $C_0,c_0<\infty$ such that, for any $R>0$, $N\ge3$ and all $t\ge0$,
\begin{equation}
        \mathbb E\Big[\sup_{0\le s\le t}
        W_1(\mu^N_s,\mu_s)\, \mathbf{1}_{\{\int \|x\|^2 \mu^N_0(dx) \le R\}}\Big]
        \le C_0N^{-\beta}\exp\{c_0(1+R)\exp(c_0t)\}.
\end{equation}

