body:
[Theorem thm:Main of arXiv:2511.10630, 'Cutoff for generalised Bernoulli--Laplace urn models'] Let $d, m \in \mathbb{N}$ be fixed with $d, m \geqslant 2$. Consider a sequence $\{\mathbf{X}^{(n)}\}_{n \in \mathbb{N}}$ of generalised Bernoulli--Laplace chains where the $n^{\mathrm{th}}$ chain has parameters $(d, m, n, \mu_n)$. Suppose that the Cheeger constant of the single ball transition matrix satisfies $\Phi_{\ast}^{(n)} = \Omega(1)$. Then, for any $\varepsilon \in (0,1)$, we have
    \begin{equation}

        \lim_{n \rightarrow \infty} \frac{t^{(n)}_{\textup{mix}}(\varepsilon)}{mn t_{\textup{mix,\,single}}^{(n)}(1/\sqrt{n})} = 1,
    \end{equation}
    where $t_{\textup{mix,\,single}}^{(n)}(1/\sqrt{n})$ denotes the $(1/\sqrt{n})$-mixing time of the rate $1$ single ball chain. In particular, the sequence $\{\mathbf{X}^{(n)}\}_{n \in \mathbb{N}}$ exhibits cutoff. Moreover, the cutoff window is of size $O(n)$. Further, if $\mu_n$ is symmetric for each $n \in \mathbb{N}$, then the equality in (equation eqn:mix of the paper) continues to hold under the assumption that $\Phi_{\ast}^{(n)} = \Omega(n^{\alpha-1})$ for some $\alpha > 0$, with a cutoff window of size $O(n/\gamma_n)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lmm Wc of arXiv:2609.02682, 'LDP for tensor forms'] For \(W_\circ(\cdot,\cdot)\) defined in (equation Wcirc of the paper), none of the optimizers of
\[

\inf_{{\boldsymbol f}=(f,1-f):\  G_{W_\circ,\mathbf 1_1}(\boldsymbol f)=1/4}
\left\{
\int_0^1
f(u)\log \frac{f(u)}{p}
+
(1-f(u))\log\frac{1-f(u)}{1-p}
du
\right\}
\]
is a constant function. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 6 (Strong solution to Hamilton--Jacobi equation) of arXiv:2605.13512, '2605.13512'] Assume \ref{ass:pde-speed}. The limiting current $v(x,t)$, given by equation \eqref{eq:vdef}, is a solution to the Cauchy problem \eqref{eq:genHJ} with flux given by \eqref{eq:discoflux}, at all points $(x,t)$ that are differentiability points of $v(x,t)$ and continuity points of $\tilde c(x,-v(x,t))$. 

Furthermore, under Assumption \ref{ass:c0strong}
almost every $(x,t) \in \bR \times \bR_+$ is a differentiability point of $v(x,t)$ and continuity point of $\tilde c(x,-v(x,t))$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 20 (It\^{o} formula for cumulants) of arXiv:2609.03924, 'Beyond normal fluctuations in local laws for Wigner matrices'] For $p\in\N$ and $T>0$, let $X_{1,t},\ldots,X_{p,t}$, $t\in[0,T]$, be complex-valued diffusion processes defined on the same probability space, i.e.
\begin{equation}
\dif X_{j,t}=\mu_{j,t}\dif t + (\bm{\sigma}_t\dif B_t)_j,
\end{equation}
where $\mu_{j,t}\in\C$, $\bm{\sigma}_t\in\C^{p\times d}$ for some $d\in\N$, and $\dif B_t$ is the standard Brownian motion in $\R^d$. Assume that $X_{j,t}$ has all finite moments for all $j\in[p]$ and $t\in [0,T]$. Then it holds that
\begin{equation}
\frac{\dif}{\dif t}\kappa\left(\lbrace X_{j,t}\rbrace_{j\in[p]}\right) = \sum_{i=1}^p \kappa\left(\mu_{i,t},\lbrace X_{j,t}\rbrace_{j\in[p]\setminus\{i\}}\right) + \sum_{1\le i<h\le p}\kappa\left(\frac{\dif}{\dif t}[X_i,X_h]_t,\lbrace X_{j,t}\rbrace_{j\in[p]\setminus\{i,h\}}\right), 

\end{equation} 
for any $t\in [0,T]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:wishart_moment of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] Let $X$ be the real symmetric (or Hermitian) deformed Gaussian IRM–Wishart matrix from (equation eq:deformed-wishart of the paper), and fix nonnegative integers $m_1,\dots,m_s$.  For each face $D_j$, set $n_j \;=\;\sum_{e\in\partial D_j}w_e$,  then
\begin{multline}

\mathbb{E}\Bigl[\prod_{j=1}^s \mathrm{Tr} \big(X^{m_j}\big)\Bigr]
=
\sum_{\Gamma \in \mathscr{D}_{s;\beta}}
\;\sum_{\substack{\eta:V(\Gamma)\to [M]\cup[N]}}
\;\sum_{\substack{w_e \ge 1 \\ \sum_{e \in \partial D_j} w_e = n_j, \ \forall j}}
\;\Biggl[\,
\prod_{j=1}^s C_{\mathrm{MP}}(m_j,n_j)\;\Biggr]
\;\\ \times 
\Biggl[\,
\prod_{e=(x,y)\in E_{\mathrm{int}}}p_{w_e}\bigl(\eta(x),\eta(y)\bigr)
\;\prod_{e=(z,w)\in E_b}(A^{(w_e)})_{\eta(z)\eta(w)}
\Biggr].  
\end{multline}
Here
\begin{itemize}
  \item $E_{\mathrm{int}}$ (resp.\ $E_b$) denotes the set of interior (resp.\ open) edges of~$\Gamma$.
  \item For an open edge $e=(z,w)$, the matrix product $(A^{w_e})_{\eta(z)\eta(w)}$ means
    \begin{equation}
(A^{\,(w_e)})_{\eta(z)\,\eta(w)}
:=
\begin{cases}
(A\,A^*)^{w_e/2}, 
& z,w\in[N],\;w_e\text{ even},\\[6pt]
(A^*\,A)^{w_e/2}, 
& z,w\in[M],\;w_e\text{ even},\\[6pt]
A\,(A^*A)^{\frac{w_e-1}{2}},
& z\in[N],\;w\in[M],\;w_e\text{ odd},\\[6pt]
A^*\,(A\,A^*)^{\frac{w_e-1}{2}},
& z\in[M],\;w\in[N],\;w_e\text{ odd}.
\end{cases}
\end{equation}
  \item With  $\mu_k$ being     the $k$-th moment of the Marchenko–Pastur law  with   $\alpha=M/N$,  
    \begin{equation}
    C_{\mathrm{MP}}(m,n):
    = 
    \begin{cases}
      \mu_m, 
        & n=0, \\[6pt]
      \dfrac{m}{n}
\displaystyle\sum_{\substack{k_1+\cdots+k_n=m\\k_1,\ldots,k_n\ge1}}
      \prod_{i=1}^n \mu_{k_i},
        & 1\le n\le m, \\[6pt]
      0, & n>m.
    \end{cases}
    \end{equation}
\end{itemize}

