V_{A,\varepsilon}(w)^{k}
\nu_{A,\varepsilon}(z)^{l}\nu_{A,\varepsilon}(w)^{l}
G_{D\setminus A,\varepsilon,\varepsilon}(z,w)^{m}
\Big].
\end{multline*}

