[Lemma 19 of arXiv:2603.28093, 'Random Stability of Random Variables'] Pick a distribution $Q$ on $[0, \infty)$, and assume $G(Q) \ne \{1\}$ is nontrivial. Then let $N$ be any nontrivial random variable with distribution from $G(Q)$, and let $Y$ be the standard $N$-stable random variable. Then:
\begin{itemize} 
\item $\mathbb E[N\ln N] < \infty$ if and only if $\mathbb E[Y] < \infty$;
\item $\mathbb E[N\ln^{a+1} N] < \infty$ for a fixed $a > 0$ if and only if $\mathbb E[Y\ln^{a}Y] < \infty$;
\item $\mathbb E[N^k] < \infty$ for a fixed $k = 2, 3, \ldots$ if and only if $\mathbb E[Y^k] < \infty$. 
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:const_increm of arXiv:2412.03366, 'Regularity of Weighted Tensorized Fractional Brownian Fields and associated function space'] [ELLV]
For all {$\alpha \in [0,1]$ and $H \in (0,1)$}, there is a constant $c_1>0$ such that the rectangular increments of $\{X^{\alpha,H}_{(x_1,x_2)}\}_{(x_1,x_2) \in \mathbb{R}^2}$ satisfy 
$$ \mathbb{E}\big[ |\Delta  X^{\alpha,H}_{(h_1,h_2);(x_1,x_2)}|^2 \big]
  \,\,  \leq   c_1 \left(\max\{|h_1|,|h_2| \}^{1-\alpha}\min\{|h_1|,|h_2| \}^{1+\alpha}\right)^{2H}
$$
for all $(x_1,x_2),(h_1,h_2) \in \mathbb{R}^2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 23 of arXiv:2604.24684, 'Waning Immunity Fails to Restore a Positive Epidemic Threshold on Power--Law Networks'] Let $\bm d :=(d_i)_{i=1}^n$ be i.i.d.\ random variables with distribution
$
\mathbb{P}(d_i=k)=C_\tau\,k^{-\tau}\mathbf{1}\{k\ge 3\}
$, and let $F$ denote the corresponding distribution function. Write
$
d^{(1)}\ge d^{(2)}\ge \cdots \ge d^{(n)}
$
for the order statistics of $d_1,\dots,d_n$. Fix any
$
\varepsilon\in \left(0,\frac{1}{2\tau-1}\right),
$
and define
$c_1:=\left(\frac{C_\tau}{\tau-1}\right)^{\!\frac{1}{\tau-1}}5^{-\frac{1}{\tau-1}}$
, $c_2:=\left(\frac{C_\tau}{\tau-1}\right)^{\!\frac{1}{\tau-1}}8^{\frac{1}{\tau-1}}
$.
Let
$
\mu:=\mathbb E[d_1]
$,
and define the event
\begin{equation}
D_\varepsilon:=
\biggl\{
\forall i\in[\lceil n^\varepsilon\rceil ,n],\
c_1\left(\frac{n}{i}\right)^{\!\frac{1}{\tau-1}}
\le d^{(i)}\le
c_2\left(\frac{n}{i}\right)^{\!\frac{1}{\tau-1}}
\biggr\}\cap
\biggl\{
\biggl|\sum_{i=1}^n d^{(i)}-n\mu\biggr|\le \frac12 n\mu
\biggr\}.
\end{equation}
Then there exists a constant $c'>0$, depending only on $\tau$, such that, for all sufficiently large $n$,
\begin{equation}
\mathbb P(D_\varepsilon)\ge
\begin{cases}
1-c'n^{-(\tau-2)}, & \tau\in(2,3),\\[1mm]
1-c'(\log n)\,n^{-1}, & \tau=3,\\[1mm]
1-c'n^{-1}, & \tau>3.
\end{cases}
\end{equation}
Moreover, on the event $D_\varepsilon$, for every
$
i\in \bigl[\lfloor n^{1-2\varepsilon(\tau-1)}\rfloor,\,\lfloor n^{1-1.1\varepsilon(\tau-1)}\rfloor\bigr]
$,
one has
\begin{equation}
n^\varepsilon\le d^{(i)}\le n^{3\varepsilon}
\end{equation}
and there exist constants $C_1,C_2>0$, depending only on $\tau$, such that
\begin{equation}
C_1 n^{1-1.1\varepsilon(\tau-2)}
\le
\sum_{i=\lfloor n^{1-2\varepsilon(\tau-1)}\rfloor}^{\lfloor n^{1-1.1\varepsilon(\tau-1)}\rfloor} d^{(i)}
\le
C_2 n^{1-1.1\varepsilon(\tau-2)}.
\end{equation}

[Definition 3 (Iterative bipartite graph process) of arXiv:2608.07239, 'Unified framework for asymptotically uniform iterative construction of generalised random '] Consider the bipartite vertex set $V=A\cup B$ with $A=\{v_1,\ldots,v_n\}$ and $B=\{v_1',\ldots,v_{n'}'\}$, consider degree sequences $\d=(d_1,\ldots,d_n)$ and $\d'=(d_1',\ldots,d_{n'}')$ of non-negative integers with $m:=d_1+\ldots+d_n=d_1'+\ldots+d_{n'}'>0$, and consider a set $X$ of forbidden edges.
		\begin{itemize}
			\item Start with no edges $E_0=\emptyset$.
			\item For $r=0,\ldots,m-1$, let $d_{i,r}$ and $d_{j,r}'$ denote the degrees of vertices $v_i$ and $v_j'$ in $(V,E_r)$, and consider those pairs of vertices $(v_i,v_j')\in A\times B$ with $d_{i,r}<d_i$, $d_{j,r}'<d_j'$, and $(v_i,v_j')\not\in E_r\cup X$.
			\begin{itemize}
				\item If no such pairs exist, let $E_{r+1}=E_r$.
				\item Otherwise, choose such a pair $(v_i,v_j')$ at random with probability proportional to $(d_i-d_{i,r})(d_j'-d_{j,r}')(1-\tfrac{d_id_j'}{2m})$, and let $E_{r+1}=E_r\cup\{(v_i,v_j')\}$.
			\end{itemize}
			\item Finally, apply rejection sampling to sample $E=E_m$ with $m$ edges.
		\end{itemize}
		This guarantees that $(V,E)$ is a simple bipartite graph with degree sequences $\d$ and $\d'$ on its parts and with no edges from $X$.

[Thm mainconvergence of arXiv:2411.12149, 'Airy limit for $\beta$-additions through Dunkl operators'] Fix $\mathbf{k}_{1},\ldots,\mathbf{k}_{l}>0$. Let $M_{1},\ldots,M_{l}$ be sequences of positive integers depending on $N$ such that \[\left|M_{p}-\mathbf{k}_{p}N^{2/3}\right|<C\] for some constant $C>0$ uniform in $N$ and $p=1,2,\ldots,l$. Take the sequence of ensembles in Eqn.~((eq_betaaddition of the paper)) satisfying the assumptions in Theorem (thm:main of the paper), with limiting parameters $P_{-1}$, $\sigma$. Then as $N\rightarrow\infty$,
 \begin{align*}
&\mathbb{E}\left[\prod_{p=1}^{l}\left(\sum_{i=1}^{N}\left(\frac{\lambda_{i}}{\mu_{+}(N)N}\right)^{M_{p}}\right)\right]
\rightarrow \mathbf L_\beta(\left(2P_{-1}\sigma\right)^{-2/3}\vec\mathbf{k}, \vec\boldsymbol{\tau}=0) .
 \end{align*}

