[Theorem thm:rmulmc_cvx of arXiv:2506.23062, 'Shifted Composition IV\@: \\ Toward Ballistic Acceleration for Log-Concave Sampling'] Let $\hat{\boldsymbol{P}}$, $\hat{\boldsymbol{P}}{}'$ denote the kernels for~(eq:rm-ulmc of the paper) and~(eq:ULMC of the paper) respectively, and let $\boldsymbol{P}$ denote the kernel for~(eq:ULD of the paper) run for time $h$.
    Assume that $0 \preceq \alpha I \preceq \nabla^2 V \preceq \beta I$ and set $\gamma = \sqrt{32\beta}$.
    Write $W^2 \coloneqq \mathcal{W}_2^2(\bs\mu,\bs\pi)$, where $\mathcal{W}_2$ denotes the $2$-Wasserstein distance in the twisted norm $(x,p) \mapsto \sqrt{\norm x^2 + \gamma_0^{-2}\,\norm p^2}$.
    \begin{enumerate}
        \item \underline{$\alpha > 0$ case:} If $\varepsilon \in (0, \widetilde O(\frac{d^{1/2}}{\kappa^{3/2}})]$ and $h = \widetilde{\Theta}( \frac{\varepsilon^{2/3}}{\beta^{1/2} d^{1/3}})$, then $\KL(\bs\mu \hat{\boldsymbol{P}}{}^{N-1}\hat{\boldsymbol{P}}{}' \mathbin{\|} \bs\pi) \leqslant \varepsilon^2$ for all
        \begin{align*}
            N = \widetilde{\Omega}\Bigl(\frac{\kappa d^{1/3}}{\varepsilon^{2/3}} \log \frac{\alpha W^2}{\varepsilon^2}\Bigr)\,.
        \end{align*}

        \item \underline{$\alpha = 0$ case:} If $\varepsilon\in  (0,\widetilde O(\frac{\beta^{3/4} W^{3/2}}{d^{1/4}})]$ and $h = \widetilde{\Theta}(\frac{\varepsilon}{\beta^{3/4} d^{1/4} W^{1/2} + \beta W})$, then $\KL(\bs\mu\hat{\boldsymbol{P}}{}^{N-1}\hat{\boldsymbol{P}}{}' \mathbin{\|} \bs\pi) \leqslant \varepsilon^2$ for
        \begin{align*}
            N = \widetilde{\Theta}\Bigl(\frac{\beta^{5/4} d^{1/4} W^{5/2} + \beta^{3/2} W^3}{\varepsilon^3}\Bigr)\,.
        \end{align*}
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 122 ({\cite{KO,RT,LTDMLS}}) of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] For any indices $i, j \in \{ x, y \}$, there exists $\mathfrak{a}_{ij} : \mathcal{T} \rightarrow \mathbb{R}$
                satisfying $\mathfrak a_{xy}=\mathfrak a_{yx}$ as well as the following two statements:
		\begin{enumerate} 
			\item For any $z \in \mathfrak{L}_{q;a,b,c}$, we have 
			\begin{flalign}
                          \displaystyle\sum_{i,j \in \{ x, y \}} 	\mathfrak{a}_{ij} (\nabla \mathcal{H}_{q;a,b,c} (z)) \cdot \partial_{ij} \mathcal{H}_{q;a,b,c} (z) = -q.

			\end{flalign}

			\item For any $\omega > 0$, there exists a constant $C = C(\omega) > 1$ such that the following holds. Whenever $\gamma\in\mathcal T$ with  $\dist (\gamma, \partial \mathcal{T}) \ge \omega$, we have
			\begin{flalign*} 
				C^{-1} \le \mathfrak{a}_{xx} (\gamma) \le C; \qquad |\mathfrak{a}_{xy} (\gamma)| \le C; \qquad C^{-1} \le \mathfrak{a}_{yy} (\gamma) \le C.
			\end{flalign*} 

		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 19 of arXiv:2609.03713, 'A Sharp Mass Threshold for Boundedness in a Critical Quasilinear Chemotaxis Model with Ind'] The function $\phi$ obeys the inequalities
\begin{equation}
	s\phi'(s)\le m\phi(s) +\phi''(1)(s-1)\,,\quad s> 0\,,
\end{equation}
and
\begin{equation}
	\frac{m}{m-1}(s^{m-1}-1)\le \phi'(s)\le \frac{m 2^{m-1}}{m-1} (s^{m-1}-1)\,,\quad s\ge 1\,,
\end{equation}
with $\phi'(s)<1$ for $s\in (0,1)$.

