body:
[Theorem 2 of arXiv:2607.22878, 'Clustering of large deviations in heavy-tailed moving averages: the catastrophe principle '] Suppose that both $\Gamma$ and $\Psi$ satisfy
Assumption~\ref{ass:tail_measure}. 
Then for any $\theta_1,\theta_2>0$,
\begin{equation}
\begin{aligned}
    &\lim_{n\to\infty} 
    \PP\big(J_n^{\Psi,+} > n\theta_1,\, J_n^{\Psi,-} < -n\theta_2 \,\big|\, E_0(n,\Gamma)\big) \\
    &\quad= 
    \frac{\int_{-\infty}^\infty  \;
        \nu\!\Big(B_y^{-1} \Gamma \cap \bigcap^*_{-\theta_2\le t \le \theta_1} \!\!  B_{y-t}^{-1}\Psi\Big) dy}
        {\int_{-\infty}^\infty \nu(B_y^{-1} \Gamma) \,dy},
\end{aligned}
\end{equation}
where $\cap^*_{t\in A}$ stands for the intersection over all rational
$t\in A$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 21 of arXiv:2604.27242, 'Statistical Inference for Homogenization Limits Driven by Wiener or Hermite Processes'] The following asymptotics hold as \(N\) grows
\begin{enumerate}
    \item If \(\alpha\in(-1,0)\): \begin{equation}
        \f{1}{N}\sum_{k=1}^{N-1}(1-k/N)(k/N)^{\alpha} \sim \f{1}{\alpha+1} - \f{1}{\alpha+2}
    \end{equation}
    \item If \(\alpha = -1\): \begin{equation}
        \f{1}{N}\sum_{k=1}^{N-1}(1-k/N)(k/N)^{-1} = \log(N) + \gamma - 1 + \frac{1}{2N} + o(N^{-2})
    \end{equation}
    \item If \(\alpha<-1\): \begin{equation}
        \f{1}{N}\sum_{k=1}^{N-1}(1-k/N)(k/N)^{\alpha} \sim \zeta(-\alpha)(1/N)^{\alpha+1}
    \end{equation}
    where \(\zeta(\cdot)\) is the Riemann zeta function.
\end{enumerate}

