body:
[Lemma lem:compute:P:e of arXiv:2607.04047, 'Top Singular Value in Sum-Products of Random Matrices'] Suppose $x_0 = \Theta(1)$. The following bounds hold:
\begin{align*}
    P(\mathcal{B}_{j^\#})  \, e^{y_{j^\#,-}}
    \;=&\;
    (1+o(1))
    \,
    \exp\Big( - \mfrac{\delta_\#^2}{2}   
    +
    \mfrac{\beta^2 \log m}{2} 
     + o(\sqrt{\log m}) \Big)
    \;,
    \refstepcounter{equation}\tag{\theequation} 
    \\
    \mfrac{
        P(\mathcal{B}_0)
        \,
        e^{y_{0,-}}
     }{P(\mathcal{B}_{j^\#})  \, e^{y_{j^\#,-}}}
     \;=&\;
     O\Big( \exp\Big(  \mfrac{\delta_\#^2}{2}   
    -
    \mfrac{\beta^2 \log m}{2} 
     + o(\sqrt{\log m}) \Big) \Big)
     \;,
     \\
    \mfrac{
        P(\mathcal{B}_j)
        \,
        e^{y_{j,-}}
     }{P(\mathcal{B}_{j^\#})  \, e^{y_{j^\#,-}}}
   \;=&\;
    O\Big(
        \exp\Big( 
            - \mfrac{y_{j,+}^2}{2 \beta^2 \log m} 
            -
            \mfrac{\beta^2 \log m}{2} 
            + 
            \mfrac{\delta_\#^2}{2}   
            +
            o(\sqrt{\log m})
        \Big) 
    \,\Big)
    \quad
    \text{ for } j \leq -1 \;,
    \\
    \mfrac{
        P(\mathcal{B}_j)
        \,
        e^{y_{j,-}}
     }{P(\mathcal{B}_{j^\#})  \, e^{y_{j^\#,-}}}
    \;=&\;
     \Theta\Big( 
        \exp\Big( 
            - \mfrac{(y_{j,-} - \beta^2 \log m)^2}{2 \beta^2 \log m} 
            +
            \mfrac{\delta_\#^2}{2}    
            +
            o(\sqrt{\log m})
        \Big) 
    \Big)
    \quad
    \text{ for } j \geq 1 \text{ and } j \neq j^\# \;.
\end{align*}

