body:
[Lemma lem:budget of arXiv:2608.07842, 'Resolution of a Conjecture on Shifted R\'enyi Divergence'] Let $D$ be a scalar $N(a,\tau^2)$ variable with $2\tau^2<w^2$. Then
$$\mathbb{E}\exp(D^2/w^2)=\Big(1-\frac{2\tau^2}{w^2}\Big)^{-1/2}\exp\Big(\frac{a^2}{w^2-2\tau^2}\Big),$$
so $\mathbb{E}\exp(D^2/w^2)=2$ iff
\begin{equation}
a^2=(w^2-2\tau^2)\Big(\log 2+{\tfrac12}\log\Big(1-\frac{2\tau^2}{w^2}\Big)\Big).
\end{equation}

[Lemma 39 of arXiv:2511.07350, 'Decoupling of clusters in independent sets in a percolated hypercube'] The following approximations hold for $\Phi_{\log}$.
\begin{enumerate}[(a)]
    \item
    For all $p \in (0,1)$, we have
    \begin{equation}
        \Var(\Phi_{\log}) = \sigma^2 (1 + o(1))
    \end{equation}
    \item 
    For $p > 0.455$, we have
    \begin{equation}
        \E[\Phi_{\log}] = \mu_1^1 - \fr{\mu_1^2}{2} + \fr{\mu_1^3}{3} + o(\sigma)
    \end{equation}
\end{enumerate}

