[Theorem thm:codiff of arXiv:2606.02003, 'Higher-Order Multifractional Stable Motion:\\ Definition and Fundamental Properties'] Under Assumption~(ass:params of the paper), for any $s, t \in \mathbb{R}$:
\begin{equation}

\tau\!\bigl(X^{(n)}_H(s),\, X^{(n)}_H(t)\bigr)
= \int_\mathbb{R}
\bigl[|f_n(s,u)|^\alpha + |f_n(t,u)|^\alpha
- |f_n(s,u) - f_n(t,u)|^\alpha\bigr]\,du.
\end{equation}

[Lem 6 of arXiv:2510.22783, 'Universality of Cutoff for Riffle Shuffling'] Let $X\sim \Hyp(n_1,n,m)$ with $\mathbb EX=\frac{n_1m}{n}\geq 10$. There exists absolute constants $C,c$ such that for all $\delta<1/2$,
		\begin{equation} 
			\mathbb P(|X-\mathbb E X|\geq (\mathbb EX)^{1/2+\delta})\leq C\exp(-c(\mathbb EX)^{2\delta}).
		\end{equation}

[Definition 6 (\cite{paper1}) of arXiv:2609.01114, 'Unbalanced spectral Tur\'an problem for color-critical graphs with prescribed large maximu'] For a graph $F$ with $\chi(F)=r+1\geq 3$, define
	\begin{equation*}
		a(F):=\min\{|I|: I\subseteq V(F)\text{ is independent and }\chi(F-I)\le r\}.
	\end{equation*}
	If $a(F)=1$, the graph $F$ is called singleton-boundary.

[Theorem 7 of arXiv:2608.30561, '\Large Informative Label Missingness in Multiclass Classification: Information Geometry an'] Under the conditions above,
\begin{equation}
