[Cor ST0 of arXiv:2609.01751, 'Orthogonal polynomials which are eigenfunctions of a partial differential operator'] Let ${\kappa}_1,\ldots, k_{d_2} > -1$. The spectral operator ${\mathfrak D}_{-1, {\boldsymbol{\kappa}}}^{{\mathbb S} \rtimes \triangle}$ can be written as 
\begin{align} 
  {\mathfrak D}_{-1, {\boldsymbol{\kappa}}}^{{\mathbb S} \rtimes \triangle} & = \frac{1}{1-|\bm y|} \Delta_0^{(\bm x)} 
      + \frac{1}{{\mathsf W}_{-1,{\boldsymbol{\kappa}}}^{{\mathbb S} \rtimes \triangle}(\bm y)} 
        \sum_{1\le i< j \le d_2} y_i y_j (\partial_{y_i} - \partial_{y_j}) {\mathsf W}_{-1,{\boldsymbol{\kappa}}}^{{\mathbb S} \rtimes \triangle}(\bm y)
   (\partial_{y_i} - \partial_{y_j}) \notag \\
   & +  \frac{1}{(1-|\bm y|)^{d_1-1}} \frac{1}{{\mathsf W}_{-1,{\boldsymbol{\kappa}}}^{{\mathbb S} \rtimes \triangle}(\bm y)}  \sum_{i=1}^{d_2}  
\partial_{y_i} (1-|\bm y|)^{d_1} y_i {\mathsf W}_{-1,{\boldsymbol{\kappa}}}^{{\mathbb S} \rtimes \triangle}(\bm y) \partial_{y_i}. 

 \end{align}
In particular, it follows that 
\begin{align}  
   & - \int_{{\mathbb S}^{d_1-1} \!\rtimes \triangle^{d_2}}{\mathfrak D}_{-1, {\boldsymbol{\kappa}}}^{{\mathbb S} \rtimes \triangle}f (\bm x,\bm y) \cdot g(\bm x, \bm y)
     {\mathsf W}_{-1, {\boldsymbol{\kappa}}}^{{\mathbb S} \rtimes \triangle}(\bm x, \bm y) \mathrm{d} \sigma(\bm x, \bm y)  \\ 
  &   =  \int_{{\mathbb S}^{d_1-1} \!\rtimes \triangle^{d_2}}  \frac{1}{1-|\bm y|} 
      \sum_{1 \le i< j \le d_1}  D_{i,j}^{(\bm x)} f(\bm x, \bm y)  D_{i,j}^{(\bm x)} g(\bm x, \bm y) 
  {\mathsf W}_{-1,{\boldsymbol{\kappa}}}^{{\mathbb S} \rtimes \triangle}(\bm x,\bm y)  \mathrm{d} \sigma(\bm x, \bm y)    \notag \\ 
  & + \int_{{\mathbb S}^{d_1-1} \!\rtimes \triangle^{d_2}}   \sum_{1\le i< j \le d_2} (\partial_{y_i} - \partial_{y_j}) f(\bm x,\bm y) \cdot 
    (\partial_{y_i} - \partial_{y_j})g(\bm x,\bm y)
  {\mathsf W}_{-1, {\boldsymbol{\kappa}}}^{{\mathbb S} \rtimes \triangle}(\bm x,\bm y)  \mathrm{d} \sigma(\bm x, \bm y)    \notag \\
    &  +  \int_{{\mathbb S}^{d_1-1} \!\rtimes \triangle^{d_2}} \sum_{i=1}^{d_2} y_i (1-|\bm y|)  \partial_{y_i} f(\bm x,\bm y) \partial_{y_i} g(\bm x,\bm y) 
       {\mathsf W}_{-1,{\boldsymbol{\kappa}}}^{{\mathbb S} \rtimes \triangle}(\bm x,\bm y)   \mathrm{d} \sigma(\bm x, \bm y).  \notag
 \end{align}

