[Prop 34 of arXiv:2607.13849, 'Rearranged Stochastic Heat Equation with an Entropy Gradient Structure'] For any smooth mean-field function $\psi: \mathcal{P}_2(\mathbb{R})\rightarrow \mathbb{R}$ with bounded, and Lipschitz continuous derivatives 

$\partial_{\mu}\psi : \mathcal{P}(\mathbb{R})\times \mathbb{R} {\rightarrow} \mathbb{R}$, $\nabla_y\partial_{\mu}\psi : \mathcal{P}(\mathbb{R})\times \mathbb{R} {\rightarrow}  \mathbb{R}$, $\partial_{\mu}^2\psi : \mathcal{P}(\mathbb{R})\times \mathbb{R} \times \mathbb{R} {\rightarrow}  \mathbb{R}$ with $\mathcal{P}(\mathbb{R})$ equipped with the $2\text{-Wasserstein}$ distance, the following holds with probability one

    \begin{equation}
    \begin{split}
        \psi(\mu_t) &= \psi(\mu_0) +\frac{1}{2}\int_0^t\int_{\mathbb{S}}\nabla_y\partial_{\mu}\psi(\mu_s,X_s(\mathbf{x}))\mathrm{d}\mathbf{x}\mathrm{d}s  \\
        &\quad -\int_0^t\int_{\mathbb{S}}\nabla_y\partial_{\mu}\psi(\mu_s,X_s(\mathbf{x}))[DX_s(\mathbf{x})]^2\mathrm{d}\mathbf{x}\mathrm{d}s
        +\frac{1}{2}\int_0^t\int_{\mathbb{S}}\nabla_y\partial_{\mu}\psi(\mu_s,X_s(\mathbf{x}))G_1(\mathbf{x})\mathrm{d}\mathbf{x}\mathrm{d}s \\
        &\quad  + \frac{1}{2}\int_0^t\int_{\mathbb{S}}\int_{\mathbb{S}}\partial_{\mu}^2\psi(\mu_s,X_s(\mathbf{x}),X_s(\mathbf{x}'))G_2(\mathbf{x},\mathbf{x}')\mathrm{d}\mathbf{x}\mathrm{d}\mathbf{x}'\mathrm{d}s +\int_0^t\int_{\mathbb{S}}\partial_{\mu}\psi(\mu_s,X_s(\mathbf{x}))\mathrm{d}W_s(\mathbf{x}),
        \end{split}
    \end{equation}
where $\mu_t:= \mathrm{Leb}_{\mathbb{S}}\circ X^{-1}_t$ and $X_t$ is the solution to \eqref{eq:4.28} and the functions $G_1$ and $G_2$ are given below:
    \begin{align}
        G_1(\mathbf{x}):= \sum_{k\in \mathbb{N}}\lambda_k^2e_k^2(\mathbf{x}), \quad G_2(\mathbf{x},\mathbf{x}'):= \sum_{k\in \mathbb{N}}\lambda_k^2e_k(\mathbf{x})e_k(\mathbf{x}'), \quad \forall \mathbf{x},\mathbf{x}' \in \mathbb{S}.
    \end{align}
and the noise $(W_t)_{t\geq 0}$ is given by \eqref{eq:noise:1.8}. (Proof in the paper; no proof environment follows the statement in the TeX.)

