[Corollary 29 (Equivalent modified formulations) of arXiv:2607.26377, '\textbf{Entire Logarithmic Signatures\\ of Bounded-Variation Paths in Finite Dimensions}'] Let $V$ be a finite-dimensional real normed space, let $\gamma:[0,T]\to V$ be a continuous tree-reduced bounded-variation path, and put $v=\gamma_T-\gamma_0$. If $v\neq0$, then the following formulations are equivalent:
\begin{enumerate}[label=\textup{(\roman*)}]
\item centred weak path conjugacy to a line in the sense of \cref{def:two-conjugacies};
\item conjugacy to $\e^v$ in the reduced bounded-variation path group;
\item a signature identity $S(\gamma)=a\e^v a^{-1}$ with $a\in\Sl(V)$.
\end{enumerate}
When $v=0$, the corresponding formulations all reduce to the constant reduced path. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 4 of arXiv:2605.09459, 'Multipoint connectivity in the branching interlacement process'] For $d \geq 9$, and $k \geq 3$. Let
  \begin{equation}

    n(k,d) = \left\lceil\frac{d(k-1)}{4}\right\rceil - (k-2).
  \end{equation}
  Assume that the reproduction law is a mean $1$ distribution with finite $2\lceil d(k-1)/4\rceil$  moment, and that the jump law is centered, has finite range and its support does not generate any strict subgroup of $\mathbb{Z}^d$. Then almost surely, for every $k$ points of the interlacement, there exist $n(k,d)$ trajectories of the interlacement that connect them. Futhermore, almost surely, there exist $k$ points of the interlacement that are not connected using less than $n(k,d)$ trajectories. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 8 (Minimal primitive support) of arXiv:2608.12492, 'Weak Limits of Wiener Chaos: Primitive--Fock Classification and Hilbert--Stein Extraction'] For $1\le s\le Q$, define
\begin{equation}
 \cS_s(F)
 =\ol{\Span}
 \left\{
 \Ran\mathscr L_{a,q,\bm m}^{(s)}:
 1\le a\le d,\ q\le Q,\ m_s\ge1
 \right\}\subset E_s.

\end{equation}
Put $\cS(F)=\bigoplus_{s\le Q}\cS_s(F)$.

[Corollary cor:ordered-generic-type-diversity of arXiv:2609.01690, 'Iterated-sumset spectra: The complete exponent law and its rank geometry'] For each fixed $k\geq3$, as $h\to\infty$, both the number of realized ordered
$h$-addition-table types and the number of realized generic $B_h$-types
are
\begin{equation}
 \Theta_k\!\left(h^{(k-1)(k-2)}\right).
\end{equation}

[Defi defi28 of arXiv:2412.08497, 'Time discretization of Quadratic Forward-Backward SDEs with singular drift'] A real valued  adapted right continuous process with left limits $(V_t)_{t\in [0,\tau]}$ is called a bounded mean oscillation $(\operatorname{BMO})$ if 
				\begin{align*}
					[V]_{\operatorname{BMO}}:= \sup_{0\leq s\leq S\leq S'\leq \tau}\|\mathbb{E}[|V_{S'}-V_{S-}|/\mathfrak{F}_{ S}]\|_{\infty} <\infty,
				\end{align*}
				where the supremum is taken over all the stopping times $S,S'$; $V_{S-} =\lim_{r\uparrow S}V_r$ and we set $V_{0-} =V_0$, by convention.

[Definition 28 (Types of nodes) of arXiv:2606.17452, 'Optional Stopping for Superhedging Supermartingales'] Given a trajectory space $\Se$ and a node $(S,j)$:
	\begin{itemize}
		\item $(S,j)$ is called an \emph{up-down node} if
		\begin{equation} 
			\sup_{\tilde{S} \in \Se_{(S, j)}}~~ (\tilde{S}_{j+1} - S_{j}) >    0\quad \mbox{and}\quad
			\inf_{\tilde{S} \in \Se_{(S, j)}} ~~(\tilde{S}_{j+1} - S_{j}) <    0.
		\end{equation}
		\item $(S,j)$ is called a \emph{flat node} if
		\begin{equation} 
			\sup_{\tilde{S} \in \Se_{(S, j)}}~~ (\tilde{S}_{j+1} - S_{j}) =    0 =
			\inf_{\tilde{S} \in \Se_{(S, j)}} ~~(\tilde{S}_{j+1} - S_{j}).
		\end{equation}
	\end{itemize}
	\noindent $(S, j)$ is called an arbitrage-free node if (\ref{upDownProperty}) or (\ref{flat}) hold, otherwise it
	is called an \emph{arbitrage node}. An arbitrage node $(S, j)$ is said to be of \emph{type I}, if there exists $\hat{S}\in\Se_{(S, j)}$	such that $\hat{S}_{j+1} = S_j$; otherwise it is said to be of \emph{type II}.

[Lemma lem:brownian-ball-localization of arXiv:2609.02829, 'Quantitative explosion and percolation of the divisible sandpile'] Assume $d<4$. For every $0<T<\infty$ there are $C=C(d)>0$ and $c=c(d)>0$
	such that, for every $A\geq1$ and every compact $K\subset\mathbb{R}^d$,
	\[
		\sup_{u\in K}
		\bigl(\mathcal U_Z(T,u)-\mathcal U_{Z,A}(T,u)\bigr)
		\leq
		Ce^{-cA^2/T}
		\sup_{\substack{z\in\mathbb{R}^d:\\ \inf_{y\in K}|z-y|\leq A}}
		\mathcal U_Z(T,z)\, .
	\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 43 of arXiv:2608.12947, 'Branch-stationary max-stable fields on rooted trees'] Assume (equation 42 of the paper) and define the law of a random field
\(Z^{Q,\pi}\) on \(\mathcal T\) by
\begin{equation}
  \Ehat{H(Z^{Q,\pi})}
  =
  \frac1{c_Q}
  \sum_{g\in\mathbb G}
  \E*{
    \rho_\pi(Q^{[g]})^\alpha
    H\left(
      \frac{Q^{[g]}}{\rho_\pi(Q^{[g]})}
    \right)
  }, \qquad H \in \mathfrak H.

\end{equation}  On
\(\{\rho_\pi(Q^{[g]})=0\}\), the ratio in
(equation 44 of the paper) may be defined arbitrarily and the
corresponding summand is understood to be zero. If
\(\widehat{\mathbb P}_\pi\) stands for the resulting probability measure,
then:
\begin{enumerate}[(i)]
\item (equation 44 of the paper) is a probability law,
\[
  \rho_\pi(Z^{Q,\pi})=1
  \quad\text{almost surely},
  \qquad
  \Ehat{(Z_v^{Q,\pi})^\alpha}=1,
  \quad v\in\mathcal T;
\]
in particular, \(Z^{Q,\pi}\neq\mathbf 0\) almost surely;
\item \(Z^{Q,\pi}\) is almost surely \(\alpha\)-summable, i.e.,
\[
  \sum_{v\in\mathcal T}(Z_v^{Q,\pi})^\alpha<\infty;
\]
\item for every \(F\in\mathfrak H_\alpha\),
\begin{equation}
  \Ehat{F(Z^{Q,\pi})}
  =
  \frac1{c_Q}
  \sum_{g\in\mathbb G}\E{F(Q^{[g]})}.

\end{equation}
Consequently, \(Z^{Q,\pi}\) is branch-BR stationary, and its
homogeneous class does not depend on \(\pi\);
\item its tail measure is
\begin{equation}
  \nu_Q(A)
  =
  \frac1{c_Q}
  \sum_{g\in\mathbb G}
  \int_0^\infty
  \mathbb P\{rQ^{[g]}\in A,\ Q^{[g]}\neq\mathbf 0\}
  \alpha r^{-\alpha-1}\mathrm d r,
  \qquad A\in\mathcal B(\mathcal F),

\end{equation}
and satisfies
\begin{equation}
  \nu_Q\bigl((B^u)^{-1}A\bigr)
  =
  \nu_Q(A),
  \qquad
  A\in\mathcal B(\mathcal F^\circ),\quad u\in\mathcal T;

\end{equation}
\item the root spectral tail field \(\Theta^Q\) is independent of
\(\pi\) and satisfies
\begin{equation}
  \E{H(\Theta^Q)}
  =
  \frac1{c_Q}
  \sum_{g\in\mathbb G}
  \E*{
    \mathbf 1_{\{Q_g>0\}}
    Q_g^\alpha
    H\left(
      \left(\frac{Q_{gv}}{Q_g}\right)_{v\in\mathcal T}
    \right)
  }, \qquad F\in\mathfrak H.

\end{equation}
The summand is understood to be zero on \(\{Q_g=0\}\). In particular, $
  \mathbb P\{\sum_{v\in\mathcal T}(\Theta_v^Q)^\alpha<\infty\}=1$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 30 of arXiv:2609.03821, 'Condensation and Metastability in the Supercritical Two-Species Zero-Range Process via Res'] For each $x\in S_{\star}$,
\begin{equation}
\langle\!\langle F_{N},-\mathcal{L}^{*}_{N}\mathbb{W}_{x}\rangle\!\rangle_{\mathcal{A}^{{\rm bulk}}_{N-1}}=o(\theta^{-1}_{N}).
\end{equation}

[Definition 108 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] Recalling the definition of $k$ from \eqref{eq:h0new}, set 
	\begin{flalign*}
		x^{\pm} =\bar{x} \pm N^{B\delta/9} \td_{\bar{z}}
	\end{flalign*} 

	\noindent and let ${\bf L}^{\pm}$ denote the line parallel to the $y$-axis and with $x$-coordinate $x^\pm$.

[Lem lemma: weight of all possible pinchings is 1 of arXiv:2411.11676, 'Surface sums for lattice Yang--Mills in the large-$N$ limit'] Fix a blue face $B$ with disjoint vertices. 
Then
\begin{equation}
	\sum_{B'\in \AF(B)}w_{\infty}(B')=1,
\end{equation}
where if $B'$ has multiple faces $\{B'_i\}_{i=1}^k$, we set $w_{\infty}(B'):= \prod_{i=1}^kw_{\deg(B'_i)/2}$.
As a consequence, if $M\in\mathcal{N}\mathcal{P}\mathcal{M}(s,K)$ is a non-separable planar embedded map and $B$ is one of its blue faces, then 
\begin{equation}
	\sum_{M'\in \AM(M,B)}w_{\infty}(M') = \prod_{f\in \BF(M)\setminus \{B\}}w_{\deg(f)/2},
\end{equation}
where we recall $\BF(M)$ is the set of blue faces of $M$.

