    \begin{equation}

    M(t,x) =  \int_0^t v(r,Z_r+x)\,dr - \sum_{\ell=2}^{\infty} \E\Big[\int_{(\ell-1) h}^{\ell h \land t} v(r,Z_r+x)\,dr \,\Big|\, \mathcal{F}_{(\ell-2)h}\Big].
