[Lemma lem:d4-difference-tail of arXiv:2609.02829, 'Quantitative explosion and percolation of the divisible sandpile'] There are constants $A_0,c,C\in(0,\infty)$ such that, for all
			$t\geq2$ and all $x\in\mathbb{Z}^4$,
			\begin{equation}
				\mathbb{E}\left[
				\exp\left\{
				c\bigl(u_t(x)-V_t(x)-A_0\log(t+2)\bigr)_+
				\right\}
				-1
				\right]
				\leq C(t+2)^{-2}\, .
			\end{equation}

[Proposition 30 of arXiv:2608.02927, 'Thinning Operation via the Poisson-F\"ollmer Process'] Let $X$ have density $f$ with respect to $\pi_{T}$ and $H(T_{1-a} (X) | \pi_{(1-a)T} ) < \infty$ for some $a < 1.$ Then 
    \begin{displaymath}
        \E_{\pi_{aT}} \Psi \big( P_{T(1-a)} f , DP_{T(1-a)} f \big) < \infty.
    \end{displaymath}
    Moreover, if $H( X | \pi_{T} ) < \infty,$ then 
    \begin{displaymath}
        \E_{\pi_{t}} \Psi \big( P_{T (1-a) } f , DP_{T (1-a) } f \big) < \infty
    \end{displaymath}
    for all $ a < 1.$

