[Theorem thm:main of arXiv:2609.03855, 'A Fejér--Riesz inequality for Dirichlet series'] There is a constant $C_0 >0$ such that 
\begin{equation}
 \int_0^1 |f(1/2+\sigma)|\,d\sigma\le C_0\|f\|_{\mathscr H^1}, \qquad f \in \mathscr H^1.
\end{equation}
Therefore, there is a constant $C_0' > 0$ such that
\begin{equation}
 \left|a_1+\sum_{n=2}^\infty \frac{a_n}{\sqrt n\log n}\right|
 \le C_0' \|f\|_{\mathscr H^1}, \qquad f \in \mathscr H^1.
\end{equation}
The sum in (equation eq:hardy of the paper) is convergent. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 41 (Intrinsicity of the four-copy functional) of arXiv:2608.12492, 'Weak Limits of Wiener Chaos: Primitive--Fock Classification and Hilbert--Stein Extraction'] The quantity in \eqref{bridge:eq:four-copy-functional} is finite,
nonnegative, and independent of the bounded representative $(f_n)$.
It is continuous on bounded subsets of $\cH_q$.  If
$
 T=\mathbb U_q^{-1}\xi
$
is the primitive--Fock terminal, then
\begin{equation}
 \boxed{\mathfrak Q_q(\xi)=\kappa_4(T).}

\end{equation}

[Lemma 12 of arXiv:2511.10814, '\Large \bf \boldmath\ \\ Convergence of the extended Kalman filter with small and state-de'] Let $\widetilde{W}(t)$ be a $\mathbb{F}$-Brownian motion with values in $\mathbb{R}^{r}$, $n \in \mathbb{N}$, and let $A$ be a family of $\mathbb{F}$-adapted $(\K, k)$-stable processes where $\K$ is $\mathbb{F}$-adapted  and $k$ is  some family of deterministic positive and  locally bounded  functions. We suppose that $\x(t)$ is a family of $\mathbb{R}^{n}$-valued semi-martingales satisfying
				\begin{equation}
					d\x(t)=A(t)\x(t)dt + F(t)dt + D(t)d\widetilde{W}(t), 
				\end{equation}
				where $F(t)$ and $D(t)$ are  $\mathbb{F}$-adapted processes satisfying   for some $ \a \in [0,1/2) $ 
				\begin{align} 
					\x^{\top}(t)\K^{-1}(t)F(t) &\leq           ~   \a k(t)\x^{\top}(t)\K^{-1}(t)\x(t) + \mathcal{O}(k(t)), \\
					D^{\top}(t)\K^{-1}(t)D(t) &=~ \mathcal{O}(k(t)).
				\end{align}	
				If $\x^{\top}(0)\K^{-1}(0)\x(0)$ is bounded in $L^{q}$, 		
				then for any $q\geq 1$ and $\eps$ small enough,  the process\\ $\x^{\top}(t)\K^{-1}(t)\x(t)$ is  bounded in $L^{q}$.

[Lemma lem:displacement2 of arXiv:2608.26765, 'Beyond Client Averaging: A Client-Independent Second-Order Stationary-Bias Component in St'] For every $h\in\{0,\ldots,H\}$,
\begin{equation}

  \frac1N\sum_{c=1}^N\mathbb{E}[(\theta_{c,h}-x)^2]\le C_H\gamma^2.
\end{equation}

[Theorem thm:qua of arXiv:2412.05142, 'Strong convergence of the Euler scheme for singular kinetic SDEs driven by $\alpha$-stable'] For any $\beta\in(1-\frac{\alpha}{2},(\alpha-1)(1+\alpha))$ and any $0<\epsilon<\frac{1}{2}+\frac{(\beta-1)}{\alpha}$ there exists a constant $N=N(\alpha,\beta,d,\|b\|_{{\mathbb C}_{\boldsymbol{a}}^{\beta}},\epsilon)$ independent of $n$ so that for any $n\in{\mathbb N}$ and $k=0,1,\ldots,n$,  $(s,t)\in[\frac{k}{n},1]_\leqslant^2$ the following holds
     \begin{align}
          &\|\int_s^tb(Z_r)-\Gamma_{r-k_n(r)}b(Z_{k_n(r)}^n)dr\|_{L_2(\Omega)|{\mathcal F}_{\frac{k}{n}}} \nonumber\\& \leqslant N|t-s|^{\frac{1}{2}+\epsilon}(n^{-(\frac{1}{2}+\frac{\beta}{(1+\alpha)\alpha}\wedge\frac{1}{2})+2\epsilon}+[Y-Y^n]_{C_p^{\frac{1}{2}}|{\mathcal F}_{\frac{k}{n}},[s,t]}+[Y-Y^n]_{C_p^0|{\mathcal F}_{\frac{k}{n}},[s,t]}).
     \end{align}

[Definition 5 of arXiv:2609.03003, 'Causal Foundation Models'] A \textbf{structural causal model} (SCM) is a Bayesian network $G$ of $K$ nodes, together with a set of \emph{exogenous variables} $\{U_k\}_{k = 1}^K$ and a set of functions $\{f_v\}_{v \in G}$ such that
\begin{equation}
    Z_k = f_{Z_k}(\text{pa}(Z_k), U_k) \qquad \forall \ k = 1, \ldots, K.
\end{equation}

[Proposition 7 of arXiv:2604.04100, '\LARGE Learning Equilibrium Fluctuation Expansions from Overdamped Langevin Dynamics'] Let  $\varepsilon\in (0,1)$ and assume that $X_\varepsilon$ is the solution of \eqref{SDE-0} with initial data satisfying Assumption \ref{A1}. Let $(\bar{X}_m)_{0\leq m\leq n}$  be the solution of \eqref{eq-barX0-intro}-\eqref{eq-barXm-intro}, respectively. 
  Then, for each $p\geq 1$ and $t>0$, there exists a constant $C(p,t,n)>0$, such that for every $m\in\{0,\dots,n\}$,
  \begin{align*}
    	\mathbb{E}\big|\bar{X}_{m}(t)\big|^{2p}\leqslant C(p,t,n).
    \end{align*}

