[Defi The coupling map of arXiv:2604.21663, 'Large deviations for non-irreducible Markov chains on Euclidean spaces'] Let $N,n, T\in \mathbb N$ be such that $T\geqslant Nn+Nr\tau_K$.
	Let $\underline u=(u^1,\ldots ,u ^N)\in \widetilde{\mathcal{W}}_n^N$. Let $\underline v=(F_n(u^1),\ldots, F_n(u^N))$. 
	Then, $\sigma(\underline v)\in \mathcal S_{Nr,T}$, and we set
	\begin{equation*}
		\Psi_{N,n,T}(\underline u)= G_{Nr,T}(\sigma(\underline v))=G_{Nr,T}(\sigma(F_n(u^1),\ldots, F_n(u^N)))\in \mathcal B(\mathcal W_{T}).
	\end{equation*}

