[Definition eq:defXYmodellambda of arXiv:2604.24743, 'The impact of disorder and non-convex interactions on delocalisation of height functions'] Given an integer $L \in \ensuremath{\mathbb{N}}$, an integer $n \geq 2$, a parameter $\lambda > 0$, two inverse temperatures $\beta_1 , \beta_2 \geq 0$, and a site percolation configuration $r \in \{ 0 , 1\}^{\Lambda_L}$, we define
 \begin{itemize}
    \item The XY height function
  \begin{multline*}
     \mu_{L , n ,\beta_1, \beta_2 , \lambda,r }^{\ensuremath{\mathbb{Z}} - \mathrm{XY}} (\left\{ \varphi \right\}) \\
     := \frac{1}{Z_{\Lambda,J}^{\ensuremath{\mathbb{Z}}-\mathrm{XY}} }  I_{\left(\varphi(0)\right)} \left( \lambda \right)\prod_{x \sim y}  \left[ I_{\left(\varphi(x) - \varphi(y)\right)} \left( r_x \beta_1 \right) I_{\left(\varphi(x) - \varphi(y)\right)} \left( r_y \beta_1 \right) I_{\left(\varphi(x) - \varphi(y)\right)} \left(  n \beta_2 \right)^{n-2} \right].
 \end{multline*}
 We denote the variance associated with this measure by $\mathrm{Var}_{L , n ,\beta_1, \beta_2 , \lambda,r}^{\ensuremath{\mathbb{Z}} - \mathrm{XY}}$.
 \item The generalised XY model
 \begin{multline} 
     \mu_{L , n , \beta_1, \beta_2 , \lambda, r}^{\mathrm{XY}} (d \theta) \\
     := \frac{1}{Z_{\Lambda_L , n ,\beta_1, \beta_2 , \lambda, r}^{\mathrm{XY}}} \exp \left( \lambda \cos(\theta_{0g}) \right) \exp \left( \beta_1  \sum_{ x \sim y} \left( r_x \cos(\theta_{xy,1}) + r_y \cos(\theta_{xy,n}) \right) \right)  \\ \times \exp  \left( n \beta_2 \sum_{ x \sim y}  \sum_{2 \leq k \leq  n-1} \cos(\theta_{xy,k})  \right)  d \theta.
 \end{multline}
We denote by $\left\langle \cdot \right\rangle_{L , n , \beta_1, \beta_2 , \lambda, r}^{\mathrm{XY}}$ the expectation with respect to this measure.
\end{itemize}
In both cases when the percolation configuration is $r \equiv 1$ (i.e., all the sites are open), we omit the subscript $r$ from the notation.

[Lemma stestimate-kv of arXiv:2507.10545, 'KPZ equation from a class of nonlinear SPDEs in infinite volume'] \fsp Fix any {\small$\e>0$}, and recall the setting of Lemma (lemma:stestimate-rep of the paper). Suppose that {\small$\mathfrak{f}_{\j}$} satisfy the following constraints:

\begin{enumerate}
\item The quantity {\small$\mathfrak{f}_{\j}[\bphi]$} depends only on {\small$\bphi_{\w}$} for {\small$\w\in\{1,\ldots,\mathfrak{l}_{\star}\}$}, where {\small$\mathfrak{l}_{\star}>0$} may depend on {\small$N$}.
\item We have {\small$\E^{\sigma}\mathfrak{f}_{\j}=0$} for any {\small$\sigma\in\R$} (see Definition (definition:gcmeasure of the paper)) and {\small$\E^{0}|\mathfrak{f}_{\j}|^{2}<\infty$}, all for each {\small$\j$}.
\end{enumerate}

Then, if we let {\small$\E^{\mathrm{path},0}$} denote {\color{black}the} expectation with respect to the law of {\small$\t\mapsto\bphi_{\t}$} with initial data {\small$\bphi_{0}\sim\mathbb{P}^{0}$}, we have

\begin{align}
&\E^{\mathrm{path},0}\Big(\mathfrak{t}_{\mathbf{Av}}^{-1}\int_{0}^{\mathfrak{t}_{\mathbf{Av}}}\exp(\mathrm{U}+\mathbf{h}^{N,\Pi}_{\t,\r,\x})\cdot\mathfrak{n}_{\mathbf{Av}}^{-1}\sum_{\j=1,\ldots,\mathfrak{n}_{\mathbf{Av}}}\mathfrak{f}_{\j}[\tau_{\x+\j}\bphi_{\t-\r}]\cdot\mathbf{G}_{\j}[\tau_{\x}\bphi_{\t-\r}]\d\r\Big)^{2}\nonumber\\
&\lesssim_{\e} N^{\e}\cdot N^{-2}\mathfrak{t}_{\mathbf{Av}}^{-1}\mathfrak{n}_{\mathbf{Av}}^{-1}\cdot\mathfrak{l}_{\star}^{3}\cdot\max_{\j=1,\ldots,\mathfrak{n}_{\mathbf{Av}}}\E^{0}|\mathfrak{f}_{\j}|^{2}. 
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

