[Proposition 3 of arXiv:2604.24392, 'Numerical approximation of Markovian BSDEs in infinite horizon and elliptic PDEs'] {Assume  \eqref{as:generatorf}, \eqref{as:b:sigma} and \eqref{as:int:X:nablaX}.}
Then there exists a function $u \in {C}^1(\bR^d,\bR^{d'})$ such that, for all $x\in \bR^d$, $\Yx=u(\Xx)$, $\nabla_x u({\Xx})\sigma(\Xx):=\bar{u}(\Xx)$ is a continuous version of $\Zx$ and we have the following probabilistic representation for $(u,\bar{u})$: for all $x\in \bR^d$,
\begin{align}
 u(x):= \Yx_0 &= \E{\int_0^\infty  e^{-as}(f(\Xx_s,u(\Xx_s),\bar{u}(\Xx_s))+a u(\Xx_s)) \ds}\\
&=\frac{1}{\theta }\E{  (f(\Xx_E,u(\Xx_E),\bar{u}(\Xx_E))+a u(\Xx_E))e^{-(a-\theta)E} },
\\
 \bar{u}(x) := \Zx_0  &= \E{\int_0^\infty  e^{-\ta s}(f(\Xx_s,u(\Xx_s),\bar{u}(\Xx_s))+ \ta u(\Xx_s))\Ux_s \ds}\\
&=\frac{\sqrt{\pi}}{\sqrt{\ttheta} }\E{  (f(\Xx_\tE,u(\Xx_\tE),\bar{u}(\Xx_\tE))+ \ta u(\Xx_\tE))\sqrt{\tE}e^{-(\ta-\ttheta)\tE}\Ux_\tE }

\end{align}
where $\theta >0$, $\ttheta >0$, $E\sim\cE(\theta)$ is independent of $W$ and $\tE \sim \Gamma(1/2,\ttheta)$ is independent of $W$. 
Lastly, we have the following growth:
\begin{align}

 |u(x)| +  \norm{\bar{u}(x)} \leqslant C(1+|x|^{r}),\quad \forall x \in \bR^d.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Mainthm thm:drago of arXiv:2607.09946, 'Statistics on Yau's conjecture: Variance asymptotics'] There exists real number $T_0>0$ such that the following holds for any $T\ge T_0$.
Let $(M,g)$ be a compact smooth Riemannian manifold of dimension $n$, possibly with boundary. Let $\phi$ be a Gaussian field of class $\mathcal{C}^3(M)$ with covariance function $E$ and parameters $\lambda=\lambda(\phi)>0$, $\sigma=\sigma(\phi)>0$, $\varepsilon=\varepsilon(\phi)$ defined as in [cgv2025StecconiTodino] (see also (def:three of the paper)), and let $\tau:=\tau(\phi)$ be as in (eq:deft of the paper).
Assume that there exist positive numbers: $ \frac{1} {\lambda T} \le r\le \rho$, satisfying the following assumptions.
\begin{enumerate}
\item The eccentricity is small:
\begin{equation} 
\varepsilon=\varepsilon(\phi)<\frac{1}{T}, \quad \text{and} \quad \tau=\tau(\phi)<\frac{1}{T}.
\end{equation}
\item The pull-back field satisfies a $\mathcal{C}^3$ boundedness assumption: 
\begin{equation} 
\sup_{\substack{x,y\in M,
\\
 \mathrm{dist}(x,y)\le r}
}
\sigma^{-2}\|j^{3,3}_{x,y}E\|_{g^{\lambda}}

\le T
\end{equation}
\item The field satisfies a $\mathcal{C}^1$ short-correlation assumption:
    \begin{equation} 
\sup_{\substack{x,y\in M,
\\
r
\le \mathrm{dist}(x,y)\le \rho
}}

\sigma^{-2}\|j^{1,1}_{x,y}E\|_{g^{\lambda}}
\le \frac{1}{4}

\end{equation}
\end{enumerate}
Then, we have the following quantitative Law Of Large Numbers:
\begin{gather}

{\mathbb{V}\mathrm{ar}}\left\{ \frac{\mathcal{L}_f(M)}{\lambda}\right\}\le

{\mathbb{V}\mathrm{ar}}\left\{ \frac{\mathcal{L}_f(M)[2]}{\lambda}\right\}

+\mathfrak{T} \rho^{-n}\left( r^{n}
+

\int_{\substack{x,y\in M,
\\
r
\le \mathrm{dist}(x,y)\le \rho}}\|\sigma^{-2}j^{1,1}_{x,y}E\|^4_{g^{\lambda}} \dd x \dd y 
\right).
\end{gather}
where $\mathfrak{T}=\mathfrak{T}(n,M,g;T)$ is a constant depending only on $n,M,g$ and on the constant $T$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma l.time_der_sol of arXiv:2411.14105, 'Simultaneous replica-symmetry breaking \\ for vector spin glasses'] Let $(L,\alpha)$ be a decomposition defined on $[0,T]$ satisfying that $L$ is smooth and $\alpha$ is continuous and strictly increasing. Let $\Phi=\Phi_{\mu,L,\alpha}$ be the associated Parisi PDE solution. Then, $\Phi$ is differentiable in $t$ at every $t\in[0,T]\times \mathbb{R}^{D}$ with
\begin{align*}
	\partial_t \Phi(t,x) = - \accentset{\mbox{\large\bfseries .}}{L}(t)\cdot \left(\mathbb{E} \left\langle \sigma\sigma^\intercal\right\rangle_{\mu,\pi_t,x,-L(t)} - \mathbb{E} \left\langle \sigma\sigma'^\intercal \mathbf{1}_{\mathbf{h}\wedge \mathbf{h}' > \alpha(t)}\right\rangle_{\mu,\pi_t,x,-L(t)}\right)
\end{align*}
where $\left\langle\cdot\right\rangle_{\mu,\pi_t,x,-L(t)}$ is given as in~(equation e.f(q),<>_q= of the paper) with $\pi_t$ from Lemma~(l.cascade_rep of the paper).

[Lem 21 of arXiv:2608.05185, '\large\bf ON THE HEAT FLOW CONJECTURE FOR RANDOM MATRICES'] Let \(N\geq1\) and \(c\in\C\) with \(|c|<1\).  Every polynomial \(P\) of
degree at most \(N\) satisfies
\begin{equation}
 \left|P(z)\right|^2
 \leq
 \left\|P\right\|_{\mathrm{L}^2(\gamma_{N;1,c,0})}^2
 \frac{1}{\sqrt{1-\left|c\right|^2}}
 \exp\!\left(NQ_{1,c,0}(z)\right).
\end{equation}

