[Defn 1 (Weak formulation) of arXiv:2604.12797, 'A free boundary problem for the mean-field limit of diffusing particles with nonlinear bou'] Let $(v,A)$ be such that (i) $t\mapsto A_t$ is continuous in $t\geq 0$, (ii) $v\geq 0$, (iii)  $(t,x) \mapsto v(t,x)$ is continuous jointly in $t>0$ and $x\geq A_t$, and (iv) $v(t,\cdot)\in L^1([A_t,\infty))$ and $v(\cdot,A_{\cdot})\in L^1([0,t])$ for all $t>0$. Let also $A_0=a_0$ and $v(t,x)\dx \rightarrow P_0$ as $t\downarrow 0$ in the topology of weak convergence of measures. Then, we say that $(v,A)$ is a weak solution of the free boundary problem \eqref{eq:classic_PDE}--\eqref{eq:classic_A_I_rate} with initial condition $(P_0,a_0)$ if 
\begin{align}
	&\int_{A_t}^\infty \!\! \phi(x)v(t,x)\dx - 	\int_{a_0}^\infty \!\! \phi(x) \di P_0(x) = \int_0^t\! \int_{A_s}^\infty \!\! \partial_{xx}\phi(x)\frac{1}{2}\sigma(s,x)^2v(s,x)\dx \ds \nonumber \\
	&+ \int_0^t \!\int_{A_s}^\infty \!\!\partial_{x}\phi(x)b(s,x)v(s,x) \dx \ds + \int_0^t  \bigl( \tfrac{1}{2} \partial_x\phi(A_s)-\gamma(s,C_s)\phi(A_s)\bigr)\sigma(s,A_s)^2v(s,A_s) \ds ,
\end{align}
for all $t\geq 0$ and all $\phi \in C^2_b(\R)$, with
\begin{equation}
	A_t=a_0 + \alpha \! \displaystyle \int_{t-\bar{d}}^{t}\varrho(t-s)I_{s} \ds, \;\;
	C_t = \!\int_{t-\bar{d}}^{t}\varrho(t-s)(I_{s}-I_{s-\bar{d}}) \ds, \;\;  I_t=1-\!\int_{A_t}^\infty \!\!\! v(t,x) \dx,
\end{equation}
for all $t>0$.

[Proposition p:averaging set multivariate trigonometric polynomial degree 1 of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Suppose that $l,n\in\N$, and that $p_1,...,p_d$ are real-valued trigonometric polynomials of degrees $m^{(1)},...m^{(d)}\in\{0,1\}^l$. Then
    \begin{equation}
        \left\{\begin{pmatrix}
            p_1(2\pi j_1/n+u_1, ..., 2\pi j_l/n+u_l)\\
            \vdots\\
            p_d(2\pi j_1/n+u_1, ..., 2\pi j_l/n+u_l)
        \end{pmatrix}:j\in\{1,...,n\}^l\right\}
    \end{equation}
    is an averaging set of $(p_1,...,p_d)$ of degree $n-1$ for all $u\in\R^l$, and not of any higher degree for almost all $u\in\R^l$ if at least one trigonometric polynomial is not constant.

    \begin{proof}
        An application of Theorem~(t:averaging set multivariate trigonometric polynomial of the paper) directly yields that the set in~(equation e:averaging set degree 01 of the paper) is an averaging set of $(p_1,...,p_d)$ of degree $m-1$.
        Now, we have to show that this does not hold for any higher degree.
        In the proof of the previous Theorem~(t:averaging set multivariate trigonometric polynomial of the paper), we saw that the problem factorizes for multivariate monomials. Here, $p_k^n$ also always contains a monomial of the form $e^{im^{(k)}_1nx_1+...+m^{(k)}_lnx_l}$ for \linebreak $k\in\{1,..,d\}$. If $p_k$ is not constant, then $m^{(k)}_j=1$ for some $j\in\{1,...,l\}$. Without loss of generality, we assume $m^{(1)}_1=1$. Then,
        \begin{equation*}
            \frac{1}{(2\pi)^l}\int_{[0,2\pi)^l} e^{im^{(k)}_1nx_1+...+m^{(k)}_lnx_l}\, dx = \prod_{k=1}^l\frac{1}{2\pi}\int_0^{2\pi} e^{im_knx}\, dx = 0,
        \end{equation*}
        and 
        \begin{equation*}
            \frac{1}{n^l}\sum_{j\in\{1,...,n\}^k} e^{im^{(1)}_1n(2\pi j_1/n+u_1)+...+im^{(1)}_ln(2\pi j_l/n+u_l)} = \prod_{k=1}^l \frac{1}{n}\sum_{j=1}^{n} e^{2\pi im^{(1)}_k j+im^{(1)}_knu_k},\quad u\in\R^l.
        \end{equation*}
        On the RHS of the second equation, the first factor is equal to $e^{inu_1 }$, and the others are either equal to $1$ or $e^{inu_k }$. In total, the product is not $0$ for almost all $u\in\R^l$, which concludes the proof.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 32 of arXiv:2507.06186, '2507.06186'] For every $\ka>0$,
there exists a constant $\th_\ka>0$ such that
for every $t\in(0,\th_\ka)$, the following holds:
\begin{align}

\lim_{\eps\to0}\mbf E\big[\msf T_{\ka,\eps}(t)\mr e^{-t\msf c_{\ka,\eps}}\big]
=\frac{\mr e^{\ka^2t\log t/2\pi}}{2\pi t}\int_D\mbf E\Big[\mbf 1_{\{\tau_D(B^{x,x}_t)>t\}}\mr e^{\ka^2\ga_t(B^{x,x}_t)}\Big]\d x;
\end{align}
\begin{align}

\lim_{\eps\to0}\mbf E\big[\msf M_{\ka,\eps}(t)\mr e^{-t\msf c_{\ka,\eps}}\big]
=\mr e^{\ka^2(t\log t-t)/2\pi}\int_D\mbf E\Big[\mbf 1_{\{\tau_D(B^x)>t\}}\mr e^{\ka^2\ga_t(B^x)}\Big]\d x;
\end{align}
\begin{multline}

\lim_{\eps\to0}\mbf{Var}\big[\msf T_{\ka,\eps}(t)\mr e^{-t\msf c_{\ka,\eps}}\big]=\frac{\mr e^{\ka^2t\log t/\pi}}{(2\pi t)^2}\int_{D^2}\mbf E\Bigg[\mbf 1_{\cap_{i\leq2}\{\tau_D({_i}B^{x_i,x_i}_t)>t\}}\\
\cdot\mr e^{\ka^2\sum_{i=1}^2\ga_t({_i}B^{x_i,x_i}_t)}\left(\mr e^{\ka^2\al_t({_1}B^{x_1,x_1}_t,{_2}B^{x_2,x_2}_t)}-1\right)\Bigg]\d x;
\end{multline}
\begin{multline}

\lim_{\eps\to0}\mbf{Var}\big[\msf M_{\ka,\eps}(t)\mr e^{-t\msf c_{\ka,\eps}}\big]=\mr e^{\ka^2(t\log t-t)/\pi}\int_{D^2}\mbf E\Bigg[\mbf 1_{\cap_{i\leq2}\{\tau_D({_i}B^{x_i})>t\}}\\
\cdot\mr e^{\ka^2\sum_{i=1}^2\ga_t({_i}B^{x_i})}\left(\mr e^{\ka^2\al_t({_1}B^{x_1},{_2}B^{x_2})}-1\right)\Bigg]\d x.
\end{multline} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 8 of arXiv:2608.27093, 'Soliton Solutions to the Curvature Flow on the 2-dimensional De Sitter Space and Applicati'] Let $\psi(s)=(\alpha(s),\tau(s),\eta(s))$ be a non-null solution of \eqref{s2} defined on the maximal interval $I$, $a>0$,  and initial condition $\psi(0)\in H\cup C\cup S$. The function $\tau(s)=b \in \mathbb{R}$, for all $s \in I$  if and only if $b \in \{-1,0,1\}$ and $I=\mathbb{R}$. Moreover,
	\begin{itemize}
		\item[i)] if $b=0$, then $\psi(s)=(0,0,\pm 1)$ is a  singular solution of \eqref{s2} and $\psi(s) \in H$ (respectively $\psi(s) \in S$) for all $s \in \mathbb{R}$, when $X$ is a spacelike curve (respectively $X$ is a timelike space),
		\item[ii)] if $X$  is a spacelike curve and $b^{2}=1$, then $a=1$ and $\psi(s)=(\pm s+\alpha(0),\pm 1,-s \mp  \alpha(0)) \in S$ for all $s \in \mathbb{R}$.
	\end{itemize}

[Definition of arXiv:2609.00794, 'On operators whose adjoints or second adjoints attain their norms'] Let $X$ and $Y$ be Banach spaces. The pair $(X, Y)$ is said to have \textit{property $(P^{\star\star})$} if there is a relatively WOT compact $K \subseteq  \mathcal{L}_{w^*,w^*}^{(2)}(X, Y)$ such that 
\begin{equation*}
    0 \in \overline{K}^{\mathrm{WOT}} \ \ \ \ \ \mbox{and} \ \ \ \ \ 0 \not\in \overline{\co}^{\|\cdot\|}(K).
\end{equation*}

