[Theorem 25 of arXiv:2609.03803, 'List-distance consistent vertices in trees are confined to a path'] For all integers $k\ge2$ and $h\ge1$,
\[
  \ldc\bigl(\Tkh\bigr)=
  \begin{cases}
    5, & \text{if } k=2 \text{ and } h=2,\\[2pt]
    3, & \text{otherwise.}
  \end{cases}
\]

[Lemm 13 (Parameter dependent construction) of arXiv:2609.01105, 'Obstruction to quasi-invariance of Gaussian measures under transport flows on Riemannian M'] Consider a local chart $\kappa : M \supset U \to V \subset \Rr^d$ with~\(V\) open and $\rho_0, \rho_1, \rho_2 \in C^{\infty}_c(V)$ such that $\rho_{k+1} = 1$ on a neighborhood of $\supp \rho_k$, for $k\in\{0,1\}$. 
There exist $q_{-2-j}(\lambda ; \cdot, \cdot) \in S^{-2-j}_{\lambda}$, $j\geq 0$, and $r_N(\lambda ; \cdot, \cdot) \in S^{-N}_{\lambda}$, $N\geq 1$ such that for all $\lambda \in \Gamma$ we have
\begin{equation}

   (\kappa_*(L-\lambda)\kappa^*)\rho_1\Op\left( \sum_{j=0}^{N-1}q_{-2-j}(\lambda)\right)\rho_0 = \rho_0 - \rho_2\Op(r_N(\lambda))\rho_0,\qquad  N \geq 1.
\end{equation}
Moreover, $\lambda \mapsto q_{-2}(\lambda)\in S^{-2}_\lambda$ is holomorphic, the functions $\lambda \mapsto q_{-2-j}(\lambda) \in S^{-2-j}_{\lambda}$ and $\lambda \mapsto r_N(\lambda) \in S^{-N}_{\lambda}$ are continuous, and the following decomposition holds: 
\begin{equation}

    q_{-2-j}(\lambda; y,\eta) = \sum_{\ell=1}^{2j}|\lambda - 1|^{\ell-\frac{j}{2}}\frac{d_{j\ell}(y,|\lambda-1|^{-\frac{1}{2}}\eta)}{(p_2(y,\eta) + 1 - \lambda)^{1+\ell}}, \qquad j \geq 1,
\end{equation}
where $p_2(y,\eta)=g^{ij}(\kappa^{-1}(y))\eta_i\eta_j$ and $d_{j\ell}\in S^{2j-\ell}$ are polynomial in the second variable. For $j=0$ there holds
\begin{equation}

    q_{-2}(\lambda;y,\eta)= \frac{1}{p_2(y,\eta) + 1 - \lambda},
\end{equation}
which is holomorphic in $\lambda \in \Gamma$.

[Lemma 31 of arXiv:2606.16636, 'Free energy of non-convex multi-species spin glasses with centered Ising spins'] Let $t>0$ and $q\in\mcl Q_\infty^\D$. With $A_j(x,y)=A_j(x,q+q_j(y))$ as in~\eqref{e.A_N(x,y),Delta(x,y)=}, we have
\begin{align}
    \bar F_N(t,q)=-\frac1N\sum_{j=1}^{N-1}\E_{x,y}A_j(x,y)+o(1).
\end{align}

