[Theorem 2 of arXiv:2512.02922, 'Asymptotics for additive functionals of particle systems via Stein's method'] If $\psi$ is a non-negative function, then under condition \textbf{(H)}, the distribution $\rho_r$ of $Z_r$ satisfies 
\begin{align}
d_{W}(\rho_r,\gamma)
  \leq 	K\frac{r^{1-\beta d}}{\sigma_r},
\end{align} 
for some positive constant $K$ independent of $r$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma Xn T estimates of arXiv:2605.16963, 'Stochastic Euler Equations with Pseudo-differential Noise: Continuous and Discontinuous Pe'] Let the conditions in Proposition (Proposition-(q u) of the paper) hold and let $\theta\in\left(\frac{d}{2}+p,{s-\max \{3\zeta,1\}}\right)$. Then ${\mathbb P}\text{-}{\rm a.s.}$ the following properties hold:
		\begin{enumerate}[label={\bf (\arabic*)},leftmargin=0.79cm]\setlength\itemsep{0.2em}
			\item  There is a function $\widehat K: [0,\infty)\times [0,\infty)\to (0,\infty)$, increasing in both variables, such that  for any $R\ge1$ and $T>0$,
			\begin{align}
				\sup_{n\ge1}\mathbb E\Big[\sup_{t\in[0,T]}\|X_n^{(R)}(t)\|^2_{\mathbb H^s}\Big|\mathcal F_0\Big] 
				\leq \widehat K(T,2R+\|\Xi\|_{{\mathbb W}^{p,\infty}})(1+\|\Xi\|_{\mathbb H^s}^2). 
			\end{align} 
			\item   Let
			$$\tau_N^{n,m}(R) \triangleq  N\land \inf\big\{t\ge 0: \|X_n^{(R)}(t)\|_{\mathbb H^s}\lor\|X_m^{(R)}(t)\|_{\mathbb H^s}\ge N\big\},\quad n,m\ge 1, \ N\ge1.$$
			Then 
			\begin{equation} 
				\lim_{n\rightarrow\infty}\sup_{m\ge n}
				\mathbb E\left[\sup_{t\in[0,\tau_N^{n,m}(R)]} \|X_n^{(R)}(t)-X_m^{(R)}(t)\|^2_{\mathbb H^\theta}\bigg|\mathcal F_0\right]=0,\quad N>0.
			\end{equation}

			\item  There exists an $\mathcal{F}_t$-progressively measurable $\mathbb H^s$-valued process $X^{(R)}=(X^{(R)}(t))_{t\ge 0}$ satisfying 
			\begin{equation}
				\mathbb E\Big[\sup_{t\in [0,T]} \|X^{(R)}(t)\|_{\mathbb H^s}^2\Big|\mathcal F_0\Big]\le \widehat K(T,2R+\|\Xi\|_{{\mathbb W}^{p,\infty}})(1+\|\Xi\|^2_{\mathbb H^s}),\quad T>0,
			\end{equation} 
			such that for some subsequence of $\{X_n^{(R)}\}_{n\ge1}$ $($still denoted by $\{X_n^{(R)}\}_{n\ge1}$ for simplicity$)$ and for all $s'\in[\theta,s)$,
			\begin{equation}
				\lim_{n\to\infty}\sup_{t\in[0,T]}\|X_n^{(R)}(t)-X^{(R)}(t)\|_{\mathbb H^{s'}}=0\quad \text{and}\quad  X_n^{(R)}\xrightarrow[]{n\to \infty}X^{(R)} \  {\rm in}\ D([0,T];\mathbb H^{s'}),\quad T>0
				\quad {\mathbb P}\text{-}{\rm a.s.}
			\end{equation}

		\end{enumerate}

[Teo T: Survival of arXiv:2606.10165, 'The frog model with death and drift on free products of complete graphs'] Let $\beta = \frac{1-\alpha}{\Delta-1}$ and assume $m \geq 2$ and $d \geq 2$ are fixed integers. We define the functions

{\allowdisplaybreaks
\begin{equation}

\begin{aligned}
\phi(r)&= -d(m-1)r^2 + 2d(m-1)r,\\[4pt] 
A(\alpha, p) &= 
\frac{
1 - \beta p (m-2)-\sqrt{[1 - \beta p (m-2)]^2 - 4 \alpha \beta p^2 d (m-1)
}}{2 \beta p d (m-1)},\\[10pt]
\gamma(\alpha, p) &= 1 - \beta p \, [d (m-1) A(\alpha, p) + m - 3],\\[10pt]
\mathscr{Q}(\alpha, p) &= -\alpha p \, [\gamma(\alpha, p) + \beta p (m-2)],\\[10pt]
\mathscr{R}(\alpha, p) &= \gamma(\alpha, p) \, [1 - \beta p (d-1) (m-1) A(\alpha, p)] - \beta p^2 (\alpha + \beta) (m-2),\\[10pt]
\mathscr{S}(\alpha, p) &= -\beta p \, [\gamma(\alpha, p) + \beta p (m-2)],\\[10pt]
B(\alpha, p) &= \frac{-\mathscr{R}(\alpha, p) + \sqrt{\mathscr{R}(\alpha, p)^2-4 \, \mathscr{Q}(\alpha, p) \, \mathscr{S}(\alpha, p)}}{2 \, \mathscr{Q}(\alpha, p)}.
\end{aligned}
\end{equation}}

Then, \(\FM{\mathbb{D}_{m,d}}{\alpha,p}\) survives with positive probability for  $(\alpha, p)$ such that $\phi(B(\alpha, p))> 1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma c:Hoffmann_crucial_site of arXiv:2608.17073, 'Near-critical percolation with sparse reinforcements'] Let $M\in{\ensuremath{\mathbb Z}} _+$ be fixed and consider the homogeneous \textbf{site} $M$-model. Let $p^*<1$ be as in Lemma (t:Hoffmann of the paper) and $p_1=1-(1-p^*)^4$ as in Remark (gri_sta of the paper). There exists $\rho = \rho(M)<1$ such that 
$$\mathbb{Q}_{p_1}^{s,\Lambda_M}(o\longleftrightarrow \infty)>0,$$ 
for $\mu_{\xi}$-almost every environment $\Lambda_M$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:useful-bound of arXiv:2512.17747, 'On exponentially height-penalized random trees'] For any real number $\alpha\in\mathbb R$ and any two strictly positive numbers $\beta,\gamma>0$, consider the function
    \begin{align*}
        F_t(x,y)=\frac{t^\alpha}{x^\beta}\exp\left(-\frac{t}{y^\gamma}\right)\,.
    \end{align*}
    Let $a_+=a_+(t)$ be strictly positive and bounded, and $\epsilon=\epsilon(t)$ converging to $0$ as $t$ diverges. 
    Then there exists $k=k(t)$ an integer depending on $t$ and a sequence of increasing values $(a_0\leq\ldots\leq a_k)$ (implicitly depending on $t$) such that $a_0=\epsilon$, $a_k=a_+$, and satisfying
    \begin{align*}
        \lim_{t\rightarrow\infty}\sum_{i=1}^kF_t(a_{i-1},a_i)=0\,.
    \end{align*}

