[Theorem thm:uniform-lower-bound of arXiv:2609.00556, 'Higgs--Demailly System and Positivity of Higgs Bundles'] If \((E,\theta)\) is H-ample, then every smooth admissible solution
of the Higgs--Demailly system satisfies
\begin{equation}
 f_t\geq-C,
\end{equation}
where \(C\) is independent of \(t\) and of the solution.

[Lemma lem:SDE-embedding-drift of arXiv:2509.08928, 'The near critical random bond Ising model via embedding deformation'] Consider the Stochastic Differential System defined on corners of $ \Upsilon^{\times} \cap  \Lambda  $, whose initial condition is given by $\mathcal{Y}^{(0)}$ and whose dynamic is given for any $\frak{p} \in \Lambda $ by $ \widehat{\mathcal{Y}}^{(s)}_{\omega}(\frak{p}):=\widehat{\mathcal{Y}}(\frak{p},\omega,s)$
 \begin{equation}
 	d \widehat{\mathcal{Y}}^{(s)}_{\omega} (\frak{p})= \frac{1}{2} \sum\limits_{z_k \in \Lambda} \sigma_k\Bigg[ \widehat{\mathcal{Y}}^{(s)}_{\omega}(c^+_k) \langle \chi_{\frak{p}}\chi_{a^+_k} \rangle_{S_{\omega}(s)} -  \widehat{\mathcal{Y}}^{(s)}_{\omega}(a^+_k) \langle \chi_{\frak{p}}\chi_{c^+_k} \rangle_{S_{\omega}(s)} \Bigg] dB^{(e_k)}_s 
 \end{equation}

Then $\mathbf{P}$-almost surely :
\begin{enumerate}
	\item There exist $T_0(\Lambda,\omega)>0$ such that there exist a strong solution to the SDE (equation eq:SDE-embedding of the paper) on $[0;T_0(\Lambda,\omega)] $.
	\item For any time $0\leq s \leq T_0 (\Lambda,\omega)$, the propagator $\widehat{\mathcal{Y}}^{(s)}_{\omega} $ the strong solution to (equation eq:SDE-embedding of the paper) is an s-embedding $\widehat{\mathcal{S}}^{(s)}_{\omega}$ of the Ising model $\widehat{S}_{\omega}(s)$.
\end{enumerate}

[Thm 82 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] Let $j\geq 0$.
For $\varepsilon>0$, set
\begin{displaymath}
\Ns_{\varepsilon}(\clus_j) = \{ z\in \inter(\Gamma_j)\setminus \clus_j \vert 
\CR(z,\inter(\Gamma_j)\setminus \clus_j)<\varepsilon \CR(z,\inter(\Gamma_j))\},
\end{displaymath}
\begin{displaymath}
\widetilde{\Ns}_{\varepsilon}(\clus_j)
= \{ z\in \inter(\Gamma_j)\setminus \clus_j \vert \CR(z,\inter(\Gamma_j)\setminus \clus_j)<\varepsilon\}.
\end{displaymath}
Then, for every $N\geq 0$,
\begin{displaymath}
\ind_{\Ns_{\varepsilon}(\clus_j)}
=
\dfrac{1}{\sqrt{2\pi}}
\sum_{k=0}^{N} (-1)^{k}
\dfrac{1}{2^{k} k! (k+1/2)}
\dfrac{\psi_{2k+1,j}}{\big(\frac{1}{2\pi}\vert\log \varepsilon\vert\big)^{k + 1/2}}
~+ o(\vert\log\varepsilon\vert^{-(N+1/2)}),
\end{displaymath}
where $o(\vert\log\varepsilon\vert^{-(N+1/2)})$ is in the sense
$L^{2}(d\PP,\sigma(\Phi),H^{-\eta}(\C))$ for $\eta>0$.
Further,
\begin{displaymath}
\ind_{\widetilde{\Ns}_{\varepsilon}(\clus_j)}
=
\dfrac{1}{\sqrt{2\pi}}
\sum_{k=0}^{N} (-1)^{k}
\dfrac{1}{2^{k} k! (k+1/2)}
\dfrac{\tilde{\psi}_{2k+1,j}}{\big(\frac{1}{2\pi}
\vert\log \varepsilon\vert\big)^{k + 1/2}}
~+ o(\vert\log\varepsilon\vert^{-(N+1/2)}),
\end{displaymath}
where
\begin{displaymath}
\tilde{\psi}_{2k+1,j} = 
\sum_{j=0}^{k} \dfrac{(2k+1)!}{2^{j} j! (2(k-j)+1)!}
\,\Big(\dfrac{1}{2\pi} \log \CR(z,\inter(\Gamma_j))\Big)^{j}\,\psi_{2(k-j)+1,j}.
\end{displaymath} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 20 of arXiv:2606.27078, 'Semimartingale Optimal Transport with Jumps: A General Framework and Equivalent Formulatio'] Let $\Theta\subseteq\mathbb{R}^d\times\mathbb{S}_+^d\times\mathcal{L}$ be closed, convex and satisfy Assumptions~\ref{B} and~\ref{J}. Moreover, let the cost function $\ell$ (defined in \eqref{definel}) satisfy Assumption~\ref{L}. Then
\begin{equation}
V(\mu_0,\mu_1)=PDE(\mu_0,\mu_1).
\end{equation}

[Lemma lem:far_term_bound_layer of arXiv:2607.04514, 'Boundary-layer asymptotics for Gaussian-smoothed singular measures'] Assume (ass:standing:measure of the paper) and~(ass:standing:chart of the paper) of (ass:standing of the paper).
  Fix \(A>0\). There exists \(\sigma_0>0\) such that
  \begin{equation*}
    \widetilde p_{{\mathrm{far}},\sigma}(a,x) = p_{{\mathrm{far}},\sigma}\bigl(y_\sigma(a,x)\bigr)
  \end{equation*}
  is well defined and satisfies \(\widetilde p_{{\mathrm{far}}, \sigma}\in \mathfrak E_r^2\) on
  \(\mathcal D_{A, \mathcal{K}_{\mathcal{S}},\sigma_0}\). Consequently, the normalized remainder
  \begin{equation*}
    \mathscr E_{\mathrm{far}}(a,x,\sigma)
    = (2\pi)^{d/2} \sigma^{k-2} \widetilde p_{{\mathrm{far}},\sigma}(a,x)
  \end{equation*}
  belongs to \(\mathfrak E_r^2\), and hence to \(\mathfrak B_r\), on the same parameter domain.

