[Defn 4 of arXiv:2607.28865, 'First-Passage Percolation on Spread-out line graphs: Microscopic Regime'] Let $a>0$ be a fixed constant satisfying Assumption \textnormal{B.\ref{ass:B1}}.
A vertex $v$ is called a \emph{pivot} if
\begin{align}
	\go_{x,v} < a, \;\; \go_{v,y} < a, \;\; \text{and} \;\; \go_{x,y} > 2a   \text{ for all }x<v<y \text{ with } 2\le  |x-y| \leq \ell.
\end{align}

[Prop propotts2 of arXiv:2609.02682, 'LDP for tensor forms'] Under the assumptions of (NewLDP of the paper), the following conclusions hold:
\begin{itemize}
\item[(i)](Characterization of Optimizers)
If ${\boldsymbol f}=(f_1,\ldots,f_c)$ is a maximizer of  the optimization problem (equation eq:potts_unconstrained_opt2 of the paper), it satisfies
\begin{equation}
f_r(x)\stackrel{\lambda-a.e.}{=}
\frac{\mu_r\exp\!\big(\beta\,\mathcal T_r[W_{\infty},\phi,{\boldsymbol f}](x)\big)}
{\sum_{s=1}^c\mu_s\exp\!\big(\beta\,\mathcal T_s[W_{\infty},\phi,{\boldsymbol f}](x)\big)},
\qquad r\in[c],
\end{equation}
where
\begin{equation}
\mathcal T_r[W,\phi,{\boldsymbol f}](x)
:=
\sum_{m=1}^v \mathcal T_r^{(m)}[W,\phi,{\boldsymbol f}](x),\qquad r\in[c],
\end{equation}
and we write $\lambda$-a.e. to mean almost everywhere w.r.t. Lebesgue measure.
\item[(ii)](Replica symmetry breaking) Suppose there exist $r,s\in[c]$ such that \[\Gamma_r({(\mu_1,\ldots,\mu_c)})\neq\Gamma_s((\mu_1,\ldots,\mu_c)),\] where
\begin{align}
\Gamma_r({\boldsymbol y})
:=
\sum_{m=1}^v
\sum_{\substack{s_1,\ldots,s_{m-1},s_{m+1},\ldots,s_v\in[c]}}
\phi(s_1,\ldots,s_{m-1},r,s_{m+1},\ldots,s_v)
\prod_{\substack{a=1\\ a\neq m}}^v y_{s_a}.
\end{align}
Moreover, assume $\beta\neq0$ and $\mathcal{V}[W_{\infty}](\cdot)$ (as in~(equation deft1 of the paper)) is not constant $\lambda$-a.e. Then none of the maximizers of (equation eq:potts_unconstrained_opt2 of the paper) are constant $\lambda$-a.e.

\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop MAP representation of Dunkl Proposition of arXiv:2411.07671, 'Long Time Behavior of General Markov Additive Processes'] Let $(\xi,\Theta)$ be the MAP corresponding to the radial Dunkl process $X^W$ via the Lamperti-Kiu transform. Then, there exists an $n$ dimensional Wiener process $W_t=(W_t^{(1)},\ldots, W_t^{(n)})$ such that $\xi$ satisfies the SDE \begin{equation*}
    d\xi_t= \sum_{i=1}^n \Theta_t^{(i)}dW_t^{(i)} + \left(\sum_{i=1}^n (\Theta_t^{(i)} \sum_{\alpha\in R_+} \frac{k(\alpha)}{<\alpha,\Theta_t>}\alpha_i) + n-2\right)dt 
\end{equation*}
and $\Theta=(\Theta^{(1)},\ldots,\Theta^{(n)})$ satisfies the SDE system \begin{multline*}
    d\Theta_t^{(i)} = dW_t^{(i)} - \Theta_t^{(i)} \sum_{j=1}^n dW_t^{(j)}  \\ 
    +\left( \sum_{\alpha\in R_+} \frac{k(\alpha)}{<\alpha,\Theta_t>}\alpha_i
    - \Theta_t^{(i)}\sum_{j=1}^n (\Theta_t^{(j)} \sum_{\alpha\in R_+} \frac{k(\alpha)}{<\alpha,\Theta_t>}\alpha_j) -\frac{\Theta_t^{(i)}}{2} \right) dt
\end{multline*} (Proof in the paper; no proof environment follows the statement in the TeX.)

