[Lemma lem:ODE-embedding of arXiv:2509.08928, 'The near critical random bond Ising model via embedding deformation'] Let $\mathcal{Y}^{(0)}:=d\mathcal{S}^{(0)}$ associated to $(S,(x^{(0)}_{e})_{e\in E(\mathbb{Z}^2)})$. Assume also that the collection of masses $(m_e)_{e\in \mathbb{Z}^2}$ vanishes outside the box $\Lambda$. Consider the differential system defined on corners of $ \Upsilon^{\times} \cap  \Lambda  $, whose initial condition is given by $\mathcal{Y}^{(0)}$ and whose dynamic is given for any $\frak{p} \in \Lambda $ by
		\begin{equation}
		\frac{d \mathcal{Y}^{(t)}(\frak{p})}{dt}= \frac{1}{2} \sum\limits_{z_k \in \Lambda}m_k \Bigg[ \mathcal{Y}^{(t)}(c^+_k) \langle \chi_{\frak{p}}\chi_{a^+_k} \rangle_{S(t)} -  \mathcal{Y}^{(t)}(a^+_k) \langle \chi_{\frak{p}}\chi_{c^+_k} \rangle_{S(t)} \Bigg].
	\end{equation}
Then 
\begin{enumerate}
	\item There exist $T_0(\Lambda)>0$ such that the ODE (equation eq:ODE-embedding of the paper) is well defined on $[0;T_0(\Lambda)] $.
	\item For any time $0\leq t \leq T_0(\Lambda) $, the fermion $\mathcal{Y}^{(t)}$ solution to (equation eq:ODE-embedding of the paper) constructs an s-embedding $\mathcal{S}^{(t)}$ of the Ising model $S(t)$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn ofn of arXiv:2506.18207, 'Cartan's Path Development, the Logarithmic Signature and a Conjecture of Lyons-Sidorova'] Assume that $\gamma:[0,T]\to R^d$ is a bounded variation path and $(0,0)=\gamma_0\neq\gamma_T$. We define the associated (with $\gamma$, $T$) normalization operator $\mathcal{A}=\mathcal{A}_{\gamma,T}$ by
$$
\mathcal{A}(\alpha)_t:=k^{-1}A\alpha_t,~\forall~t\in[0,S],
$$
where $\alpha:[0,S]\to R^d$ is a bounded variation path, the rotation $A$ and the scaling $k$ are given by  
\begin{equation}
A
=\left(
\begin{array}{cc}
\cos(\theta) & \sin(\theta) \\
-\sin(\theta) &\cos(\theta)\\
\end{array} 
\right)
=\frac{1}{|\gamma_T|}\left(
\begin{array}{cc}
 x_T & y_T \\
-y_T & x_T\\
\end{array} 
\right),\quad\quad k=|\gamma_T|.
\end{equation}
For any one-form $f(\cdot):=\left(
\begin{array}{c}
f_1  \\
f_2 \\
\end{array} 
\right)(\cdot)$, we define its adjoint operator $\mathcal{A}^*$ by 
\begin{equation*}
\mathcal{A}^*(f)(\cdot)=k^{-1} A^{-1}\left(
\begin{array}{l}
f_1  \\
f_2 \\
\end{array} 
\right)\left(k^{-1}A\cdot\right)
\end{equation*}

[Corollary coro:tail_bound of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] Under the assumption of Theorem (thm:main_thm of the paper), if $x>0$ and $x^2 t_N N^{-\frac{1}{3}}< c_0$ for some small absolute constant, then there exist constants $c, C>0$, such that
\begin{equation}
    \mathbb{P}\Big(\|\frac{1}{2}X\|_{\mathrm{op}}>1+xN^{-\frac{2}{3}}\Big)\le C(1+ e^{C \tau x})e^{-c x^{\frac{3}{2}}}.
\end{equation}

