body:
[Proposition 15 (\cite{Cerrai2001}) of arXiv:2512.05340, 'The rate of convergence of the critical mean-field $O(N)$ magnetization via multivariate n'] Let $V$ satisfy Assumption~\ref{assumption: assumptions on V}. For $u\in\RR^d$ and $t>0$, define
\begin{equation}
        I_{u}^{x}(t) := \frac{1}{\sqrt{2}t}\int_{0}^{t}\<\,\sU_{u}^x(s), \dbs \>.
\end{equation}
Then for any $\varphi \in C_{b}$, any $t>0$ and any $u,v,w\in\RR^d$ it holds that,
\begin{equation}
  D_{u}P_{t}\varphi(x) = \EE\left\< \grad\varphi(X_{t}^{x}),\,\sU_{u}^x(t)\right\>,
\end{equation}
\begin{equation}
  \begin{split}
  D^{2} P_{t}\varphi(x)[u,v] &= \EE\left(D P_{t/2}\varphi(X_{t/2}^{x})[\sU_{u}^x(t/2)]I_{v}^{x}(t/2)\right) \\
  &\quad +\frac{2}{t}\EE\int_{0}^{t/2}D P_{t-s}\varphi(X_{s}^{x})[\sU_{u,v}^x(s)]\, \ds,
  \end{split}
\end{equation}
and 
\begin{equation}
  D^{3} P_{t}\varphi(x)[u,v,w] = K_1^{x,t}(u,v,w) + K_2^{x,t}(u,v,w) + K_3^{x,t}(u,v,w) + K_4^{x,t}(u,v,w) + K_4^{x,t}(v,u,w)
\end{equation}
where
\begin{align}
K_1^{x,t}(u,v,w)&:= \EE \,\left(D^{2} P_{t/2}\varphi(X_{t/2}^{x})[\,\sU_{u}^x(t/2),\sU_{v}^x(t/2)] I_{w}^{x}(t/2)\right) \\
K_2^{x,t}(u,v,w)&:= \EE \,\left(D P_{t/2}\varphi(X_{t/2}^{x})[\sU_{u,v}^x(t/2)]I_{w}^{x}(t/2)\right)\\ 
K_3^{x,t}(u,v,w)&:= \frac{2}{t}\EE\int_{0}^{t/2}D P_{t-s}\varphi(X_{s}^{x})[\,\sU_{u,v,w}^x(s)]\, \ds,\\
K_4^{x,t}(u,v,w)&:= \frac{2}{t}\EE\int_{0}^{t/2}D^{2} P_{t-s}\varphi(X_{s}^{x})[\sU_{u,v}^x(s), \,\sU_w^x(s)]\, \ds.
  \end{align}

