[Proposition 7 of arXiv:2609.00087, 'Translational tiles without spectra\\ in finite abelian $p$-groups'] The sets in Appendix~\ref{app:exp4-data} satisfy the following properties.
\begin{enumerate}
\item $E$ is a spectrum of $K$;
\item $E\oplus T_0=H$ and $E\oplus T_1=H$;
\item $K$ does not tile $H$;
\item for every $0\ne d\in K-K$,
\[
 |\widehat{\1_{T_0}}(d)|^2\ne
 |\widehat{\1_{T_1}}(d)|^2.
\]
\end{enumerate}

[Lemma 32 of arXiv:2609.03736, '2609.03736'] If $A$ is feasible for $\operatorname{LP}_n(d)$ with objective $M$, then
\begin{equation}
 A_i^{\mathrm{sh}}=\frac{n-i}{n}A_i
 \qquad(0\leq i\leq n-1)

\end{equation}
is feasible for $\operatorname{LP}_{n-1}(d)$ and has objective at least
$M/2$.  Consequently, for $0<\delta'<\delta<1/2$,
\begin{equation}
 R_D(\delta)\geq
 1-\frac{\delta}{\delta'}\bigl(1-R_D(\delta')\bigr).

\end{equation}

[Theorem thm-tail-D-x of arXiv:2504.20963, 'Exponential moments of truncated branching random walk martingales'] Suppose $\Phi '(1) =0$. Define 
\begin{equation}
  X= \sum_{|u|=1} [1+ (V(u))_+] e^{- V(u)} . 
\end{equation}  
If the random variable $X$ admits a finite exponential moment, then  there exists constants $C,c>0$   such that 
\begin{equation}
    \mathbb{P}(D^{(x)}_{n} > y )  \leq  C \,  R(x)e^{-x} \, e^{-c y} 
\end{equation}   
for all $ x >0 $, $y \ge 1$  and $ n \in \mathbb{N} \cup \{ \infty \}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition Induced events of arXiv:2603.28936, 'Composition of random functions and word reconstruction'] For all $V_A^-,V_B^-,V_A^+,V_B^+\subseteq [n]$ and functions $\psi_a: V_A^+ \to V_A^-$ and $\psi_b: V_B^+ \to V_B^-$, we let $F(V_A^-,V_B^-,V_A^+,V_B^+,\psi_a,\psi_b)$ be the intersection of the following events (seen as events under the probability measure $\mathbb P$):
\begin{itemize}
\item[-] $\mathbf{a}(x)=\psi_a(x)$, for all $x\in V_A^+$;

\item[-] $\mathbf{b}(x)=\psi_b(x)$, for all $x\in V_B^+$;

\item[-]  $\mathbf{a}^{-1}(y)=\psi^{-1}_a(y)$, for all $y\in V_A^-$; and

\item[-]  $\mathbf{b}^{-1}(y)=\psi^{-1}_b(y)$, for all $y\in V_B^-$.
\end{itemize}
We denote $f_a^-=|V_A^-|$, $f_b^-=|V_B^-|$, $f_a^+=|V_A^+|$ and $f_b^+=|V_B^+|$. We call such an event an \emph{induced} event.  If the role of $V_A^-,V_B^-,V_A^+,V_B^+,\psi_a,\psi_b$ is irrelevant in the context, we write $F:= F(V_A^-,V_B^-,V_A^+,V_B^+,\psi_a,\psi_b)$ to keep the notation light. We also write $\textrm{Supp}(F):= V_A^-\cup V_B^-\cup V_A^+\cup V_B^+$ and $|F|:= |\textrm{Supp}(F)|$.

[Lemma 15 of arXiv:2607.27082, '2607.27082'] Let $X$ be a symmetric strictly $\alpha$-stable Lévy process with
$1<\alpha<2$ and Lévy measure \eqref{Levygene}. Then, for every
$0<\theta<1$,
\begin{equation}
\E[(\tau_1^+(X))^{-\theta}]<\infty.
\end{equation}

[Proposition prop:concentration of arXiv:2412.00279, 'Optimal local storage policy based on stochastic intensities and its large scale behavior'] Assume the above quantile is exact, in the sense that $E[U_{\theta_C}(0)] = C$. Take $C=cN$ with $0< c \leqslant 1$. Then for any $\varepsilon>0$:
  \begin{equation*}
    {\rm P}\left(\left| \frac{U_{\theta_C}(0)}{N} - c\right|>\varepsilon\right)\leqslant 2e^{-2N\varepsilon^2},
  \end{equation*}
  and therefore $U_{\theta_C}(0)/N\overset{{\rm P}}{\longrightarrow} c$ as $N\to\infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 22 of arXiv:2606.12720, 'On McDiarmid's Inequality under Dependence \\ via Approximate Tensorization of Entropy'] {Gaussian Hamming-Lipschitz Concentration}


    Let $X \sim \mathcal N(\mu, \Sigma)$ on $\R^n$ with $\Sigma \in \R^{n \times n}$. Assume $f : \R^n \to \R$ fulfills the bounded differences property with constants $c = (c_1,...,c_n)\T$. Then, with $\kappa^\star(\Sigma) := \eigmax{D^{1/2} \Sigma D^{1/2}}$ where $D := \diagonal{\Sigma\inv}$, 
    \begin{align*}
        \P\Parent{|f(X) - \E[f(X)]| \geq t} 
        \leq 2\exp\Parent{-\frac{2t^2}{\kappa^\star(\Sigma) \twonorm{c}^2}}
        \quad \text{for all $t > 0$}. 
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma eq:uncut-trace-derivative-formula of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[lemma]{lem:uncut-logdet-derivatives}
For \(\eta>0\), \(A,C\in\operatorname{Sym}_n\), and \(r\ge1\),
\begin{equation}
 \frac{\,\mathrm d^r}{\,\mathrm d s^r}
 \operatorname{Tr}\ell_\eta(A+sC)\bigg|_{s=0}
 =
 (-1)^{r-1}(r-1)!\,
 \Re\operatorname{Tr}\!\left\{\bigl((A-i\eta I_n)^{-1}C\bigr)^r\right\}.
\end{equation}
Consequently,
\begin{align}
 \abs{D\operatorname{Tr}\ell_\eta(A)[C]}
 &\le\eta^{-1}\sqrt n\left\lVertC\right\rVert_{\mathrm{HS}},
 \\
 \abs{D^r\operatorname{Tr}\ell_\eta(A)[C,\ldots,C]}
 &\le(r-1)!\eta^{-r}
 \left\lVertC\right\rVert_{\mathrm{HS}}^2\left\lVertC\right\rVert_{\mathrm{op}}^{r-2},
 \qquad r\ge2.

\end{align}
The bounds are uniform in \(n,A,C\).

[Lemma lemmas2.1 of arXiv:2608.01279, 'Stochastic heat equation with nondegenerate Hölder diffusion coefficient: uniqueness below'] Let \((W,W')\) be two independent cylindrical Wiener processes on \(H\),
and let \(a_t,b_t\) be bounded predictable processes
satisfying \(a_t(x)^2+b_t(x)^2=1\) for all $x\in\mathbb{T}$ (so that both processes lie in $L^\infty(\mathbb{T})$ a.s.) Define

\begin{equation}
\begin{aligned}
dB^0_t&=a_t\,dW_t+b_t\,dW'_t,\\
dB^1_t&=b_t\,dW_t-a_t\,dW'_t.
\end{aligned}

\end{equation}
Then \((B^0,B^1)\) is a pair of independent cylindrical Wiener
processes in the enlarged filtration.

