[Theorem 2 (Hitting before killing and forest connectivity) of arXiv:2607.13210, 'Punctured Wilson--Evolving Sets and Root Identities for Massive Kirchhoff Forests'] Let $U\subset V$ and $x\notin U$. Then
\begin{equation}
  h_q(x,U)
  =
  1-\frac{1}{\pi(x)}
  \Ee^{V\setminus U}_{\{x\}}
  \left[\pi\left(S_{T_q}^{V\setminus U}\right)\right].
\end{equation}
Moreover, for every $x,y\in V$, we get:
\begin{equation}
  \Pp(y\in L_x)\leq h_q(x,y).
\end{equation}

\begin{equation}
  \Pp(x\leftrightarrow_q y)
  \leq
  \sum_{z\in V}h_q(x,z)h_q(y,z).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 2 of arXiv:2605.23222, 'On global solutions to the semidiscrete stochastic heat equation'] Let $\Omega' \in \Fc$ such that $Q(\Omega') = 1$ and $\theta_t(\Omega') = \Omega'$ for all $t \in \R$. A measurable map $Z: \Z^d \times \R \times \Omega' \to (0, \infty)$ is called a \emph{global stationary solution} to~\eqref{eq:sSHE} if: 
\begin{enumerate}
\item For every $y \in \Z^d$, $s, t \in \R$ with $s < t$, and $\omega \in \Omega'$, 
$$
Z(y,t,\omega) = \sum_{x \in \Z^d} Z(x,s,\omega) Z_{x,s}^{y,t}(\omega); 
$$
\item For every $y \in \Z^d$, $t \in \R$, and $\omega \in \Omega'$, one has $Z(y,t,\omega) = Z(y,0,\theta_t \omega)$; 
\item For every $y \in \Z^d$, the map $\omega \mapsto Z(y,0,\omega)$ is $(\Fc_{-\infty,0}^{'}, \Bc_0^{\infty})$-measurable, where $\Fc_{-\infty,0}^{'}$ is the restriction of $\sigma(W^x_u: u \leq 0, x \in \Z^d)$ to $\Omega'$ and where $\Bc_0^{\infty}$ is the Borel $\sigma$-field on $(0, \infty)$.  
\end{enumerate}

[Definition 31 of arXiv:2607.29495, 'Fast Mixing for Low-Temperature Potts Models via Poisson Trees'] Let $\ell$ be a positive integer and
let $T\sim \cT^{\down}$.  For every vertex $v\in V(T)$, 
let $T^{\down}_{v,\ell}$ be the maximal subtree of~$T_v$ in which each root-to-leaf path contains at most $\ell$ down-good vertices, excluding the root~$v$.

[Lemma of arXiv:2411.07157, 'Rough differential equations in the flow approach'] Let $\mu \in[0,1]$, $\tau_i \in \mathfrak{T}$, and $\text{$\mathfrak{z}$}^{\tau_i} \in {\mcb{C}}[\tau_i]\,$ for $i = 1,2$. 
We can then write 
\[
\text{$\mathfrak{z}$}^{\tau_2}
\graft^\mu\text{$\mathfrak{z}$}^{\tau_1}=\prod_{\tau\in\mathfrak{T}} \big(\text{$\mathfrak{z}$}^{\tau_2}\graft^\mu\text{$\mathfrak{z}$}^{\tau_1}\big)^\tau\,,
\]
where one has $\big(\text{$\mathfrak{z}$}^{\tau_2}\graft^\mu\text{$\mathfrak{z}$}^{\tau_1}\big)^\tau \in {\mcb{C}}[\tau]$. Moreover, for any $\underline{\tau} \in \tau$, $\underline{\tau}_1 \in \tau_1$ and $\underline{\tau}_2 \in \tau$, again writing for $n \in N(\underline{\tau}_1)$ $\underline{\tau}_{1,2,n} = \underline{\tau}_{2} \graft_{n} \underline{\tau}_{1}$, we have
\begin{equ}  
\big(\text{$\mathfrak{z}$}^{\tau_2}\graft^\mu\text{$\mathfrak{z}$}^{\tau_1}\big)^{\underline{\tau}}
\eqdef
\iota_{\underline{\tau}}
\big(\text{$\mathfrak{z}$}^{\tau_2}\graft^\mu\text{$\mathfrak{z}$}^{\tau_1}\big)^{\tau}
=
\sum_{\substack{n\in N(\underline{\tau}_1)\\
\underline{\tau}_{1,2,n}\in\tau}}\
\frac{1}{|\mathrm{Aut}(\tau)|} 
\sum_{ f \in \mathrm{Iso}(\underline{\tau}_{1,2,n},\underline{\tau})}
\mathbf{f} \big( \text{$\mathfrak{z}$}^{\underline{\tau}_2} \graft^{\mu}_{n} \text{$\mathfrak{z}$}^{\underline{\tau}_1} \big)\;.
\end{equ}

