[Proposition of arXiv:2606.21556, 'Mean field limit of non-exchangeable interacting diffusions on co-evolutionary networks'] The following conditions are equivalent:
	\begin{enumerate}
		\item[(i)] The map \([0,1]\to \mathcal{P}(\mathcal{C}^d_T)\), given by \(\xi \mapsto P^{\xi}\), is measurable
		when \(\mathcal{P}(\mathcal{C}^d_T)\) is endowed with the narrow topology.
		\item[(ii)] For every \(0\leq t_1\leq \ldots\leq t_n\leq T\) with \(n\in \mathbb{N}\), the map
		\[
			\begin{aligned}
				[0,1] &\longrightarrow \mathcal{P}((\mathbb{R}^d)^n) \\
				\xi &\longmapsto \pi_{t_1,\ldots,t_n \#}  P^{\xi},
			\end{aligned}
		\]
		is measurable.
	\end{enumerate}

[Lemma lem:boundary_part_of_loops of arXiv:2609.04140, 'The conformally invariant metric on $\CLE_4$ III:\\ uniqueness'] Fix $j \in \{1,\ldots,N\}$.  If 
	\begin{align*}
		\partial U_j \not \subseteq \overline{\bigcup_{\SCL \in \Gamma_A^{\mathrm{out}} \cup \Gamma_A^{\mathrm{in}} \cup \Gamma_A} \SCL},
	\end{align*}
	then we have that $U_j$ is surrounded by an outermost loop in $\overline{\Gamma}$.

[Corollary 12 of arXiv:2604.13149, 'The Distributional Tail of Worst--Case Quickselect'] For every \(t>0\),
\begin{equation}
\PP{\Svar>t}
\le
\inf_{\theta>0}\exp\!\bigl(-\theta t+2e^\theta\bigr).
\end{equation}
In particular, for every \(t>2\),
\begin{equation}
\PP{\Svar>t}
\le
\exp\!\Bigl(-t\log(t/2)+t\Bigr)
=
\exp\!\Bigl(-t\log t+(1+\log 2)t\Bigr).
\end{equation}
Equivalently,
\begin{equation}
-\log \PP{\Svar>t}
\ge
t\log t-(1+\log 2)t,
\qquad t>2.
\end{equation}

[Lemma lem:moment-M of arXiv:2412.05142, 'Strong convergence of the Euler scheme for singular kinetic SDEs driven by $\alpha$-stable'] Let $M$ be as (equation def:noise of the paper). Then for any $p\geqslant1,\gamma>0$, for any $(s,t)\in[0,1]_\leqslant^2$,  there  exists $C=C(\gamma,p,d,\alpha,\epsilon)>0$ so that
    \begin{align}

         \big\||M_t-\Gamma_{t-s}M_s|_{\boldsymbol{a}}^\gamma\wedge1\big\|_{L_p(\Omega)}  \leqslant C|t-s|^{\frac{\gamma}{\alpha}\wedge\frac{1}{p}-\epsilon}.
    \end{align}

