body:
[Theorem thm:5.1 of arXiv:2608.27474, 'Nonlocality of Cover-Time Changes Under Edge Addition'] For a path start \(x_j\), \(0\le j\le L\),
\begin{equation}
\boxed{
\delta_{x_j}(\lambda)
=2\lambda\left[
j-\frac{2L+3}{1+2\lambda}
+\frac{jL(L+3)}{(L+1)D_L(\lambda)}
\right].
}

\end{equation}
For either endpoint start \(u\) or \(v\),
\begin{equation}
\boxed{
\delta_u(\lambda)=\delta_v(\lambda)
=\lambda\left[
2L+1-\frac{2(2L+3)}{1+2\lambda}
+\frac{L(L+3)(2L+1)}{(L+1)D_L(\lambda)}
\right].
}

\end{equation}

At unit conductance no response vanishes. More precisely, for \(L\ge1\),

\begin{equation}
\delta_{x_j}(1)<0
\quad\Longleftrightarrow\quad
0\le 2j\le L+1,

\end{equation}
and all remaining path starts have positive response. When \(L=0\),
the sole path start has response \(-2\). Endpoint starts satisfy
\begin{equation}
\delta_u(1)=\delta_v(1)
=\frac{2(6L^3+11L^2-L-3)}
{3(L+1)(3L+2)},

\end{equation}
which is \(-1\) for \(L=0\) and strictly positive for every
\(L\ge1\).

[Definition SAZAS of arXiv:2411.04590, 'Singular stochastic delay equations driven by fractional Brownian motion: Dynamics, longti'] Let $\frac{1}{3} < \gamma \leq \frac{1}{2}$, and let $X:\mathbb{R} \to \mathbb{R}^d$ be such that $(X, \mathbb{X})$ is a \emph{$\gamma$-rough path}. Fix $r > 0$. We say that $\mathbf{X}$ is a \emph{delayed $\gamma$-rough path} if there exists a continuous function $\mathbb{X}(-r)$ given by
		\begin{align*}
			\mathbb{X}(-r): \mathbb{R} \times \mathbb{R} \to \mathbb{R}^d \otimes \mathbb{R}^d
		\end{align*}
		such that for every interval $[a,b] \subset \mathbb{R}$,
		\begin{align}
			\begin{split}
				&\Vert\mathbb{X}(-r)\Vert_{2\gamma,[a,b]}< \infty, \\
				& \quad \mathbb{X}_{s,t}(-r) = \mathbb{X}_{s,u}(-r) + \mathbb{X}_{u,t}(-r) + X_{s-r,u-r} \otimes X_{u,t}, \quad \forall s, u, t \in \mathbb{R}, \ s < u < t.
			\end{split}
		\end{align}
		We denote a delayed $\gamma$-rough path by $\mathbf{X} = (X, \mathbb{X}, \mathbb{X}(-r))$. For an interval $J = [a,b]$, we define the norm of $\mathbf{X}$ as
		\begin{align*}
			\|\mathbf{X}\|_{\gamma, J} := \|X\|_{\gamma,J} +\Vert\mathbb{X}\Vert_{2\gamma,J}+ \Vert\mathbb{X}(-r)\Vert_{2\gamma,J}.

		\end{align*}
		We use $\mathscr{C}^{\gamma}_2(\mathbb{R}^d)$ to denote the set of delayed $\gamma$-rough paths.

[Proposition prop:weld-sle-loop of arXiv:2510.05850, 'Three-point connectivity constant for $q$-state Potts spin clusters'] For $\kappa \in (8/3,4)$ and $\gamma=\sqrt{\kappa}$, there exists a constant $C=C(\kappa)$ such that
    \begin{equation}
        \mathrm{QS}_2 \otimes \SLE_\kappa^{\rm sep} = C \int_0^\infty \mathrm{QD}_{1,0}(\ell) \times \ell\,\mathrm{QD}_{1,0}(\ell) \mathop{}\!\mathrm{d} \ell,
    \end{equation}
    where the right-hand side represents the uniform conformal welding along the boundaries of two independent samples from $\mathrm{QD}_{1,0}$ conditioned to have the same quantum boundary lengths. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defin 15 of arXiv:2604.03548, 'Degree-preserving conservative processes and a unified approach for their hydrodynamics'] For $\delta>0$ and a path $\pi$ in ${D([0,T],H^{-m}(\mathbb T))}$, the uniform modulus of continuity of $\pi$, is defined by
\begin{equation*}
\omega_{\delta}(\pi)=\sup_{\substack{|s-t|<\delta, \\0\leq{s,t}\leq{T}}}\|\pi_{t}-\pi_{s}\|_{-m}.
\end{equation*}

