[Proposition prop: Gamma-stability of arXiv:2604.05941, 'Banach spaces of continuous paths with finite $p$-th variation'] In the setting of Theorem~(thm: transported Banach of the paper), assume that the embedding
    $B\hookrightarrow L^p([0,1])$ is continuous. Consider the mapping
    \begin{equation}    
        y \mapsto [y]^{(p)}_{\mathbb{T}}
    \end{equation}
    from $(\mathcal L_{\bar x}(B), \|\cdot\|_{\mathcal L})$ to $(C([0,1]), \|\cdot\|_{\infty})$. Then the following statements hold.
    \begin{enumerate}[(i)]
        \item For $y_i=g_i\bar x\in\mathcal L_{\bar x}(B)$, $i=1,2$,
        \begin{equation}
            \big\| [y_1]^{(p)}_{\mathbb{T}} - [y_2]^{(p)}_{\mathbb{T}} \big\|_{\infty}
            \le C_p\,\big\||g_1|^p-|g_2|^p\big\|_{L^1}.
        \end{equation}
        \item If $y_n\to y$ in $(\mathcal L_{\bar x}(B),\|\cdot\|_{\mathcal L})$, then
        $[y_n]^{(p)}_{\mathbb{T}} \to [y]^{(p)}_{\mathbb{T}}$ uniformly on $[0,1]$.
        \item The mapping (equation eq: mappping of the paper) is locally Lipschitz. More precisely, if $K_{B,p}>0$ is such that $\|g\|_{L^p}\le K_{B,p}\|g\|_B$ for $g\in B$, then for $y_i=g_i\bar x$
        \begin{equation}
            \big\| [y_1]^{(p)}_{\mathbb{T}} - [y_2]^{(p)}_{\mathbb{T}} \big\|_{\infty}
            \le p C_p K_{B,p}^{p} \Big(\|y_1\|_{\mathcal L}^{p-1}+\|y_2\|_{\mathcal L}^{p-1}\Big)\,\|y_1-y_2\|_{\mathcal L}.
        \end{equation}
        In particular, on each ball $\{y:\ \|y\|_{\mathcal L}\le R\}$, (equation eq: mappping of the paper) is Lipschitz with constant
        $2pC_p K_{B,p}^p R^{p-1}$.
    \end{enumerate}

