[Definition of arXiv:2609.00978, 'Towards Categorical K\"ahler Geometry'] Given a quiver $Q$, define $\cA(Q)$ to be the graded $*$-algebra with the following basis:
\begin{itemize}
    \item $e_i$, $f_i$ for each vertex $i\in Q_0$, $|e_i|=|f_i|=0$, $e_i^*=e_i$, $f_i^*=f_i$,
    \item $a$, $a^*$ for each arrow $a\in Q_1$, $|a|=1$, $|a^*|=-1$. 
\end{itemize}
The non-zero products are:
\begin{gather*}
    e_i^2=e_i, \qquad e_if_i=f_ie_i=f_i, \qquad
    e_ja=ae_i=a,\qquad e_ia^*=a^*e_j=a^*, \\
    aa^*=\sqrt{-1}f_j, \qquad a^*a=-\sqrt{-1}f_i,
\end{gather*}
where $a\colon i\to j$ is any arrow.

[Definition def:laplacian-general of arXiv:2505.02685, 'On the Spectral Expansion of Monotone Subsets of the Hypercube'] The \emph{directed Laplacian operator} of $G$ is the operator $\mathscr{L}^- = \mathscr{L}^-_{G} : L^2(V) \to
    L^2(V)$ given by
    \begin{equation}
        \mathscr{L}^-f \vcentcolon= \frac{1}{2} \sum_{u,v \in V} w(u,v) \left(f(u) - f(v)\right)^+ (e_v - e_u)
    \end{equation}
    for each $f \in L^2(V)$. In this paper, we use the notation $x^{+}:=\max\{x,0\}$, for $x\in \mathbb{R}$.

[Lemma eq:useful_bound_1 of arXiv:2607.18011, 'From local giants to locality in long-range percolation'] \thlabel{lem:useful_bounds}
    Let $\alpha \in(0,2)$ and $\delta \in (\max(0, 1-\alpha),2-\alpha)$.

    For all $c > 0$ we can choose $r_0$ sufficiently large such that  for all $i \geq 1$

    \begin{align}

        \varepsilon_i 
        \kappa_{i,j} 
        r_{i-1}^{d(2 - \alpha - \delta)} 
        & \geq 
        c 
        r_{i}^{d(2 - \alpha - \delta)},
        \\

        (r_i / r_0)^{d(2 -\alpha - \delta)} 
        & \geq 
        c
        \log(e/\varepsilon_{i+1}),
        \\

        \log
        (
            6 
            (
                e 
                \kappa_{i,j}
            )^2
        )
        -
        \kappa_{i,j}
        r_{i-1}^{2d}/r_i^{d \alpha}
        & \geq 
        c
        (r_i/r_0)^{d(2-\alpha-\delta)}.
    \end{align}

