[Proposition thm3 of arXiv:2411.13430, 'Optimal subelliptic super-Poincar\'e and isoperimetric inequalities on stratified Lie grou'] Assume as in Theorem (thm1 of the paper) except that $n_1 = 1$. If $p = \alpha + 1$ then $I_\mu \gtrsim \mathcal{U}_1$, and otherwise if $p > \alpha + 1$ then $I_\mu$ satisfies 
    \begin{equation}
        I_\mu \gtrsim_\delta \mathcal{U}_r, \quad r = \frac{(\alpha+1-\delta)p}{\alpha+1-\delta + \alpha(p-\delta)} \in \left[1, \frac{(\alpha+1)p}{\alpha+1+\alpha p}\right)
    \end{equation}
    for each $\delta \in (0, 1]$ and where $\gtrsim_\delta$ indicates the constant depends on $\delta$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 11 of arXiv:2605.17494, 'Generalized intersection exponents and local cut points for three-dimensional Brownian loo'] There exist constants $c_1,c_2$ such that the following. For every $0<\epsilon<\frac{1}{2}$, define
    $$V^-=((u+A_{\frac{1}{20}})\cup \mathcal{B}_{\frac{\epsilon}{2}}(u))\cap \mathcal{B}_e, V=((u+A)\cup \mathcal{B}_{\epsilon}(u))\cap \mathcal{B}_e.$$
    Then if $x \in S_0,|x-u| \le \frac{\epsilon}{4}$,
\begin{equation}
    \Pb^{x}(B[0,T_1] \subseteq V^-) \ge c_1\epsilon^{c_2}.    
    \end{equation}

[Proposition 14 (Universal construction in the regime $q\ge1$) of arXiv:2608.31157, 'Sharp Approximation Rates for Neural Networks with Affine Latent Parameterizations'] Let $d,S,D\in\N^+$ with $S\le D$, and let $q,K,\widehat{L}_{d,D}$ be the
quantities in \eqref{eq:qK}.  Assume $q\ge1$.  There exist an architecture
$\Phi\in\Arch(N_d,\widehat{L}_{d,D})$ with input dimension $d$ and an affine map
\[
 \calA_0\in\aff(3S+1,P_\Phi),
\]
both independent of $f$.  For every $f\in C([0,1]^d)$, there exists
$\bmxi_f\in\R^{3S+1}$ such that, with $\bmtheta_f:=\calA_0(\bmxi_f)$, one has
\begin{equation}
 \left\lVert f-\Phi_{\bmtheta_f}\right\rVert_{L^\infty([0,1]^d)}
 \le(d+2)\omega_f\bigl(\tfrac{\sqrt d}{K}\bigr).
\end{equation}
Moreover,
\begin{equation}
 P_\Phi\le B_dD.
\end{equation}

[Theorem thm:mart of arXiv:2607.10708, 'A class of Markov processes with resetting and applications to cybersecurity'] Let $X=(N,\Lambda,C)$  be a self-exciting PDMP with resetting. Then, the following processes are $({(\mathcal F_t)}_{t \ge 0}, \mathbb P^{\,\alpha,x})$-martingales for each $x\in S$:
\begin{align}
M^{N}_t&= N_t -\int_0^t\Lambda_s ds + \int_0^t (N_s+1)\Lambda_s {\bar{G}_{\ell}(N_s+1, A-\Lambda_s)}ds; \\
M^{\Lambda }_t&= \Lambda_t- \int_0^t \big(\alpha(\beta-\Lambda_s)+  L^o(N_s+1, \Lambda_s)\big)ds,\\
M^{C}_t&= C_t-\mu_Z \int_0^t\Lambda_s ds,
\end{align}
where $\bar{G}_\ell=1-G_\ell$,  and
\begin{equation} 
L^o(n,\lambda):= \lambda ({\lambda^o} - \lambda) \bar{G}_{\ell}(n, (A-\lambda)\textrm{-}) +  \lambda \int\mathds{1}_{\{y<A-\lambda\}} \, y \,dG_{\ell}(n, y).
\end{equation}

[Definition 3 (Discrete height function) of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] Given a simply-connected, tilable domain $D$, a tiling $\eta\in\Omega_D$, and a point $z_0\in D\cap \mathbb T_N$, we define $H_{\eta} : D \cap \mathbb{T}_N \rightarrow \mathbb{R}$ as follows. First set $H_\eta(z_0)=0$; then, $H_{\eta}$ is determined by the relations 
  \begin{eqnarray}

    H_\eta(z')-H_\eta(z)=N^{-1}\cdot
    \begin{cases}
      -1+{\bf 1}_{(z,z') \text{ is the edge of a lozenge in $\eta$}} & \text{if } z'-z=(N^{-1},0) \\
      {\bf 1}_{(z,z') \text{  is the edge of a lozenge in $\eta$}} & \text{if } z'-z=(0,N^{-1})
    \end{cases}.
  \end{eqnarray}

\noindent We further extend $H_{\eta}$ to $D$ by linearity. In the specific case $D=\mX_{a,b,c}$ we always choose $z_0=(0,0)$.

