body:
[Lemma 15 of arXiv:2606.21111, 'On Elephant Random Walk with Delayed Amnesia'] For $n\ge a$, let $Y_n$ be as defined in \eqref{Yn}. Then,
\begin{equation*}
\mathbb{E}(Y_n^2)\sim\begin{cases}\frac{n^{2a-1}}{4a(1-p)-1}\ \ \text{for}\ 0\le p<(4a-1)/4a,\vspace{.1cm}\\
	n^{2a-1}\log n\ \ \text{for}\  p=(4a-1)/4a,\vspace{.1cm}\\
	c'n^{2a(2p-1)}\ \ \text{for}\  (4a-1)/4a<p\le1,
\end{cases}
\end{equation*}	
where $c'$ is some non zero constant. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 25 (Straight signature line) of arXiv:2607.26377, '\textbf{Entire Logarithmic Signatures\\ of Bounded-Variation Paths in Finite Dimensions}'] Let $E$ be a finite-dimensional real Hilbert space, denote its norm by $\norm{\cdot}_E$, and let $0\neq v\in E$.
Then
\[
\mathcal{A}_v=\set{\e^{tv}:t\in\R}
\]
is a closed geodesic line in $(\Sl(E),d_\infty)$, and
\begin{equation}
d_\infty(\e^{sv},\e^{tv})=\abs{t-s}\,\norm{v}_E
\qquad (s,t\in\R).
\end{equation}
If $a\in\Sl(E)$ and $g=a\e^v a^{-1}$, then
\[
\mathcal{A}=a\mathcal{A}_v
 =\set{a\e^{tv}:t\in\R}
\]
is a closed convex geodesic line, invariant under left multiplication by $g$, and
\begin{equation}
g\,a\e^{tv}=a\e^{(t+1)v}.
\end{equation}

[Lemma lemma12 of arXiv:2511.19391, 'Central limit theorem for supercritical Crump-Mode-Jagers processes counted with non-indiv'] Let $\varphi$ be a random characteristic. 
\begin{enumerate}[label=(\textbf{\roman*})]
\item If there exist $\delta_{1} \in [0, \alpha)$ and $\delta_{2} \in  (\alpha, \infty)$ such that $\sup_{t\in \mathbb{R}} e^{-(\delta_{1} t \wedge \delta_{2} t)} |\varphi(t)| \in L^{1}(\Omega, \mathcal{F}, \mathbb{P})$, then $\varphi$ satisfies (C1 of the paper). 

\item If there exist $\delta_{1} \in [0, \alpha/2)$ and $\delta_{2} \in  (\alpha/2, \infty)$ such that $\sup_{t\in \mathbb{R}} e^{-(\delta_{1} t \wedge \delta_{2} t)} |\varphi(t)| \in L^{2}(\Omega, \mathcal{F}, \mathbb{P})$, then $\varphi$ satisfies (C2 of the paper)-(C3 of the paper). 
\setcounter{Cond5}{\value{enumi}}
\end{enumerate}

\noindent Suppose further that that assumptions (A1 of the paper)-(A7 of the paper) holds. 
\begin{enumerate}[label=(\textbf{\roman*})]
\setcounter{enumi}{\value{Cond5}}
\item If there exists $\delta_{2} \in  [\vartheta, \infty)$ such that $\sup_{t\in (-\infty, 0)} e^{-\delta_{2} t} |\varphi(t)| \in L^{1}(\Omega, \mathcal{F}, \mathbb{P})$, then, for all $h \in \mathbb{N}_{0}$ and $\varepsilon >0$, 
\begin{align}  
\mathbb{E} \left[ \sum_{i=0}^{h} \sum_{|u|=i} \sup_{|s-t|\leq \varepsilon}|\varphi_{u}(s-S(u))\mathbf{1}_{(-\infty,0)}(s-S(u))| \right] < \infty. 
\end{align}

\item If there exist $\delta_{1} \in [\vartheta, \alpha]$ and $\delta_{2} \in  [\delta_{1}, \infty)$ such that $\sup_{t\in \mathbb{R}} e^{-(\delta_{1} t \wedge \delta_{2} t)} |\varphi(t)| \in L^{2}(\Omega, \mathcal{F}, \mathbb{P})$, then, for all $h \in \mathbb{N}_{0}$ and $\varepsilon >0$,  
\begin{align}  
\left(\sum_{i=0}^{h} \left( \sum_{|u|=i} |\varphi_{u}(t-S(u))| \right)^{2}\right)_{|s-t|\leq \varepsilon} \quad \text{is uniformly integrable}.
\end{align}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

