[Corollary 3 (\textsf{Stationary terminal condition}) of arXiv:2609.02064, 'Coalescence and fluctuations of O'Connell--Yor polymers\\ via the free-energy correlation '] For $n\geq1$, $\be>0$, and $x\neq\wt x$,
  \begin{align}
    \frac{\partial}{\partial x}
    \EE\bigl[
      F_{\wt x}^{\rstat,\be}F_x^{\rstat,\be}
    \bigr]
    =
    \EE\bigl[Q_0^{\rstat,\be}\{\ga_n>-x\}\bigr]
    -\ind_{\{\wt x<x\}}.
  \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 3 of arXiv:2607.07552, 'Weak convergence rate for the Cox--Ingersoll--Ross process'] Let $f\in\mathcal{C}^{(q)}((0,\infty),\mathbb{R})$ and $m\geq q$, $m\in\mathbb{N}$, be such that there exists $K>0$ with
	\begin{equation}
		|f^{(q)}(x)|\leq K(1+x^m)\quad\forall x\geq 0.
	\end{equation}
	Then the function $v:\mathbb{R}_{+}\times[0,T]\to\mathbb{R}$ defined by $v(x,t):=\mathbb{E}^x[f(X_{T-t})]$ satisfies the PDE
	\begin{equation}
		\partial_t v+b(x)\partial_x v+{\sigma(x)^2\over 2}\partial_{xx}v=0,\quad v(T,x)=f(x).
	\end{equation}
	Moreover, the derivatives of $v$ are uniformly bounded, and there exists $K>0$ such that
	\begin{equation}
		\left|\partial^{k}_x\partial^{r}_t v(x,t)\right|\leq K(1+x^{m+q+r})\quad\forall(x,t)\in\mathbb{R}_{+}\times[0,T],\quad k+2r\leq q.
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

