body:
[Theorem thm:tailrl-weight-form of arXiv:2609.02987, 'Tail Likelihood Reinforcement Learning'] For an input $x$, the population-level gradient of TailRL{} is estimable as,
\begin{equation}
\nabla_\theta J_{\mathrm{TailRL{}}}(\theta;x)
=\mathbb{E}_{z\sim\pi_\theta(\cdot\mid x)}
\left[
\left(
\int_0^{r(x,z)}
\frac{d\tau}{p_\theta(x,\tau)}
\right)
S(x,z)
\right].

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 3 (Reference-compatible state lift) of arXiv:2609.02196, 'Schr\"odinger Bridges on Lie Group Manifolds for Probabilistic Intrinsic Generation'] If \(Q_i(\dd g\dd\bm\xi)=Q_i^\G(\dd g)Q_i(\dd\bm\xi\mid g)\) and \(\rho\ll Q_i^\G\), then the unique state law with group marginal \(\rho\) minimizing \(\KL(\cdot\|Q_i)\) is
\begin{equation*}
\pi^\circ(\dd g\dd\bm\xi)=\rho(\dd g)Q_i(\dd\bm\xi\mid g).
\end{equation*}
The proof is given in \cref{app:proof-canonical-lift}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 1 (Resolvents) of arXiv:2608.29872, 'Local Laws and Outlier Eigenvalues for Spiked Separable Covariance Matrices'] For $z = E+ \ii \eta \in \mathbb C_+,$ we define the following resolvents for $\al=1,2$: 
\begin{equation}
 \mathcal G_{\al}(X,z):=\left({\mathcal Q}_{\al}(X) -z\right)^{-1} , \ \ \ \wt{\mathcal G}_{\al} (X,z):=(\wt{\mathcal Q}_{\al}(X)-z)^{-1} .
\end{equation}
 We denote the ESD $\rho^{(p)}$ of ${\mathcal Q}_{1}$ and its Stieltjes transform as
\be
\rho^{(p)} := \frac{1}{p} \sum_{i\in\cal I_1} \delta_{\lambda_i({\mathcal Q}_1)},\quad m^{(p)}(z):=\int \frac{\rho^{(p)}(\dd x)}{x-z}=\frac{1}{p} \mathrm{Tr} \, \mathcal G_1(z).
\ee
We also introduce the following quantities:
\begin{equation}
 m_1^{(n)}(z):= \frac{1}n\tr \left(A \mathcal G_1(z)\right) ,\quad m_2^{(n)}(z):=\frac{1}{n}\tr\left( B\mathcal G_2(z)\right). 
\end{equation}

[Lemma eq:gaussian-shift of arXiv:2607.14087, 'Stochastic Domination of Gaussian Maxima: A Resolution of the Weak Simplex Conjecture'] \label[lemma]{lem:gaussian-shift}
Let $X\sim\mathcal N(0,R)$ for a positive-semidefinite matrix $R$.  For every
$a\in\mathbb R^m$ and every nonnegative Borel function
$F:\mathbb R^m\to[0,\infty]$,
\begin{equation}
  \mathbb E\!\left[e^{a^{\mathsf T}X}F(X)\right]
  =e^{\frac12a^{\mathsf T}Ra}\mathbb E F(X+Ra).
\end{equation}

[Theorem 16 ({\cite[Theorem 4.12) of arXiv:2607.27150, 'Modelling Anomalous Diffusion: The Role of CTRWs and Non-Local Dynamics'] {savtoa}}]
		Let  $\alpha: \mathbb{R}\mapsto (0,1)$, with $\alpha^*=\min_{x\in \mathbb{R}}\alpha(x)>0, \max_{x\in\mathbb{R}}\alpha(x)<1$ and \[1>\lim_{x \to +\infty}\alpha(x)=\alpha_I>\alpha^*,\,\,1>\lim_{x\to -\infty}\alpha(x)=\alpha_J>\alpha^*.\] Also, let there exist $\beta_0>0$ small enough such that for all $\beta_0\geq \beta$, the set $A_\beta=\{x\in\mathbb{R}:\alpha(x)<\alpha^*+\beta<1\}$ is bounded and satisfies $0<\mathpzc{l}({A_\beta})<\infty$ and $\mathpzc{l}(\partial A_\beta)=0$. Then,
		\begin{enumerate}
			\item if $2\alpha^*<\min\{\alpha_I,\alpha_J\}$, then for all $0\leq \beta\leq \beta_0$
			\begin{equation}
				\lim_{t \to +\infty}\frac{\int_{0}^{t}\mathds{1}_{[B(L(s))\in A_\beta]}ds}{t}=1,\,\mathds{P}^{(x,0)}\text{-a.s.};
			\end{equation}
			\item  if $2\alpha^*>\min\{ \alpha_I,\alpha_J\}$, then for any $K>0$,
			\begin{equation}
				\lim_{t \to +\infty}\frac{\int_{0}^{t}\mathds{1}_{\big[B(L(s))\in A^c_\beta\cap [-K,K]^c\big]}ds}{t}=1,\,\mathds{P}^{(x,0)}\text{-a.s.}.
			\end{equation}
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:howardlieblemma of arXiv:2411.09516, 'Sharp Matrix Empirical Bernstein Inequalities\footnote{NeurIPS 2025 Poster}'] Let $\{  \mathbf{Z} _n \}$ be an $\mathcal{S}_d$-valued, adapted martingale difference sequence. Let $\{ \mathbf{C} _n\}$ be an $\mathcal{S}_d$-valued adapted process, $\{ \mathbf{C} _n'\}$ be an $\mathcal{S}_d$-valued predictable process. If 
\begin{equation}
    \mathbb E  (\exp(  \mathbf{Z} _n -   \mathbf{C} _n) | \mathcal{F}_{n-1}) \preceq \exp(   \mathbf{C} _n'  ),
\end{equation}
holds for all $n$, then the process
\begin{equation}
  \textstyle  L_n = \mathrm{tr} \exp \left( \sum_{i=1}^n  \mathbf{Z} _i -  \sum_{i=1}^n  (  \mathbf{C} _i +  \mathbf{C} _i' )  \right)
\end{equation}
is a nonnegative supermartingale. Further,
\begin{equation}
\textstyle   L_n \geqslant \exp \left( \lambda_{\max}\left(\sum_{i=1}^n  \mathbf{Z} _i \right)-   \lambda_{\max}\left( \sum_{i=1}^n (  \mathbf{C} _i +  \mathbf{C} _i' ) \right)  \right).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor derivative bound on ratio of G_n of arXiv:2603.17858, 'Decay of correlations and zeros for the hard-core model'] Given $\lambda_+>\lambda_->0$, $C>0$ and $\alpha\in (0,1)$ there exists a constant $A>1$ such that the following holds: if $(\lambda_n)$ and $(\widehat\lambda_n)$ in $[\lambda_-,\lambda_+]$  satisfy $|\lambda_n-\widehat \lambda_n|<C\alpha^n$ for all $n$, then 
    \begin{equation}

        1/A\leq \abs[\bigg]{\frac{G_{n}'}{\widehat{G}_{n}'}} \leq A.
    \end{equation}

[Proposition 37 of arXiv:2608.26084, 'Localic Esakia Duality\\via Conic Frames'] There is a functor
	\begin{align*}
		\cone\colon \rosLoc &\longrightarrow \dcFrm^\op;
		\\
		(X,R)&\longmapsto (\Opens X,\Down);
		\\
		f &\longmapsto f^{-1}.
	\end{align*}

