body:
[Theorem LUE left soft of arXiv:2605.12777, 'Mesoscopic Rates of Convergence for Complex Wishart Matrices at the Leftmost Spectrum Edge'] (left soft edge) Consider an LUE $L_{a,N}$ such that $\lim\limits_{N\rightarrow\infty}\frac{N}{n}=\gamma\in(0,1)$ where $n:=N+a$. Let $I\subset[s,+\infty)$ for $s>-\infty$. Define parameters:
    \begin{equation*}
      \begin{array}{ll}
      \mu^L_{k,m}:=\left(\sqrt{k+\frac{1}{2}}-\sqrt{m+\frac{1}{2}}\right)^2,\\
      \sigma^L_{k,m}:=\left(\sqrt{k+\frac{1}{2}}-\sqrt{m+\frac{1}{2}}\right)\left(\left(m+\frac{1}{2}\right)^{-\frac{1}{2}}-\left(k+\frac{1}{2}\right)^{-\frac{1}{2}}\right)^{\frac{1}{3}},
      \end{array}
    \end{equation*}
\begin{equation*}
    \mu_L=\left(\frac{1}{\sqrt{\sigma_{n-1,N}^{L}}}+\frac{1}{\sqrt{\sigma_{n,N-1}^{L}}}\right)\left(\frac{1}{\mu^L_{n-1,N}\sqrt{\sigma_{n-1,N}^L}}+\frac{1}{\mu^L_{n,N-1}\sqrt{\sigma_{n,N-1}^{L}}}\right)^{-1}
\end{equation*}
and
\begin{equation*}
    \sigma_L=\left(\frac{\sqrt{\sigma_{n-1,N}^{L}}}{\mu^L_{n-1,N}}+\frac{\sqrt{\sigma_{n,N-1}^{L}}}{\mu^L_{n,N-1}}\right)\left(\frac{1}{\mu^L_{n-1,N}\sqrt{\sigma_{n-1,N}^{L}}}+\frac{1}{\mu^L_{n,N-1}\sqrt{\sigma_{n,N-1}^{L}}}\right)^{-1}.
\end{equation*}
Let $\mathcal{X}_{L_{a,N}}^{LS}$ denote the left-soft-edge-scaled point process for $L_{a,N}$ with the kernel $K_{L_{a,N}}^{LS}(x,y):=\sigma_{L}K_{L_{a,N}}(t_{L_{N}}(x),t_{L_{N}}(y))$ where $t_{L_N}(x):=\mu_{L}-\sigma_{L}x$ for any $x\in I$. Then on $A\subset I$, there exists $n(s,\gamma)\in\mathbb{N}$ such that for any $N>n(s,\gamma)$,
\begin{equation}
W_1(\mathcal{N}_{L_{a,N}}^{LS},\mathcal{N}_{Ai})\le\frac{g(s,\gamma)e^{-s}}{N^{\frac{2}{3}}}
\end{equation}
where $g(s,\gamma)$ is continuous and non-increasing with respect to $s$ for any fixed $\gamma$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:pnqn of arXiv:2607.22291, 'Rare subtree patterns in size-conditioned Bienaymé trees: Poisson approximation and declum'] Assume (hyp:M of the paper) holds for $(G_k)$ along $(k_{n})$ with respect to $(M_{n})$. Set $p_n = \P(I_1^{(M_n)}=1)$ and $r_n = \sqrt{a_{M_n} a_n}$. Then:
\begin{enumerate}
\item[(i)] $\P(I_1^{(M_n)} = 1, |S_{M_n}| > r_n) = o(p_n)$.
\item[(ii)] $p_n \sim q_n \sim \pi_n$.
\end{enumerate}

[Lemma lem:cdE of arXiv:2601.10624, 'Source localisation in simple random walks'] For each $d \geqslant 5$, we have
    \begin{equation*}
        \widetilde{c}(d) \geqslant \mathbb{E}[J]^{-1}.
    \end{equation*}
    Consequently, $\widetilde{c}(d) > 0$ for each $d \geqslant 5$, and
    \begin{equation*}
        \widetilde{c}(d) = 1 - O(1/d).
    \end{equation*}

