[Thm thm1.2 of arXiv:2412.08497, 'Time discretization of Quadratic Forward-Backward SDEs with singular drift'] Consider FBSDE (equation 2.1 of the paper)--(equation 2.2 of the paper) such that $b$ and $g$ satisfy Assumptions (assum2.1 of the paper) and the terminal value $\xi$ has the following structure
				\begin{itemize}
					\item Let $\pi_0: 0=s_0 <\cdots < s_{r-1}<s_r=T$ be a partition, we set $\xi= \varphi(X_{s_0},\cdots,X_{s_r})$, where $\varphi: \mathbb{R}^{m\times r} \rightarrow \mathbb{R}$ is bounded and satisfies (equation 2.6 of the paper)--(equation 2.7 of the paper). 
					\item Let $\pi_1: 0=t_0 <t_1<\cdots < t_N=T$ be another partition and $h= \sup_j|t_{j+1}-t_j|$.
				\end{itemize}
				Then, for any $p >p_0'> 1$ there is a constant $C$ only depending on $p,d,T$, $\|b\|_{L^{\infty}([0,T];C_b(\mathbb{R}^d))}$ and $S(\varphi)$ and not depending on the partitions $\pi_0$ and $\pi_1$ such that  
				\begin{align*}
					\mathbb{E} \big[\sup_{v\in [s,t]}|Y_v-Y_t|^{2p}\big] \leq C |t-s|^p\\
					\sum_{j=0}^{N-1}\mathbb{E}\Big(\int_{t_j}^{t_{j+1}}|Z_t - Z_{t_j}|^2 \mathrm{d}t \Big)^p \leq C h^p.
				\end{align*}
				where $p_0'$ satisfied $1/p_0 + 1/p_0' =1$ and $p_0$ is such that $\mathcal{E}\left(\nabla_z g*W\right) \in L^{p_0}$.

[Conjecture conj:conjectural_limit_of_full_barcode_kernel of arXiv:2507.22011, 'Random Lozenge Waterfall:\\Dimensional Collapse of Gibbs Measures'] The following limit exists for all $t,s\in \mathbb{Z}$:
	\begin{equation}

		\lim_{L\to\infty}
		\mathbf{i}^{t-s} q^{2L(s-t)}\hspace{1pt}
		K^{\mathrm{barcode}}_{(L)}(s,t)
		\eqcolon
		\mathcal{K}^{\mathrm{barcode}}(s,t).
	\end{equation}
	The limit kernel $\mathcal{K}^{\mathrm{barcode}}(s,t)$
	is symmetric in $s$ and $t$,
	and is $2\times 2$ block Toeplitz:
	\begin{equation*}
	\begin{pmatrix}
		\mathcal{K}^{\mathrm{barcode}}(s,t)& \mathcal{K}^{\mathrm{barcode}}(s,t+1)\\
		\mathcal{K}^{\mathrm{barcode}}(s+1,t) & \mathcal{K}^{\mathrm{barcode}}(s+1,t+1)
	\end{pmatrix}
	=
		\begin{pmatrix}
			\mathcal{K}^{\mathrm{barcode}}_{00}(s-t) & \mathcal{K}^{\mathrm{barcode}}_{01}(s-t)\\
			\mathcal{K}^{\mathrm{barcode}}_{10}(s-t) & \mathcal{K}^{\mathrm{barcode}}_{11}(s-t)
		\end{pmatrix},
		\qquad s,t\in 2\mathbb{Z}.
	\end{equation*} (Stated as a conjecture by the paper; open unless the paper says otherwise.)

[Lemma 18 of arXiv:2609.00183, '2609.00183'] There exists $C>0$ depending only on the constant in the estimates \cite[(29)--(33)]{dm} and the Lipschitz constant of $u$ such that
    \begin{equation}
        \lim_{t\to 0}\frac{E(v_t)-E(v)}{t}\leq C|w|\int_{\Omega}\xi(d^2(v,P_0)+|\nabla v|^2).
    \end{equation}

