[Proposition 24 (Positive-time smoothing and regular restart) of arXiv:2608.30027, 'Under Ricci flow, a 3-torus goes flat'] Fix \(K_0<\infty\).  There are constants
\[
        \beta_{\mathrm{reg}}>0,\qquad C_{\mathrm{reg}}<\infty,
        \qquad \Lambda_{\mathrm{reg}}<\infty,
\]
depending only on \(K_0,N,\sigma\), with the following property.

\medskip
\noindent\textbf{Hypotheses.}
Let \(r(\tau)\), \(1\leq\tau\leq100\), be an invariant Ricci flow satisfying
\begin{equation}
        |\sec_{r(\tau)}|\leq K_0/\tau.
\end{equation}
Let \(q(\tau)\) be a Ricci--DeTurck flow relative to \(r(\tau)\) and assume
\begin{equation}
        \|q-r\|_{X_r^N[1,100]}\leq\beta_{\mathrm{reg}}.
\end{equation}

\medskip
\noindent\textbf{Rescale and average.}
Put
\[
        q^+(1)=100^{-1}q(100),\qquad
        \rho^+=100^{-1}r(100),\qquad
        r^+(1)=\overline{q^+(1)}.
\]

\medskip
\noindent\textbf{Conclusion.}
Then \(r^+(1)\) is Riemannian,
\[
        \BG_N(\rho^+;\Lambda_{\mathrm{reg}}),\qquad
        \BG_N(r^+(1);\Lambda_{\mathrm{reg}}),
\]
and
\begin{equation}
\begin{split}
 &\|q^+(1)-\rho^+\|_{C^{N+5,\sigma}(M,\rho^+)}
 +\|r^+(1)-\rho^+\|_{C^{N+5,\sigma}(M,\rho^+)}\\
 &\qquad\leq C_{\mathrm{reg}}
 \|q-r\|_{C^0(M\times[1,100],r)}.
\end{split}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem Lap UB of arXiv:2608.25471, 'Exact Hausdorff measures and fine geometry of collisions of independent Markov processes'] For all sufficiently small $r > 0$,
  we have the following.
  For any $x_0 \in M$ and $\lambda > 0$, it holds that
  \begin{align}
    \frac{1}{\mu(B(x_0, r))} 
    \int_{B(x_0,r)}\! \hat{E}_{\diag(x)}\!\left[\exp\!\left(-\lambda \Pi_{r^{d^{\mathrm{min}}_\mathrm{w}}}(B(x_0, r)) \right)\right] \mu(dx)
    \leq     
    \frac{\tilde{c}_1}{1 + \tilde{c}_2 \lambda r^{d^{\mathrm{min}}_\mathrm{w}d_{\mathrm{ct}}}}.
  \end{align}

[Cor lambda_conv of arXiv:2509.08659, 'Gap metrics for stationary point processes and quantitative convexity of the free energy'] Let $1<p<2$  and let  $\mathsf{P}_i\in  \mathcal P_{s,1}(\Gamma)$, $i=0,1$ with  finite free energy $\mathcal F_{\beta}(\mathsf{P}_i)<\infty$, and $\Pi_i:= \mathsf{gap}(\mathsf{P}_i)$ for  $i=0,1$. Assume that the function $f^{p/(p-2)}$  (cf. assumption (assumption1 of the paper)) is convex on $[0,\infty)$ and  $\int f^{p/(p-2)}( \mathsf{s}_1)\Pi_i(d \mathsf{s})<\infty$ for $i=0,1$. Then $ \mathscr W_p(\mathsf{P}_0,\mathsf{P}_1)<\infty$ and 
     \begin{align*}
     \mathcal F_{\beta}(\mathsf{P}_{t})&\leq (1-t)\mathcal F_{\beta}(\mathsf{P}_{0})+t\mathcal F_{\beta}(\mathsf{P}_{1})\\
     &-\frac{\beta(1-t)t}{2} \mathscr W_p^2(\mathsf{P}_0,\mathsf{P}_1)\left[ \max\left(\int f^{p/(p-2)}( \mathsf{s}_1)\Pi_0(d \mathsf{s}),\int f^{p/(p-2)}( \mathsf{s}_1)\Pi_1(d \mathsf{s})\right)\right]^{\frac{p-2}{p}},
\end{align*}
 where  $ \mathsf{Q}\in  \mathsf{Cpl}_{s,m}(\mathsf{P}_0,\mathsf{P}_1)$ is the $\mathscr W_p-$optimal coupling from  Theorem (thm:interaction_gain of the paper), $\mathsf U:=\iota( \mathsf{Q})$ and  $\mathsf{P}_t:= \mathsf{gap}^{-1}\left((T_t)_{\#}\mathsf U\right)$.

