[Proposition 5 of arXiv:2604.24684, 'Waning Immunity Fails to Restore a Positive Epidemic Threshold on Power--Law Networks'] Let $G=(V,E)$ be a graph, let $v\in V$, and let $U\subseteq N(v)$ be a set of neighbors of~$v$ with $|U|\ge k$. Let $\boldsymbol{\sigma}(0)$ be an arbitrary deterministic initial configuration on $V$, subject only to the condition that $v$ is $k^{1/24}$-lit among $U$ at time 0. Then there exists an event $A^{(v)}\in \mathcal{G}(v, U)$, such that for all sufficiently large $k$, the following holds:
\begin{enumerate}
  \item[\normalfont (i)] On ${A}^{(v)}$, the vertex $v$ remains $k^{1/96}$-lit among $U$ throughout the time interval $\big[0,\tfrac{1}{48}\log k\big]$;
  \item[\normalfont (ii)] On ${A}^{(v)}$, the vertex $v$ remains $k^{1/24}$-lit among $U$ throughout the time interval $[\frac{1}{48}\log k ,3k^{\min\{\rho,\lambda,1\}/200}]$;
    \item[\normalfont (iii)] On ${A}^{(v)}$, there exist random times $T_i$ for $i=1,\dots,\lfloor k^{\min\{\rho,\lambda,1\}/400}\rfloor+1$ such that each $T_i$ is measurable with respect to $\mathcal{G}(v,U)$, $T_{i+1}-T_i\ge 3$, $T_{i}\le k^{\min\{\rho,\lambda,1\}/200}$, and $v$ is infected at time $T_i$ for every $i=1,\dots, \lfloor k^{\min\{\rho,\lambda,1\}/400}\rfloor$;
  \item[\normalfont (iv)] $\mathbb{P}({A}^{(v)}) \ge 1 - k^{-\min\{\rho,\lambda,1\}/200}$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:self_scaling_convergence of arXiv:2608.29448, '\method: Self-Scaled Adaptive Preconditioning for Physics-Informed Learning'] Let \(S_k=W_k-W_{k-1}\), \(Y_k=\nabla \mathcal{L}(W_k)-\nabla \mathcal{L}(W_{k-1})\), and let
\(K_k\succ 0\) denote the Kronecker metric whose quadratic form is $s_k^\top K_k s_k = \operatorname{Tr}\!\left(S_k^\top L_k^{-1}S_kR_k^{-1}\right)$, where \(s_k=\operatorname{vec}(S_k)\). Assume \(s_k\neq 0\) and
\(s_k^\top y_k>0\). Define $a_k=s_k^\top K_k s_k$ and $c_k=s_k^\top y_k$. Then the scaling factor
\begin{align*}
\tau_k
=
\min\left\{
1,
\frac{c_k}{a_k}
\right\}
=
\min\left\{
1,
\frac{s_k^\top y_k}{s_k^\top K_k s_k}
\right\}
\end{align*}
is the unique solution of the clipped one-dimensional log-secant matching
problem
\begin{align*}
\tau_k
=
\arg\min_{0<\tau\le 1}
\left[
\log
\frac{s_k^\top y_k}
{s_k^\top(\tau K_k)s_k}
\right]^2 .
\end{align*}

If \(y_k=H_ks_k+r_k\), then, whenever the unclipped solution is active,
the scaled Kronecker quadratic form satisfies $s_k^\top(\tau_kK_k)s_k = s_k^\top H_ks_k+s_k^\top r_k$. Thus the mismatch between the scaled Kronecker secant energy and the true
directional curvature is exactly the directional secant error \(s_k^\top r_k\). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop: S_emerge of arXiv:2608.00399, 'The Heavy-tailed Frog Model'] Let $d \ge 1$ and $s \in (d, 2d)$. Then, for any $\varepsilon > 0$, there exist $\beta_0, C > 0$ depending on $\varepsilon, d, s$ such that $\beta_1 > \beta_0$ implies
    \begin{align*}
        \lim_{m \rightarrow \infty} \hat{\mathbb P}_{m,\beta_1} \left( \exists \, A \subseteq \mathbb{T}^d_m \text{ s.t. } A \text{ is } \textup{Hom$\left(\left\lfloor(\log m)^{\frac{1}{2d - s} + \varepsilon}\right\rfloor, \rho_m\right)$} \text{ and } \textup{QC$\big(\Delta + \varepsilon\big)$} \right) = 1
    \end{align*}
where $\rho_m = (\frac{1}{\log \log m})^{C}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 80 of arXiv:2608.26084, 'Localic Esakia Duality\\via Conic Frames'] We denote by:
	\begin{enumerate}
		\item $\EFrm_\weak$ the full subcategory of~$\dcFrm$ whose objects are Esakia frames;
		\item $\EFrm_\strong$ the wide subcategory of~$\EFrm_\weak$ whose morphisms are the \emph{strong conic morphisms}~$h\colon (E,\dc)\to (F,\dcx)$ satisfying~$h\circ \dc = \dcx\circ h$.
	\end{enumerate}

[Lemma 15 of arXiv:2608.19832, 'Sharp Convex Concentration for Symmetric Random Tensors with Subgaussian Coordinates'] Under the assumptions of \Cref{thm:main},
\begin{equation}
 \Pp\left\{
 \abs{\norm X^2-n}>C_K(\sqrt{nu}+u)
 \right\}
 \le2e^{-c_Ku}
\end{equation}
for every $u\ge1$.

[Prop 22 of arXiv:2606.08115, '2606.08115'] Let condition (C) be valid for a two-dimensional random walk $\left\{ \ov{S}_n\right\}$.
Then for any $\alpha > 0$ there exists a positive parameter $C = C(\alpha)$ such that for any sufficiently large $n$ and any
$\ov{x} \in K$:
\begin{equation}

\pr\left(\tau(\ov{x})> n, \ov{S}_n +\ov{x} \in K \backslash K_{n, \alpha}\right) \le \frac{C \ln^2n}{n^{p/2 + 1}} u\left(\ov{x}_0 + M \ov{x}\right),
\end{equation}
where
\begin{equation}

K_{n, \alpha}:= \left\{\ov{z} \in K: \mathrm{dist}\left(\ov{z}, \partial K\right) > \alpha \ln n\right\}.
\end{equation}

