body:
[Theorem general-ThmB of arXiv:2601.21762, 'Navier-Stokes with a fractional transport noise as a limit of multi-scale dynamics'] Consider the setting of Lemma~(le:uniform-estimate of the paper).
     Then the  following statements hold.
    \begin{itemize}
        \item[(i)] There exists a subsequence $\{ u^{\epsilon_n}\}$ such that $u^{\epsilon_n} \rightarrow u$ in  $L^{2}([0,T];H) \cap C([0,T],H_{w})$, 
        and the limit $u$ is a rough path solution to (equation eq:limit-eq of the paper)
        \begin{equation*}
            \partial_t u = \nu \Delta u- \Pi[(u \cdot \nabla) u] - \Pi[(d \mathbf{B} \cdot \nabla) u],
        \end{equation*}
        in case of ((sf of the paper)) and in case of (equation sf2 of the paper), it solves 
         \begin{equation*}
            \partial_t u = \nu \Delta u- \Pi[(u \cdot \nabla) u] - \Pi[(d \mathbf{Z} \cdot \nabla) u].
        \end{equation*}

        \item[(ii)] The convergence $\{ u^{\epsilon_n}\}$ also holds in an analog of a controlled rough path distance, meaning:
        $$ u^{\epsilon_n} \rightarrow u \text{ in } C^{\frac{1}{\alpha-\delta} \textrm{-var}}([0,T]; H^{-1})$$
        $$ R^{u^{\epsilon_n}} \rightarrow R^u \text{ in } C^{\frac{1}{2(\alpha-\delta)}\textrm{-var}}([0,T]; H^{-2})$$
        hold for any $\delta>0$.
    \end{itemize}

[Theorem 1 of arXiv:2609.01333, '2609.01333'] For each $\kappa>0$, there exists $\gamma_*=\gamma_*(\kappa)\in  \Big(0, \, \frac{1}{2\pi} \tfrac{1}{\frac{1}{\kappa} - \frac{1}{\sqrt{\kappa^2+1}}}\Big)$ such that for every $\alpha \in (0,1)$ and $\gamma\in (0,\gamma_*)$, there exists   $\lambda_{*}=\lambda_*(\kappa, \gamma)>0$ and a smooth curve
\begin{align*}
 I: (-\varepsilon_0,\varepsilon_0) &\longrightarrow  (0,\infty) \times C^{2,\alpha}(\R),\quad  s\longmapsto (\lambda_s,u_s)
 \end{align*}
satisfying   $I(0)= (\lambda_0,u_0) \equiv( \lambda_{*},0)$. Moreover,  the  following properties hold.
\begin{enumerate}[$(a)$]
\item For each $s \in (-\varepsilon_0, \varepsilon_0)$,  $u_s\in C^{2,\alpha}(\R)$ is even, $2\pi$-periodic, and takes the form
\begin{align*}
u_s(t) = s\big(\cos(t) + \omega_s(t)\big),
\end{align*}
where $\omega: (-\varepsilon_0, \varepsilon_0) \to C^{2,\alpha}(\mathbb{R})$, $s \mapsto \omega_s$ is a smooth curve satisfying $\omega_0 \equiv 0$, $\omega_s\in C^{2,\alpha}(\R)$ is even, $\omega_s$ is $2\pi$-periodic and satisfies
\begin{align*}
\int_{0}^{2\pi} \omega_s(t) \cos(t) \mathrm{d}t = 0.
\end{align*}
\item Each function $\varphi_s = \lambda_s + u_s$ satisfies  $\varphi_s\in C^{2,\alpha}(\R)$,  $\varphi_s\geq \frac{\lambda_*}{2}$, $\varphi_0=\lambda_*$ and
\begin{align}

H_{\partial\Omega_{\varphi_s}}(x) + \gamma \int_{\Omega_{\varphi_s}} G_\kappa(|x-y|)  \mathrm{d}y = C_{\lambda_s,\kappa} \qquad \text{for all } x \in \partial\Omega_{\varphi_s}
\end{align}
where the constant $C_{\lambda_s,\kappa}$ satisfies $C_{\lambda_s,\kappa}\leq C_{\lambda_*,\kappa}$ with

\begin{align*}
C_{\lambda_s,\kappa} &=H_{\partial\Omega_{\lambda_s}}\hspace{-0.7ex}
(0,\lambda_s e_1)+\gamma \int_{\Omega_{\lambda_s}}\hspace{-2ex} G_\kappa(|(0,\lambda_s e_1)-z|) \mathrm{d}z=\frac{1}{\lambda_s}
+ 2\gamma\lambda_s^2 \int_{B_1} \hspace{-2ex}K_0(\lambda_s \kappa|e_1-y|)\mathrm{d}y,
\end{align*}
\end{enumerate}
where $e_1=(1,0)\in \R^2$ and  $K_\nu$ is the modified Bessel function of the second kind of order $\nu$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 28 of arXiv:2609.01362, '{Double cluster swapping for spin models: \\Pfaffian relations and sharpness}'] Let $\eps > 0$. Then, there exists $C = C(\eps,P,\G)$ such that 
	\begin{equation}
	\left< |\vp_o| \right>_{\G,\beta,h} \leq C
	\end{equation} 
	for all $0 \leq \beta \leq 1 / \eps$ and $0 \leq h \leq 1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:powermean of arXiv:2608.23765, '\texorpdfstring{Tight Majorizations and Convergence Rates\\ of Nuclear Norm Minimization I'] For $-\infty \leq q \leq \infty$, the \emph{$q$-power mean} \\ $\mathcal{M}_{q}(a,b)$ of two numbers $a, b > 0$ is given by
	\begin{equation} 
		\mathcal{M}_{q}(a,b) = 
		\begin{cases}
			\min(a,b), & \text{ if } q = -\infty, \\
			\left(\frac{ a^q + b^q }{2}\right)^{\frac{1}{q}}, & \text{ if } q \in (-\infty,0) \cup (0,\infty), \\
			\sqrt{a b}, & \text{ if } q = 0, \\
			\max(a,b), & \text{ if } q = \infty. \\
		\end{cases}
	\end{equation}

[Lemma 8 of arXiv:2608.25164, 'A time-fractional Kalman filter'] Let the process $N(t)$ be defined as in \eqref{4.21}--\eqref{4.3}. Then the following properties hold
\begin{myenumerate}
    \item
    $N$ is a Gaussian process;
    \item
    $\E[N(t)]=0$ for all $t$;
    \item
    $\E[N^2(t)]= \int_0^t D^2(s) ds$;
    \item 
    $\mathcal{L}(N)=\mathcal{L}(Y)$;
    \item
    $N$ has orthogonal, and hence independent, increments;
    \item
    Define
    \begin{align}
        dM(t)&=\frac{1}{D(t)} dN(t)= \frac{1}{D(t)}dY(t) -\frac{G(t)}{D(t)} \widehat{X}(t)dt \nonumber\\
        &=\frac{G(t)}{D(t)} \big[X(t)-\widehat{X}(t)\big]dt + dB_2(t).
    \end{align}
Then, for all $s,s'\geq0$,
\begin{align*}
\E[M(s)M(s')]=\min(s,s').
\end{align*}
 \item 
 $M$ is a Brownian motion.
    \end{myenumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 26 of arXiv:2604.03777, 'Equilibrium fluctuations for a multi-species particle system with long jumps'] Let $\gamma >0$, $0 \leq s \leq t \leq T$, $n \in \mathbb{N}_+$ and $ \widehat{b}_n \in \mathbb{R}$. Moreover, let $(F_x)_{x \in \mathbb{Z}}: \Omega \mapsto \mathbb{R}$ be a sequence of mappings such that 
\begin{align}
 \forall x \in \mathbb{Z}, \; \forall s \in [0,T], \; \forall n \in \mathbb{N}_+, \quad & \mathbb{E}_{\nu_{\rho}} \big[ \big\{ F_x(\eta_s^n) \big\}^{2} \big] \leq \frac{C_1}{L^{2}},  \\
 \forall x,y \in \mathbb{Z}: |y-x| \geq 2 K, \; \forall s \in [0,T], \; \forall n \in \mathbb{N}_+, \quad & \mathbb{E}_{\nu_{\rho}} \big[ F_x(\eta_r^n) \; F_y(\eta_r^n) \big]=0. 
\end{align}	
	for some constants $C_1, L>0$ and $K \in \mathbb{N}_+$. Recall the definition of $\| \cdot \|_{2,n}$ in \eqref{L2discnorm}. It holds
	\begin{align*}
\forall n \in \mathbb{N}_+, \quad		\mathbb{E}_{\nu_{\rho}} \Bigg[ \Bigg\{ \widehat{b}_n \int_s^t \dd r \sum_{x}   \nabla H ( \tfrac{ \lfloor x - r v_n \rfloor }{n}  )    F_x(\eta_r^n)  \Bigg\}^{2} \Bigg] \leq 2 C_1 (t-s)^{2} n \frac{(\widehat{b}_n)^2 K}{L^{2}} \| \nabla H \|^{2}_{2,n}.
	\end{align*}

