[Definition 8 (Iterative edge-colored graph process) of arXiv:2608.07239, 'Unified framework for asymptotically uniform iterative construction of generalised random '] Consider the vertex set $V=\{v_1,\ldots,v_n\}$, and for $g=1,\ldots,\chi$, consider a degree sequence $\d^{(g)}=(d_1^{(g)},\ldots,d_n^{(g)})$ of non-negative integers with $2m^{(g)}:=d_1^{(g)}+\ldots+d_n^{(g)}>0$ even, and consider a set $X^{(g)}$ of forbidden edges. For $g=1,\ldots,\chi$, define $$\b^{(g)}_{i,j}:=\frac{d_i^{(g)}d_j^{(g)}}{4m^{(g)}}+\sum_{\substack{h=g+1,\ldots,\chi\\\{v_i,v_j\}\not\in X^{(h)}}}\frac{d_i^{(h)}d_j^{(h)}}{2m^{(h)}}.$$ For $g=1,\ldots,\chi$, sample $E^{(g)}$ with the following steps:
		\begin{itemize}
			\item Start with no edges $E_0^{(g)}=\emptyset$.
			\item For $r=0,\ldots,m^{(g)}-1$, let $d_{i,r}^{(g)}$ denote the degree of vertex $v_i$ in $(V,E_r^{(g)})$, and consider those pairs of vertices $v_i,v_j\in V$ with $i\neq j$, $d_{i,r}^{(g)}<d_i^{(g)}$, $d_{j,r}^{(g)}<d_j^{(g)}$, and $\{v_i,v_j\}\not\in E_r^{(g)}\cup X^{(g)}\cup E^{(1)}\cup\ldots\cup E^{(g-1)}$.
			\begin{itemize}
				\item If no such pairs exist, let $E_{r+1}^{(g)}=E_r^{(g)}$.
				\item Otherwise, choose such a pair $v_i,v_j$ at random with probability proportional to $(d_i^{(g)}-d_{i,r}^{(g)})(d_j^{(g)}-d_{j,r}^{(g)})(1-\b^{(g)}_{i,j})$, and let $E_{r+1}^{(g)}=E_r^{(g)}\cup\{\{v_i,v_j\}\}$.
			\end{itemize}
			\item Finally, apply rejection sampling to sample $E^{(g)}=E_{m^{(g)}}^{(g)}$ with $m^{(g)}$ edges.
		\end{itemize}
		This guarantees that $(V,E^{(g)})$ for $g=1,\ldots,\chi$ are edge-disjoint simple graphs with degree sequence $\d^{(g)}$ and with no edges from $X^{(g)}$.

[Lemma lem:outside_lower_matched of arXiv:2609.03264, 'Certified Spherical MUSIC for 3D Localization under Adversarial Subspace Perturbations'] Suppose $\mu_X<1$ and $A_\gamma$ as given in (equation eq:A-gamma of the paper)  is positive. 
