		\int\limits_{\mathbb R}
		\varphi(u) p_{\infty,r}(u)\, du,
    \qquad  \textrm{as } T\rightarrow\infty.
	\end{equation*}

[Proposition cor:Pn_chebyshev of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] For every integer \(n\ge1\),   \(\mathcal P_n\) defined  in (equation def:Pn of the paper) can be expressed in terms of Chebyshev polynomials of first kind as  
\begin{equation}
\frac{1}{2\,\alpha^{n/2}}\,\mathcal P_n(x)
\;=\;
T_n\!\Bigl(\frac{x - (1+\alpha)}{2\sqrt{\alpha}}\Bigr)
\;-\;
\int T_n\!\Bigl(\frac{t - (1+\alpha)}{2\sqrt{\alpha}}\Bigr)\,d\mu_{\mathrm{MP},\alpha}(t).
\end{equation}
Moreover, it can also  explicitly be    given by  Chebyshev polynomials of second  kind 
\begin{equation}
 U_n\!\bigl(\tfrac{x-(1+\alpha)}{2\sqrt\alpha}\bigr)
   +\sqrt\alpha\,U_{n-1}\!\bigl(\tfrac{x-(1+\alpha)}{2\sqrt\alpha}\bigr)
\;=\;
\sum_{i=0}^{n-1} \frac{1}{2}\alpha^{\lfloor \frac{i}{2}\rfloor-\frac{n}{2}}\;\mathcal P_{\,n-i}(x).
\end{equation}

