[Cor 3 of arXiv:2604.07370, 'Probabilistic Weyl law for twisted Toeplitz matrices with rough symbols'] Let $p$, $\delta$ and $Q_N$ be as in Theorem \ref{Théorème final}. Let $R_N$ be an $N^d\times N^d$ complex deterministic matrix such that there exists $0<\kappa_4\leq d$ so that
    \begin{equation}
        \mathrm{rank}(R_N)=\mc{O}(N^{d-\kappa_4})\m\m\m\m\text{and}\m\m\m\m \norme{R_N}=\mc{O}(1) .

    \end{equation}
    Then, the empirical spectral measure $\mu_N$ of $M_N(p)+R_N+\delta Q_N$ converges weakly in probability to $p_*\mathrm{L}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 21 ({\cite{BF85}*{Theorem 4(c)}}) of arXiv:2609.03836, 'Koszul Orlik--Solomon Algebras from Non-supersolvable Arrangements'] \label[Thm]{thm:tensor_product_Koszul}
    Let $R, S$ be standard graded-commutative  $\mathbb{K}$-algebras.
    The graded-commutative tensor product algebra $R \otimes_{\mathbb{K}} S$ is Koszul if and only if both $R$ and $S$ are. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 15 of arXiv:2608.02927, 'Thinning Operation via the Poisson-F\"ollmer Process'] [Harrem\"oes, Johnson and Kontoyiannis \cite{HJK3}]
    Let $(X_{i})_{1 \le i \le n}$ be independent $\N$--valued random variables. Then, we have
    \begin{displaymath}
        I \Bigg( \sum_{i=1}^{n} X_{i} \Big| \pi_{\lambda} \Bigg) \le \sum_{i=1}^{n} \frac{\E X_{i}}{\lambda} I \Big( X_{i} \big| \pi_{\E X_{i} } \Big) 
    \end{displaymath}
    where $\lambda := \sum_{i=1}^{n} \E X_{i}  .$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:locallinearp1 of arXiv:2608.23765, '\texorpdfstring{Tight Majorizations and Convergence Rates\\ of Nuclear Norm Minimization I'] Let $\mathbf{X}_\star\in \mathbb{R}^{d_1 \times d_2}$ be a matrix of rank $r$.
Assume that the measurement operator $\mathcal{A}$ satisfies the NSP of (def:NSP:statement of the paper) of order $r$ with constant $\eta_r < 3/5$ and of order $1$ with constant  $\eta_1 \leq \eta_r$. Let $\left(  \mathbf{X}^{(k)}\right)_{k\geq 0}$ and $ \left(\varepsilon_{k} \right)_{k \geq 0}$ be the iterates and smoothing parameters of $\texttt{MatrixIRLS}$ with input $\mathbf{y} = \mathcal{A}(\mathbf{X}_\star)$, arbitrary initial weight operator $W^{(0)}$ and $\widetilde{r} = r$. Let $A_{\eta_r}$ be defined as in (eq:A_eta_r:def of the paper). Assume that \texttt{MatrixIRLS}'s weight operators $\W{\mathbf{X}^{(k)}}{\varepsilon_{k}}$ are defined based on harmonic-mean core matrices (eq:harmonic:mean of the paper) and that there is a natural number $\tilde{k}$ such that
\begin{equation}
	\nucnorm{\Xk{(\tilde{k})} - \mathbf{X}_\star} 
	\le \frac{\sigma_r (\mathbf{X}_\star )}{9 \max  \left( \eta_1 \sqrt{d}, 2\right) }.
\end{equation}
Then for all iterations $k \ge \tilde{k}$ carried out by (alg:algo1 of the paper) it holds that 
\begin{equation}
      \mathcal{J}_{\varepsilon_{k}} \left( \mathbf{X}^{(k)} \right)  -  \nucnorm{ \mathbf{X}_\star } \le \left(  1-  c_{\eta_r}   \right)^{k-\tilde{k}} \left(    \mathcal{J}_{\varepsilon_{\tilde{k}}} \left( \Xk{(\tilde{k})} \right) -  \nucnorm{\mathbf{X}_\star} \right)
\end{equation}
as well as
\begin{equation}
\nucnorm{ \mathbf{X}^{(k)} - \mathbf{X}_\star}\le A_{\eta_r} \left(  1-  c_{\eta_r}   \right)^{k-\tilde{k}}  \nucnorm{ \Xk{(\tilde{k})}-\mathbf{X}_\star}.
\end{equation}
Here, the constant $c_{\eta_r}$ depends only on the NSP constant $\eta_r$ and is given by
\begin{equation} 
c_{\eta_r}
=
\frac{(3-5\eta_r)^{2}(1-\eta_r)^{3}}{8(1+\eta_r)^{2}(3+2\eta_r)\Bigl[8(1-\eta_r)^{3}+(3+\eta_r)^{2}(1+\eta_r)(3+2\eta_r)\Bigr]}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

