     u_{\kappa,l}\,\to \, u ,\qquad \text{in }L^p(\Omega; L^r( [0,T] ; L^r (\mathbb{T}^d))),
    \end{equation}
    as $\kappa\to 0$ and $l\to \infty$, for any $p\in [1,\infty)$ and $r <(\alpha+m)+ \frac{2}{d}(\alpha+1)$.

