body:
[Def weighted stable nodal family of arXiv:2609.04023, 'Characterizing Contractions and Weighted Blowdowns'] \begin{enumerate}
    \item Define input data to be a tuple $(g,\mathscr{A}):=(g,a_1,\dots,a_n)$ consisting of an integer $g\ge 0$ and the {\em weight data} $(a_1,\dots,a_n)\in \mathbb{Q}^n$ satisfying $0<a_j\leq 1$ for $j=1,\ldots,n$ and $2g-2+a_1+a_2+\dots +a_n>0$.
    \item A family of nodal curves with marked points $(C,s_1,\ldots,s_n)\xrightarrow{\pi}B$ is stable of type $(g,\mathscr{A})$ if
    \begin{itemize}
        \item the sections $s_1,\ldots,s_n$ lie in the smooth locus of $\pi$,
        \item for any $\{i_1,\dots, i_r\}\subseteq [n]$ such that $\bigcap_{j=1}^{r}s_{i_j}(B)\neq\emptyset$, we have $a_{i_1}+\dots +a_{i_r}\leq 1$ and,
        \item $K_{\pi}+a_1s_1+a_2s_2+\dots +a_ns_n$ is $\pi$-ample.
    \end{itemize}
\end{enumerate}

[Lemma L5 of arXiv:2608.22945, 'A Momentum-Based Variance-Reduced Algorithm for Federated Multiobjective Optimization'] Suppose that Assumptions (A1 of the paper) and (A3 of the paper) hold. If $\max\{1152e^2(1-\beta)^2 \left(\eta KL\right)^2, 1152e^2(1-\beta)^2 \left(\eta \gamma KL^2\right)^2\} \leq \beta^{2}$, then the following inequality holds:
\begin{equation*}
	\sum_{t=0}^{T-1} \Xi_{s}^t \leq \frac{\beta^{2}}{288 e^2 K^{2} L^{2}} \sum_{t=0}^{T-1}\left(\mathcal{E}_{s}^{t-1}+\mathbb{E}[\|g^{t-1}\|^{2}]\right)+4 \eta^{2}TD^2.
\end{equation*}

[Theorem thm:logdecay of arXiv:2609.03980, 'Decay Rates and Domain Dependence of a Coupled Wave-Heat System with Spatially Dependant H'] Let $(\Omega,\Omega_w,\Omega_h)$ be a Lipschitz interface triple in $\mathbb{R}^n$ and let $S\in L^\infty(\Omega_h,\mathbb{C}^{n\times n}) $ be an accretive heat coefficient, i.e., 
    $$\re(\overline{v}^\top S(x) v) \gtrsim  |v|^2 $$ for all $x\in \mathbb{C}^n$ and almost all $x \in \Omega_h$. Then the semigroup $T_S^\perp$ generated by the generator $A_S^\perp$ of the coupled wave-heat system~(equation eq:1 of the paper) possesses logarithmic decay with rate $1/d=1$, i.e.,  \begin{align*}
        \forall k \in \mathbb{N} ~ \exists C_k>0:  \|T_S^\perp(t)x\|_{\mathbb{H}_1} \leq \frac{C_k}{\log(t+2)^k} \|x\|_{(A_S^\perp)^k} ~ \forall t\geq0,  x\in \operatorname{dom}\left((A_S^\perp)^k\right).
    \end{align*}

