body:
[Thm 1 of arXiv:2609.03713, 'A Sharp Mass Threshold for Boundedness in a Critical Quasilinear Chemotaxis Model with Ind'] Let $p\in (2d,\infty)$ and consider an initial value
\begin{equation}
    (u^0,w^0)\in W_{p}^{1,+}(\Omega)  \times L_\infty^+(\Omega) \,.
\end{equation}
Then there is a unique couple $(u,w)$ of functions satisfying
\begin{subequations}
\begin{align}
&u \in  C^1\big((0,\infty),L_p(\Omega)\big) \cap  C\big((0,\infty),W_{p,N}^{2}(\Omega)\big)\cap C\big([0,\infty),W_{p}^{1}(\Omega) \big)\,,\\
& w\in C^1 \big([0,\infty),L_\infty(\Omega)\big)\,,\qquad v := \mathcal{K}[w-\langle w\rangle] \in C^1\big([0,\infty),W_{p,N}^{2}(\Omega)\big)\,,
\end{align}
such that $(u,v,w)$ is a global non-negative strong solution to~\eqref{E}.
\end{subequations}
In fact, the mapping 
\begin{equation*}
	\boldsymbol{\Psi}:(u^0,w^0)\mapsto (u,w)
\end{equation*} 
defines a global semiflow on $W_{p}^{1,+}(\Omega) \times L_\infty^+(\Omega)$.  
Moreover, 
\begin{itemize}
    \item  for $t\ge 0$, it holds that
    \begin{equation}
        \|u(t)\|_1 = \|u^0\|_1\,, \quad \|w(t)\|_1 \le \max\big\{ \|w^0\|_1 , \|u^0\|_1 \big\}\,; 
    \end{equation}
	\item  if $u\in L_\infty((0,\infty),L_m(\Omega))$, then $(u,w)\in L_\infty((0,\infty)\times\Omega,\R^2)$;
	\item  if $\Omega=\mathbb{B}_R$  and $(u^0,w^0)$ are radially symmetric, then $(u,v,w)(t)$ are radially symmetric for all $t\ge 0$.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop eq:strong:Markov:N of arXiv:2411.12717, 'Excursion theory for Markov processes indexed by Lévy trees'] Let $T$ be a $(\overline{\mathcal{F}}_{t+})$-stopping time such that  $T > 0$, $\mathbf{N}_{x,r}$-a.e. For every non-negative $\overline{\mathcal{F}}_{T+}$-measurable function $\Phi$  and non-negative measurable function $F$ on $\mathbb{D}(\mathbb{R}_+, \mathcal{M}_{f}(\mathbb{R}_+)\times \mathcal{W}_{\overline{E}})$, we have 
\begin{equation} 
    \mathbf{N}_{x,r} \big( \mathbbm{1}_{\{T<\infty\}} \Phi \cdot  F \big( (\rho_{T + s }, \overline{W}_{T + s } : s \geq 0  ) \big)  \big) 
    = 
    \mathbf{N}_{x,r} \big( \mathbbm{1}_{\{T<\infty\}}  \Phi \cdot  \mathbb{E}^{\dag}_{\rho_T, \overline{W}_T} [ F ]   \big).  
\end{equation}

[Theorem 1 of arXiv:2608.19832, 'Sharp Convex Concentration for Symmetric Random Tensors with Subgaussian Coordinates'] Let $X_1,\ldots,X_n$ be independent. Assume that
\[
 \E X_i=0,\qquad \E X_i^2=1,\qquad \norm{X_i}_{\psi_2}\le K.
\]
Let $L>0$, let $f:H_d\to\R$ be convex and $L$-Lipschitz, and put
$Z=f(X^{\otimes d})$. There are constants $c_K,C_K>0$ such that
\begin{equation}
 \Pp\left\{
 \abs{Z-\E Z}>
 C_KL n^{(d-1)/2}
 \left(d\sqrt u+\sqrt{d u\log\left(e+\frac nu\right)}\right)
 \right\}
 \le C e^{-c_Ku}
\end{equation}
whenever
\[
 1\le u\le c_K\frac{n}{d^2}.
\]
The corresponding moment estimate is the following. If $d\le c_K\sqrt n$, then
\begin{equation}
 \norm{Z-\E Z}_{L_p}
 \le C_KL n^{(d-1)/2}
 \left(d\sqrt p+\sqrt{d p\log\left(e+\frac np\right)}\right)
\end{equation}
for
\[
 1\le p\le c_K\frac{n}{d^2}.
\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 2-l05 of arXiv:2412.04015, 'Linear fluctuation of interfaces in Glauber-Kawasaki dynamics'] There exists a finite constant ${\mathfrak c}({\boldsymbol u}^N)$, depending only on
${\boldsymbol u}^N$, $A$ and the dimension $d$, uniformly bounded in $N$
($\sup_N {\mathfrak c}({\boldsymbol u}^N) < \infty$), such that
\begin{equation*}
\begin{aligned}
& K\, \int  {\mathcal W}^{(2)}_\ell \, f\; d\nu^N \; \le\;
\delta\, N^2 \, I^E_{N}(f; \nu^N)
\; +\; {\mathfrak c}({\boldsymbol u}^N)  \, K\, \sum_{x\in{\mathbb T}_N^d}
\int (\omega^{\ell} _{x})^2 \, f \; d\nu^N
\\
& \;+\; {\mathfrak c}({\boldsymbol u}^N)  \, 
\Big(\frac{K}{N}\Big)^2 \Big\{ \, \frac{1}{\delta}\, \Big[ \, 1 \,+\, 
\frac{K\, s_d(\ell) \,}{N^2} \,\Big] \,+ \,  (1+\lambda)  \Big\} \, \,
\int \sum_{k=1}^d \sum_{x\in{\mathbb T}_N^d} (H^{(\ell)}_{k,x})^2 \, f  \;
d\nu^N
\\
& \quad \;+\; {\mathfrak c} ({\boldsymbol u}^N)\, K^2\, N^{d-2}
\,\Big\{\, \delta \,+\, \frac{s_d(\ell)}{\lambda} \,\Big\} 
\end{aligned}
\end{equation*}
for all $0<\delta<1$, $\lambda>0$, density $f$ with respect to $\nu^N$
and $N> 4\ell$. In this formula, $s_d(\ell)$ is the sequence
introduced in (equation 2-18 of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma L:truncated-moments of arXiv:2607.17113, 'Two-time spatial decorrelation for the flat KPZ fixed point'] For every $0<s<t$ and every $\eta\in(0,1)$,
  \begin{equation}
    \sup_{|x|\ge1}
    \|H_{\eta |x|}(t,s,x)\|_4 <\infty.

  \end{equation}

[Corollary C:smallball of arXiv:2602.05317, 'Strong local nondeterminism for stochastic time-fractional\\ slow and fast diffusion equat'] Suppose condition (equation E:main of the paper) holds.
  \begin{enumerate}[\rm (i)]

    \item Suppose $\beta\in(0,2)$; or $\beta=2$, $\gamma\in[0,1]$, $\ell<\alpha(\gamma+1/2)$. If $\rho \in (0,1)$,
          then for any compact interval $I\subset (0,\infty)$, there exist two
          constants $0<C_7\le C_7'<\infty$ such that for all $x_0\in \mathbb{R}^d$ and all
          $\varepsilon \in (0, 1)$,
          \begin{align}
            \exp\left( - \frac{C_7'}{\varepsilon^{1/\rho}} \right)
            \le \mathbb{P}\left\{ \sup_{t\in I} |u(t,x_0)| \le \varepsilon \right\}
            \le \exp\left( - \frac{C_7}{\varepsilon^{1/\rho}} \right).
          \end{align}

    \item If $\tilde\rho\in (0,1)$, then for any $t_0>0$ and compact rectangle
          $J$ in $\mathbb{R}^d$, there exist two constants $0<C_8\le C_8'<\infty$ such that
          for all $\varepsilon\in(0,1)$,
          \begin{align}
            \exp\left( - \frac{C_8'}{\varepsilon^{d/\tilde\rho}} \right)
            \le \mathbb{P}\left\{ \sup_{x\in J} |u(t_0,x)| \le \varepsilon \right\}
            \le \exp\left( - \frac{C_8}{\varepsilon^{d/\tilde\rho}} \right).
          \end{align}

  \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

