body:
[Lemma equiv-quotient of arXiv:2608.28504, 'Global $\bm\infty$-categories and global Thom spectra'] Let $\alpha\colon G\to G'$ be a homomorphism of compact Lie groups, and let $H$ be any other compact Lie groups. Then $\alpha_!\colon\cat{$\bm{(H\times G)}$-Top}\to \cat{$\bm{(H\times G')}$-Top}$ sends $\mathcal G_{H,G}$-weak equivalences between Hausdorff $(H\times G)$-spaces with free $\ker(\alpha)$-action to $\mathcal G_{H,G'}$-weak equivalences.
    \begin{proof}
        Consider $G'$ as a $(H\times G\times G')$-space with $G'$ acting via left multiplication, $H$ acting trivially, and with $g\in G$ acting via right multiplication by $\alpha(g)^{-1}$. Then $\alpha_!$ factors as
        \[
            \cat{$\bm{(H\times G)}$-Top}\xrightarrow{\;G'\times{-}\;}\cat{$\bm{(H\times G\times G')}$-Top}\xrightarrow{\;(-)/G\;}\cat{$\bm{(H\times G')}$-Top}.
        \]
        It is clear that the first functor preserves Hausdorffness and sends $\mathcal G_{H,G}$-weak equivalences to $\mathcal G_{H,G'\times G}$-weak equivalences. Moreover, if $X$ is $\ker(\alpha)$-free, then $G'\times X$ is $G$-free, as every point of $G'$ has $G$-isotropy $\ker(\alpha)$. It therefore suffices to show that the second functor sends $\mathcal G_{H,G\times G'}$-weak equivalences between $G$-free Hausdorff spaces to $\mathcal G_{H,G'}$-weak equivalences.

        If $X$ is any $G$-free space, $K\subset H$ is any closed subgroup, and $\varphi\colon K\to G'$ is any homomorphism, then [schwede2018global]*{Proposition~B.17} shows that the tautological map
        \begin{equation}
            \begin{aligned}
                \smash{\coprod_{\alpha\colon K\to G}X^{(\alpha,\varphi)}/C(\im\alpha)}&\longrightarrow (X/G)^\varphi\\
                [x]&\longmapsto[x]
            \end{aligned}
        \end{equation}
        is a homeomorphism, where the coproduct runs over $G$-conjugacy classes of continuous group homomorphisms $K\to G$, and $C(\im\alpha)$ denotes the centralizer of the image of $\alpha$ in $G$. Thus, if $f\colon X\to Y$ is a $\mathcal G_{H,G}$-weak equivalence of $G$-free Hausdorff spaces, then $(f/G)^\varphi$ splits as a coproduct of the maps $f^{(\alpha,\varphi)}/C(\im\alpha)$. By assumption, each $f^{(\alpha,\varphi)}$ is a non-equivariant weak equivalence. As $C(\im\alpha)\subset G$ acts freely on $X$ and $Y$, Lemma~(lemma:quotient-we of the paper) therefore shows that also the quotient $f^{(\alpha,\varphi)}/C(\im\alpha)$ is a weak homotopy equivalence.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition eq:rhoelli of arXiv:2607.18635, 'Remainders of generalised Taylor expansions and a priori bounds for rough differential equ'] For any binary tree $\rho\in{\mathcal T}_b$ and for $\ell\in\{1,\ldots, m_L(\rho)+1\}$, we define
	\begin{equation}
	\rho^{(\ell)}_i:=\rho_i\,, \quad i=1,\ldots,\ell-1, \qquad \rho^{(\ell)}_\ell:=P_{\rho,\ell}\,,
	\end{equation}
see Definition (Def: trunk of the paper). Then we introduce the linear operation $\mathcal{A}:{\mathcal T}_b\to\bigoplus_{i\ge 1} {\mathcal T}_b^{\otimes i}$:
	\begin{align}
		&\mathcal{A}(\rho):=\sum_{\ell=1}^{m_L(\rho)+1}(-1)^{\un{(\ell>1)}}\bigotimes_{i=1}^{\ell}\rho^{(\ell)}_i\,.
	\end{align}

[Proposition prop:small_jump_bound_comonotonic of arXiv:2411.03609, 'Asymptotically optimal Wasserstein couplings for the small-time stable domain of attractio'] Let L\'evy processes 
$\bm{X}$ and $\bm{Y}$
have characteristic triplets denoted by $(\bm{\gamma_X},\bm{\Sigma_X}\bm{\Sigma_X}^{\scalebox{0.6}{$\top$}},\nu_{\bm{X}})$ and $(\bm{\gamma_Y},\bm{\Sigma_Y}\bm{\Sigma_Y}^{\scalebox{0.6}{$\top$}},\nu_{\bm{Y}})$, respectively.
Assume that 
 the L\'evy measures of $\nu_{\bm{X}}$ and $\nu_{\bm{Y}}$ admit the radial decomposition in~(equation eq:radial_decomp of the paper)
and construct the processes $(\bm{M^X},\bm{M^Y},\bm{L^X},\bm{L^Y})$ 
by~(equation eq:comono_coupling_1 of the paper) and~(equation eq:comono_coupling_2 of the paper), independent of standard Brownian motions $\bm{B^X}$ and $\bm{B^Y}$ on $\mathbb{R}^d$. Then there exists constants $\bm{\varpi_X},\bm{\varpi_Y}\in\mathbb{R}^d$, such that $\bm{X}_t\overset{d}{=} \bm{\varpi_X}t+\bm{\Sigma_X}\bm{B}^{\bm{X}}_t+\bm{M}^{\bm{X}}_t+\bm{L}^{\bm{X}}_t$ and $\bm{Y}_t\overset{d}{=} \bm{\varpi_Y}t+\bm{\Sigma_Y}\bm{B}^{\bm{Y}}_t+\bm{M}^{\bm{Y}}_t+\bm{L}^{\bm{Y}}_t$ for all $t\in[0,1]$. Moreover, this  coupling of $\bm{X}$ and $\bm{Y}$ satisfies   
\begin{align}
    \mathds{E}\bigg[\sup_{t \in [0,1]}\big|\bm{M^X}_t-\bm{M^Y}_t\big|^2\bigg]&\leqslant 4\int_{[\varepsilon,\infty)\times \mathbb{S}^{d-1}} (\rho_{\bm{X}}^{\leftarrow}(x,\bm{v})-\rho_{\bm{Y}}^{\leftarrow}(x,\bm{v}))^2 \mathrm{d} x \otimes \sigma(\mathrm{d} \bm{v}).
\end{align}
Furthermore, if $\int_{\mathbb{R}^d_{\bm{0}}}|\bm{w}|^2\1_{\mathbb{R}^d \setminus B_{\bm{0}}(1)}(\bm{w})\nu_{\bm{X}}(\mathrm{d}\bm{w})<\infty$ and $\int_{\mathbb{R}^d_{\bm{0}}}|\bm{w}|^2\1_{\mathbb{R}^d \setminus B_{\bm{0}}(1)}(\bm{w})\nu_{\bm{Y}}(\mathrm{d}\bm{w})<\infty$, then 
\begin{equation}

\mathds{E}\bigg[\sup_{t\in[0,1]}\big|\bm{M^X}_t+\bm{L^X}_t-(\bm{M^Y}_t+\bm{L^Y}_t)-\bm{m}t\big|^2\bigg]
\leqslant 4\int_{(0,\infty)\times \mathbb{S}^{d-1}}(\rho_{\bm{X}}^{\leftarrow}(x,\bm{v})-\rho_{\bm{Y}}^{\leftarrow}(x,\bm{v}))^2 \mathrm{d} x \otimes \sigma(\mathrm{d} \bm{v}),
\end{equation}
were we define $\bm{m}\coloneqq\mathds{E}[\bm{L^X}_1-\bm{L^Y}_1]
=\int_{(0,\varepsilon)\times \mathbb{S}^{d-1}}\bm{v}
(\rho_{\bm{X}}^{\leftarrow}(x,\bm{v})-\rho_{\bm{Y}}^{\leftarrow}(x,\bm{v}))\mathrm{d} s \otimes\sigma(\mathrm{d}\bm{v})\in\mathbb{R}^d$. In particular, 
\begin{equation}

\begin{split}
\mathcal{W}_2(\bm{X},\bm{Y})
&\leqslant |\bm{\varpi_X}-\bm{\varpi_Y}+\bm{m}|
    + 2 d^{1/2}|\bm{\Sigma_X}-\bm{\Sigma_Y}|\\
&\qquad   + 2\bigg(\int_{(0,\infty)\times \mathbb{S}^{d-1}}(\rho_{\bm{X}}^{\leftarrow}(x,\bm{v})-\rho_{\bm{Y}}^{\leftarrow}(x,\bm{v}))^2 \mathrm{d} x \otimes \sigma(\mathrm{d} \bm{v})\bigg)^{1/2}.
\end{split}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 9 of arXiv:2512.05340, 'The rate of convergence of the critical mean-field $O(N)$ magnetization via multivariate n'] Let $V$ satisfy Assumption~\ref{assumption: assumptions on V} and let $\mu$ be the probability measure with Lebesgue density proportional
  to $e^{-V}$. The semigroup $P_{t}$ corresponding to~\eqref{eq: overdamped langevin} satisfies
    \begin{equation}
        \sup_{h \in \lipone}\left|P_{t}h(x) - \mu(h)\right| \leq 2\,\left(|x| + m_{1}(\mu)\right)\,e^{-\eta t}
    \end{equation}
    where $m_{1}(\mu) < \infty$ denotes the first absolute moment of $\mu$, and
    \begin{equation}
        \eta := \left(\frac{1}{4B^2}\right)\wedge\left(\frac{c_1}{4(k+1)}\right)^{2/(k+2)}.
    \end{equation}

