body:
[Proposition 10 of arXiv:2606.16164, 'A Low-Regularity Semigroup Sewing Lemma via Quotient Structures'] Set $\gamma\in(0,1]$, $\alpha\in\mathbb{R}$, and $\tau\in[0,T]$. Let  $h\in Z\hat C^{\gamma}(\Delta_T^3;B_\alpha)$ and define $h^\tau$ by \eqref{eq:frozen-defect}. Then
\begin{equation}
h^\tau \in ZC^{\gamma}(\Delta_\tau^3;B_\alpha) \quad \text{and} \quad \|h^\tau\|_{\gamma,\alpha;\tau}
\le
M_{\alpha,T}\|h\|_{\gamma,\alpha}.
\end{equation}
Furthermore, if $\gamma\in(0,1)$ and $R\in E^{\gamma}(\Delta_T^2; B_\alpha)$, then $\Theta_\tau R \in F^{\gamma}(\Delta_\tau^2; B_\alpha)$
and for every $0<\varepsilon<\gamma$,
\[\|\Theta_\tau R\|_{\gamma-\varepsilon,\alpha+\varepsilon;\tau}\le M_{\alpha+\varepsilon,T}\|R\|_{\gamma-\varepsilon,\alpha+\varepsilon};\]
if $R\in E_{\log}^{1}(\Delta_T^2; B_\alpha)$, then $\Theta_\tau R \in F_{\log}^{1}(\Delta_\tau^2; B_\alpha)$ and for every $\varepsilon\in(0,1)$,
\[\|\Theta_\tau R\|_{1-\varepsilon,\alpha+\varepsilon;\tau}\le M_{\alpha+\varepsilon,T}\|R\|_{1-\varepsilon,\alpha+\varepsilon},\]
while $\|\Theta_\tau R\|_{1,\log;\tau,\alpha}\le M_{\alpha,T} \|R\|_{1,\log;\alpha}$.

[Lemma lem:LTtoZhardcore of arXiv:2411.18563, 'Lower tails for triangles inside the critical window'] Suppose $p\in[0,1]$ and set $\lambda = p/(1-p)$. Then
    \begin{align}
        \mathbb{P}_p(X=0) = (1-p)^{\binom{n}{2}} Z(\lambda, 1)\,,
    \end{align}
    and the measures $\mu_{\lambda, 1}$ and $G(n,p)$ conditioned on the event $\{X = 0\}$ are identical. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 2 of arXiv:2604.12317, 'Weak solution for distribution dependent SDEs driven by L\'{e}vy noise'] (i) For \( f \in \mathbf{W}^{1,1} \), there exists a constant \( C_{d}>0 \) and a Lebesgue measure zero set \( E \) such that for all \( x, y \notin E \),
\begin{equation}
    |f(x)-f(y)| \leq C_{d}|x-y|(\mathcal{M}|\nabla f|(x)+\mathcal{M}|\nabla f|(y)).
\end{equation}
(ii) For \( p>1 \), there exists a constant \( C_{d, p}>0 \) such that for all \( f \in L^{p}(\mathbb{R}^{d}) \),
\begin{equation}
    \|\mathcal{M} f\|_{p} \leq C_{d, p}\|f\|_{p}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 9 of arXiv:2608.06646, 'Three-dimensional stochastic wave equation with non-Lipschitz coefficients'] For $F_{n,m}$ defined in~\eqref{E:DefFnm}, it holds that for all $p\ge 2$
    \begin{align}
        \P\lr{F_{n,m}^c}\le C^p2^{4m}K^{-4}n^{-1}\lr{\log_+ n}^3e^{cp\beta t_n} 2^{-mp(\red{\gamma\wedge\mu})}\lr{K2^{n-m\varepsilon}}^{-p}\,,
    \end{align}
    where
\begin{align*}
    \beta=\sqrt{L_{b_{N_n}}}+p^{\frac{1}{\bar{\nu}+1}}L_{\sigma_{N_n}}^{\frac{2}{\bar{\nu}+1}}\,,\quad 
    t_n=\frac{1}{K}\sum_{k=1}^n\frac{1}{k}\,,
\end{align*}
{$\bar{\nu} = \min\{\nu, \nu_1, \nu_2\}$,}$0<\gamma<\bar{\gamma} = \min\{\alpha_1, \alpha_2, \alpha_3,  \gamma_1, \gamma_2\}$ and $\mu$ is defined in Proposition~\ref{P:TemptInc}.

