body:
[Proposition prop:cr-moment-intro of arXiv:2510.05850, 'Three-point connectivity constant for $q$-state Potts spin clusters'] Consider the continuum fuzzy Potts model with $q \in (1,4)$, $\kappa = 4\arccos(-\sqrt{q}/2)/\pi \in (8/3,4)$, and $r = 1/q$. 

    \begin{itemize}
        \item Let $\lambda>\frac{2}{\kappa}+\frac{3\kappa}{32}-1$ and $\theta=\frac{\pi}{\kappa} \sqrt{(4-\kappa)^2-8\kappa\lambda}$. Then
        \begin{equation}
            \mathbb{E}[(\mathsf{R}_{R \to B})^\lambda]=\frac{\cos(\frac{\pi(4-\kappa)}{\kappa})}{\cos(\theta)}.
        \end{equation}
        Moreover, if $\lambda \le \frac{2}{\kappa}+\frac{3\kappa}{32}-1$, the left-hand side of~(equation eq:cr-1-23-intro of the paper) is infinite.

        \item Let $-\lambda_0$ be the unique solution in $(0,1-\frac{\kappa}{8}-\frac{3}{2\kappa})$ to the equation
        \begin{equation*}
            \frac{\sin( \frac{\pi(\kappa-1)}{\kappa} \sqrt{(4-\kappa)^2+8\kappa x})}{\sin( \frac{\pi(2-\kappa)}{2\kappa}\sqrt{(4-\kappa)^2+8\kappa x})}=-2 \cos(\pi \tfrac{4-\kappa}{2}).
        \end{equation*}
        For $\lambda>\lambda_0$ and $\theta=\frac{\pi}{\kappa} \sqrt{(4-\kappa)^2-8\kappa\lambda}$,
        \begin{equation}
            \mathbb{E}[(\mathsf{R}_{B \to R})^\lambda] = \frac{1}{2 \cos(\frac{\pi(4-\kappa)}{\kappa})} \cdot \frac{\sin((\kappa-2) \theta) + 2 \cos(\pi \frac{4-\kappa}{2}) \sin((2-\frac{\kappa}{2}) \theta)}{\sin((\kappa-1) \theta) + 2 \cos(\pi \frac{4-\kappa}{2}) \sin((1-\frac{\kappa}{2}) \theta)}.
        \end{equation}
        Moreover, if $\lambda \le \lambda_0$, the left-hand side of~(equation eq:cr-23-1-intro of the paper) is infinite.
    \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

