[Lemma lem:ran_det of arXiv:2411.14818, 'Scaling limits of solitons in the Box-Ball system'] For any $\mathbf{q} \in \mathcal{Q}$, $k \in {\mathbb{N}}$, $1 \le \ell \le k - 1$, $i \in {\mathbb{Z}}$, $\mathbf{T} > 0$ and $\delta > 0$, we have
                \begin{align}
                    \varlimsup_{{n \to \infty}}\nu_{\mathbf{q}}\left( \sup_{0 \le t \le \mathbf{T}} \frac{1}{n} \left| \Delta Y^{{i}}_{k, \ell}\left(\mathbf{q}, \lfloor n^2 t \rfloor\right) - \sum_{j = 1}^{ \lfloor v_{k-\ell}\left(\theta^{\ell}\mathbf{q}\right)  n^2 t \rfloor} \left( \zeta_{\ell}\left(j\right) - \alpha_{\ell}\left(\mathbf{q}\right) \right) \right| > \delta \right) = 0.
                \end{align}

