[Theorem thm:LaCroix-Gaussian-realization of arXiv:2609.03532, 'Airy limit for the Jack process and topological expansion'] For every $N\in\mathbb Z_{\geq1}$ and $b>-1$,
\begin{equation}
  \mathcal M(N,\boldsymbol y,z;b)
  =
  2(1+b)z\frac{\partial}{\partial z}
  \log\left\langle
    \exp\left\{
      \frac1{1+b}\sum_{k\geq1}
      \frac{y_k z^{k/2}}{k}p_k(\boldsymbol u)
    \right\}
  \right\rangle_{N,\beta}.

\end{equation}
Equivalently, for every $\nu=(k_1,\ldots,k_m)\vdash2E$,
\begin{align}
  \frac{2E(1+b)^{1-m}}
       {|\operatorname{Aut}(\nu)|\prod_{p=1}^m k_p}
  \kappa_{N,\beta}(p_{k_1},\ldots,p_{k_m})
  &=
  \sum_{v\geq1}N^v d_{v,\nu}(b)
  \notag\\
  &=
  \sum_{\substack{g\in\frac12\mathbb Z_{\geq0}\\
                    E-m+2-2g\geq1}}
  N^{E-m+2-2g}
  \sum_{\eta=0}^{2g}r_{g,\nu,\eta}b^\eta.

\end{align}

[Proposition 22 of arXiv:2609.04033, 'From configuration spaces to graph complexes via $\mathbf{FA}$-modules'] Let $d>0$.  The $\mathbf{FS}$-module structure on $H^d(\Gamma_{2,\ast})$ lifts to an $\mathbf{FA}$-module given by:	

	\begin{itemize}
		\item  If $d\equiv 2 \text{ mod } 4$ then $H^d(\Gamma_{2,\ast}) = 0$.
		\item  If $d\equiv 0 \text{ mod } 4$ then $H^d(\Gamma_{2,\ast}) = 
		\mathsf{C}_{(2^{d/2})}$.
		\item If $d=q+1$ is odd then 

	$$H^{d}(\Gamma_{2,\ast}) = 
\ds\bigoplus_{0\leq i<q/2} w_{i,q}\mathsf{C}_{(2^i,1^{q-2i})}$$

where 
$$w_{i,q} = \begin{cases}
	 \text{dim}(\op{M}_{q-2i+2}) & \text{ if } i \text{ is odd,} \\ 	 
	 \text{dim}(\op{S}_{q-2i+2}) & \text{ if } i \text{ is even.} 
\end{cases}
$$
the dimensions of the space of modular (resp.\ modular cusp) forms of the given weight.
	\end{itemize}

[Prop 15 of arXiv:2608.03956, 'From Triangular Array Progression\\ to Near-Log-Concave State Transitions'] Let $\tau^{(1)}$ be defined by $\tau^{(1)}_{n,j} \triangleq \T^{(1)}_{n + 3, j + 3}$ for every $n \geq 0$ and $1 \leq j \leq n +1$. Then, 
\begin{enumerate}
\item $\tau^{(1)}_{n,*}$ is a strictly-positive log-concave sequence for every $n\geq 2$
\item $\tau^{(1)}$ generates a lower-triangular Toeplitz matrix by setting $\emph{diag}(\tau^{(1)}) = 0$  
\end{enumerate}

[Lemma 47 of arXiv:2601.16377, '2601.16377'] Suppose that Assumption~\ref{Assumptions_Theta} holds and let
$\nu$ be an integrable signed measure on
$\amsmathbb{A}$ such that
\begin{equation}

\forall e \in [\mathfrak{e}]\qquad \mathfrak r_e\big((\nu([\hat a'_h,\hat b'_h]))_{h = 1}^H\big) = 0.
\end{equation}
Then the limit in \eqref{eq_functional_quadratic_alternative} is either nonpositive or $-\infty$, and it admits the Fourier representation \eqref{eq_Fourier}
\begin{equation}

 \mathcal I^{(2)}[\boldsymbol{\nu}]=-\int_{0}^{+\infty} \frac{\dd s}{s}\bigg( \sum_{g,h = 1}^H \theta_{g,h}\,\widehat \nu_g(s) \widehat \nu_{h}^*(s) \bigg).
\end{equation}
 In particular, both sides of \eqref{eq_I_quadratic_Fourier} are nonpositive and they achieve the value $-\infty$ simultaneously.

