[Lemma 33 of arXiv:2604.26549, 'Existence and uniqueness results of a stochastic nonlinear heat equation with a constraint'] Let us recall the processes $\wtilde{M}_m$ and $\wtilde{M}$ defined in \eqref{eqn-martingale} and \eqref{eqn-martingale-1}, respectively. Then, for fixed $\psi \in L^2(\bO)$ and $0\le s\leq t \le T$
				\begin{align}
					\lim_{m\to\infty} \wtilde{\E}\big[(\wtilde{M}_m(t) -\wtilde{M}_m(s),\psi)h(\wtilde{u}_{m}|_{[0,s]})\big] = \wtilde{\E}\big[(\wtilde{M}(t) -\wtilde{M}(s),\psi)h(\wtilde{u}|_{[0,s]})\big].
				\end{align}

[Proposition 49 of arXiv:2606.16636, 'Free energy of non-convex multi-species spin glasses with centered Ising spins'] For every $t\geq0$ and every $q=(q_s)_{s\in\sS}\in\mcl Q_2^\sS$, writing $q^\lambda:=\sum_{s\in\sS}\lambda_s q_s$,
we have
\begin{align}

    u(t,q^\lambda)\leq f(t,q)\leq \sum_{s\in\sS}\lambda_s u(t,q_s).
\end{align}
In particular, we have $f(t,0)=u(t,0)$.

