[Prop connection of arXiv:2412.09471, 'On the moderate deviation principles in the sparse multi-type Erd\H{o}s R\'enyi random gra'] For all $(\gamma_k)\in{\mathbb N}^{{\mathbb S}_n}$ such that $\sum_{k\in {\mathbb S}_n}k\gamma_k=\mu^n n$, 
    \begin{multline*}
        {\mathbb P}\left(t_n(k)=\gamma_k, \forall k\in{\mathbb S}_{n}\right)
={\mathbb P}\left(\sum_{i=1}^{N(nZ_n)}\ind{X_i^{n}=k}=\gamma_k,\forall k\in{\mathbb S}_n\bigg|\sum_{i=1}^{N(nZ_n)}X_i^{n}=\mu^n n\right).
    \end{multline*}
    Moreover,
    \begin{multline}
         \mathbb{P}\left(\sum_{i=1}^{N(nZ_n)}X_i^n=\mu^n n\right)=
         \frac{e^{-Z_n n}
         n^n
         \prod_{r,s}{(1-\frac{\kappa(r,s)}{n})^{\frac{n^2\mu^n_s\mu^n_r}{2}}\prod_s{(\mu^n_s)^{n\mu^n_s}}}}

         {\prod_{s\in\mathcal{S}}(n\mu^n_s)!}.
    \end{multline}
    For any $k\in {\mathbb S}_n$,
    \[{\mathbb P}\left(\mathcal{C}^n_{\max}=k\right)={\mathbb P}\left(\max_{1\leq i\leq N(nZ_n)}X_i^n=k\bigg|\sum_{i=1}^{N(nZ_n)}X_i^{n}=\mu^n n\right).
    \]
    For all $l\in{\mathbb N}^+$,
    \[
    {\mathbb P}\left(C_n=l\right)={\mathbb P}\left(N(nZ_n)=l\bigg|\sum_{i=1}^{N(nZ_n)}X_i^n=\mu^n n\right).
    \]

