[Theorem thm:main of arXiv:2509.02074, 'On the Kolmogorov-Feller weak law of large numbers for the Fr\'{e}chet mean on non-compact'] Suppose that Condition (C) holds. If either of the following conditions is satisfied, then $\mu_{n} \overset{\mathbb{P}}{\to} \mu$ as $n$ tends to infinity.
\begin{enumerate}
  \item[(i)] For some $\mu_0 \in M$, it holds that $\sum_{i=1}^{n} \mathbb{P}(d(X_i, \mu_0) > n) \underset{n \to \infty}{\to} 0$ and $n^{-2}\sum_{i=1}^{n}\mathbb{E}[d^2\{\overline{X_{n,i}}(\mu_0), \mu_0\}] \underset{n \to \infty}{\to} 0$;

  \item[(ii)] The $X_i$'s are identically distributed and for some $\mu_0 \in M$, $n\mathbb{P}(d(X_1, \mu_0) > n) \underset{n \to \infty}{\to} 0$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:hidden-parameter of arXiv:2605.17082, 'Spectral Purification in Reversible Markov Chains: Hidden Parameters, Observable Equivalen'] The \emph{hidden purification parameter} is
\begin{equation}
x_k := a_3\,\rho_\star^{2k} = \frac{c_3^2}{c_2^2}\left(\frac{\lambda_3}{\lambda_2}\right)^{2k}.
\end{equation}

[Lem strip to rectangle of arXiv:2608.18045, 'Supercritical sharpness for the random cluster representation of real-valued spin models'] Let $\beta>\beta_c$. For every $h>0$ sufficiently large, there exist $\delta,c_2>0$ such that, for every $L$ large enough,
\begin{equation}
\Psi^{0,h}_{\mathcal R(L,\delta L),\beta}[\partial^{{\rm bot}} \mathcal R(L, \delta L) \longleftrightarrow\partial^{{\rm top}} \mathcal R(L, \delta L)] \geq 1 - e^{-c_2 L^{d-1}}. 
\end{equation}

[Theorem 9 of arXiv:2608.21905, '\bf Ruin theory incorporating MIPP-type jumps'] Suppose $c>\lambda^nm$, then
\begin{equation}
\begin{split}
 \mathcal{L}_{\Lambda_n}(\theta)=\frac{c-\lambda^nm}{c\theta-\lambda(1-g_{n-1}^{\circ}(E[e^{-\theta\xi}]))},\quad \theta>0.
\end{split}
\end{equation}

