[Dfn 79 ({\cite[Definitions 2.5.6 and 8.1.1) of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] {HDP18}}]\quad\par
  \begin{itemize}
    \item [$\rm{(i)}$]For a real-valued random variable $X$, we define its sub-Gaussian norm 
  $\|X\|_{\psi_2}$ by setting
  \begin{align*}
    \|X\|_{\psi_2}:=\inf\{t>0:E[\exp(X^2/t^2)]\le 2\}.
  \end{align*}
   \item [$\rm{(ii)}$]Let $(X_t)_{t\in T}$ be a real-valued stochastic process on a metric space $(T,d)$.
   We say the process has a sub-Gaussian increments if there exists a constant $K\in (0,\infty)$
   such that
   \begin{align}
    \|X_t-X_s\|_{\psi_2}\le Kd(s,t),\qquad s,\;t\in T.
   \end{align}
  \end{itemize}

[Theorem 15 of arXiv:2605.08844, 'Signature Kernel and Schwinger-Dyson Kernel Equations as Two-Parameter Rough Differential '] Let \(g\) be defined by \eqref{def_g_sig}. If \(Z\) is a solution to
\begin{equation}
Z_{t,v}
=
1+\int_{[a,t]\times[c,v]} g(Z)_{s,u}\,d(\mathbf{X}_s,\mathbf{Y}_u)
\end{equation}
in the sense of Definition \ref{solution_2d_RDE}, then
\(
Z = K^{\mathbf{X},\mathbf{Y}}.
\)
In particular, \(K^{\mathbf{X},\mathbf{Y}}\) is the unique solution to \eqref{signature_kernel_RDE}.

Moreover, if \(\tilde{\mathbf{X}} \in \Omega G_{p,\omega_{\mathbf{X}}}([a,b],V)\) and
\(\tilde{\mathbf{Y}} \in \Omega G_{q,\omega_{\mathbf{Y}}}([c,d],V)\), then
\[
\|K^{\mathbf{X},\mathbf{Y}}-K^{\tilde{\mathbf{X}},\tilde{\mathbf{Y}}}\|_{\infty}
\leq
C_{p,q,\omega_{\mathbf{X}},\omega_{\mathbf{Y}}}
\big(
\|\mathbf{X}-\tilde{\mathbf{X}}\|_{p}
+
\|\mathbf{Y}-\tilde{\mathbf{Y}}\|_{q}
\big).
\]

[Prop 4 of arXiv:2604.24189, 'Malliavin calculus and densities for chaos-driven stochastic differential equations'] Under the conditions and with the notations of Proposition \ref{pro:Nualart}, the mapping
\begin{align}
T & \, : \, W_{2}^{1-\alpha}\left(0, T; \mathbb{R}^{m}\right) \times  W_{1}^{\alpha}\left(0, T; \mathbb{R}^{d}\right) \to  W_{1}^{\alpha}\left(0, T; \mathbb{R}^{d}\right) \nonumber \\ &\, : \, (\psi,x) \mapsto x-x_0-\int_0^\star b(x_s) ds - \int_0^\star \sigma(x_s) d(\varphi_s+\psi_s)
\end{align}
is Fréchet differentiable with, for any $(\psi,x) \in W_{2}^{1-\alpha}\left(0, T; \mathbb{R}^{m}\right) \times  W_{1}^{\alpha}\left(0, T; \mathbb{R}^{d}\right)$, $\phi \in W_{2}^{1-\alpha}\left(0, T; \mathbb{R}^{m}\right) $ and $y \in W_{1}^{\alpha}\left(0, T; \mathbb{R}^{d}\right)$, for all $1 \leq k \leq d$,
\begin{equation}
(\mathcal{D}_1 T (\psi,x) [\phi])^k = - \sum_{\ell=1}^m \int_0^\star \sigma_{k,\ell}(x_s) d\phi_s^\ell
\end{equation}
and
\begin{equation}
(\mathcal{D}_2 T (\psi,x) [y])^k=y^k-\sum_{p=1}^d \int_0^\star \partial_p b_k(x_s)y_s^k ds - \sum_{p=1}^d \sum_{\ell=1}^m \int_0^\star \partial_k \sigma_{p,\ell} d(\varphi_s^\ell+\psi_s^\ell).
\end{equation}
Furthermore, $\mathcal{D}_2 T (0,x)$ is a linear homeomorphism from $W_{1}^{\alpha}\left(0, T; \mathbb{R}^{d}\right)$ to\\  $C^{1-\alpha}\left(0, T; \mathbb{R}^{d}\right)$ and we have, for any $\varphi \in W_{2}^{1-\alpha}\left(0, T ; \mathbb{R}^{m}\right)$
\begin{equation}
\mathcal{D} \Psi (\varphi)=-\mathcal{D}_2 T (0,x)^{-1} \circ \mathcal{D}_1 T (0,x).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 11 of arXiv:2608.21014, 'The stochastic Cahn--Hilliard equation in critical spaces'] Under Assumption~\ref{assumption_weakened_setting}, the following hold:
\begin{enumerate}[label=(\alph*)]
\item There exists a constant $C > 0$ such that for all $u\in V$ we have
\begin{align}
     \langle Au,u \rangle= \| \Delta u\|^2_{H^1} \geq \frac{1}{C} \|u \|^2_{V}-\|u \|^2_H.
\end{align}
\item For all $u,v\in V$ we have 
\begin{align}
    \|F(u)-F(v) \|_{V^\ast} &\lesssim \sum_{j=1}^3 \big(1+\|u \|_{\beta_j}^{\rho_j}+\|v \|^{\rho_j} _{\beta_j}\big)\| u-v\|_{\beta_j},\\
     \|F(u) \|_{V^\ast} &\lesssim \sum_{j=1}^3 \big(1+\|u \|_{\beta_j}^{\rho_j+1}\big),
\end{align}

where $(\beta_1, \rho_1) \coloneq (\frac{7}{12}, 0)$, $(\beta_2, \rho_2) \coloneq  ( \frac{7}{12}, 2 )$ and $(\beta_3, \rho_3) = ( \frac{1}{2}+\frac{d-2}{12}, 2 )$.

\item 
The mapping $G:[0,\infty)\times \Omega \times V \to \sL_2(\ell^2,H)$ is $\sP\otimes \sB(V)$-measurable and almost everywhere on $[0, \infty) \times \Omega$ and for all $u, v \in V$ we have

\begin{align}
    \| G(t,u)-G(t,v) \|_{\sL_2(\ell^2,H)} &\lesssim \sum_{j=4}^6 \big(1+\|u \|_{\beta_j}^{\rho_j}+\|v \|^{\rho_j} _{\beta_j}\big)\| u-v\|_{\beta_j},\\
     \| G(t,u) \|_{\sL_2(\ell^2,H)} &\lesssim \sum_{j=4}^6 \big(1+\|u \|_{\beta_j}^{\rho_j+1}\big),
\end{align}

where $(\beta_4,\rho_4) \coloneq  (\frac{7}{12},1)$, $(\beta_5,\rho_5) = (\frac{d+6}{16},1)$, and $(\beta_6,\rho_6) = (\frac{3}{4},0)$.
\end{enumerate}

