[Theorem eq:strassens of arXiv:2507.01236, 'Disintegration theorem for multifunctions, \\ with applications to empirical Wasserstein d'] Let $(\mathfrak{X}, \mathcal{A}, \mu)$ and $(\mathfrak{Y}, \mathcal{B}, \nu)$ be Polish probability spaces, and let $\omega$ be a nonempty, closed subset of $\mathfrak{X} \times \mathfrak{Y}$.  Then there exists a probability measure $\lambda$ on $\mathfrak{X}\times \mathfrak{Y}$ (with its Borel $\sigma$-algebra) with marginals $\mu$ and $\nu$ such that $\lambda(\omega) = 1$ if and only if
    \begin{equation}
    \mu\big(\pi_{\mathfrak{X}}(\omega\cap(\mathfrak{X}\times U))\big)\geq \nu(U)
    \end{equation}
    for all open sets $U\subseteq \mathfrak{Y}$, where $\pi_{\mathfrak{X}}:\mathfrak{X}\times \mathfrak{Y}\rightarrow \mathfrak{X}$ is the projection of $\mathfrak{X} \times \mathfrak{Y}$ onto $\mathfrak{X}$.

[Theorem thm:lines of arXiv:2608.30254, 'Exact Recovery Thresholds for Weighted Data Selection\\ in Vector-Valued Linear Regression'] Let the features span $\mathbb{R}^d$ and $\tau(D)=(m+1)d=k$. Then:
\begin{enumerate}
\item every data point with $x_i\ne0$ belongs to some positive circuit of
  dyads supported on a single feature line and of size exactly $m+1$;
\item there is no positive circuit of dyads whose features span a subspace of
  dimension $\ge2$, and no line circuit of size $\le m$; in particular no
  point has $x_i\ne0$ and $\rho_i=0$;
\item the nonzero features lie on exactly $d$ linearly independent lines.
\end{enumerate}
Consequently, any dataset whose nonzero features are \emph{not} of this
$d$-line form satisfies $\tau(D)\le(m+1)d-1$ and is recovered exactly within
budget $(m+1)d-1$.

[Proposition 44 of arXiv:2607.07283, 'Multi-time Markov renewal chains and stratified renewal theorems'] For $x\in C$, the first-entrance kernel into $D$ is

\begin{equation*}
g_D=\psi^C*q^{C,D}.
\end{equation*}

In particular,

\begin{equation*}
g_D(k)(x,D)=\Pp_x\left(\tau_D<\infty,\ S_{\tau_D}=k\right),
\qquad k\in\N^d.
\end{equation*}

Consequently, for an initial law $\nu$ on $C$, the distribution of the first entrance over the lower rectangle with upper corner $k$ is

\begin{equation*}
F_{\nu,D}(k)=\int_C\sum_{r\leqd k}g_D(r)(x,D)\nu(\dd x),
\end{equation*}

and the reliability surface is

\begin{equation*}
R_{\nu,D}(k)=1-F_{\nu,D}(k).
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 12 of arXiv:2609.00598, 'Supercritical mean--field limit for magnetized Hamiltonian dynamics'] With the same assumptions and notations of {\rm Theorem {\rm\ref{main thm 1}}}, the following identity holds for all $t\in \mathbb{R}_{+}${\rm:}
\begin{align}
\frac{\dd}{\dd t}\mathcal{E}_{\varepsilon}(t)=&-\int_{\mathbb{T}^{2}\times \mathbb{R}^{2}} (\xi-v)^{\otimes 2}:D^{\mathbf{s}}_xvf_{\varepsilon}\ \dd x\dd \xi +\int_{\mathbb{T}^{2}\times \mathbb{R}^{2}} (\xi-v)\cdot \nabla_{x} p f_{\varepsilon}\ \dd x\dd \xi \notag
\\
&+\varepsilon\int_{\mathbb{T}^{2}} D^{\mathbf{s}}_{x}v:\nabla_{x} \Phi_{\varepsilon}^{\otimes 2}\ \dd x. 

\end{align}
Consequently, the following estimate holds{\rm:} 
\begin{align}
\mathcal{E}_{\varepsilon}(t)\leq \mathcal{E}_{\varepsilon}(0)+2\left\Vert D^{\mathbf{s}}v\right\Vert_{\infty} \int_{0}^{t}\mathcal{E}_{\varepsilon}(\tau)\ \dd \tau+O(\sqrt{\varepsilon}) 
\qquad \mbox{for all $t\in [0,T]$},      
\end{align}
so that
\begin{align}
 \underset{t\in [0,T]}{\sup}\mathcal{E}_{\varepsilon}(t)\underset{\varepsilon\rightarrow 0}{\longrightarrow}0 
 \qquad \mbox{provided}\ \mathcal{E}_{\varepsilon}(0)\underset{\varepsilon\rightarrow 0}{\longrightarrow }0.      
\end{align}

[Proposition of arXiv:2607.09946, 'Statistics on Yau's conjecture: Variance asymptotics'] Let $(M,g)$ be a compact Riemannian manifold and let $0< \eta_\ell\le \ell$ be a real sequence such that $\exists\lim_{\ell\to +\infty} \ell^{-1}\eta_\ell =1-\alpha $. Assume that $\varepsilon_\ell=\varepsilon(\phi_{I_\ell}^M)<1$. Then, 
\begin{equation} 
\mathbb{E}\left\{ Y_M([\ell-\eta_\ell,\ell]) \right\}=1+\mathrm{O}(\varepsilon_\ell).
\end{equation}

[Lemma Determinant lemma of arXiv:2608.27248, 'Optimal Transport and the ABP Method in Higher Codimension'] Set $Z=\nabla^\Sigma\log f+H\in\mathbb{R}^{n+4}$.  For every $(x,y)\in\mathcal{C}$,
\begin{equation}
 \operatorname{tr} Q_x(y)=nf(x)^{\frac{1}{n-1}}
 -\big(h_{\mathcal E}(Z(x))+\langle Z(x),\Phi(x,y)\rangle\big),
\end{equation}
and
\begin{equation}
 0\leq\bigl(\det Q_x(y)\bigr)^{\frac{1}{n}}
 \leq\frac{\operatorname{tr} Q_x(y)}n\leq f(x)^{\frac{1}{n-1}}.
\end{equation}

