[Cor one-environment-lemma of arXiv:2507.09421, 'Stability of randomly switching stochastic reaction networks with asymptotically linear tr'] Suppose that $M$ is a $d\times d$ matrix which is associated to a mass-action CRN in the sense of equation (equation eq:associated CRN of the paper); suppose further that the CRN has at-most-monomolecular reactions. Suppose that there exists a vector $v\in\mathbb R_{\ge0}^d$ such that $(vM)_m>0$ for each $m$ such that $v_m>0$, where as above $(vM)_m$ is the $m$-th entry of the vector $vM$. Then for each constant $C\in\mathbb R$ and each $x\in\mathbb Z^d_{\ge0}$ such that $\operatorname{supp}(v)\cap\operatorname{supp}(x)\ne\varnothing$, there exists an $x^0\in\mathbb Z^d_{\ge0}$ such that $x^0$ is reachable from $x$ and $v\cdot x^0>C$.
\begin{proof}
We can view this as a switched process in one environment with $M_1=M$ and switching matrix $Q=(0)$. Applying Lemma (lem:v cdot x^0>C of the paper), the result is immediate.
\end{proof}

[Proposition CanoncialSpaceProperties of arXiv:2411.12522, 'Canonical insurance models: stochastic equations and comparison theorems'] For  $s \in [0,\infty)$ and $i \in \mathcal{Z}$, let $Y$ be  a $\mathbb{P}_s^i$-integrable random variable. Then
	\begin{itemize}
		\item[(i)] For  $C \in \mathcal{F}_{s-}$ and $j \in \mathcal{Z}$  it holds that
		\begin{align*}
			\mathbb{E}_{s}^i[  \mathds{1}_C \, Y  ] &=  \mathds{1}_{C}\,  \mathbb{E}_{s}^i[ Y],\\
			\mathbb{E}_{s}^i[ I^j(s) \,  Y  ] &= \mathds{1}_{j=i} \,  \mathbb{E}_{s}^i[ Y]{,}
		\end{align*}
		\item[(ii)] {f}or $t \in [s,\infty)$ and $n \in \mathbb{N}_0$ it holds that
		\begin{align*}
			\mathbb{E}_{s}^i[Y] &= \mathbb{E}_{s}^i[\mathbb{E}_{t}^{Z(t)}[Y]],\\
			\mathds{1}_{\{\tau_n > s\}}	\, \mathbb{E}_{s}^i[Y] &= \mathds{1}_{\{\tau_n > s\}}	\,  \mathbb{E}_{s}^i[\mathbb{E}_{\tau_n}^{\zeta_n}[Y]].
		\end{align*}

	\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

