[Corollary cor:conditional-limit of arXiv:2609.01690, 'Iterated-sumset spectra: The complete exponent law and its rank geometry'] Fix $k\geq3$, and take the limits first as $q\to\infty$ and then as
$h\to\infty$.  If $A$ is uniform in $\binom{[q]}k$, conditional on $A$
not being a $B_h$-set, then
\begin{equation}
 \frac{\tau(A)}h\ \Longrightarrow\ X_k,
 \qquad \mathbb P(X_k\leq t)=t^{k-2}\quad(0\leq t\leq1).
\end{equation}
Equivalently, $X_k$ has the $\operatorname{Beta}(k-2,1)$ law.  Moreover,
\begin{equation}
 \frac{|hA|}{M_{h,k}}\ \Longrightarrow\
 Y_k:=1-(1-X_k)^{k-1},
\end{equation}
whose distribution function is
\begin{equation}
 \mathbb P(Y_k\leq y)=
 \left[1-(1-y)^{1/(k-1)}\right]^{k-2}
 \qquad(0\leq y\leq1).
\end{equation}
Furthermore,
\begin{equation}
 \mathbb E Y_k
 =1-\frac{(k-2)!(k-1)!}{(2k-3)!}.
\end{equation}

[Theorem local1 of arXiv:2605.10309, 'Exponential Decay of $L^2$-Solutions to Stochastic Nonlinear Schr\"odinger Equations Drive'] Assume (H1) and (H2), and let $1<\alpha <1+\frac{4}{d}$.
Then for any $x\in L^2$ and $0<T<\infty$, there exists a sequence of $L^2$-solutions $(X_n,\tau_n), n\in\mathbb{N}$ of (equation SNLS of the paper) where $(\tau_n)_{n\in\mathbb{N}}$ is a sequence of increasing stopping times.
For every $n\ge 1$, it holds ${
{\mathbf{P}}\text{-a.s.}}$ that
\begin{align}
X_n|_{[0,\tau_n]}\in C([0,\tau_n];L^2)\cap L^{q}(0,\tau_n;L^{\alpha+1}),
\end{align}
and uniqueness holds in $C([0,\tau_n];L^2)\cap L^{q}(0,\tau_n;L^{\alpha+1})$. Here, $(q,\alpha+1)$ is a Strichartz pair, where $q=\frac{4(\alpha+1)}{d(\alpha-1)}\in (2+\frac{4}{d},\infty).$
Moreover, defining $\displaystyle \tau^*(x)=\lim_{n\to\infty}\tau_n$ and $\displaystyle X=\lim_{n\to\infty}X_n\mathbf{1}_{[0,\tau^*(x))}$, we have the blowup alternative, that is, for ${
{\mathbf{P}}\text{-a.s.}} \ \omega$, if $\tau^*(x)(\omega)<T$, then
\[ \lim_{t\to \tau^*(x)(\omega)}\|X(t)(\omega)\|_{L^2}=\infty. \] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem block-cut of arXiv:2609.00110, 'Phase Transition and Fluctuation Results for First-Passage Percolation on Spread-Out Cycle'] Assume that $b>2\ell$. Then, with $S_n^{(b)}$ as defined in~(equation eq:block-cut-sum of the paper), we have
\begin{align}
 0\leqslant S_n^{(b)}-T_{[n]} \leqslant \sum_{i=1}^{q-1}(Y_{i,-}^{(\ell)} + Y_{i,+}^{(\ell)}).
\end{align}

[Deff def:invasion-rates of arXiv:2601.19145, 'Stochastic Persistence in Infinite Dimensions'] Fix $\mu \in P_{inv}(\mathcal{M}_0)$ (see (inv-meas of the paper)), $k \in \{1,\dots,m\}$, and suppose $\mu(\{x_k = 0\}) = 1$ 
    Let $\tilde{x}$ be a process satisfying
    \begin{align*}
        d\tilde x_k &= [d_k\Delta \tilde x_k + \tilde x_k(m_k -\sum_{j\neq k}a_{kj}\tilde x_j)]dt + \sigma_k'(0)\tilde x_kdW_k(t) \\
        d\tilde x_i &= [d_i\Delta \tilde x_i + \tilde x_i(m_i - a_{ii}\tilde x_i -\sum_{j \neq i,k}a_{ij} \tilde x_j)]dt + \sigma_i(\tilde x_i)dW_i(t) \qquad i \neq k \,. 
    \end{align*}
    Define 
    \begin{equation}
        r_k(\mu) \coloneqq \inf_{\nu \in P_k(\mu)} \nu\Big(\int_D v_k\Big(m_k - \sum_{j\neq k} a_{kj}\tilde x_j\Big) - \frac{1}{2} \sigma_k'(0)^2\sum_{i=1}^\infty \lambda_{ki}^2\Big(\int_D e_{ki} v_k\Big)^2\Big) \,,
    \end{equation}
    where $P_k(\mu)$ denotes the set of all invariant measures (see  (inv-meas of the paper)) $\nu$ for the process $(v_k,\tilde x_{-k}) \coloneqq (\tilde x_k/\|\tilde x_k\|_{L^1}, \tilde x_{-k})$ satisfying $\phi^*\nu = \mu$. Here, $\phi$ is given by $\phi(v,x_{-k}) = (x_1,\dots,x_{k-1},0,x_{k+1},\dots,x_m)$, $\phi^*\nu(A) = \nu(\phi^{-1}(A))$, and  $x_{-k} = ( x_1,\dots, x_{k-1}, x_{k+1},\dots, x_m)$.

    For a general $\mu \in P_{inv}(\mathcal{M}_0)$, by invariance there is $p \in [0,1]$ and $\mu_1, \mu_2 \in P_{inv}(\mathcal{M}_0)$ such that $\mu_1(\{x_k = 0\}) = 1$, $\mu_2(\{x_k = 0\}) = 0$, and $\mu = p\mu_1 + (1-p)\mu_2$. Then we 
    we define $r_k(\mu) = pr_k(\mu_1)$.

[Thm 58 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] Let $x\in F,x_n\in F_n,\kappa\in [1/2,1],p\in [1,\infty],\alpha\in (0,\alpha_n),t>0$ and $f\in\BL^{\kappa}(M)$.
Then, under the condition $1_{\kappa,p}$,
we have that
\begin{align*}
  |P_t(G^{\alpha})^{\circ 2}f(x)-P_t^n(G^{\alpha,n})^{\circ 2}f(x_n)|
  \lesssim&\g{c}{sg1,n}
    \Bigl\{ \|f\|_{K_n}(d_{\rm{H}}(F,F_n)+d_{\rm{H}}(F,F_n)^{\kappa}+d(x,x_n))\\
    &\quad\quad\quad\quad\quad\qquad\qquad\qquad\qquad +\|f\|_{\BL^{\kappa}(K_n)}d_{\BL^{\kappa}}(\mu,\mu_n)\Bigr\}\\
    \leq&\g{c}{sg1,n}\|f\|_{\BL^{\kappa}(K_n)}( d_{\rm{H}}(F,F_n)+d_{\rm{H}}(F,F_n)^{\kappa}+d(x,x_n)+d_{\BL^{\kappa}}(\mu,\mu_n) ),
\end{align*}
where 
\begin{align*}
  \g{c}{sg1,n}:=\g{c}{estres,n}(t+\alpha^{-1}+\alpha^{-1}c_1(t,\kappa,p)\mu(F)^{1/p})+\alpha^{-1}\mu(F)^{1/p}( c_1(t,\kappa,p)+c_1([0,t],\kappa,p)).
\end{align*}

[Definition def:path_sol_MKV of arXiv:2608.30493, '\bf McKean-Vlasov Differential Equations:\\ {An introduction and a focus on some kinetic m'] Let $(W,(\mathcal{F}_t)_t)$ be a Brownian motion and \textcolor{black}{$\xi\in m\mathcal{F}_0$}. A (pathwise) solution to MKV$({\bf b},{\boldsymbol\sigma};\textcolor{black}{ \xi, W, (\mathcal{F}_t)_t})$ 
is a 
process $X$ such that the triple $(\textcolor{black}{W}, (\mathcal{F}_t)_t, X)$ 
is a (general) solution to MKV$({\bf b},{\boldsymbol\sigma})$ with 
\begin{equation}
\textcolor{black}{X_0 = \xi}. \vspace{-10pt}
\end{equation}

[Lem 9 of arXiv:2609.01101, '2609.01101'] There exist constants $A_2\ge1$ and $\eta_0\ge1$, depending only on
the fixed fields and on $\mathbf a$, such that the following
holds.  Let $\eta\ge\eta_0$ be fixed, and suppose that $T$ is sufficiently
large in terms of $\eta$.  Set
\begin{equation}
N=T^{1/2},\qquad \gamma=\frac12+\frac{\eta}{\log T}.
\end{equation}
Then, uniformly for $|b_i|\le T/2$,
\begin{align}
\sum_{n\le N}\frac{|c_{\mathbf b}(n)|^2}{n^{2\gamma}}
&\gg \eta^{-A_2}B(T,\mathbf b,\mathbf a), \\
\sum_{n\le N}\frac{|c_{\mathbf b}(n)|^2}{n}
&\ll B(T,\mathbf b,\mathbf a).                 
\end{align}

