body:
[Theorem 10 (Critical logarithmic estimate) of arXiv:2608.17540, 'Pathwise stability for one-dimensional SDEs driven by Brownian motion and a symmetric stab'] Assume Assumptions~\ref{ass:baseline}--\ref{ass:solutions} and $B,A,S<1$. Suppose $\wt\eta=1/\alpha$ and set
\[
  \Theta:=\max\{B,A,S\}.
\]
Then there exists $C>0$ such that, for $0<\Theta<1$,
\begin{equation}
\sup_{0\le t\le T}\E|X_t-\wt X_t|^{\alpha-1}
\le C\left[|x_0-\wt x_0|^{\alpha-1}+\left(\log\frac1\Theta\right)^{-1}\right].
\end{equation}
When $\Theta=0$, the right-hand side is understood as $C|x_0-\wt x_0|^{\alpha-1}$ by the limiting convention.

[Lemma lm:B-cK of arXiv:2507.08757, 'Strong existence and uniqueness of the tilt-indexed Busemann process in the planar corner '] Fix ${\widehat B}\in\widehat{\mathcal{K}}$. 
Suppose $s\in(0,1]$ satisfies 
	\begin{align}
	\mathbb{P}\bigl( \forall u,v\in\mathbb{Z}^2:{\boldsymbol{\pi}}^{{\widehat B},u,s}\curlywedgeuparrow {\boldsymbol{\pi}}^{{\widehat B},v,s}\hspace{0.7pt}\bigr) =1.
	\end{align}
Then $A^s$, defined by (equation B-def of the paper), is a shift-covariant recovering cocycle. For any $u\in\mathbb{Z}^2$ and $\{x,y\}\subset u+\mathbb{Z}^2_+$, $A^s(x,y)$ is $\mathcal{F}^{+}_u$-measurable, up to events of zero $\mathbb{P}$-measure.

[Prop RW/RI to independent RI coupling of arXiv:2411.16398, 'Large Deviations of Cover Time of Tori in Dimensions $d\geq 3$'] Let $\delta > 0$. Assume that $R \in [1, \frac{N}{1+\delta}]$ and $\boldsymbol{F} \subset \mathbb{T}_N$ (resp.\ $F \subset Q(0,N)$) is $(1+\delta)R$-well separated. Then for every $u>0$, $\rho \in (0,1)$, there exists a probability measure $\widetilde{\mathsf{P}}$ (resp.\ $\widetilde{\mathbb{P}}$) extending $\mathsf{P}$ (resp.\ $\mathbb{P}$) and carrying independent random interlacements $\left(\mathcal{I}^{(x),u(1\pm\rho)}\right)_{x\in F}$ with the same law as $\mathcal{I}^{u(1\pm\rho)}$, such that
    \begin{multline}

        \widetilde{\mathsf{P}}\Big(\mathcal{I}^{(x), u(1-\rho)} \cap Q_R(x) \subset X[0, uN^d] \cap Q_R(\boldsymbol{x}) \subset \mathcal{I}^{(x), u(1+\rho)} \cap Q_R(x) \text{\quad for all } x \in F \Big) \\
        \geq 1-C|F|R^{2d}\lceil uR^{d-2}\rceil \exp\Big(-c\rho\sqrt{uR^{d-2}}\Big), 
    \end{multline}
    resp.
    \begin{multline}

        \widetilde{\mathbb{P}}\Big(\mathcal{I}^{(x), u(1-\rho)} \cap Q_R(x) \subset \mathcal{I}^u \cap Q_R(\boldsymbol{x}) \subset \mathcal{I}^{(x), u(1+\rho)} \cap Q_R(x) \text{\quad for all } x \in F \Big) \geq \\
        1-C|F|R^{2d}\exp\big(-c\rho^2 uR^{d-2}\big)
    \end{multline}
    for some constants $c,C \in (0, \infty)$ depending only on $\delta$ and $d$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:heat-kernel-bound of arXiv:2604.20008, 'Mixing times of Langevin dynamics for \\ spiked matrix models'] For any $X_0=x_0\in\mathbf{S}_N$, and any $t\le 1$, we have
    \begin{align*}
        |\rho_t(x)|<  t^{-\frac {N-1}2}\exp\left(C N\right)\,,
    \end{align*}
    for some constants $C(\beta)$ independent of $N$ and $x_0,x$.

    Thus, the heat kernel $K(t,x,y)$ is bounded by the same quantity. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 7 of arXiv:2608.21014, 'The stochastic Cahn--Hilliard equation in critical spaces'] Let $1<q<\infty$ and let $(e_k)_{k\geq 1}$ be an orthonormal basis of
$\ell^2$. Then the space
\begin{align}
    \bigg\{\sum_{k=1}^N f_k\otimes e_k \colon N\ge 1,\;f_k\in \nH^{2,q}(\sO) \bigg\}
\end{align}
is dense in $\nH^{2,q}(\sO;\ell^2)$. Here, $(f_k\otimes e_k)(x)\ce f_k(x)e_k$ for $x\in \sO$.

[Lem finite-n-coming-generation of arXiv:2609.00110, 'Phase Transition and Fluctuation Results for First-Passage Percolation on Spread-Out Cycle'] For $r\geqslant0$, define the stopping line $\mathcal{I}_n(r)$ and its associated martingale value $\mathcal{W}_n(r)$ by
\begin{align*}
 \mathcal{I}_n(r):= \{u\ne\varnothing:\tau_{u^-}\leqslant r<\tau_u\}, \qquad 
 \mathcal{W}_n(r):= \sum_{u\in\mathcal{I}_n(r)}e^{-\alpha_n\tau_u},
\end{align*}
where $u^-$ denotes the parent of $u$. For $n_0$ sufficiently large, there exist constants $c,C>0$ such that uniformly for $n\geqslant n_0$ and $r\geqslant0$,
\begin{alignat*}{2}
 \E\mathcal{W}_n(r)&=1, 
 &\E\sum_{u\in\mathcal{I}_n(r)}e^{-2\alpha_n\tau_u} &\leqslant e^{-\alpha_nr},\\
 \E\abs{\mathcal{W}_{n,\infty}-\mathcal{W}_n(r)}^2 &\leqslant Ce^{-\alpha_nr},\qquad 
 &\E\sum_{u\in\mathcal{I}_n(r)} e^{-\alpha_n\tau_u}\mathds{1}\{\tau_u>2r\} 
 &\leqslant C(1+r)e^{-cr}.
\end{alignat*}

