[Lemma lem:tech-lemma-2 of arXiv:2606.19507, 'The $t$-Split Two-Periodic Aztec Diamond Model'] For any $w \in \gamma_1$,
    \begin{equation}
        \sum_{k=1}^\infty \left(F_{\alpha,2}(w)F_{\beta,1}(w)\right)^k = c(w)F_{\alpha,2}(w)F_{\beta,1}(w)
    \end{equation}
    where $c(w)$ is defined by equation (equation eq:c-def of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma l:conv of arXiv:2604.03979, 'Stationary Distributions in Monotone Markov Models: Theory and Applications'] There exists an $x^* \in \mathsf{X}$ such that

    \begin{equation}
         d(T_t \, \bar x, x^*) \to 0
         \quad \text{as} \quad
         t \to \infty.
    \end{equation}

[Definition def:XYgeneralpercsite of arXiv:2604.24743, 'The impact of disorder and non-convex interactions on delocalisation of height functions'] Let us fix an integer $L \in \ensuremath{\mathbb{N}}$, a percolation configuration $r \in \{0,1\}^{\Lambda_L}$, and define four models of height functions:
\begin{itemize}
    \item Given an inverse temperature $\beta \geq 0$, we define 
    \begin{equation} 
    \mu_{\Lambda_L , \beta,r}^{\ensuremath{\mathbb{Z}}-\mathrm{XY}} (\left\{ \varphi \right\}) := \frac{1}{Z_{\Lambda_L,\beta,r}^{\ensuremath{\mathbb{Z}}-\mathrm{XY}} } \prod_{x \sim y} I_{\left(\varphi(x) - \varphi(y)\right)} \left( r_x r_y \beta \right) .
\end{equation}
We denote by $\mathrm{Var}_{L , \beta , r}^{\ensuremath{\mathbb{Z}}-\mathrm{XY}}$ the variance with respect to the measure $\mu_{\Lambda_L , \beta, r}^{\ensuremath{\mathbb{Z}}-\mathrm{XY}}$.
    \item Given an inverse temperature $\beta \geq 0$, we define
\begin{equation*}
    \mu_{\Lambda_L , \beta,r}^{\ensuremath{\mathbb{Z}}-\mathrm{GFF}} (\left\{ \varphi \right\}) := \frac{1}{Z_{\Lambda_L,\beta,r}^{\ensuremath{\mathbb{Z}}-\mathrm{GFF}} } \exp \left( - \frac{1}{2\beta} \sum_{x \sim y} \frac{\left( \varphi(x) - \varphi(y) \right)^2}{r_x r_y} \right).
\end{equation*}
We denote by $\mathrm{Var}_{L , \beta , r}^{\ensuremath{\mathbb{Z}}-\mathrm{GFF}}$ the variance with respect to the measure $\mu_{\Lambda_L , \beta, r}^{\ensuremath{\mathbb{Z}}-\mathrm{GFF}}$.
    \item Given an integer $n \geq 2$ and two inverse temperatures $\beta_1 , \beta_2 \geq 0$, we define
\begin{equation} 
    \mu_{\Lambda_L , n, \beta_1, \beta_2, r}^{\ensuremath{\mathbb{Z}}-\mathrm{XY}} (\left\{ \varphi \right\}) := \frac{1}{Z_{\Lambda_L , n, \beta_1, \beta_2, r}^{\ensuremath{\mathbb{Z}}-\mathrm{XY}} }  \prod_{x \sim y}  \left[ I_{\left(\varphi(x) - \varphi(y)\right)} \left( r_x \beta_1 \right) I_{\left(\varphi(x) - \varphi(y)\right)} \left( r_y \beta_1 \right) \left(I_{\left(\varphi(x) - \varphi(y)\right)} \left(  n \beta_2 \right)\right)^{n-2} \right]. 
\end{equation}
We denote by $\mathrm{Var}_{L , n, \beta_1, \beta_2, r}^{\ensuremath{\mathbb{Z}}-\mathrm{XY}}$ the variance with respect to the measure $\mu_{\Lambda_L , n, \beta_1, \beta_2, r}^{\ensuremath{\mathbb{Z}}-\mathrm{XY}}$.
\item Given two inverse temperatures $\beta_1 , \beta_2 \geq 0$, we define
   \begin{equation} 
        \mu_{\Lambda_L, \beta_1 , \beta_2 ,r}^{\ensuremath{\mathbb{Z}}-\mathrm{XY}/\mathrm{GFF}}(\left\{ \varphi \right\}) := \frac{1}{Z_{\Lambda_L, \beta_1 , \beta_2 }^{\ensuremath{\mathbb{Z}}-\mathrm{XY}/\mathrm{GFF}}} \prod_{x \sim y}  I_{\left(\varphi(x) - \varphi(y)\right)} \left(r_x  \beta_1 \right)  I_{\left(\varphi(x) - \varphi(y)\right)} \left(r_y  \beta_1 \right)  \exp \left( - \frac{\left( \varphi(x) - \varphi(y) \right)^2}{2\beta_2} \right).
    \end{equation}
    We denote by $\mathrm{Var}_{L , \beta_1 , \beta_2 , r}^{\ensuremath{\mathbb{Z}}-\mathrm{XY/GFF}}$ the variance with respect to the measure $\mu_{\Lambda_L , \beta_1 , \beta_2, r}^{\ensuremath{\mathbb{Z}}-\mathrm{XY/GFF}}$.
\end{itemize}

[Theorem 7 of arXiv:2606.15178, 'The distribution of the de Moivre experiment'] The moment of order $r$ of the bi$^{s}$nomial distribution, denoted by $M(r)$, has a polynomial form generated by the partial Bell polynomials:
	\begin{equation}
		M(r)=\sum_{k=1}^{r} (n)_k B_{r,k}\Big(\sum_{l=1}^{s}l p^l q^{s-l},\sum_{l=1}^{s}l^2 p^l q^{s-l},\ldots,\sum_{l=1}^{s}l^{r-k+1} p^l q^{s-l}\Big), \quad \text{ for } p\neq q,
	\end{equation} 
	and
	\begin{equation}
		M(r)=\sum_{k=1}^{r} (n)_k p^{ks} B_{r,k}\Big(\sum_{l=1}^{s}l ,\sum_{l=1}^{s}l^2,\ldots,\sum_{l=1}^{s}l^{r-k+1} \Big),\quad \text{ for } p= q,
	\end{equation}
	where $ (n)_k $ is the falling factorial, $ (n)_k=n(n-1)\cdots(n-k+1). $

[Proposition prop:NS of arXiv:2411.06838, 'Generalized Wasserstein Barycenters'] A sequence $(\gamma_n)_{n\in \mathbb{N}} \subset \mathcal{P}_2^{sw}(Z)$ and a measure $\gamma \in \mathcal{P}_2^{sw}(Z)$ satisfy
\begin{itemize}
	\item[\rm{(i)}] $\gamma_n \rightharpoonup \gamma$ narrowly in $\mathcal{P}(Z)$;
	\item[\rm{(ii)}] $\displaystyle \lim_{n\to \infty} \int_Z |x|^2\, {\rm d}\gamma_n(x,y) \to \int_Z |x|^2\, {\rm d} \gamma(x,y)$;
	\item[\rm{(iii)}] $\displaystyle \sup_{n \in \mathbb{N}} \int_Z |y|^2\, {\rm d}\gamma_n(x,y) < +\infty$, 
\end{itemize}	
if and only if
\[
	\gamma_n \to \gamma\quad  \text{in}\quad \mathcal{P}_2^{sw}(Z).
\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm Main Theorem Statement of arXiv:2411.01633, 'On the Limit of the Tridiagonal Model \\for $\beta$-Dyson Brownian Motion'] Fix a $k \in \mathbb{N}$ and let $\{a_j\}_{j=1}^n, \{b_j\}_{j=1}^{n-1}$ be the tridiagonal entry (processes) as in (equation eq:tridiagonalmatrix of the paper), from the $n\times n$ tridiagonalized GOE process. Define 
\begin{equation*}
E_n(t):=\left(a_1(t),\dots, a_k(t), \frac{1}{\sqrt{n}}(b_1(t)^2-n),\dots ,\frac{1}{\sqrt{n}}(b_k(t)^2-n)\right).
\end{equation*} 
Then, $E_n(t)$ converges weakly in $C[0,\infty)$ to a vector process $E(t)=(A_1(t),\dots,A_k(t),B_1(t),\dots,B_k(t))$ as $n\to\infty$, where
\begin{equation*}
    \frac{1}{\sqrt{2}}E(t) \sim \mathbf{OU}_{2k}(1,3,\dots,2k-1,2,4,\dots,2k).
\end{equation*} 
More explicitly, the components $A_j(t) \in C[0,\infty)$ and $B_j(t) \in C[0,\infty)$ are jointly-independent centered Ornstein--Uhlenbeck processes with covariances given as $\mathrm{Cov}(A_j(t),A_j(s))=2e^{-(2j-1)|t-s|}$ and $\mathrm{Cov}(B_j(t),B_j(s))=2e^{-2j|t-s|}$, for $j=1,\dots,k$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 29 (Universal polynomial inequality) of arXiv:2605.11451, '2605.11451'] Let $0<s<1$ and $s^2\le r\le s$. Then
\begin{equation}
 (1+s^2)(1+r)(1+r^3)\le2(1+r^2s)^2.
\end{equation}

[Definition Thick quantum disk of arXiv:2510.05850, 'Three-point connectivity constant for $q$-state Potts spin clusters'] For $W \ge \frac{\gamma^2}{2}$, we define the measure $\mathcal{M}_2^{\rm disk}(W)$ as follows. Write $\beta=\gamma+\frac{2-W}{\gamma}$ and let $(B_t)_{t \ge 0}$ be a standard Brownian motion conditioned on $B_{2t}-(Q-\beta)t<0$ for all $t>0$, and $(\widetilde B_t)_{t \ge 0}$ be its independent copy. Let
    \begin{equation*}
        Y_t=
        \begin{cases}
            B_{2t}-(Q-\beta) t, & \mbox{ for }\,t \ge 0, \\
            \widetilde B_{-2t}+(Q-\beta)t, & \mbox{ for }\,t<0,
        \end{cases}
    \end{equation*}
    and set $h_1(z)=Y_{\mathrm{Re} z}$ for each $z \in \mathcal{S}$. Let $h_2$ be a random generalized function with the same law as $h_\mathcal{S}^2$ defined above and independent from $h_1$.
    Sample $\mathbf{c} \in \mathbb{R}$ independently from the measure $\frac{\gamma}{2} e^{(\beta-Q)c} \mathop{}\!\mathrm{d} c$, and set $\phi(z)=h_1(z)+h_2(z)+\mathbf{c}$. The infinite measure $\mathcal{M}_2^{\rm disk}(W)$ is defined as the law of $(\mathcal{S},\phi,-\infty,+\infty)/{\sim_\gamma}$.

[Lemma 14 of arXiv:2607.13273, 'Asymptotics of transition densities for L\'evy processes with stochastic resetting'] For every $\lambda < m$ we have 
        \begin{equation}
            \lim\limits_{\substack{|y|\to\infty,\,t\to\infty\\ t/|y|^{\alpha/2}<M}}
            \frac{\eta(\kappa(t,y),1)e^{(m-\lambda)t}|y|^{-\alpha/2}}{\int\limits_0^{\kappa(t,y)} e^{(m-\lambda)\frac{|y|^{\alpha/2}}{\sqrt{2^\alpha m}}s}\eta(s,1)\, \dx[s]} = \frac{m-\lambda}{\sqrt{2^\alpha m}}.
        \end{equation}

