[Theorem thm:fixed-shell-minimax of arXiv:2608.20295, 'Physical-Support Confidence Sets for Highly Coherent Dictionaries'] Under Assumption~(ass:frozen-shell of the paper) and the interior compatibility
condition in Supplementary Section~(sec:supp-minimax-setup of the paper), there exist
fixed positive constants and transition thresholds such that
\begin{equation}
\begin{aligned}
\mathcal R_{N,T}^{(q,r)}(s)
&\ge
c\max\left[
    \mathbf 1\{I_G^{(r)}\le c_G\},
    \;
    s\,\mathbf 1\{I_S\le c_S\},
    \right.\\[-1mm]
&\hspace{30mm}\left.
    s\wedge\frac{1}{\sqrt N\,s^2}
\right].
\end{aligned}

\end{equation}
When $I_G^{(r)}$ and $I_S$ exceed their fixed resolution thresholds, the cross-dictionary correspondence of Theorem~(thm:honest-region of the paper), with $\epsilon_N\le CN^{-1/2}$, satisfies 
\[
\sup_{\xi\in\mathfrak P^p_{q,r}(s)}
\mathbb E_\xi
\operatorname{diam}_{\mathrm{pr}}
\left(
    \widehat{\mathfrak C}_{q,r,s}^{p}
\right)
\le
C\left(
    s\wedge\frac{1}{\sqrt N\,s^2}
\right).
\]
Together with the lower bound, this yields 
\begin{equation}
    \mathcal R_{N,T}^{(q,r)}(s)
    \asymp
    s\wedge\frac{1}{\sqrt N\,s^2}.

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Def 5 of arXiv:2604.24189, 'Malliavin calculus and densities for chaos-driven stochastic differential equations'] A $\mathcal{U}$-valued random variable $F : \Omega \to \mathcal{U}$ is said to be
\begin{enumerate}[(a)]
\item \emph{ray absolutely continuous} \textbf{(RAC)} if, for every $h\in \mathfrak{H}$, there exists a $\mathcal{U}$-valued random variable $\hat{F}_h : \Omega \to \mathcal{U}$ such that $F=\hat{F}_h$ $\mathbb{P}$-a.s.\ and, for every $\omega \in \Omega$, the map $\mathbb{R} \ni\varepsilon\mapsto \hat{F}_h(\omega+\varepsilon\,j(h))$ is absolutely continuous;
\item \emph{stochastically Gâteaux differentiable} \textbf{(SGD)} if there exists a random variable $G: \Omega\to \mathcal{L}_{HS}(j(\mathfrak{H}),\mathcal{U})$ such that, for every $h\in \mathfrak{H}$,
\begin{equation}
\frac{1}{\varepsilon}(F(\bullet + \varepsilon\,j(h))-F) \overset{\mathbb{P}}{\longrightarrow} G(\bullet)[j(h)] \qquad\text{ as } \varepsilon\to 0.
\end{equation}
The operator $G$ is unique $\mathbb{P}$-a.s., and is denoted by $\hat{D}F$. Higher-order derivatives are defined inductively: if $\hat{D}^{n-1}F$ is \textbf{(SGD)}, then $\hat{D}^{n}F:=\hat{D}(\hat{D}^{n-1}F)$.
\end{enumerate}

