body:
[Lemma LargeDevBalls of arXiv:2608.17031, 'A shape theorem for periodic branching diffusion'] The following holds:
    \begin{enumerate}[(i)]
        \item Let $\zeta \in \{y\in \mathbb{R}^d: \Phi(y)> 0\}$ and $\epsilon \in (0,1)$ be such that $B(\zeta, \epsilon)\subset \{y\in \mathbb{R}^d: \Phi(y)\geq \epsilon\}$, then
    \begin{equation}
        \mathbf{E}_0\Bigg[\sum_{v\in \mathcal{N}_t}\mathds{1}_{\{X_v(t)\in tB(\zeta,\epsilon)\}}\Bigg] \to 0 \ \ \mathrm{ as } \ \ t\to +\infty.
    \end{equation}
        \item Let $\zeta \in \mathrm{int}(\{y\in \mathbb{R}^d: \Phi(y)\leq 0\})$ and $\epsilon \in (0,1)$ be such that $B(\zeta, \epsilon)\subset \{y\in \mathbb{R}^d: \Phi(y)\leq \epsilon\}$, then
    \begin{equation}
        \mathbf{E}_0\Bigg[\sum_{v\in \mathcal{N}_t}\mathds{1}_{\{X_v(t)\in tB(\zeta,\epsilon)\}}\Bigg] \to + \infty \ \ \mathrm{ as } \ \ t\to +\infty.
    \end{equation}
    \end{enumerate}

