[Lemma eq:zero-first-moment of arXiv:2607.14087, 'Stochastic Domination of Gaussian Maxima: A Resolution of the Weak Simplex Conjecture'] \label[lemma]{thm:centered-product}
Let $R$ be an $m\times m$ correlation matrix and let $X\sim\mathcal N(0,R)$.  For
each $i$, let $f_i:\mathbb R\to[0,\infty)$ be bounded and log-concave, with positive
Gaussian integral, and suppose that
\begin{equation}
  \int_{\mathbb R}z f_i(z)\,d\gamma_1(z)=0.
\end{equation}
Then
\begin{equation}
  \mathbb E\prod_{i=1}^m f_i(X_i)
  \geq \prod_{i=1}^m \mathbb E f_i(X_i)
  =\prod_{i=1}^m\int_{\mathbb R}f_i\,d\gamma_1.
\end{equation}
The covariance matrix $R$ may be singular. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma epslowerbound of arXiv:2608.23765, '\texorpdfstring{Tight Majorizations and Convergence Rates\\ of Nuclear Norm Minimization I'] Assume that the linear measurement operator $\mathcal{A}: \mathbb{R}^{d_1 \times d_2} \rightarrow \mathbb{R}^m$ satisfies the NSP of order~$r$ with constant $ \eta_r < 1 $.
	Moreover, assume that $\mathbf{X}_\star$ has rank~$r$.
    Let $\left(  \mathbf{X}^{(k)}\right)_{k\geq 0}$ and $ \left(\varepsilon_{k} \right)_{k \geq 0}$ be the iterates and smoothing parameters of $\texttt{MatrixIRLS}$ with input $\mathbf{y} = \mathcal{A}(\mathbf{X}_\star)$, arbitrary initial weight operator $\mathbf{W}^{(0)}$, $\widetilde{r} = r$, based on $q$-power mean weight operators with $q \in [-1,\infty]$ or on one-sided weight operators $\W{\mathbf{X}^{(k)}}{\varepsilon_k}(\cdot)$.
	Then, for all natural numbers $k \ge 1$, it holds that 
	\begin{equation*}
		\varepsilon_k \ge  \vartheta \frac{\besterrNuc{\mathbf{X}^{(k)}}{r}}{d},
	\end{equation*}
	where
	\begin{equation*}
	\vartheta
	:=
	\frac{1-\eta_r}{\left(1+\eta_r\right)\left(\frac{3}{2}+\eta_r\right)}.
	\end{equation*}

