[Lemma lem:codiff-finite of arXiv:2606.02003, 'Higher-Order Multifractional Stable Motion:\\ Definition and Fundamental Properties'] Let $X = I(f_1)$, $Y = I(f_2)$ be jointly S$\alpha$S with
$\alpha \in (1,2]$ and $f_1, f_2 \in L^\alpha(E,m)$. Then:
\begin{enumerate}[label=(\roman*)]
\item \textbf{Finiteness and bound.}
  \begin{equation}

  0 \leq \tau(X,Y) \leq 2\min\!\bigl(\|X\|_\alpha^\alpha,
  \|Y\|_\alpha^\alpha\bigr) < \infty.
  \end{equation}
\item \textbf{Symmetry.} $\tau(X,Y) = \tau(Y,X)$.
\item \textbf{Independence.} $X \perp Y \Rightarrow \tau(X,Y) = 0$.
\item \textbf{Gaussian case.} For $\alpha = 2$:
  $\tau(X,Y) = \mathrm{Cov}(X,Y)$.
\item \textbf{Integral formula.}
  \begin{equation}

  \tau(X,Y)
  = \int_E\!\bigl[|f_1|^\alpha + |f_2|^\alpha
    - |f_1 - f_2|^\alpha\bigr]\,dm.
  \end{equation}
\end{enumerate}

[Lemma lem:L2_convergence_drift of arXiv:2606.12143, 'Continuous stochastic flows driven by white noise and their duals'] For any $T\ge r$, as $n\to\infty$, the following convergence holds almost surely,
	\begin{align*}
		\sup_{r\le x\le T} \left| \left(X^n(x)-\int_r^x b_n(X^n(u),u)\ensuremath{\mathrm{d}} u\right) - \left(X(x)-\int_r^x b(X(u),u)\ensuremath{\mathrm{d}} u\right) \right| \to 0.
	\end{align*}

[Lemma induction-statement of arXiv:2607.22480, 'Distinguishability threshold for random geometric graphs'] Assume that $H\in \mathcal{E}$. Then for every $0\leq s\leq n-1$,
{\relscale{0.95}\begin{align*}
\mathbb{P}\Big[G(n,d,p)\big|_{[s+1,n]}\!=\!H_s\wedge \mathcal{F} \Big|\mathcal{G}_s\Big]
\leq \!\!\!\!\!\!\prod_{s<i<j\leq n}\!\!\!\!\!\Phi_{sij}
\exp\!\Big(Z_s + &\frac{\kappa_{\triangle}N_{\triangle}(H_s)}{\sqrt{d}}
+\frac{\kappa_\square N_{\square}(H_s)}{d}+\frac{\kappa_{\diamond} N_{\diamond}(H_s)}{d}
+ \widetilde O\Big((n\!-\!s)R_{n, d, p}\Big)\!\Big),
\end{align*}}
where $\kappa_\triangle=\frac{a^3}{p^3(1-p)^3}, \kappa_\square=\frac{a^4}{p^4(1-p)^4}-\frac{2a^6}{p^5(1-p)^5}$, and $\kappa_{\diamond}=\frac{a^5}{p^5(1-p)^5}\Big(z_p-\frac{a(1-2p)}{p(1-p)}\Big)$,
\[
\Phi_{sij}=
\begin{cases}
\Phi\Big(-z_p+\sqrt d\,\langle \pi_s(\boldsymbol{v}_i),\pi_s(\boldsymbol{v}_j)\rangle\Big),& ij\in E(H),\\[2mm]
\Phi\Big(z_p-\sqrt d\,\langle \pi_s(\boldsymbol{v}_i),\pi_s(\boldsymbol{v}_j)\rangle\Big),& ij\notin E(H),
\end{cases}
\]
and
$Z_s=\sum_{\substack{s<i< j\leq n\\s<r<n}}\lambda_{ij}\lambda_{ir}\lambda_{jr}(z_p-\lambda_{ij})\langle \pi_s(\boldsymbol{v}_i), \pi_s(\boldsymbol{v}_j)\rangle .$ (Proof in the paper; no proof environment follows the statement in the TeX.)

