[Corollary 12 of arXiv:2609.01333, '2609.01333'] Let $\gamma_* > 0$ be given as in Theorem~\ref{thm:Lambda-star}, and fix $\lambda > 0$ and $\gamma \in (0, \gamma_*)$.
\begin{itemize}
\item All eigenfunctions of the operator $L_\lambda: X \to Y$ are of the form
\begin{align*}
\varphi_k(t) = c e_k(t), \quad c \in \R, \qquad \text{where } e_k(t) = \cos(kt) \text{ for } k \in \mathbb{N}.
\end{align*}
\item The sequence of eigenvalues $ \{\sigma_{\lambda,\gamma}(k)\}_{k \in \mathbb{N}}$ is strictly increasing with
$ \sigma_{\lambda,\gamma}(k)\to  \infty $ as $k\to\infty$. In particular, each  $\sigma_{\lambda,\gamma}(k)$  is a simple eigenvalue.
\item Moreover, the kernel of $L_{\lambda_{*}}$ is given by $N (L_{\lambda_{*}})= \R\cos(\cdot)$.
\end{itemize}

