body:
[Prop 28 of arXiv:2607.21759, 'Marchenko--Pastur law for tensor powers of exchangeable unconditional vectors'] For any unconditional isotropic log-concave vector $\mathbf X$, there exists an absolute constant $L$ such that \[
        \E(X_1^8\dotsm X_r^8) \leq L^{2r}
    \] for all $1 \leq r \leq n$. (In general, we have for any fixed exponent $1 \leq q < \infty$, $\nm{X_1\dotsm X_r}_{L^q(\Pr)} \leq L^r$.)

[Lemma 60 of arXiv:2607.18104, '2607.18104'] Fix some $M\in \N$. Assume that the initial data $ (\eta_0^{N,i,j})$ for $i \in \lbr M \rbr, j\in \{ 1,2\}$ of the above exclusion processes is $N$-periodic with $k=k(N)$ particles, satisfies $\eta_0^{N,i,1}=\eta_0^{N,i,2}$ for all $i\in \lbr M\rbr$, and for some constant $C>0$ 
    \begin{equation}
\Ber_{\rho+CN^{-1/2}}^{N} \succeq \P( \eta_0^{N,i,1} \in \, \cdot \, ) \succeq \Ber_{\rho-CN^{-1/2}}^{N}
\end{equation} for all $N \in \N$, $i\in \lbr M \rbr$, and  $\rho \in [\mathfrak{a},1-\mathfrak{a}]$ for some $\mathfrak{a}>0$. Then there exist  $c_0,C_0>0$, depending only on $\mathfrak{a},q$ and $C$, but not $\theta,\rho,N$, such that under the patched coupling,  for all $\delta>0$
\begin{equation}
\begin{split}
    \Ppatch\left( \eta_t^{N,i,1}(x)=\eta_t^{N,i,2}(x) \ \forall (x,t)\in \mathcal{I}^{\rho}_{\delta,N}\Big(\frac{3}{8},\frac{5}{8}\Big)  \right) &\geq 1 - C_0 \exp(-c_0\delta^{-1}) , \\
    \Ppatch\left( \eta_t^{N,i,1}(x)=\eta_t^{N,i,2}(x+N) \ \forall (x,t)\in \mathcal{I}^{\rho}_{\delta,N}\Big(-\frac{1}{8},\frac{1}{8}\Big)\right) &\geq 1 - C_0 \exp(-c_0\delta^{-1}) .
\end{split}
\end{equation}

