body:
[Definition def:type FL, duality group, type F of arXiv:2609.00233, 'A survey on mapping class groups of 3-manifolds'] We say that a group $G$ is:
    \begin{itemize}
        \item of \emph{type FL} if there is a finite-length resolution of $\mathbb{Z}$ as a $\mathbb{Z}G$-module by free finitely-generated $\mathbb{Z}G$-modules;
        \item a ($\mathbb{Z}$-)\emph{duality group} if there exists a (right) $\mathbb{Z}G$-module $D$ and $n \in \mathbb{Z}_{\geq 0}$ such that for all $k$ and all $\mathbb{Z}G$-modules $M$, we have natural isomorphisms
        \[H^k(G;M) \cong H_{n-k}(G;D \otimes_{\mathbb{Z}} M)\]
        (in this case say that the \emph{dimension} of $G$ is $n$);
        \item \emph{geometrically finite} (or \emph{of type F}) if there exists an aspherical finite CW-complex with fundamental group $G$, i.e.~there is a finite $K(G, 1)$-complex.
    \end{itemize}
    For any of these properties $P$, we say that $G$ is \emph{virtually P} if it has a finite-index subgroup which is $P$ (and we say $G$ is of \emph{type VFL} if it is virtually of type \emph{FL}).

[Cor 15 of arXiv:2605.15501, 'Well-posedness of the obstacle problem for generalized Dean--Kawasaki equation\thanks{ The'] For the lower obstacle problem, in which we require $u\geq\psi$ on $Q_T$ rather than $u\leq\psi$, the corresponding approximating penalized equation \eqref{eq:appro penalized eq} becomes
\begin{align}
\mathrm{d}u_{\alpha,n,\varepsilon} & =\Big[\Delta\Phi(u_{\alpha,n,\varepsilon})+\alpha\Delta u_{\alpha,n,\varepsilon}+\frac{1}{2}\nabla\cdot(F_{1}[\sigma_n^{\prime}(u_{\alpha,n,\varepsilon})]^{2}\nabla u_{\alpha,n,\varepsilon}+\sigma_n(u_{\alpha,n,\varepsilon})\sigma_n^{\prime}(u_{\alpha,n,\varepsilon})F_{2})\nonumber \\
 & \quad-\nabla \cdot g(u_{\alpha,n,\varepsilon})+\frac{1}{\varepsilon}(u_{\alpha,n,\varepsilon}-\psi)^{-}\Big]\mathrm{d}t-\nabla\cdot(\sigma_{n}(u_{\alpha,n,\varepsilon})\mathrm{d}\xi^{F}).
\end{align}
A priori estimates for the solution $u_{\alpha,n,\varepsilon}$ to \eqref{eq:appro penalized eq lower obstacle} remain valid under additional assumptions that $|\sigma(r)|\leq C(1+|r|)$ and $p=2$ using Gronwall inequality instead of \cite[Lemma 5.4]{fehrman2021wellarxiv}.
This includes the important Dean--Kawasaki equation
\begin{align*}
\mathrm{d}u & =\Delta\Phi(u)\mathrm{d}t+\nabla\cdot\sqrt{\Phi(u)}\circ\mathrm{d}\xi^{F},
\end{align*}
provided that $|\Phi(r)|\leq C(1+|r|^{2})$ for all $r\in\mathbb{R}$, and thus in particular covers the case $\Phi(r)=r$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Ppn 142 (\hyperlink{proof:p.IAMP-to-SDE-limit.Ax.y}{proved in \S\ref{ss:proof.iamp.diffus.limit}}) of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] In the setting of Theorem~\ref{thm:IAMP-main}\ref{i:IAMP-main-main},  the IAMP defined by \eqref{eq:proxy-y-amp-def}--\eqref{eq:x-amp-def} satisfies the bound
  \[
  \sup\bigg\{
  \plim_{N\to\infty}
  \frac{\|\bA_{\ell}\by^\ell-\bx^\ell\|}{N^{1/2}}
  : 0\le \ell\le\ubl
  \bigg\}
  \leq 
  C\delta^{1/4}
  +C_0\epsilon^{1/2}\,.\]
where $C=C(L,\alpha)$ and $C_0=C_0(\alpha)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 43 of arXiv:2510.22783, 'Universality of Cutoff for Riffle Shuffling'] Consider events ${F}_i$, ${F}'_i$ (for each $i \in \{\iota(p),\ldots,\tau(p)-2\}$), ${F}_{\tau(p)-1}$, ${F}'_{\tau(p)-1}$ and ${F}^{(\p)}$ of the form above. Suppose that there exists $\gamma>0$ such that for each $i \in [\iota(p),\tau(p)-2]$, the conditional estimate 
        \begin{equation}

            \E\big[|E^\p_{\for}(G,G')|-|E_{\for}^p(G_i,G_i')| \,\big\vert\, \mathbf a_i, \mathbf{a}'_i\big] \leq \gamma 
        \end{equation}
        holds on the event ${F}_i\cap{F}'_i$.
        Then
        \begin{equation} 
            \E[e^{t E^\p_{\for}(G,G')}\cdot 1_{{F}^{(\p)}}] \leq 1+2e^t\gamma
        \end{equation}
        for any $N$ sufficiently large, $t>0$ and $e^t\gamma<\frac{1}{10}$.

[Proposition prop:quasicont-conseq of arXiv:2510.13659, 'On the energy image density conjecture of Bouleau and Hirsch'] Let  $(X,d,\mu, \mathcal{E}_p, \mathcal{F}_p, \Gamma_p)$ be a regular $p$-Dirichlet space.
		If $f\in \mathcal{F}_p$ is quasicontinuous and let $A\subset X$ be Borel measurable, then the following hold: 
		\begin{enumerate}
			\item If $\cCap(A)=0$, then $\Gamma_p\langle f\rangle(A)=0$.
			\item If $g \in \Lip(\mathbb{R})$ with $g(0)=0$, then $g \circ f \in \mathcal{F}_p$ and 
			\[
			\Gamma_p\langle g\circ f\rangle  \le( \Lip_a[g] \circ f)^p \cdot \Gamma_p\langle f\rangle.
			\]
			\item If $g\in \Lip(\mathbb{R}^n)$ with $g(0)=0$, and $f=(f_1,\dots, f_n)$ with $f_i\in \mathcal{F}_p$ and $f_i$ are quasicontinuous, then
			\begin{equation} 
				\Gamma_p\langle g\circ f\rangle  \le \left(1 \vee n^{(p-2)/2}\right) (\Lip_a[g] \circ f)^p\cdot \sum_{i=1}^n \Gamma_p\langle f_i\rangle.
			\end{equation}
		\end{enumerate}

