body:
[Theorem 9 of arXiv:2606.03661, '2606.03661'] Let $\alpha \in (0,1)$, $\nu \in \mathbb{R}$ and $m \in \mathbb{N}$. Then, the function $\Psi_\alpha^\nu(-\kappa t)$ admits the asymptotic expansion
\begin{equation}

\Psi_\alpha^\nu(-\kappa t) =  -\frac{G(1+\nu)}{G(2+\nu-\alpha)}
\sum_{k=1}^m \rho_k  
(\kappa t)^{-(\nu+k)} 
 + \mathcal{O}\left(|\kappa t|^{-(\nu+m+1/2)}\right),
\end{equation}
where 
\begin{equation}

\rho_k = \underset{\varepsilon=0}{\operatorname{Res}} \left[\frac{(\kappa t)^{-\varepsilon} \Gamma(\nu+k+\varepsilon)G(2-\alpha-k-\varepsilon)}{  G(1-k-\varepsilon)} \right], \qquad (k = 1,2,\ldots,m).
\end{equation}

[Lemma lem:comparaison_esperances of arXiv:2605.30999, 'Functional central limit theorems for $U$-statistics of $\beta$-mixing data'] Let $\left(X_j\right)_{j\geqslant 1}$ be a strictly stationary sequence of random variables taking values in a measurable space $\pr{S,\mathcal{S}}$. Let $f\colon S^m\to \mathbb R$ be a measurable function, where $S^m$ is endowed with the product $\sigma$-algebra. 
Let $\left(m\left(u,v\right)\right)_{\substack{1\leqslant u\leqslant \ell\\ 1\leqslant v\leqslant r_u}}$ be integers such that 
\begin{equation*}
    m\left(1,1\right)<\dots<m\left(1,r_1\right)<m\left(2,1\right)<\dots< m\left(2,r_2\right)<\dots< m\left(\ell,1\right)<\dots<m\left(\ell,r_\ell\right).
\end{equation*}
Let $r=\sum_{u=1}^\ell r_u$. Let $\left(\xi_j\right)_{j=1}^r$ be a sequence of random variables such that for each $j$, $\xi_j$ has the same distribution as $X_1$ and 
\begin{multline*}
    \mathcal{L}\pr{\pr{\xi_{m\left(1,1\right)},\dots,\xi_{m\left(1,r_1\right)},\xi_{m\left(2,1\right)},
\dots,\xi_{m\left(2,r_2\right)},\dots,\xi_{m\left(\ell,1\right)},\dots,\xi_{m\left(\ell,r_\ell\right)}  }}\\
=\mathcal{L}\pr{X_{m\left(1,1\right)},\dots,X_{m\left(1,r_1\right)} }
\otimes \dots\otimes \mathcal{L}\pr{X_{m\left(\ell,1\right)},\dots,X_{m\left(\ell,r_\ell\right)} }.
\end{multline*}
Suppose that there exists a constant $R$ such that for each $x_1,\dots,x_m\in S$,  $\left|f\left(x_1,\dots,x_m\right)\right|\leqslant R$.
Then the following inequality takes place
\begin{multline}
    \abs{\E{f\pr{X_{m\left(1,1\right)},\dots,X_{m\left(\ell,r_\ell\right)} }}-
    \E{f\pr{\xi_{m\left(1,1\right)},\dots,\xi_{m\left(\ell,r_\ell\right)} }}}
\\    \leqslant 2\sum_{i=1}^{\ell-1}
    \beta\left(m\left(i+1,1\right)-m\left(i,r_i\right)\right)R.
\end{multline} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Def P of arXiv:2411.15954, 'A gradient model for the Bernstein polynomial basis'] For each fixed natural numbers $\ell \leq L<N$, each $0\leq j\leq L$ and each $\eta\in\Omega_N$, let 
\begin{align}
    \mathbf{p}_{\ell;L}
    &:=
    \frac{1}{L+1}
    \sum_{j=0}^{L}
    \mathbf{p}_{\ell;L}^j
    \quad\text{with}\quad
    \mathbf{p}_{\ell;L}^j(\eta)
    :=
    \frac{\binom{m_j^L(\eta)}{\ell}}{\binom{L}{\ell}}
    \mathbf{1}
    \{
    m_j^L(\eta)\geq \ell
    \}
    .    
\end{align}
    We refer to the process induced by setting $\mathbf{c}=\mathbf{p}_{\ell;L}$ in (equation generic:gen of the paper) as $\text{PMM}_{L}(\ell)$, and its corresponding Markov generator as $\mathcal{L}_N^{\ell;L}$.

[Proposition 12 of arXiv:2609.02478, 'Improved Weyl bounds on short intervals'] Let $k\ge3$ and $K=k(k-1)$.  For every sufficiently small fixed
$\delta=\delta(k)>0$ and every $\varepsilon>0$, the following holds for all sufficiently large $N$.  If
\begin{equation}
  |g_k(\boldsymbol\alpha;N)|
  >N^{1-1/K+\varepsilon},
\end{equation}
then, for the set of centres supplied by \cref{lem:all-cuts}, there are distinct $x,y\in X$ such that
\begin{equation}
  \|\beta_j(x)-\beta_j(y)\|
  <\delta N^{-j}
  \qquad(1\le j\le k-1).
\end{equation}

[Lem 21 of arXiv:2609.03777, '2609.03777'] Let $k,k_1,k_2\in\ZZ_{\geq3}$ and $r\geq0$. There exists a real number $M\geq0$ such that for $\tau\in C$ and $N\in\ZZ_{>0}$, we have
\begin{align}
&\summ{\mu_1,\mu_2\in\latzero}\frac{\LL(|\mu_1|+|\mu_2|)^m}{|\mu_1|^{k_1}|\mu_2|^{k_2}}\left|G^{(N;\mu_1,\mu_2)}_{\{2\}^r}(\tau)-G^{(\infty;\mu_1,\mu_2)}_{\{2\}^r}(\tau)\right|\ll_{C,k_1,k_2,r,m}\frac{\LL(N)^M}{N^2},\\
&\summ{\mu\in\latzero}\frac{\LL(|\mu|)^m}{|\mu|^k}\left|G^{(N;\mu,0)}_{\{2\}^r}(\tau)-G^{(\infty;\mu,0)}_{\{2\}^r}(\tau)\right|\ll_{C,k,r,m}\frac{\LL(N)^M}{N^2}\,.
\end{align}

