body:
[Definition def:lerw of arXiv:2411.13505, 'Capacity of loop-erased random walk'] Let $\omega\in\Omega$ be a one-sided nearest-neighbour, transient path in $\mathbb{Z}^d$. The loop-erasure $\LE(\omega)$ of $\omega$ is the path obtained by erasing loops from $\omega$ chronologically. To be precise, $\LE(\omega)_i=\omega_{\ell_i}$, where the times $(\ell_i)_{i\geq0}$ are defined inductively as $\ell_0=0$ and $\ell_{i+1}=1+\max\{k\colon\omega_k=\omega_{\ell_i}\}$. When $S$ is a simple random walk on $\mathbb{Z}^d$ for $d\geq3$, we write
\begin{equation}
	\eta:=\LE(S[0,\infty)).
\end{equation}
This is well-defined, since simple random walk is almost surely transient for $d\geq3$.

[Definition of arXiv:2412.04589, 'Inverting the Markovian projection for pure jump processes'] We use the following notation.
	\begin{enumerate}[label=(\roman*), nosep]
		\item Let $a \in \mathbb{R}^n$. Define $S_k(a) \coloneqq \sum_{i=1}^k a_i$ for $0 \leq k \leq n$. In particular, $S_0(a) = 0$ by our convention.

		\item Let $\varnothing \neq A \subseteq \mathbb{R}$. The collection of all finite (including empty) sums of elements of $A$ is denoted by $\operatorname{FS}(A)$, namely
		\begin{equation*}
			\operatorname{FS}(A) \coloneqq \{S_k(a): a \in A^k,\, k \in \mathbb{N}\},
		\end{equation*}
		where $A^0 \coloneqq \{0\}$ by convention.
	\end{enumerate}

[Lemma driftcompar of arXiv:2605.10617, 'Logarithmic scaling of selective sweep curves:\\ from tents to houses'] For $p> 1/2$ and $k=1,2,\ldots$
\begin{equation}
 \mathbb{P}(W_p^*(1) = k+1 \mid W_p^*(0) =k)  >  \mathbb{P}(W_{1/2}^*(1) = k+1 \mid W_{1/2}^*(0) =k).
\end{equation}

