[Lemma 3step of arXiv:2608.09589, 'On stochastic stability of systems\\ driven by red noise\thanks{The authors gratefully ack'] For $\delta_2$ and $C_2$ as in Lemma (foster-lyapunov of the paper),
\begin{equation}
    \mathbb{E}[V(\bar{X}_{n+1},\bar{Y}_{n+1})\mid\mathcal{F}_n']\leq \delta_2 V(\bar{X}_{n},\bar{Y}_{n})+C_2.
    \end{equation}
    Furthermore, $C_{3}>0$ and $\delta_3$ as in Lemma (foster-lyapunov of the paper), on the event
$\{|X_n|+B|Y_n|+|\bar{X}_{n}|+B|\bar{Y}_{n}|>2C_3\}$
\begin{equation}

    \begin{aligned}
      &\mathbb{E}_n[V(X_{n+1},Y_{n+1})+V(\bar{X}_{n+1},\bar{Y}_{n+1})\mid\mathcal{F}_{n}']\\
      \leq~&\delta_3 [V(X_{n},Y_{n}) +V(\bar{X}_{n},\bar{Y}_{n})].
    \end{aligned}    
\end{equation}

