body:
[Lemma 34 (Multiplication between the $n$th and first chaos) of arXiv:2605.14630, '2605.14630'] Assume $f\in\H^{\otimes n}$ and $g\in\H$. Then 
\begin{equation}
 \hat I_n(f)\hat I_1(g) 
 = \hat I_{n+1}(f\otimes g) + \hat I_{n-1}(f\star_1g)\;,
\end{equation} 
where $\star_1$ denotes the \emph{contraction operation} 
\begin{equation}

 (f\star_1g)(i_1,\dots,i_{n-1}) 
 = \sum_{\Sigma\in\frakS(1,n)}
 \sum_{j=1}^N f(\Sigma(j,i_1,\dots,i_{n-1}))g(j)\;. 
\end{equation}

