[Corollary 53 of arXiv:2607.21374, 'Local structure at the maximum and sharp persistence asymptotics of rough fractional Brown'] Put \(\theta:=1-H\).  Then
\begin{equation}
  z(u)=\EE_{Q^1}e^{-u^HV^1},

\end{equation}
and, on \((0,\infty)\),
\begin{equation}
  \pi_H(\mathrm du)=c_H^{\mathrm{mix}}z(u)u^{\theta-1}\,\mathrm du,
  \qquad
  (c_H^{\mathrm{mix}})^{-1}
  =\int_0^\infty z(u)u^{\theta-1}\,\mathrm du.

\end{equation}
Moreover, for every \(c>0\),
\begin{equation}
  \frac{\mathcal Z(ca)}{\mathcal Z(a)}
  \longrightarrow c^{-\theta}.

\end{equation}

[Proposition 52 of arXiv:2608.29585, '2608.29585'] For every zero-framed knot $K$ and every $n\ge2$,
\begin{equation}
 H_1^{(n)}(K;q)=[n-1]_qF_K(q^n,q).
\end{equation}

[Lemma lem:2nd-pNC of arXiv:2605.01444, 'From second moments to pairwise negative correlation: \\applications to minimal and unifor'] Suppose $G=(V,E)$ is a finite, connected graph. Let ${\ensuremath{\mathscr T}} (G)$ be the set of spanning trees of $G$ and let ${\ensuremath{\mathbf P}} $ be an $\mathrm{Aut}(G)$-invariant probability measure supported on ${\ensuremath{\mathscr T}} (G)$ (${\ensuremath{\mathbf E}} $ denotes the corresponding expectation); examples include the UST measure ${\ensuremath{\mathbb P}} _\mathrm{UST}$ and the MST measure ${\ensuremath{\mathbb P}} _\mathrm{MST}$. For $e,f\in E$, denote by $e\sim f$ if $e$ and $f$ are adjacent edges in $G$ (i.e., they share a common endpoint), and by $e\not\sim f$ if they are non-adjacent. Write $n=|V|$. For $x\in V$ and $\omega\in\{0,1\}^E$, let $\deg(x;\omega)$ denote the degree of $x$ in the subgraph $\big(V,\eta(\omega)\big)$. Then we have the equalities
	\begin{equation}
	\sum_{e\sim f}{\ensuremath{\mathbf P}} \big[\omega(e)=\omega(f)=1\big]=\sum_{x\in V}{\ensuremath{\mathbf E}} \big[ \deg(x;\omega)^2 \big]-2(n-1)\,,
	\end{equation}
	where the sum on the left-hand side runs over all ordered pairs of distinct adjacent edges $e,f$; and
	\begin{equation}
	\sum_{e\not\sim f}{\ensuremath{\mathbf P}} \big[\omega(e)=\omega(f)=1\big]=n(n-1)-\sum_{x\in V}{\ensuremath{\mathbf E}} \big[ \deg(x;\omega)^2 \big]\,,
	\end{equation}
	where the sum on the left-hand side runs over all ordered non-adjacent pairs of edges.

[Proposition 18 of arXiv:2604.01852, 'The on/off Brownian snake'] In the setting of Corollary \ref{corollary range sbm in range oosbm}, we have, for each $\delta>0$, $\mathbb{P}_{(\mu_{\rm d}, \mu_{\rm a})}$-a.s. that
    \begin{equation*}
        \overline{\bigcup_{s \geq \delta} \text{supp}(\mathcal{Y}_s)} \subseteq \mathcal{R}(\mathcal{X}) \cup \text{supp}(\mu_{\rm d}) \cup \text{supp}(\mu_{\rm a}).
    \end{equation*}
    and therefore we have $\mathbb{P}_{(\mu_{\rm d}, \mu_{\rm a})}$-a.s.
    \begin{equation*}
        \mathcal{R}(\mathcal{Y}^{(\rm d)}) \cup \mathcal{R}(\mathcal{Y}^{(\rm a)}) = \mathcal{R}(\mathcal{Y}) \subseteq \mathcal{R}(\mathcal{X}) \cup \text{supp}(\mu_{\rm d}) \cup \text{supp}(\mu_{\rm a}).
    \end{equation*}
    \begin{proof}
        Consider the representation of $\overline{\bigcup_{s \geq \delta} \text{supp}(\mathcal{Y}_s)}$ given in Lemma \ref{lemma support sbm interval}, and let $i \in I$, $r \in [0,\sigma(f^i)]$, $s > 0$. We have that there exists $q \in \mathbb{Q}$ such that $H^i_r(s)>q>0$. Therefore, as can be seen from the proof of Corollary \ref{corollary range sbm in range oosbm}, we have that $\hat{w}^i_r \in \overline{\bigcup_{y \geq q} \text{supp}(\mathcal{X}_y)}$. We can repeat the process for a countable dense set of points $\hat{w}^i_r$ in $\overline{\bigcup_{s \geq \delta} \text{supp}(\mathcal{Y}_s)}$. Then, by taking the countable union over $q$ for $q \in \mathbb{Q}$ we can conclude that
        \begin{equation*}
            \overline{\bigcup_{s \geq \delta} \text{supp}(\mathcal{Y}_s)} \subseteq \overline{\mathcal{R}(\mathcal{X})} \hspace{0.5cm} \mathbb{P}_{(\mu_{\rm d}, \mu_{\rm a})}-\text{a.s.}
        \end{equation*}
        Therefore, taking a countable union over $\delta$ for $\delta \in \mathbb{Q}$ gives us that 
        \begin{equation*}
            \mathcal{R}(\mathcal{Y}) = \bigcup_{\delta >0}  \overline{\bigcup_{s \geq \delta} \text{supp}(\mathcal{Y}_s)}  = \bigcup_{\delta >0, \delta \in \mathbb{Q}} \overline{\bigcup_{s \geq \delta} \text{supp}(\mathcal{Y}_s)} \subseteq  \overline{\mathcal{R}(\mathcal{X})}.
        \end{equation*}
        The result then follows as $\overline{\mathcal{R}(\mathcal{X})} \subseteq \mathcal{R}(\mathcal{X}) \cup \text{supp}(\mu_{\rm d}) \cup \text{supp}(\mu_{\rm a})$. To see this first note that for each $i \in I$ the set $\{\hat{w}^i_t, t \in [0,\sigma(f^i)]\}$ is a closed set. However, as only finitely many excursions $f^i$ exceed height $y$ for any $y>0$ we have that any limit point outside of $\mathcal{R}(\mathcal{X})$ must be a limit point of the points $\{b_i, i \in I\}$ and therefore must be in the support of $\mu_{\rm d}$ or of $\mu_{\rm a}$ (this is noted in the remark after \cite[Corollary IV.9]{le1999spatial} and it is observation that motivates for their definition for $\mathcal{R}$ that we are also using here in this paper).
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:gmc-cm-shift of arXiv:2608.02459, 'Response Calculus for Spectral Simplicity\\ and Joint Eigenvalue Densities'] For every $g\inH_{\mathrm{reg}}$,
\begin{equation}
 M_{x+g}=e^{\gamma g}M_x,
 \qquad x,x+g\in\Omega_{\rm GMC}.
\end{equation}
In particular, for each fixed $g\inH_{\mathrm{reg}}$,
\begin{equation}
        M_{h+g}=e^{\gamma g}M_h
        \qquad\text{almost surely}.
\end{equation}

[Lemma 14 of arXiv:2605.15931, '2605.15931'] We have
		$$
		n\tilde{\tau}^n(X)\,{\stackrel{\textnormal{w}}{\to}}\,\tau^1(\sigma(x)W):=\inf\{t:\|\sigma(x)W_t\|=1\}
		$$
		{as $n\to \infty$.}

