[Proposition prop:sharp-v-estimate of arXiv:2608.30904, 'Entire monotone solutions of the anisotropic Allen--Cahn equation in dimension 5'] There exist $\beta\in(0,1)$ and $C<\infty$ such that
\begin{equation}
|v_{\varepsilon,f}(x)|
+\varepsilon|Dv_{\varepsilon,f}(x)|
\le
C\varepsilon^2\rho(x)^{-2}
\qquad (x\in\mathbb R^4).
\end{equation}
For every $x\in\mathbb R^4$,
\begin{equation}
\bigl\|
v_{\varepsilon,f}(x+\varepsilon\,\cdot)
\bigr\|_{C^{1,\beta}(B_{1/2})}
\le
C\varepsilon^2\rho(x)^{-2}.
\end{equation}
For $\varepsilon$ sufficiently small,
\begin{equation}
\|v_{\varepsilon,f}\|_{L^\infty(\mathbb R^4)}
\le C\varepsilon^2<\tau_*,
\end{equation}
and
\[
N_{\varepsilon,\tau_*}(U_{\varepsilon,f}+v_{\varepsilon,f})
=
N_\varepsilon(U_{\varepsilon,f}+v_{\varepsilon,f}).
\]

[Theorem 18 of arXiv:2608.24675, 'Towards Liouville Quantum Gravity on fractals'] Let $|\gamma|<\sqrt{d_H/C_0}$ and let $\nu^\gamma$ be the LQG measure on $K$. For any $i=1,2,3$,
    \begin{equation*}
        \nu^\gamma\stackrel{d}{=}(\sigma_i)_\#\nu^\gamma.
    \end{equation*}

[Corollary cor.S_max of arXiv:2411.04778, 'Coupling between Brownian motion and random walks on the infinite percolation cluster'] There exists $C:=C(d,\mathfrak{p})>0$, such that for almost every $\omega\in\Omega$ and every $y\in\mathscr{C}_\infty$, for all
		$T \geqslant \mathcal{R}(y)^2$, we have
		\begin{align}
			\sup_{t\in[0,T]}\vert S_t-y\vert \leqslant \mathcal{O}^\omega_1(C \sqrt{T}),
		\end{align}
		where $\mathcal{O}^\omega_1(\cdot)$ is associated with $P^\omega_y$.

