[Lemma 54 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Assume the notation in Lemma \ref{Lem.PowerSeriesSG}. There exist constants $\delta_2 \in (0,\delta_0]$ and $\epsilon_2 > 0$, depending on $q, \kappa, c$, such that for $r \in [0, \delta_2]$
\begin{equation}
\Real \left [\GFt(z) - \GFt(c) \right] \geq \epsilon_2 \cdot r^2, \mbox{ if } z = c + r e^{\pm \im \pi/2}.
\end{equation}

[Proposition 25 of arXiv:2608.30875, 'A Decomposition Theorem for Topological Semi-small Maps'] Let $f : X \longrightarrow Y$ be an almost covering such that $X$ and the fibered set $R$ are closed topological manifolds, and $Y$ is a closed topological $n$-pseudomanifold. Assume that the restriction $f|_{f^{-1}(R)} : f^{-1}(R) \longrightarrow R$ is a fiber bundle with fiber $F$, a closed orientable topological manifold, and that $\operatorname{codim}_{X}(f^{-1}(R)) \geq 2$. Let $\overline{p} \in \{\overline{n}, \overline{m} \}$ be a perversity. Moreover,
      	\begin{enumerate}
      		\item suppose that the normal bundle of $B:=f^{-1}(R)$ exists and is orientable, and that for each $r \in R$ there is a trivializing neighborhood $U$ of $r$ such that the connecting homomorphism in the Gysin sequence of the normal bundle of $B$ restricted to $f^{-1}(U)$ vanishes in degree $\operatorname{codim}_{X}(B)-1$.
      		\end{enumerate}
      		Let $R(f\vert_{X \setminus B})_{\ast}\underline{\mathbb{Q}}_{X \setminus B} \simeq \underline{\mathbb{Q}}_{Y \setminus R} \oplus \mathcal{L}$, where $\mathcal{L}$ is the local system on $Y \setminus R$ induced by the covering map $f\vert_{X \setminus B}$. If $\overline{p}(\operatorname{codim}_{Y}(R))+1 = \operatorname{codim}_{X}(B)$ and $\operatorname{codim}_{Y}(R)$ is even, then
      	\begin{align}
      		Rf_{\ast}\underline{\mathbb{Q}}_{X}[n] \simeq h_{\ast} \big((R^{0}f\vert_{B})_{\ast} \underline{\mathbb{Q}}_{B}[\dim(B)]\big) \oplus IC^{\overline{p}}_{Y} (\underline{\mathbb{Q}}_{Y \setminus R} \oplus \mathcal{L}),
      	\end{align}
      	where $h: R\hookrightarrow Y$ is the inclusion, and $IC^{\overline{p}}_{Y}$ is Deligne's sheaf complex with respect to the stratification $Y \supset R$.

