[Proposition 22 of arXiv:2608.19065, 'Boundedly exchangeable graphs'] For any $B \in \widehat{\Bcal}(S)$ with $\pbb(\nu(B) = 0) < 1$, let $W_B$ and $W'_B$ be two local graphons for $\xi$ on $B$. Then there exist $\lambda\vert_{[0,1]}$-preserving transformations $T, T' : [0,1] \to [0,1]$ such that
    \begin{equation} 
        W_B \circ (T \otimes T) = W'_B \circ (T' \otimes T') \quad \lambda^{\otimes 2}\text{-a.e.\ }
    \end{equation}

[Proposition 59 of arXiv:2607.18104, '2607.18104'] Let $C>0$, $\theta \in \R$, $N\in \N$ and $\mathfrak{a}\in (0,1)$. Let $\rho \in [\mathfrak{a},1-\mathfrak{a}]$ and consider ASEPs $(\eta_t)_{t \geq 0}$ and $(\bar{\eta}^{\per}_t)_{t \geq 0}$ evolving according to the extended $(\rho,\theta,1,N)$-reference frame basic coupling. Consider (random) data $\eta^{N} \in \{0,1\}^{N}$ with 
\begin{equation}
 \textup{Ber}_{\rho+CN^{-1/2}}^{N} \succeq \P( \eta^{N} \in \, \cdot \, ) \succeq  \textup{Ber}_{\rho-CN^{-1/2}}^{N} ,  
\end{equation} where $\textup{Ber}_{\rho}^{N}$ denotes the Bernoulli-$\rho$-product measure on $\{0,1\}^{N}$. Define initial data $\eta_0\in \{0,1\}^{\mathbb{Z}}$
\begin{equation}
\eta_0(x):=\eta^N(x- \lfloor \theta N \rfloor )
\end{equation} for all $x \in \lbr \theta N+1, (1+\theta)N \rbr$. For all
$x \notin \lbr \theta N+1, (1+\theta)N\rbr$, let $\eta_0(x)$ be occupied independently with probability $\rho$. For initial data $\tilde{\eta}_0$, assume that \eqref{eq:AgreeLocally} holds, but extend the configuration outside of $\lbr \theta N+1, (1+\theta)N \rbr$ periodically. Then there exist some $\tilde{c},\tilde{C}>0$, depending only on $\mathfrak{a}$, $q$ and $C$, and not $\theta,N,\rho$, such that the extended colored ASEP  $(\xi_t)_{t \geq 0}$ from Definition~\ref{def:ExtendedCouplingASEP} and  
\begin{equation*}
    \mathcal{A}^{\theta}_{\delta,N} := \left\{ \xi_t(x) \in \{\zero,\one \}  \, \forall (x,t) \in \mathcal{I}^{\rho}_{\delta,N}\Big(\frac{1}{8}+\theta,\frac{7}{8}+\theta\Big)  \right\}
\end{equation*} satisfy for all $\delta>0$ 
\begin{equation}
\liminf_{N \rightarrow \infty}\Pex\big( \mathcal{A}^{\theta}_{\delta,N} \big)   \geq 1- \tilde{C} \exp(-\tilde{c} \delta^{-1} ) . 
\end{equation} 
Furthermore,  \eqref{eq:GoodControlASEP} continues to hold when $(\xi_t)_{t\geq 0}$ is defined the as a full-space extended colored ASEP with reference frame $\mathcal{I}^{\rho}_{N}\big(\theta,1+\theta\big)$ for two full-space ASEPs, i.e., we obtain $(\xi_t)_{t\geq 0}$ as in Definition~\ref{def:ExtendedCouplingASEP} with respect to two ASEPs on the integers, which evolve under the (extended) basic coupling along edges in $\mathcal{I}^{\rho}_{N}\big(\theta,1+\theta\big)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop long-term-est1 of arXiv:2602.17579, 'Non-equilibrium functional inequalities for finite Markov chains'] Let $M$ be an irreducible generator. 
    Then, for any $\delta \in (0,1)$ there exists an $\alpha_\ast>0$ such that for all initial data $\zeta_0, \mu_0 \in \mathcal{P}(\ensuremath{\mathbb{Z}})$ and corresponding solutions $\zeta_t, \mu_t$ of the forward Kolmogorov equation (equation eq:full-forw-K of the paper) holds 
    \begin{equation}
       0< \alpha_\ast \leq \alpha_{\gLSI}(\zeta_t) \leq 2\alpha_{\gPI} (\zeta_t)
    \end{equation}
    for all $t \geq \delta$ and 
    \begin{equation}
        \operatorname{var}_{\zeta_t} \biggl( \frac{\mu_t}{\zeta_t}\biggr)\leq \operatorname{var}_{\zeta_0}\biggl( \frac{\mu_0}{\zeta_0}\biggr) \min\left(1,e^{-\alpha_\ast (t - \delta)}\right),
        \ \  \mathscr{H}_{\zeta_t} \biggl( \frac{\mu_t}{\zeta_t}\biggr)\leq \mathscr{H}_{\zeta_0}\biggl( \frac{\mu_0}{\zeta_0}\biggr) \min\left(1,e^{-\alpha_\ast (t - \delta)}\right)
    \end{equation}
    for all $t \geq 0$.

