body:
[Definition def:SUSY1eps of arXiv:2604.20660, 'The Legendre structure of the TAP complexity\\ for the Ising spin glass'] Let $\zeta\in\mathrm{Prefix}_2(u,q)$ for some $u,q\in(0,1)$.
		We define $\mathrm{SUSY}_1(\zeta,\varepsilon)$ as the set of $\mathbf{m}\in[-1+\delta_\varepsilon,1-\delta_\varepsilon]^N$ such that
		\begin{equation*}
			\left|\frac{1}{N}\|\mathbf{m}\|^2-q\right|\leq\varepsilon,
			\qquad
			\left|\frac{1}{N}\langle\partial_m h_\zeta(q,\mathbf{m}),\mathbf{m}\rangle
			-\xi'(q)\int_0^1\zeta([0,t])\,\mathrm{d} t\right|\leq \varepsilon,
		\end{equation*}
		and
		\begin{equation*}
			\mathrm{dist}\!\bigl(\zeta_\mathbf{m},\,\zeta|_{(q,1]}+\zeta([0,q])\,\delta_q\bigr)\leq\varepsilon,
		\end{equation*}
		where we recall that $\mathrm{dist}$ is as in (equation def:dist of the paper).

[Lemma 16 of arXiv:2609.03084, 'Convergence rates to traveling waves for an FKPP model with nonlinear advection'] For $x \geq 2t$, let
        \begin{equation}
            \phi(t, x) = \frac{K(x-2t)}{t^{3/2}}e^{-(x-2t)}e^{\frac{-(x-2t)^2}{4t}},
        \end{equation}
        where $K$ is a positive constant.
        Then there exists a $T > 0$ such that
        \begin{equation}
            \bar \phi(t, x) = \left(1- \frac{1}{t^{1/4}}\right) \phi(t, x) 
        \end{equation}
        is a nonnegative supersolution of \eqref{main_eq} for $t > T$.

[Definition D:main-nondegenerate-arc of arXiv:2607.15966, 'Canonical Mandelbrot Cascades on Curves Are Rajchman'] A map \(\gamma:[0,1]\to\mathbb{R}^2\) is a fixed nondegenerate \(C^2\) embedded arc if it is a \(C^2\) embedding and
\begin{equation}
\inf_{t\in[0,1]}|\gamma'(t)|>0,
\qquad
\inf_{t\in[0,1]}
|\det(\gamma'(t),\gamma''(t))|>0.
\end{equation}

[Dfn 4 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] Let $(X,d^X)$ be a metric space. For a function $f:X\to\R$, a non-empty subset
  $A\subseteq X$ and a real number $\kappa\in (0,1]$, we define $\|f\|_A,$ $\|f\|_{\Lip^{\kappa}(A)}\in [0,\infty],$ and $\|f\|_{\BL^{\kappa}(A)}\in [0,\infty]$ 
  as follows.
  \begin{equation*}
    \|f\|_A:=\sup_{a\in A}|f(a)|,\qquad \|f\|_{\Lip^{\kappa}(A)}:=\sup_{\substack{x,y\in A\\x\neq y}}\frac{|f(x)-f(y)|}{d^X(x,y)^{\kappa}},
  \end{equation*}
  and
  \begin{equation*}
    \|f\|_{\BL^{\kappa}(A)}:=\|f\|_A+\|f\|_{\Lip^{\kappa}(A)}.
  \end{equation*} 
  If $A$ is a singleton, we set $\|f\|_{\Lip^{\kappa}(A)}=0$. 
  The quantity $\|f\|_{\Lip^{\kappa}(A)}$ is the $\kappa$-H\"older constant of $f|_A$, 
  and we call $\|\cdot\|_{\BL^{\kappa}(A)}$ the $\BL^{\kappa}(A)$ norm 
  or simply the $\BL^{\kappa}$ norm if $A$ is clear from the context.
Also, we denote the set of functions with a finite $\BL^{\kappa}(A)$ norm by
$\BL^{\kappa}(A)$. Namely,
  \begin{equation*}
  \BL^{\kappa}(A):=\{f:X\to\R:\|f\|_{\BL^{\kappa}(A)}<\infty\}.
\end{equation*}

[Lem 20 of arXiv:2604.03777, 'Equilibrium fluctuations for a multi-species particle system with long jumps'] Let $\gamma >0$, $0 \leq s \leq t \leq T$, $n \in \mathbb{N}_+$ and $A_n$ be an arbitrary subset of $\mathbb{Z}^{2}$. Then
\begin{align*} 
	&	\mathbb{E}_{\nu_{\rho}} \Bigg[ \Bigg\{ \int_s^t \dd r \frac{ \Theta(n) K_n }{\sqrt{n}}    \sum_{(x,y) \in A_n} B_{r,v}^{H,n}(x,y) a(y-x)   \bar{\xi} _x^{\alpha}( \eta_r^n ) \bar{\xi} _y^{\beta}( \eta_r^n ) \Bigg\}^{2} \Bigg] \leq \widehat{C} (t-s)^{2} \frac{  \big[ \Theta(n) K_n \big]^{2}  }{ n^{4}  } \mathbbm{1}_{ \{ \gamma \geq 1 \} },
\end{align*}
where for every $z,w \in \mathbb{Z}^{2}$, $B_{r,v}^{H,n}(z,w):=[  H ( \tfrac{w - r v_n }{n}  ) - H ( \tfrac{z - r v_n }{n}  )  ] - [  H ( \tfrac{ \lfloor w - r v_n \rfloor }{n}  ) - H ( \tfrac{ \lfloor z - r v_n \rfloor }{n}  )  ]$. Furthermore, if $H \in C_c^2(\mathbb{R})$, the role of $\widehat{C}$ is fulfilled by some constant $C(H)$ satisfying \eqref{Cinvshift}.

