body:
[Theorem thm:multiclass-lb of arXiv:2608.20480, 'When Clean Data Hurts: Learning with Monotone \\ Corruptions Beyond Binary Classification'] There exist countable discrete spaces $\mathcal{X},\mathcal{Y}$ and a countable
    hypothesis class $\mathcal{H}\subseteq\mathcal{Y}^\mathcal{X}$ such that:
    \begin{enumerate}
        \item \textbf{Clean proper learning.}
        There is a deterministic proper learner $\mathcal{L}$ such that for every
        $(\varepsilon,\delta)\in(0,1)^2$, distribution $\mathcal{D}$ over $\mathcal{X}$, and
        target hypothesis $h^\star\in\mathcal{H}$, with probability at least
        $1-\delta$ over
        $C=\{(x_i,y_i)\}_{i\in[n]}$, where $x_1,\ldots,x_n$ are drawn
        i.i.d.\ from $\mathcal{D}$ and $y_i=h^\star(x_i)$ for every $i$, it holds
        that
        $\operatorname{err}_{\mathcal{D},h^\star}(\mathcal{L}(C))\le\varepsilon$ whenever
        \begin{align*}
            n
            \ge
            100\cdot
            \frac{
                1+\log(1/\varepsilon)+\log(1/\delta)
            }{\varepsilon}.
        \end{align*}

        \item \textbf{Every learner foiled by some monotone adversary.}
        For every learner $\mathcal{L}$, possibly improper and randomized, and
        every $n$, there are a distribution $\mathcal{D}$, a target hypothesis
        $h^\star\in\mathcal{H}$, and a monotone adversary $\mathcal{A}$ that uses $n$
        clean and $m=n$ adversarial samples such that
        \begin{align*}
            \mathbb{E}_{S\sim
                \mathtt{Adv}_{\mathcal{D},h^\star,\mathcal{A}}(n,m)}
            \left[
                \operatorname{err}_{\mathcal{D},h^\star}(\mathcal{L}(S))
            \right]
            \ge
            \frac14.
        \end{align*}
    \end{enumerate}
    Moreover, $d_{\mathrm{DS}}(\mathcal{H})=2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 4 of arXiv:2604.27485, 'On large deviation principles for general random processes \footnote{Research supported by'] In the general case, the l.d.p.\ always implies the l.l.d.p. Con\-versely, let the following condition be met: for any $N>0$ there exists a $v>0$ such that 
\begin{equation}

\limsup_{T\to\infty} \frac1T \ln \mathbf{P} (|z(T)|>v) \le -N.
\end{equation}
Then the  l.l.d.p.\ implies the l.d.p. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 10 of arXiv:2604.05910, '\textbf{Well-posedness and Hurst parameter estimation for fluid equations driven by fracti'] There exists a constant $C=C\left( t\right) $ independent of $n$ and $H$ such
that 
\begin{equation}
\mathbb{E}\left[ \left( \left( \frac{1}{n}\right) ^{1-2H}\sum_{j\in \mathcal{A}
_{t}^{n}}\left( W_{t_{j+1}}^{H}-W_{t_{j}}^{H}\right) ^{2}-t\right) ^{2}
\right] \leq \frac{C}{n^{4-4H}}.  
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition error4d of arXiv:2605.12777, 'Mesoscopic Rates of Convergence for Complex Wishart Matrices at the Leftmost Spectrum Edge'] Let $R'_{n-1,N}(s)$ and $R'_{n,N-1}(s)$ be the error terms given in (equation a4D of the paper), then
    \begin{equation*}
        N^{\frac{2}{3}}|R'_{n-1,N}(s)||Ai'(s)|,~N^{\frac{2}{3}}|R'_{n,N-1}(s)||Ai'(s)|\le C(s_0,\gamma)e^{-\frac{s}{2}}
    \end{equation*}
    for any $s\in\left[s_0,N^\frac{1}{6}\right]$ when $N$ is large.

