[Defn GibbsDefinition of arXiv:2605.06429, '\large \bf $\mathsf{GL}_N(\mathbb{C})$ BROWNIAN MOTION AND STOCHASTIC PDE ON ENTIRE FUNCTI'] Let $N \in \mathbb{N}\cup \{\infty\}$. We say that a line ensemble $\mathcal{L}\in \mathrm{C}(\llbracket 1, N \rrbracket)$ satisfies the Gibbs resampling property with respect to the law of the $\mathsf{A}$-bridge if for all $\llbracket \ell,\ell+k-1 \rrbracket \subset \llbracket 1, N \rrbracket$ with $\ell, k \ge 1$ and any $[a,b]\in \mathbb{R}_+$ we have
\begin{equation}
\mathsf{Law}\left(\mathcal{L}|_{\llbracket \ell,\ell+k-1 \rrbracket \times [a,b]}|\mathscr{F}_{\mathrm{ext}}\left(\llbracket \ell, \ell+k-1 \rrbracket \times (a,b) \right)\right)=\mathbf{P}_{\mathrm{avoid}}^{a,b;\mathbf{x},\mathbf{y};u,l},\ \ \textnormal{ almost surely,}
\end{equation}
where the external sigma-algebra $\mathscr{F}_{\mathrm{ext}}\left(\llbracket \ell, \ell+k-1 \rrbracket \times (a,b) \right)$ is defined as
\begin{equation}
\mathscr{F}_{\mathrm{ext}}\left(\llbracket \ell, \ell+k-1 \rrbracket \times (a,b) \right)= \sigma\left(\mathcal{L}_j(t);(j,t)\notin \llbracket \ell, \ell+k-1 \rrbracket\times (a,b)\right), 
\end{equation}
and the (random) boundary data $\mathbf{x},\mathbf{y},u,l$ given by,
\begin{align*}
\mathbf{x}=\left(\mathcal{L}_\ell(a),\mathcal{L}_{\ell+1}(a),\dots,\mathcal{L}_{k+\ell-1}(a)\right), \  \mathbf{y}=\left(\mathcal{L}_{\ell}(b),\mathcal{L}_{\ell+1}(b),\dots,\mathcal{L}_{k+\ell-1}(b)\right), \ u=\mathcal{L}_{\ell-1},  \ l=\mathcal{L}_{\ell+k},
\end{align*}
with the convention $\mathcal{L}_{0}\equiv \infty$, $\mathcal{L}_{N+1}\equiv -\infty$.

[Definition Plaquette variable of arXiv:2605.16162, 'Deconfinement For $\mathrm{SO}(3)$ Lattice Yang--Mills at Strong Coupling'] Given a lattice gauge configuration $Q : E_\Lambda^+ \ra G$ and an oriented plaquette $p = e_1 e_2 e_3 e_4$, we define the plaquette variable (abusing notation)
\begin{equs}
Q_p := Q_{e_1} Q_{e_2} Q_{e_3} Q_{e_4}.
\end{equs}

[Prop solntobicausalmongeegs of arXiv:2412.02948, 'Causal transport on path space'] Let $\sigma \in \mathscr{A}^{d,d}$, $b \in \mathscr{A}^{d,1}$ be such that the SDE \begin{equation}

    dX_t = b\del{t,X} dt + \sigma\del{t,X} dB_t, \; X_0 = 0,    
    \end{equation}
has a unique weak solution $\eta := \mu^{\sigma,b}_0$, where  $\sigma\del{t,\omega}$ is invertible for all $\del{t,\omega}$. 

 Let $\overline{\sigma} \in \mathscr{A}^{d,d}$ be such that $\overline{\sigma}(t,\omega)=\kappa(t)u(t,\omega)$ with $u(t,\omega)\in {\cal O}^d$ and assume the SDE 
  \begin{equation}

dY_t = \overline{b}\del{t} dt + \overline{\sigma}\del{t,Y} dB_t, \; Y_0 = 0,        
    \end{equation}

 has a unique, strong solution with law $\nu := \mu^{\overline{\sigma}, \overline{b}}_0$. Denote the corresponding  It\^o  map   by $F^{\overline{\sigma}, \overline{b}}_0 : \mathcal{W}^d \rightarrow \mathcal{W}^d$. 

Then an optimal transport from $\eta$ to $\nu$ for a cost of the form (equation eq.separablecost of the paper)  is given by the bicausal Monge map 
    \[
    \mathcal{W}^d \ni \omega \mapsto T\del{\omega} := F^{ \sqrt{\overline{\sigma} \overline{\sigma}^*},\overline{b}}_0\del{\int_0^\cdot Q_s \sigma^{-1}\del{s,X} dM^\eta\del{s} }

    \] 
    where $Q : \sbr{0,1} \times \mathcal{W}^d \rightarrow \mathcal{O}^d$ is a $\deln{\mathcal{H}^\eta_t}_{t \in \sbr{0,1}}$-progressively measurable process given by $Q_t\del{\omega} = Q\del{t,\omega} := V\del{t,\omega} U^*\del{t,\omega}$ for $U\del{t,\omega}, V\del{t,\omega} \in \mathcal{O}^d$ appearing in the SVD of matrix $\sigma\del{s,\omega} \sqrt{\overline{\sigma} \overline{\sigma}^*\del{s}}$. In particular, \begin{multline*}
    K\del{\eta,\nu} = M\del{\eta,\nu} = \mathbb{E}^{\eta}\del{h\del{\int_0^\cdot b\del{s,X} ds - \int_0^\cdot \overline{b}\del{s} ds}} + \\
    \mathbb{E}^{\eta} \del{g\del{\int_0^1 \Tr\del{ \sigma\del{s,X} \sigma^*\del{s,X} + \overline{\sigma} \overline{\sigma}^*\del{s}} ds - 2 \int_0^1 \Tr\del{\sigma\del{s,X} \sqrt{\overline{\sigma} \overline{\sigma}^*\del{s}} Q\del{s,X}} ds}}.
    \end{multline*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:CT-TASEP-seed-linear of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] The seed functions $\psi_{t,r,n}$ and $\phi_{t,r,n}$
defined in \S(sec:CT-TASEP-kernel-reform of the paper) satisfy the
dual linear problem
(equation eq:sc-dual-linear-1 of the paper)--(equation eq:sc-dual-linear-j of the paper)
and its adjoint
(equation eq:sc-dual-adjoint-1 of the paper)--(equation eq:sc-dual-adjoint-j of the paper)
with shifts
$T = e^{\partial_r}$, $\partial_1 = \partial_t$,
$S_2 = e^{\partial_n}$ and constant scalar edge weights
$(c_1, \lambda_1) = (-\tfrac{1}{2}, -\tfrac{1}{2})$,
$(c_2, \lambda_2) = (2, 1)$.
Explicitly:
\begin{align}
\partial_t \psi_{t,r+1,n}
&= -\tfrac{1}{2}\bigl(\psi_{t,r+1,n}
   - \psi_{t,r,n}\bigr),
 \\
\psi_{t,r,n+1}
&= 2\psi_{t,r+1,n} - \psi_{t,r,n},

\end{align}
and
\begin{align}
\partial_t \phi_{t,r+1,n}
&= -\tfrac{1}{2}\bigl(\phi_{t,r+2,n}
   - \phi_{t,r+1,n}\bigr),
 \\
\phi_{t,r+1,n}
&= 2\phi_{t,r,n+1} - \phi_{t,r+1,n+1}.

\end{align}

