\begin{multline*}
  {\mathfrak D}_\alpha:=\Big\{ {\vv s} \in \CC^2, {\vv t} \in \CC^2 \; :\;  s_i - t_j \not\in [0,\infty), \; \re(s_i)<\alpha, \;\re(t_j)>-\alpha
