[Prop 19 of arXiv:2507.08909, 'Annealed almost periodic entropy'] Consider a $(k+\ell+m)$-by-$(k+\ell+m)$ self-adjoint matrix
	\begin{equation}
		Q := \left[\begin{array}{ccc} Q_{11} & Q_{12} & R\\ Q_{12}^\ast & Q_{22} & Q_{23} \\ R^\ast & Q_{23}^\ast & Q_{33}\end{array}\right].
	\end{equation}
	Assume that the submatrices
	\[Q_{(1\cup 2)} := \left[\begin{array}{cc} Q_{11} & Q_{12}\\ Q_{12}^\ast & Q_{22}\end{array}\right] \qquad \hbox{and} \qquad Q_{(2\cup 3)} := \left[\begin{array}{cc} Q_{22} & Q_{23}\\ Q_{23}^\ast & Q_{33}\end{array}\right]\]
	are both positive semidefinite.  Then $Q$ is positive semidefinite if and only if it has the form
	\begin{equation}
		\left[\begin{array}{ccc} Q_{12}Q^\dag_{22} Q_{12}^\ast & Q_{12} & Q_{12} Q^\dag_{22} Q_{23}\\ Q_{12}^\ast & Q_{22} & Q_{23} \\ Q_{23}^\ast Q^\dag_{22}Q_{12}^\ast  & Q_{23}^\ast & Q_{23}^\ast Q^\dag_{22} Q_{23}\end{array}\right] + \left[\begin{array}{ccc} S_{11} & 0 & S_{11}^{1/2}CS_{33}^{1/2}\\ 0 & 0 & 0 \\ S_{33}^{1/2}C^\ast S_{11}^{1/2} & 0 & S_{33}\end{array}\right],
	\end{equation}
	where
	\begin{equation}
		S_{11} := Q_{11} - Q_{12}Q^\dag_{22}Q_{12}^\ast \quad \hbox{and} \quad S_{33} := Q_{33} - Q_{23}^\ast Q^\dag_{22}Q_{23}
	\end{equation}
	are generalized Schur complements and $C \in \Xi(m,k)$.

	If $Q_{(1\cup 2)}$ and $Q_{(2\cup 3)}$ are both nonsingular, then the contraction $C$ promised here is unique, and the whole of $Q$ is nonsingular if and only if $C$ is a strict contraction.

[Lemma 39 (Projection and gate decomposition) of arXiv:2607.26377, '\textbf{Entire Logarithmic Signatures\\ of Bounded-Variation Paths in Finite Dimensions}'] Let $(\mathscr{T},d)$ be a complete metric tree and let $C\subset\mathscr{T}$ be nonempty, closed, and convex. Every $x\in\mathscr{T}$ has a unique metric projection $p\in C$. Moreover, $p\in[x,c]$ for every $c\in C$. If $p$ and $q$ are the projections of $x$ and $y$, respectively, and $p\neq q$, then
\begin{equation}
[x,y]=[x,p]\cup[p,q]\cup[q,y],
\end{equation}
where consecutive pieces meet only at their common endpoint and $[x,p]\cap[q,y]=\varnothing$.

Let T be a consistent theory in a countable language \mathcal{L}, and for each n, let \Sigma_n(x) be a non-principal type. Then T has a countable model \mathcal{M} that omits every \Sigma_n.
Countable language \mathcal{L}
Non-principal types \Sigma_n

[Lemma 22 (Shape-operator characterization) of arXiv:2608.29406, 'Partially Totally Real Submanifolds of Sasakian Manifolds'] The normal morphism \(F\) is parallel if and only if
\begin{equation}
 A_{fV}X=P A_VX
\end{equation}
for every tangent vector field \(X\) and normal vector field \(V\).
Moreover, whenever \(F\) is parallel,
\begin{equation}
 PA_V=-A_VP,
 \qquad
 A_{fV}=-A_VP .
\end{equation}

[Theorem 3 of arXiv:2606.06489, 'The Missing Central Limit Theorems for Local Functionals of Berry's Random Wave Model'] As $R\to\infty$, the \emph{defect} or \emph{signed volume} of Berry's model,
    \begin{equation*}
    D(R)=|\set{x\in B_R: u_1(x)>0}|-|\set{x\in B_R: u_1(x)<0}|,
    \quad R>0,    
    \end{equation*}
    satisfies $\var D(R)\sim C R^d$, $C>0$, and $\frac{D(R)}{\sqrt{\var D(R)}}$ converges in 1-Wasserstein distance to a standard Gaussian random variable as $\R\to\infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 20 of arXiv:2609.01362, '{Double cluster swapping for spin models: \\Pfaffian relations and sharpness}'] Let $S \subset V$ be such that $|S| \leq 3$. Suppose any vertex $v \in S \setminus \Vis$ is only adjacent to vertices which are separated from $W$ by $S$. 
	Then, there is a classical spin model $ \widetilde{\vp}$ on the reduced graph $ \widetilde{G} = ( \widetilde{V}, \widetilde{E}) := R(G,S)$ and scaling factors $r_u > 0$ for each $u \in S$ such that
	\begin{enumerate}[(i)]
		\item the reference measure on all spins in $S \setminus \Vis$ becomes the Ising measure $\l\propto \delta_{1} + \delta_{-1}$,
			and remains the same on all other spins in $ \widetilde{V}$.
		\item  the boundary correlation functions satisfy
		\begin{equation}
			\langle \vp({A}) \rangle = \Big( \prod_{u \in A}  r_u \Big) \langle \widetilde{\vp}(A) \rangle_{ \widetilde{G}}
            \end{equation}
            for all $A \subset W$. 
	\end{enumerate}

[Lemma 25 (Composition and differences) of arXiv:2609.01589, 'Uniform stability of expanding simple waves for Euler--Poisson--Boltzmann: a singular comp'] Let $I\Subset\R$ be compact and $F\in C^{m+1}(I)$.
If $f$ takes values in $I$, $f\in L^\infty$, and
$\nabla f\in H^{m-1}$, then
\begin{equation}
 \norm{\nabla F(f)}_{H^{m-1}}
 \le C_{F,I,m}\left(1+\norm{\nabla f}_{H^{m-1}}^m\right).

\end{equation}
If $f_1,f_2$ take values in $I$, $f_1-f_2\in H^m$, and their relative
coefficient norms are bounded by $R$, then
\begin{equation}
 \norm{F(f_1)-F(f_2)}_{H^m}
 \le C_{F,I,m,R}\norm{f_1-f_2}_{H^m}.

\end{equation}
For a function $f\in H^m$ and a normalization $F(0)=0$, this also gives
\begin{equation}
 \norm{F(f)}_{H^m}
 \le C_{F,\norm f_\infty,m}
 (1+\norm f_{H^m}^{m-1})\norm f_{H^m}.

\end{equation}

