[Theorem thm-SLLN-det of arXiv:2411.14876, 'Limit theorems for stochastic exponentials of matrix-valued L\'evy processes \\'] Let $L=(L_t)_{t\geq 0}$ be a Lévy process in $\mathbb{R}^{d\times d}$ fulfilling (equation eq-nonsingular of the paper) and let $D=(D_t)_{t\geq 0}$ be the determinant process of its stochastic exponential defined in (equation eq-detprocess of the paper). 
	\begin{enumerate}
		\item If (equation eq-hatDmeancond of the paper) holds, then a.s.
		\begin{align*} \lefteqn{\lim_{t\to \infty} t^{-1} \log |D_t|}\\ &= \operatorname{tr}(\gamma_L)  - \frac12 \sum_{m,n=1}^d \sigma_{(m,n),(n,m)}  + \int_S \Big( \log|\det(\Id+x)|  -\operatorname{tr}(x)   \mathds{1}_{\{\|\operatorname{vec} x \|\leq 1\}}   \Big)\nu_L(dx).\end{align*} 
		\item If (equation eq-hatDmeancond of the paper) fails, then a.s.
		$$\limsup_{t\to \infty} t^{-1} |\log |D_t||=\infty.$$
	\end{enumerate}

[Defination 1 of arXiv:2511.10814, '\Large \bf \boldmath\ \\ Convergence of the extended Kalman filter with small and state-de'] Let $(M(t))_{t \geq 0}$  and  $(\covm(t))_{t \geq 0}$ be  two  observable  processes  with  values respectively   in  $\mathbb{R}^n$ 
		and the set of positive-definite symmetric   matrices of order $n$. A process which  at  any  time  $t$ is Gaussian   with mean $M(t)$  and  covariance matrix $ \covm(t) =\varepsilon \qcovm (t)$ will  be  said  to  be an  extended  Kalman  filter  for \eqref{FiltPb} if   $M(t)$  is  solution of 	
		\begin{equation}
			M(t) = M(0) + \int_{0}^{t} f(s,M(s) )ds +
			\int_{0}^{t}G(s)\big[d\obs(s)-h(s,M(s))ds\big], 
		\end{equation}
		where 
		\begin{equation} G(t)=\big[ \coDifS \coDifO^\top (t,M(t)) +\qcovm(t)  \nabla_yh^\top(t,M(t))\big]\big( \coDifO\coDifO^\top\big)^{-1} (t,M(t)), 
			\hspace*{1.5em}	
		\end{equation}	
		\noindent and  $\qcovm(t)$ is solution  of the  Riccati  equation		
		\begin{align} 
			\begin{split}		
				\dot{\qcovm}(t)= & - \qcovm(t)[ \nabla_y h^\top (\coDifO\coDifO^\top)^{-1}  \nabla_yh](t,M(t)) \qcovm(t)
				\\	&
				+ \big[ \nabla_y f - \coDifS \coDifO^\top(\coDifO\coDifO^\top)^{-1} \nabla_y h\big](t,M(t))\qcovm(t) \\
				&+ \qcovm(t)\big[ \nabla_y f - \coDifS \coDifO^\top(\coDifO\coDifO^\top)^{-1}  \nabla_y h\big]^{\top}(t,M(t))  
				+\af(t,M(t)), 			
			\end{split}	 
		\end{align}
		where  the absolute term $\af$ is given by 
		\begin{equation}
			\af(t,M(t))=\sigma\sigma^\top(t,M(t)) + \coDifS ( I-\coDifO^\top(\coDifO\coDifO^\top)^{-1}\coDifO)\coDifS^\top (t,M(t)).
			\hspace*{5em}		
		\end{equation}

