[Corollary 37 of arXiv:2604.26549, 'Existence and uniqueness results of a stochastic nonlinear heat equation with a constraint'] Let $\wtilde{M}$ be the process defined in \eqref{eqn-martingale-1}. Then, for $t\in[0, T]$, the quadratic variation of $\wtilde{M}$ is given by
				\begin{align}
					\llbracket \wtilde{M}\rrbracket_t=\int_0^t\sum_{i=1}^M\|\Nn_i(u(s))\|_{L^2(\bO)}^2ds.
				\end{align}

[Corollary 26 of arXiv:2604.01852, 'The on/off Brownian snake'] Let $\mu_{\rm d}$, $\mu_{\rm a} \in \mathcal{M}_F(\mathbb{R}^d)$ and let $(\mathcal{Y}_t^{(\rm d)}, \mathcal{Y}_t^{(\rm a)})_{t \geq 0}$ be an $\text{ooSBM}(4, c, \Tilde{c})$ started from $(\mu_{\rm d}, \mu_{\rm a})$. Then $\mathbb{P}_{(\mu_{\rm d}, \mu_{\rm a})}$-a.s. there exist $(N_k, k \in \mathbb{N})$ finite constants such that for $k \in \mathbb{N}$ and for $s$, $t \in \mathbb{R}$ with $k \leq s < t < k+1$ we have
    \begin{equation*}
        \overline{\bigcup_{s \leq u \leq t} \text{supp}(\mathcal{Y}_u^{(\rm d)}) \cup \text{supp}(\mathcal{Y}_u^{(\rm a)})} \subseteq \text{supp}(\mathcal{Y}_s^{(\rm d)}) \cup \text{supp}(\mathcal{Y}_s^{(\rm a)})^{N_kH(t-s)}.
    \end{equation*}
    \begin{proof}
        Lemma \ref{lemma oosbm finite propagation}, along with the Markov property for ooSBM, establishes the claim for $k=0$. The general result can then be derived from the $k=0$ case and then again by the Markov property of ooSBM.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 17 of arXiv:2609.01436, '2609.01436'] Uniformly in $k\geq0$,
\begin{equation}
 m_k\asymp1+k,
 \qquad
 \gamma_k\asymp
 b_0\frac{\varepsilon_k^{\eta-1}}{1+k},
 \qquad
 Q_k\asymp
 \frac{\varepsilon_k^{3/2}}{\sqrt{1+k}}.
\end{equation}
Moreover, there exists an integer $k_0=k_0(N)\geq0$ such that
\begin{equation}
 (e^2-1)^2Ne^{-2m_k}\leq\frac{Q_k}{2}
\end{equation}
for every $k\geq k_0$.

[Defn 6 of arXiv:2608.03956, 'From Triangular Array Progression\\ to Near-Log-Concave State Transitions'] Let $\eta = [\eta_1,\ldots,\eta_{n+1}]$ for $n\geq 2$ be a sequence, where $\min(\eta) > 0$. Define 
\begin{align}
\Theta_{i}(\eta) = \max\left( \log(\eta_{i-1}) + \log(\eta_{i+1}) - 2\log(\eta_i) \,,\, 0 \right), 
\end{align}
for every $i\in\{2,\ldots,n\}$. Then,
\begin{align}
\Theta(\eta) = \sum_{i=2}^{n} \Theta_{i}(\eta), 
\end{align}
is called the \emph{log-concavity deviation} of $\eta$ under logarithmic scaling.

[Lemma 24 (Integration by parts) of arXiv:2605.14630, '2605.14630'] Assume $X \sim \cN(0,C)$. 
For any $i\in\intset{1,N}$, the equality 
\begin{equation}

 \bigexpec{X_i f(X)} = \sum_{j=1}^N C_{ij} \bigexpec{\partial_j f(X)}
\end{equation} 
holds for all differentiable $f:\R^N\to\R$ such that both sides of the equality are 
well-defined.

