[Corollary cor_estimation_SID of arXiv:2411.08846, 'On the Number of Crossings and Bouncings\\ of a Diffusion at a Sticky Threshold'] Let $\mathcal P_x =(\Omega, \bF, (\bF_t)_{t\ge 0}, \Prob_x)$ be a filtered probability space and let $X$ be an $(\bF_t)_{t\ge 0}$-adapted process solution to (equation eq_stickySDE of the paper) on $\mathcal P_x$. 
The statistic defined by 
\begin{equation}
	\begin{aligned}
		\varrho_n(X) &= \left(\frac{ 4}{\sigma(0)} \sqrt{\frac 2 \pi} \right) \frac{1}{\sqrt n}\frac{\cC{2}{n,t}(X)}{ \cC{1}{n,t}(X)},
		& n&\in \IN,
	\end{aligned}
\end{equation}
is a consistent estimators of $\rho $, conditionally on the event $\mathcal H_t =\{\tau^{X}_0 < t\}= \{\exists\; s \in [0,t) \colon  X_s = 0\}$.
This means that (see~Definition~(def_conditional_convergence_in_probability of the paper)),  $\varrho_n(X)  \longrightarrow  \rho $, in $\Prob^{\mathcal H_t}_x $-probability, as $n \longrightarrow  \infty $.

[Lemma lem:two-cut-kernel of arXiv:2609.03532, 'Airy limit for the Jack process and topological expansion'] Uniformly in $L\ge 0$ and $\delta\in\mathbb Z$,
\begin{equation}
  \mathcal T_L(\delta)\leq C(L+1)^{1/2}.

\end{equation}
In the pathwise expansion of $\mathcal T_L(\delta)$, restrict the sum
to configurations satisfying at least one of the following conditions:
$A\geq R$, $B\geq R$, or the unrestricted middle
walk $W^{\mathrm c}$ satisfies
$\operatorname{osc}(W^{\mathrm c})\geq R$.  The restricted sum is
bounded by
\begin{equation}
  C(L+1)^{1/2}
  \exp\!\left\{-\frac{cR^2}{L+R+1}\right\}.

\end{equation}

[Lemma lem:abstract-fixed-submersion-nullity of arXiv:2608.02459, 'Response Calculus for Spectral Simplicity\\ and Joint Eigenvalue Densities'] Let $g\in\mathcal Q^M$.  If $E\in\mathcal B(\mathbb R^M)$ and
$\mathcal L^M(E)=0$, then
\begin{equation*}
 \Omega_{\nu,g}^{\rm sub}
 \cap\Lambda_{\nu}^{-1}(E)
 \in\mathcal B(X),
 \qquad
 \mathbb P\left(
 \Omega_{\nu,g}^{\rm sub}
 \cap\Lambda_{\nu}^{-1}(E)
 \right)=0.
\end{equation*}

[Lemma lemma-sum-prod-L-x-j-delta of arXiv:2606.13147, 'Scaling limits of the single-curve interface and outermost loops in the planar random fiel'] Let $0 < \alpha < 1$. There exists a constant $C>0$ depending on $D$ only such that for any $k \in \mathbb{N}$,
    \begin{equation*}
        \delta^{2k} \sum_{(x_1,\dots,x_k) \in D_{\delta}^k \setminus B_k(\delta)} \big[\prod_{j=1}^{k} L(x_j)\big]^{-\alpha} \leq C^kk^{\alpha k}
    \end{equation*}
    where we have set $B_k(\delta):= \{(x_1,\dots,x_k) \in D_{\delta}^k: \exists i \neq j, \vert x_i - x_j \vert \leq 4\delta \}$.

[Prop 3recurrence of arXiv:2506.07158, 'The diffusivity of supercritical Bernoulli percolation is infinitely differentiable'] Under the same condition as Proposition~(pr:key_estimate of the paper), there exist constants $C, C^*, \widetilde{C} < +\infty$ depending on $i,j,\alpha,h,N,k,d,\mathsf{r}$ satisfying
		\begin{align*}
			I^{* \;(N,k)}_{\; m,\alpha, h}(i,j) &\leqslant C^*(i,j,\alpha, h,N,k,d,\mathsf{r}), \\
			\widetilde{I}^{ \;(N,k)}_{\; m,\alpha, h}(i,j) &\leqslant \widetilde{C}(i,j,\alpha,h,N,k,d,\mathsf{r}), \\
			I^{\; (N,k)}_{\; m,\alpha, h}(i,j) &\leqslant C(i,j,\alpha,h,N,k,d,\mathsf{r}). \\
		\end{align*}

