[Corollary 67 of arXiv:2607.10486, 'Weak martingale solutions to stochastic Navier-Stokes-Cahn-Hilliard system with transport '] Let $(\delta_n)_{n\in \mathbb{N}}\subset (0,1)$ such that $\delta_n \to 0$ as $n \to \infty$. Assume Assumption \ref{ass-A3} holds. Suppose that $\bu_n \to \bu$ in $L^2([0,T] \times \domO)$. Then, we have
\begin{equation}
\lim_{n \to \infty} \int_0^T \int_{\domO} \Vert \bg_{n}(t,x;\bu_n(t,x)) -  \bg(t,x;\bu(t,x)) \Vert_\mathrm{Y}^2\, \d x\,\d t
=0.
\end{equation}

[Proposition prop:lbm-cluster-response of arXiv:2608.02459, 'Response Calculus for Spectral Simplicity\\ and Joint Eigenvalue Densities'] For these branches, the response operator has matrix
\begin{equation}
 \left(\inner{B_f^\Lambda(M_x)\phi_j}{\phi_i}
              _{L^2(M_x)}\right)_{i,j=1}^r
 =-\gamma\Lambda
 \left(\int_Df\phi_i\phi_j\,dM_x\right)_{i,j=1}^r,

\end{equation}
and its eigenvalues are precisely the branch derivatives:
\begin{equation}
 \{\lambda_j'(0):1\le j\le r\}
 =\Spec\bigl(B_f^\Lambda(M_x)\bigr)
 \quad\text{as multisets}.

\end{equation}

[Defi 2 of arXiv:2607.13849, 'Rearranged Stochastic Heat Equation with an Entropy Gradient Structure'] On a given 
        probabilistic set-up $(\Omega,\mathfrak{F},{\mathbb F}=\{\mathfrak{F}_t\}_{t\geq 0},\mathbb{P},(W_t)_{t \geq 0})$, and for
        an $\mathfrak{F}_0\text{-measurable}$ initial condition $X_0$ with values in $\mathcal{U}^2(\mathbb{S})$, satisfying 
        ${\mathbb E}[\| X_0\|_2^p]<+\infty$ for all $p \geq 1$, we say that a pair of processes $(X_t,\eta_t)_{t\geq 0}$ solves the rearranged SHE \eqref{0.1}, initialized at $X_0$, if
		\begin{itemize}
			\item[1.] $(X_t)_{t\geq 0}$ is a continuous $\mathbb{F}\text{-adapted}$ process with values in $\mathcal{U}^2(\mathbb{S})$;
			\item [2.]  $(\eta_t)_{t\geq 0}$ is a continuous $\mathbb{F}\text{-adapted}$ process with values in $\mathcal{H}^{-2}_{\mathrm{Sym}}(\mathbb{S})$, starting from $0$ at $0$, such that, with probability one, for any $\phi \in \mathcal{H}^{2}_{\mathrm{Sym}}(\mathbb{S})\cap \mathcal{U}^2(\mathbb{S})$, the path $(\langle \eta_t,\phi\rangle)_{t\geq 0}$ is non-decreasing;
			\item[3.] with probability one, for any $\phi \in \mathcal{H}^{2}_{\mathrm{Sym}}(\mathbb{S})$, for all $t\geq 0$,
			\begin{equation}
				\langle X_t,\phi\rangle = \langle X_0,\phi\rangle + \int_0^t \langle X_s,\Delta \varphi\rangle \mathrm{d}s + \langle W_t,\phi\rangle + \langle \eta_t,\phi \rangle.
			\end{equation}
			\item[4.] for any $t\geq 0$,
			\begin{align}
				\lim_{\epsilon\searrow 0 }\mathbb{E} \int_0^t {\rm e}^{\epsilon \Delta} X_s\cdot \mathrm{d} \eta_s = 0.
			\end{align}
		\end{itemize}

[Proposition prop:uniform_approximation_fat_shattering of arXiv:2609.03129, 'A Closed-Form Formula for Consistent Lipschitz Regression on Metric Spaces with Sparse Neu'] Let $(X,\rho,\mathfrak{m})$ be a compact $d$-Ahlfors regular metric measure space, for some $d>0$, let $B,L>0$, and fix $\mathcal{F}\subseteq C(X,\mathbb{R})$. There exist constants $\varepsilon_0,c>0$ such that, if there is a fixed tolerance $0<\varepsilon<\min\{B/2,L\varepsilon_0\}$ such that, for every $f\in\operatorname{Lip}((X,\rho),[-B,B];L)$, there is some $\hat{f}\in\mathcal{F}$ satisfying
\begin{equation}

    \|f-\hat{f}\|_\infty
\le
    \varepsilon,
\end{equation}
then, for every $\varepsilon\le\gamma<\min\{B/2,L\varepsilon_0\}$,
\begin{equation}

    \operatorname{fat}_{\gamma}(\mathcal{F})
\ge
    c
    \left(
        \frac{L}{\gamma}
    \right)^d.
\end{equation}

[Thm 3 of arXiv:2606.18877, 'Ergodic Properties of Non-Linear Density-Dependent Perturbations of the Ornstein--Uhlenbec'] Under the same assumptions as in Lemma~\ref{lem:unifbound}, the weak solution \(p\) of~\eqref{eq:NFPE} belongs to the class \(C^{1+\beta/2,2+\beta}_{\mathrm{loc}}\bigl((0,T)\times\mathbb R^d\bigr)\) for some \(\beta\in(0,1)\) and any \(T>0\) fixed. In particular, it is a locally classical solution. Moreover, for any \(t\in(0,T)\) and \(x\in\R^d\) its gradient satisfies
    \begin{equation}
    \Vert \nabla p_t(x)\Vert_2
    \leq \frac{c_1(d,K,b_0,c_0,\Xi(0),L_{\mathrm{Lip}}(\Xi))}{\min\left(1,\sqrt{t/2}\right)}
    (1+\Vert x\Vert_2)\exp\left\{
    -\frac{\Xi(0)}{4}\Vert x\Vert_2^2
    \right\},
    \end{equation}
    where \(L_{\mathrm{Lip}}(\Xi)\) is the Lipschitz constant of \(\Xi\), and \(c_1(d,K,b_0,c_0,\Xi(0),L_{\mathrm{Lip}}(\Xi))\) is some constant. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition thm:LSI:wu of arXiv:2412.07710, 'An H-theorem for a conditional McKean-Vlasov process related to interacting diffusions on '] Let $\varphi \in C^2(\ensuremath{\mathbb{R}}^d)$. Define the differential operator $\mathcal{L}_\varphi := \Delta - 
abla \varphi \cdot 
abla$. Let  $\mathcal{L}_\varphi^{-1}$ denote the Poisson operator, which is the inverse of $\mathcal{L}_\varphi$ on the Banach space of Lipschitz continuous functions $C_{	ext{
ormalfont Lip}, 0}(\ensuremath{\mathbb{R}}^d)$. That is, for $f \in C_{	ext{
ormalfont Lip}, 0}(\ensuremath{\mathbb{R}}^d)$, $h = \mathcal{L}_\varphi^{-1} f$ if $\mathcal{L}_{\varphi} h = f$. Recall the definition of $w(r, \varphi)$ in (equation eq:LSI:w of the paper). If
     egin{align*}
        \hat{c}(\varphi) :=  rac{1}{4} \int_0^\infty s \exp igg(\int_0^s  rac{1}{4}w(r, \phi) dr  igg) ds < \infty,
    \end{align*}
    then $\mathcal{L}_\varphi^{-1}$ is a bounded operator on $C_{	ext{
ormalfont Lip}, 0}(\ensuremath{\mathbb{R}}^d)$ and we have $\|\mathcal{L}_\varphi^{-1} \|_{	ext{
ormalfont Lip}} < \hat{c}(\varphi).$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop Dtilde-implies-coupling of arXiv:2605.08052, 'Rapid phase ordering of Ising dynamics on $\mathbb Z^2$'] The event $\{\widetilde{D}_k(B) =0\}$ implies that $U_{T_k}^{B,\pi \wedge Q}(B) =  U_{T_k}^{B,\pi}(B)$. If moreover 
    \begin{align*}
        \mathsf{StatEquiv}_{\ge k}(B) & = \bigcap_{k'\ge k} \bigcap_{B' \in \mathscr{B}_{k'}: B\subset B'} \mathsf{StatEquiv}(B')\,.
    \end{align*}
    holds, then we have that $X_{T_k}^{\pi \wedge Q}(B) = X_{T_k}^{\pi}(B)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 16 (\cite{namba74}, see also Section 2.1 in \cite{Streets-Ustinovskiy21}) of arXiv:2608.30638, 'On compact steady pluriclosed soliton surfaces'] Let $(M,J)$ be a primary Hopf surface of class $1$, and we work over the open subset $\{z_1z_2\neq 0\}$. Consider the logarithmic coordinates
\begin{equation}
    w_j=x_j+\sqrt{-1}y_j=\log z_j.
\end{equation}
Define
\begin{equation}
    R_j=\partial_{x_j}, T_j= J R_j=\partial_{y_j}.
\end{equation}
Write
\begin{equation}
    a=\Re\log\alpha,\ b=\Re\log\beta,
\end{equation}
and consider
\begin{equation}
    Z=aR_1+b R_2.
\end{equation}
Then the maximal compact torus $T_{\mathrm {std}}\subset G$ has Lie algebra
\begin{equation}
    \mathfrak t_{\mathrm {std}}=\mathrm{span}_{\mathbb R}\{T_1, T_2, Z\}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

