[Lem pure-phase-decay-of-correlations of arXiv:2605.08052, 'Rapid phase ordering of Ising dynamics on $\mathbb Z^2$'] Let $\pi_\infty^-$ be the infinite volume minus measure, and fix some finite sets $U,V$. For $\beta>\beta_0$, we have 
    \begin{align*}
        \|\pi_\infty^- (\sigma(V) \in \cdot) - \pi_\infty^-(\sigma(V) \in \cdot \mid \sigma(U)\equiv -1)\|_{{\textsc{tv}}}\le |U| e^{ - \beta d(U,V)}\,.
    \end{align*}

[Lemma 8 of arXiv:2604.18871, 'Quantitative approximation of the Vlasov(--Fokker--Planck)--Navier--Stokes system by stoch'] Let $f,g \in L^2([0,T];H^1(\T^d)^d)$ with $f$ that is divergence-free. Let $p>d$ and $\gamma\in (\frac{d}{p},1)$. Then there exists $C>0$ such that for any $t\in [0,T]$,
\begin{equation*}
\int_{0}^{t} \Big\Vert e^{\left(  t-s\right) \Delta} P \big[ (f_{s} \cdot \nabla)g_s\big] \Big\Vert _{\gamma,p} \dd s \leq C \int_{0}^{t}  \frac{1}{(t-s)^{\frac{1+\gamma}{2}}} \left\Vert f_{s} \otimes g_{s} \right\Vert _{L^p_{x}}  \dd s .
\end{equation*}

[Theorem 11 of arXiv:2608.30089, 'On the Coefficients of Hurwitz-Type Matrix Polynomials'] Let \(\mathbf f_n\) be the matrix polynomial \eqref{hup01}, and let
\(\Xi_m^{(j)}\), \(\Phi_m^{(j)}\),
\(\Psi_m^{(j)}\), and \(\Theta_m^{(j)}\)
be as in \eqref{01-eq}, \eqref{11-eq},
\eqref{04-eq}, and \eqref{06-eq}.
Then the coefficients of \(\mathbf f_n\) admit the following
representations.
For \(n=2m\), \(m\geq1\),
\begin{align}
A_{n-k}
=
\begin{cases}
\displaystyle
\Phi_m^{(j)}
\widehat H_{1,0}^{-1}\widehat H_{2,0}
\cdots
\widehat H_{1,m-1}^{-1}\widehat H_{2,m-1},
&
\text{if } k=2j,\quad 0\leq j\leq m,
\\[2ex]
\displaystyle
\Psi_m^{(j)}
\widehat H_{1,0}^{-1}\widehat H_{2,0}
\cdots
\widehat H_{1,m-1}^{-1}\widehat H_{2,m-1},
&
\text{if } k=2j+1,\quad 0\leq j\leq m-1.
\end{cases}
\end{align}

For \(n=2m+1\), \(m\geq0\),
\begin{align}
A_{n-k}
=
\begin{cases}
\displaystyle
\Xi_m^{(j)}
\widehat H_{1,0}\widehat H_{2,0}^{-1}
\widehat H_{1,1}
\cdots
\widehat H_{2,m-1}^{-1}\widehat H_{1,m},
&
\text{if } k=2j,\quad 0\leq j\leq m,
\\[2ex]
\displaystyle
\Theta_m^{(j)}
\widehat H_{1,0}\widehat H_{2,0}^{-1}
\widehat H_{1,1}
\cdots
\widehat H_{2,m-1}^{-1}\widehat H_{1,m},
&
\text{if } k=2j+1,\quad 0\leq j\leq m.
\end{cases}
\end{align}
For \(m=0\), there are no factors following
\(\widehat H_{1,0}\); hence the product appearing in
\eqref{coef2CC} is understood to be simply
\(\widehat H_{1,0}\).

