[Cor 46 of arXiv:2509.01797, 'Relation between Wick powers and excursion clusters of the 2D GFF'] Let $\eta>0$, $\varepsilon>0$ and $b\in2\lambda\N$ with $b\geq v + 2\lambda$.
Then
\begin{displaymath}
\E\Big[\Big\Vert
\ind_{\Ns_{\varepsilon}(A)}
-\E\big[\ind_{\Ns_{\varepsilon}(A)}\big\vert  A_{0,b},\ell_{0,b}\big]
\Big\Vert_{H^{-\eta}(\C)}^{2}\Big]
\qquad
\text{and}
\qquad
\E\Big[\Big\Vert
\ind_{\widetilde{\Ns}_{\varepsilon}(A)}
-\E\big[\ind_{\widetilde{\Ns}_{\varepsilon}(A)}\big\vert  A_{0,b},\ell_{0,b}\big]
\Big\Vert_{H^{-\eta}(\C)}^{2}\Big]
\end{displaymath}
are bounded by
\begin{equation}

\int_{D^{2}}
e^{-(b-v-2\lambda)^{2}/(2\log(2)/\pi + 2 G_{D}(z,w))}
\LK_{\eta}(\vert w-z\vert)
\,d^{2}z\,d^{2}w.
\end{equation}
Given a deterministic smooth cutoff function $f_{0}:D\rightarrow [0,1]$, compactly supported in $D$,
then
\begin{displaymath}
\E\Big[\Big\Vert
f_{0}\ind_{\widetilde{\Ns}_{\varepsilon}(A)}
-\E\big[f_{0}\ind_{\widetilde{\Ns}_{\varepsilon}(A)}\big\vert  A_{0,b},\ell_{0,b}\big]
\Big\Vert_{H^{-\eta}(\C)}^{2}\Big]
\end{displaymath}
is again bounded by \eqref{Eq ind norm Gauss}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 18 (Exact WKBC representation) of arXiv:2609.02196, 'Schr\"odinger Bridges on Lie Group Manifolds for Probabilistic Intrinsic Generation'] For \(\beta^*=\log g_T\), differentiation under the wrapped-kernel integral gives
\begin{equation*}
h_t^{\beta^*}=h_t,
\qquad
\bm u_t^{\rm WKBC}=\sqrt{2\gamma}\nabla_{\bm\xi}\log h_t^{\beta^*}=\bm u_t^*.
\end{equation*}
The forward process must be initialized from
\begin{equation*}
p_0^{\rm SB}(x)=q_0(x)f_0(\mathcal O_0(x))h_0^{\beta^*}(x).
\end{equation*}
When only the source group coordinate is observed,
\begin{equation*}
P_0^{\rm SB}(\dd\bm\xi\mid g)
=
\frac{h_0^{\beta^*}(g,\bm\xi)Q_0(\dd\bm\xi\mid g)}
{\int h_0^{\beta^*}(g,\bm\eta)Q_0(\dd\bm\eta\mid g)}.
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 11 of arXiv:2609.01101, '2609.01101'] Let $U$ be analytic in a neighbourhood of the closed strip
$\alpha\le\Re s\le\beta$, and suppose that, for some $C\ge0$,
\begin{equation*}
|U(\sigma+it)|\ll(1+|t|)^C
\end{equation*}
uniformly for $\alpha\le\sigma\le\beta$.  Suppose its boundary values have
finite weighted norms.  If
$\alpha\le\sigma\le\beta$ and
\begin{equation*}
\vartheta=\frac{\sigma-\alpha}{\beta-\alpha},
\end{equation*}
then
\begin{equation}
\mathcal M_\sigma(U)
\le \exp\!\left(\vartheta(1-\vartheta)(\beta-\alpha)^2\right)
\mathcal M_\alpha(U)^{1-\vartheta}
\mathcal M_\beta(U)^{\vartheta}.
\end{equation}
More generally, suppose that $U$ is analytic in the open strip, has
polynomial growth uniformly on its closed substrips, and that
\begin{equation*}
\mathcal M_{\alpha+\delta}(U)\longrightarrow\mathcal M_\alpha(U),
\qquad
\mathcal M_{\beta-\delta}(U)\longrightarrow\mathcal M_\beta(U)
\end{equation*}
as $\delta\downarrow0$, with finite limits.  Then the same conclusion
holds with these one-sided endpoint norms.

