[Corollary of arXiv:2608.22945, 'A Momentum-Based Variance-Reduced Algorithm for Federated Multiobjective Optimization'] Under the conditions of
	Theorem~(T1 of the paper), FSMGDA-M-VR attains an $\epsilon$-Pareto stationary
	solution with communication complexity
\begin{equation*}
	\mathcal{O}\left(
	\max\left\{
	\frac{L(1+D^2)\sigma\Delta(1+S)^{\frac{3}{2}}}
	{KM\epsilon^{\frac{3}{2}}},
	\frac{LS\Delta}{\epsilon},
	\frac{(1+S)G_0^2}{\epsilon},
	\left(
	\frac{C_1}{\epsilon}
	\right)^{\frac{3}{4}},
	\frac{\sigma^2(1+S)}{KM\epsilon},
	\left(
	\frac{(1+S)\sigma^2}{KM\epsilon}
	\right)^{\frac{1}{2}}
	\right\}
	\right),
\end{equation*}
	where
\begin{equation*}
	C_1:=
	\frac{(1+S)\sigma^2}{KM}
	\left(
	\frac{MKL^2(1+D^2)^2\Delta^2}{\sigma^4}
	\right)^{2/3}.
\end{equation*}
Moreover, the corresponding sample complexity is
\begin{equation*}
	\mathcal{O}\left(SMK\max\left\{
	\frac{L(1+D^2)\sigma\Delta(1+S)^{\frac{3}{2}}}
	{KM\epsilon^{\frac{3}{2}}},
	\frac{LS\Delta}{\epsilon},
	\frac{(1+S)G_0^2}{\epsilon},
	\left(
	\frac{C_1}{\epsilon}
	\right)^{\frac{3}{4}},
	\frac{\sigma^2(1+S)}{KM\epsilon},
	\left(
	\frac{(1+S)\sigma^2}{KM\epsilon}
	\right)^{\frac{1}{2}}
	\right\}
	\right).
\end{equation*}

