[Theorem 5 (Theorem \ref{DecoTheo3}) of arXiv:2608.30875, 'A Decomposition Theorem for Topological Semi-small Maps'] Let $f : X \rightarrow Y$ be a topologically semi-small map such that $X$ is a closed topological manifolds, the fibered set $R$ is a closed stratified space, and $Y$ is a closed topological $n$-pseudomanifold. Set $B:=f^{-1}(R)$, let $R=\bigsqcup_{\beta}T_{\beta}$ be a suitable decomposition of the fibered set, and let $R_{\operatorname{rel}}$ be its relevant part. Furthermore, let the filtration $Y \supset Y_{n_{R}}(=R) \supset Y_{n_{R}-1} \supset \cdots$ be the refined stratification on $Y$ obtained by Proposition~\ref{RefinedStra}, where $n_{R}:= \dim(R)$. Set $S_{k}:= Y_{k} \setminus Y_{k-1}$, and assume the followings:
        \begin{enumerate}
        	\item for each $r \in R$ the fiber $f^{-1}(r)$ is a closed orientable topological manifold;
        	\item the normal bundle of the manifold $f^{-1}(S_{k})$ in $X$ exists, for each $0 \leq k \leq n_{R}$, and is orientable, and for each $S_{k'}\in R_{\operatorname{rel}}$ and each $r\in S_{k'}$ there is a small open neighborhood $U$ of $r$ such that the connecting homomorphism in the Gysin sequence of the normal bundle of $S_{k}$ restricted to $f^{-1}(U)$ vanishes in degree $\operatorname{codim}_{X}(B)-1$.
        	\end{enumerate}
        	Let $R(f|_{X \setminus B})_{*}\,\underline{\mathbb{Q}}_{X \setminus B}\simeq \underline{\mathbb{Q}}_{Y \setminus R}\oplus \mathcal{L}$, where $\mathcal{L}$ is the local system on $Y \setminus R$ associated to the covering map $f|_{X \setminus B}$. If each $\operatorname{codim}_{Y}(S_{k})$ is even and $\operatorname{codim}_{X}(B)\geq 2$, then
        \begin{align*}
        	Rf_{\ast}\underline{\mathbb{Q}}_{X}[n]\simeq \bigoplus_{S_{k} \in R_{\operatorname{rel}}}\iota_{k\ast}(IC_{\overline{S_{k}}} (R^{0}f\vert_{f^{-1}(S_{k})}\underline{\mathbb{Q}}_{S_{k}})) \oplus IC_{Y}(\underline{\mathbb{Q}}_{Y \setminus R} \oplus \mathcal{L}),
        \end{align*}
        where $\iota_{k}:\overline{S_{k}} \hookrightarrow Y$ is the canonical closed inclusion, and $IC^{\overline{p}}_{Y}$ is Deligne's intersection complex with respect to the above refined stratification and the perversity $\overline{p}\in\{\overline{n},\overline{m}\}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorema WPMS of arXiv:2608.30777, 'Inhomogeneous nonlinear Schr\"odinger equation \\ in Fourier-Lebesgue and modulation space'] Let $1\leq p, q \leq \infty$ and $s\geq 0.$ We have following results in (equation NLS of the paper):
\begin{enumerate} 
\item  [Wang2006, wango, Kasso2009, Bhimani2016, CorderoJMAA] LWP in $M_s^{p,1} $ for $  \alpha-1 \in 2\mathbb N$ and small-data GWP  $M^{2,1}$  for  $\alpha=3$. 
\item GWP in 
\begin{itemize}
    \item[-]  [oh2018global, guo20171d] $M^{2,q}$ for $2\leq q< \infty$ and $\alpha=3$. 
    \item[-] [Klaus] $M^{p,q}$ for $1\leq q\leq  p \leq 2$ or $M^{p,q}_s$ for $s>1/q', 1\leq p \leq 2$  or $M_1^{p,1}$ for $2\leq p< \infty.$
    \item[-] [LeonidIn,leonidthesis, Bhimani20251d]   $M^{p, p'}$ for $p$ sufficiently close to 2, and $\alpha \in (1,5)$.
\end{itemize}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:sharp-type-compression of arXiv:2609.01690, 'Iterated-sumset spectra: The complete exponent law and its rank geometry'] For every $h\geq2$ and $k\geq3$,
\begin{equation}
 \max_{\mathsf T\in\mathfrak T^{\max}_{h,k}}\mu_h(\mathsf T)=h^{k-2}.
\end{equation}
Thus the maximal-rank boundary is sharp not only for individual sets: one
weak addition-table type itself forces the critical normalized diameter.

[Theorem 13 (Theorem 2.2 of \cite{zhang2016central}) of arXiv:2604.17302, 'Elephant random walk with attributed steps and extractions of random sizes'] Suppose $\{Z_{n}\}$ converges to the constant $\theta^{*}$ almost surely, and that Assumption~\eqref{gen_assump_dist_2} is satisfied. Suppose $0<\rho<1/2$, that
\begin{equation}
\sum_{i=0}^{n-1}\E\left[\Delta M_{i+1}\left(\Delta M_{i+1}\right)^{t}\Big|\mathcal{F}_{i}\right]=O(n) \text{ almost surely},
\end{equation}
and that there exists some $0<\epsilon<1-\rho$ such that
\begin{equation}
\sum_{i=0}^{n-1}\delta_{i}=o\left(n^{1-\rho-\epsilon}\right) \text{ almost surely}.
\end{equation}
Then there exist complex random variables $W_{1},\ldots,W_{s}$ such that 
\begin{equation}
\frac{n^{\rho}}{(\log n)^{\nu-1}}(Z_{n}-\theta^{*})-\sum_{j\in[s]:\text{Re}(-\lambda_{j})=\rho,\nu_{j}=\nu}\exp\left\{i\text{Im}(\lambda_{j})\log n\right\}W_{j}\left(T^{-1}\right)^{t}e_{j}\convas 0,
\end{equation}
where $i=\sqrt{-1}$, the notation $\text{Im}(\lambda)$ indicates the imaginary part of $\lambda$, the matrix $T$ is as defined via \eqref{similarity_eq_general}, and $e_{j}$ is the $d$-dimensional column vector such that, if its first $\nu_{1}$ coordinates make up its first block, the next $\nu_{2}$ coordinates make up its second block, and so on, then the $\nu_{j}$-th coordinate of its $j$-th block equals $1$, and all other coordinates equal $0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 6 of arXiv:2607.10486, 'Weak martingale solutions to stochastic Navier-Stokes-Cahn-Hilliard system with transport '] If $\phi \in \zero{H}{2}(\domO)$ and 
   \begin{equation}
       \cp(\phi) \coloneqq - \varepsilon \Delta \phi + \alpha(\psi^\prime(\phi) - \avg{\psi^\prime(\phi)}), \;\; \; \phi \in \zero{H}{2}(\domO),
   \end{equation}
then $\cp(\phi)\nabla \phi \in \mathbb{L}^2(\domO)$ and 
  \begin{equation}
     \bR_0(\phi,\phi)=  -\frac{1}{\eps} \P (\cp(\phi)\nabla \phi).
   \end{equation}

