[Thm 43 (Anti-concentration/heat kernel estimates) of arXiv:2510.22155, 'Random walks in space-time random media in all spatial dimensions: the full subcritical fl'] Fix $\sigma>0$, $M>0$, $K > 0$. Let $F:[0,\infty)\to[0,\infty)$ be decreasing and of exponential decay at infinity. Let $\br_0 \in \Ekk$ be centered and $\delta$-repulsive. Then
    \begin{itemize} 
    \item Case $d\ge 2$: there exists $\epsilon=\epsilon(F,\sigma,M,\delta)>0$ and $C=C(F,\sigma,M,\delta,K)>0$ such that uniformly over $\x\in I^k$ and $\y\in \mathbb R^{kd}$ and integers $r\ge 0$ one has the bound $$
       \sup_{\substack{\br\in \Ekk\\d_{\mathrm{SRI}}(\br,\br_0) <\epsilon
       }}
       \; \Pbb ( |\mathbf R_r-r\mathbf s(\nu_{\br}) -\y|\leq 1) < C r^{-kd/2} \big( 1+ r^{-1/2} |\x-\y|\big)^{-K}. $$
       \item $d=1$. We have the weaker estimate just for the centered chain: $$\mathbf P_{\x}^{\br_0} ( |\mathbf R_r - \y|\le 1) \leq Cr^{-kd/2}  \big( 1+ r^{-1/2} |\x-\y|\big)^{-K}.$$ We also have the following time-averaged bound for non-centered chains when $q\ge 4$: there exists $\epsilon>0$ so that for all $\lambda>0$ one has 
        $$  \sup_{\substack{\br \in \Ek\\d(\br,\br_0)<\epsilon }} \sup_{\x\in I^k} \sup_{r\in\mathbb Z_{\ge 0}} \Ebb [ e^{ \lambda r^{-1/2} \sum_{s=0}^{r-1} \sum_{1\le i'<j'\le k} \ind_{\{|R^{i'}_s-R^{j'}_s|\le 1 \}} }]<\infty.$$ 
       \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem lem_uniqueness of arXiv:2606.23648, '\textsc{Optimal Stopping for a Diffusion with Unobserved Bernoulli Drift}'] Under the one-interval geometry (equation one_interval_phi_geometry of the paper), and recalling (equation def_Jx of the paper), there
    exists a unique \(q_x\in(\underline q_x,\overline q_x)\) such that
    \begin{equation}
        J_x(q_x)=0.
    \end{equation}

[Theorem rho bound of arXiv:2412.01086, 'Spectral radii of sparse non-Hermitian random matrices'] {k09}}] 
For an $n\times n$ matrix $A$ with $n>2$ and for $k\geq 1$,
\begin{align*}
C_n^{-\sigma_n(k)/k}\left( \frac{\| A\|^n}{\| A^n\|}\right)^{-\nu_n(k)/k}\| A^k\|^{1/k}\leq \rho (A)\leq \| A^k\|^{1/k},
\end{align*}
where
\begin{align*}
C_n =n^{3n/2}, \quad \sigma_n(k) = \frac{(n-1)^3}{(n-2)^2}k^{\frac{\log (n-1)}{\log n}}, \quad \nu_n(k) =\frac{(n-1)^2}{n-2}k^{\frac{\log (n-1)}{\log n}}.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 6 of arXiv:2606.11271, '\LARGE The $K$-th nearest neighbor random walk on a Poisson point process gets trapped'] For any $\varepsilon >0$, $A>0$ and $n\in \N$, $X_n$ is called an $(\varepsilon, A)$-pioneer point if there exist some $\rho \in [0,A]$ and some $c\in \R^d$ such that 
\begin{itemize}
\item[$(i)$] $B(c,\varepsilon) \subset B(X_n, \rho) \cap (\R^d \setminus E_n)$;
\item[$(ii)$] $| (\chi \smallsetminus \{X_n\})\cap \left(   B(X_n, \rho) \cap E_n  \right) | < M$.
\end{itemize}
The set of $(\varepsilon, A)$-pioneer points is denoted by
$$
\V_p (\varepsilon, A) \coloneqq \{ x\in \chi \,:\, \exists n \in \N \,,\, X_n =x \textrm{ and $X_n$ is $(\varepsilon, A)$-pioneer}\} \,.
$$

[Definition 34 of arXiv:2605.11801, 'A non-local singular non-linear Fokker-Planck PDE'] We define the domain 
   \begin{equation*}
\mathcal D_{\mathcal L} : =  \{ f \in C_T\mathcal C^{(1+\beta)+}:   \exists g \in  C_T\bar {\mathcal C}_c^{0+}  \text{ such that $f$ is a weak solution of \eqref{eq:PDE} with } f_T \in \bar{\mathcal C}_c^{(1+\beta)+  }\}.
\end{equation*}

[Lemma 12 (Monotonicity of the corrector energy) of arXiv:2604.21143, 'Quantitative homogenization for the critical long-range random conductance model'] Let~$U \subset V$ be bounded Lipschitz domains in~$\Rd$, and let~$\eps \in (0,1)$.
		For every~$p \in \Rd$, the correctors~$\phi_U$ and~$\phi_V$ defined by~\eqref{eq:elleqdefnu} on~$U^\eps$ and~$V^\eps$ satisfy
		\begin{equation}

			D_\a^\eps(\phi_U) \le D_\a^\eps(\phi_V)\,.
		\end{equation}
		Consequently,
		\begin{equation}

			\|\phi_U\|_{H^1_{\mathrm{crit}}(U^\eps)}^2 + \|\phi_U\|_{L^2(U^\eps)}^2
			\le C\bigl(\|\phi_V\|_{H^1_{\mathrm{crit}}(V^\eps)}^2 + \|\phi_V\|_{L^2(V^\eps)}^2\bigr)\,,
		\end{equation}
		where~$C$ depends only on~$d$,~$\lambda$, and~$\operatorname{diam}(U)$.

[Lemma 19 of arXiv:2604.17302, 'Elephant random walk with attributed steps and extractions of random sizes'] Let $\mathcal{A}$, and $\mathcal{A}_{n}\subset \mathcal{A}$ for each $n\in\mathbb{N}$, be compact subsets of $\mathbb{R}^{d}$. Let $Q$, taking values in $\mathcal{A}$, and $Q_{n}$, taking values in $\mathcal{A}_{n}$, for each $n\in\mathbb{N}$, be random variables, such that $\{Q_{n}\}$ converges almost surely to $Q$. Let $f_{n}:\mathcal{A}_{n}\rightarrow\mathbb{R}$ for each $n$, and $f:\mathcal{A}\rightarrow\mathbb{R}$ with $f\in\mathcal{C}^{(0)}(\mathcal{A})$. Let $\beta_{n}>0$ for each $n$ be such that 
\begin{equation}
\sup\left\{\left|f_{n}(x)-f(x)\right|:x\in \mathcal{A}_{n}\right\}\leqslant \beta_{n} \text{ for each } n\in\mathbb{N} \quad \text{and} \quad \beta_{n}\rightarrow 0 \text{ as } n\rightarrow\infty. 
\end{equation}
Then the Cesaro average
\begin{equation}
\frac{1}{n}\sum_{i=1}^{n}f_{i}(Q_{i}) \convas f(Q) \text{ as }n\rightarrow\infty.
\end{equation} 

Alternatively, let $Q$ as well as $Q_{n}$, for each $n\in\mathbb{N}$, take values in $\mathcal{A}$, and let $Q_{n}\convas Q$. Let $f_{n}:\mathcal{A}\rightarrow\mathbb{R}$ and $f_{n}\in\mathcal{C}^{(0)}(\mathcal{A})$ for each $n\in\mathbb{N}$, and $f:\mathcal{A}\rightarrow\mathbb{R}$, such that $\{f_{n}\}$ converges uniformly to $f$ on $\mathcal{A}$. Then, once again, the conclusion of \eqref{Cesaro_convergence} holds. A special case of this scenario is where $f_{n}\equiv f$ for each $n\in\mathbb{N}$.

[Definition 47 of arXiv:2607.18104, '2607.18104'] The \textbf{asymmetric simple exclusion process (ASEP)} on $\Z$ with parameter $q\in [0,1)$ is a continuous-time Markov chain $(\eta_t)_{t \geq 0}$ on $\{0,1\}^{\Z}$ with generator
\begin{equation}
L_{\Z}f(\eta) = \sum_{x \in \Z} \big(\eta(x)(1-\eta(x+1)) + q \eta(x+1)(1-\eta(x))\big)\big[ f(\eta^{x,x+1})- f(\eta) \big] 
\end{equation} acting on the core of cylinder functions $f \colon \{0,1\}^{\Z} \rightarrow \R$. 
Here, $\eta^{x,x+1}$ denotes the configuration, where we swap the values of $x$ and $x+1$, and leave all other values in $\eta$ unchanged, i.e.,
\begin{equation}
    \eta^{x,x+1}(y) := \begin{cases}
        \eta(x+1) & \text{ if } y=x \\
        \eta(x) & \text{ if } y=x+1 \\
        \eta(y) & \text{ otherwise. }
    \end{cases}
\end{equation}
 We define the \textbf{wrapped periodic asymmetric simple exclusion process (periodic ASEP)} as the continuous-time Markov chain $(\eta^{\per}_t)_{t \geq 0}$ on $\{0,1\}^{\Z/N\Z}$ with respect to the generator
\begin{equation}
L_{\per}f(\eta) = \sum_{x \in \Z/N\Z} \big(\eta(x)(1-\eta(x+1)) + q \eta(x+1)(1-\eta(x))\big)\big[ f(\eta^{x,x+1})- f(\eta) \big] 
\end{equation} for all cylinder functions $f \colon \{0,1\}^{\Z/N\Z} \rightarrow \R$. We extend the wrapped periodic ASEP $(\eta^{\per}_t)_{t \geq 0}$ to the \textbf{unwrapped periodic ASEP} $(\epb_t)_{t \geq 0}$ on $\{0,1\}^{\Z}$ by setting for all $t\geq 0$
\begin{equation}
    \epb_t(x) := \eta_t( x \textup{ mod } N) . 
\end{equation}

[Lemma lem_sticky_refl_principle of arXiv:2411.08846, 'On the Number of Crossings and Bouncings\\ of a Diffusion at a Sticky Threshold'] Let $X$ be the sticky Brownian motion of stickiness parameter $\rho>0$ defined on the filtered probability space $ \mathcal P_x = (\Omega, \bF, (\bF_t)_{t\ge 0},\Prob_x) $ such that $\Prob_x$-a.s., $X_0 = x$ (in particular, $X$ is $(\mathcal F_t)_{t\ge 0}$-adapted). 
Let $X' $ be the process defined for all $t\ge 0 $ by
\begin{equation}

	X'_t = 
	\begin{dcases}
		X_t & t< \tau^{X}_{0},\\
		-X_t & t\ge \tau^{X}_{0}.\\
	\end{dcases}
\end{equation}
The process $X'$ defined this way is a sticky Brownian motion of stickiness parameter $\rho$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:nSD[a,b] of arXiv:2411.15401, 'The reference interval in higher-order stochastic dominance'] [{\color{black}[J80]}]
Let $a,b\in[-\infty,\infty]$ with $a<b$ and $n\in\mathbb{N}$. For $X,Y\in\mathcal X_{[a,b]}$, we say that $X$ dominates $Y$ in the sense of $n$th-order stochastic dominance on $[a,b]$ ($n{\rm SD}_{[a,b]}$), denoted by $X\ge_{n}^{[a,b]} Y$ or $F_X\ge_{n}^{[a,b]} F_Y$ if 
\begin{align*}
F_X^{[n]}(\eta)\le F_Y^{[n]}(\eta),~\forall \eta\in[a,b]~{\rm and}~F_X^{[k]}(b)\le F_Y^{[k]}(b)~{\rm for}~ k\in[n]
\end{align*}
or equivalently,
\begin{align*}
\mathbb{E}[(\eta-X)_+^{n-1}]\le \mathbb{E}[(\eta-Y)_+^{n-1}],~\forall \eta\in[a,b]~{\rm and}~\mathbb{E}[(b-X)^{k-1}]\le \mathbb{E}[(b-Y)^{k-1}]~{\rm for}~ k\in[n].
\end{align*}

[Thm 30 of arXiv:2510.23423, 'One-arm exponents of the high-dimensional Ising model'] Let $d\geq 4$. There exists $C_{\textup{mag}}=C_{\textup{mag}}(d)\geq 1$ such that, for every $h\geq0$,
		\begin{equation}
			m(\beta_c,h)\leq C_{\textup{mag}}\left\{
			\begin{array}{ll}
				h^{1/3} & \mbox{if } d>4, \\
				h^{1/3}|\log h| & \mbox{if }d=4.
			\end{array}
			\right.
		\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 41 of arXiv:2511.07350, 'Decoupling of clusters in independent sets in a percolated hypercube'] Recall the definitions of $\Delta$ and $\tilde{\Delta}$ from \eqref{eq:deltadef} above.
\begin{enumerate}[(a)]
    \item For all $p \in (0,1)$, we have
    \begin{equation}
        \E[\Delta] = \mu_2
        \qquad \text{and} \qquad
        \E[\tilde{\Delta}] = \tilde{\mu}_2.
    \end{equation}

    \item For all $p > 0.391$, we have
    \begin{equation}
        \Var(\Delta) \ll 1
        \qquad \text{and} \qquad
        \Var(\tilde{\Delta}) \ll 1.
    \end{equation}
    Additionally for $p > 0.391$, we have
    \begin{equation}
        \E[ \sum_{\fd_1 \sim \fd_2} \phi_{\fd_1} \phi_{\fd_2} ] \ll 1
        \qquad \text{and} \qquad
        \E[ \sum_{\fd_1 \sim \fd_2} \fphi_{\fd_1} \fphi_{\fd_2} ] \ll 1,
    \end{equation}
    where $\fd_1 \sim \fd_2$ if the neighborhoods of the two dimers overlap.
\end{enumerate}

