body:
[Definition def:F-double-critical of arXiv:2604.20215, '\bf Edge Universality for Inhomogeneous Random Matrices II: Markov Chain Comparison and Cr'] For    an  $r\times r$ matrix
\begin{equation}
    \mathfrak{A}(t) := \sum_{i=1}^q e^{\tau_i t} \boldsymbol{v}_i \boldsymbol{v}_i^T, \quad t \ge 0,
\end{equation}
we   define a quadratic form  in real variables $\{z_i\}$ by
\begin{equation}
    \mathfrak{A}[t;\{z_i\}_{i=1}^r](x,y)=\sum_{i,j=1}^r (\mathfrak{A}(t))_{ij}\sqrt{\delta(x-z_i)}\sqrt{\delta(y-z_j)}.
\end{equation}
For a typical connected diagram $\Gamma = (V, E)$,  we define the weight function  $\mathcal{W}_\Gamma$ as
\begin{equation}
    \mathcal{W}_\Gamma(x, \{\alpha_e\}) = \prod_{e=(u,v) \in E_{\mathrm{int}}} \theta_{\alpha}(x_u - x_v, \alpha_e \gamma^\alpha) \prod_{e=(u,v) \in E_b} \mathfrak{A}[\alpha_e;\{z_i\}_{i=1}^r](x_u,x_v),
\end{equation}
and the corresponding limiting diagram function $\mathcal{F}^{\mathfrak{A}}_\Gamma$   for  $t_1, \dots, t_s > 0$ as the integral
\begin{equation}
    \mathcal{F}^{\mathfrak{A}}_\Gamma(t_1, \dots, t_s; \{z_i\}_{i=1}^r;\gamma^\alpha) =
    \frac{C_\Gamma}{\prod_{j=1}^s t_j}  \int_{\mathbb{T}^{|V|}} \int_{\mathfrak{C}(\{t_i\})} \mathcal{W}_\Gamma(x, \{\alpha_e\}) \prod_{e \in E} d\alpha_e \prod_{v \in V} dx_v.
\end{equation}
Here in the product $\prod_{e=(u,v) \in E_b}$, each vertex  $u\in V_b$ carries   the variable $x_u$   exactly twice and   the square-root delta functions are interpreted according to the rule
\begin{equation}
    \sqrt{\delta(x_u-z_1)}\sqrt{\delta(x_u-z_2)}=\begin{cases}
        \delta(x_u-z_1),&z_1=z_2,\\
        0,&z_1\ne z_2.
    \end{cases}
\end{equation}

[Lemma 12 (Supercritical sign geometry) of arXiv:2608.20638, 'Provable Edge-of-Stability for Adam on a One-Dimensional Quadratic'] Suppose that $w_{t+1}>2$.
\begin{enumerate}[label=\textup{(\roman*)}]
\item If $x_th_t>0$, then $x_{t+1}h_{t+1}>0$ and
\begin{equation}
    \abs{x_{t+1}}>(w_{t+1}-1)\abs{x_t}.

\end{equation}
\item If $x_th_t<0$ and $x_{t+1}h_{t+1}<0$, then
\begin{equation}
    \abs{x_{t+1}}<
       \frac{\abs{x_t}}{w_{t+1}-1}.

\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma l:uc of arXiv:2603.22652, 'A cohesive account on the ergodic behaviours and scaling limits of Random Walks in Cooling'] If the environment law $\mu$ is uniformly elliptic, $\lim_k z_k = z$, and $\lim_k n_k =\infty$ then, for $m_k = |[[n_k z]]_{n_k} - [[n_k z_{k}]]_{n_k}|$ 
\begin{equation}
\liminf_k  \frac{\log {\mathbb {P}}\prt{X_{n_k - m_k} =\left[ \left[ n_kz \right] \right]_{n_k}}
  -\log {\mathbb {P}}_0\prt{X_{n_k} =\left[ \left[ n_kz_k \right] \right]_{n_k}}}{n_k} \geq 0.
\end{equation}

