[Proposition 20 (Power-law summability) of arXiv:2606.26065, 'Localized Centered Second-Chaos Operators'] Assume that, for some $C_G>0$ and $\Gamma\in\R$,
\begin{equation}
 \mathcal G(N)\le C_G N^{-\Gamma}\qquad (N\in\Dyd).
\end{equation}
If
\begin{equation}
 \Gamma>\frac d2,\qquad
 \sigma>\max\{0,d-\Gamma\},\qquad
 \beta<\Gamma-d,
 \qquad
 \zeta<\Gamma-d,
\end{equation}
then one can choose $\eps>0$ so small that
\begin{equation}
 \mathfrak S_H^{(\eps)}(\beta,\sigma)
 +\mathfrak S_B^{(\eps)}(\zeta,\sigma)<\infty.
\end{equation}

[Theorem thm:LIL of arXiv:2608.20537, 'Persistent anisotropy in multi-dimensional\\ branching Brownian motion'] Let $\beta \in \mathcal{C}^2\big([0, \infty); \mathbb{R}\big)$ satisfy $t \dot{\beta}_t \to 0$ as $t \to \infty$.
  If 
  \begin{equation}

    \int_1^\infty \frac{\mathrm{d} r}{r \exp \beta_r} = \infty,
  \end{equation}
  then almost surely, for every nonempty open $U \subset S^{d-1}$, there exist sequences $t_n \nearrow \infty$ and $p_n \in \mathcal{P}_{t_n}$ such that for all $n \in \mathbb{N}$,
  \begin{equation}

    R_{t_n}(p_n) = 2t_n + \frac{d-2}{2} \log t_n + \beta_{t_n} \quad \text{and} \quad \Theta_{t_n}(p_n) \in U.
  \end{equation}
  If (equation eq:integral-condition of the paper) does not hold, then almost surely there exists $\tau > 0$ such that for all $t > \tau,$
  \begin{equation*}
    \max_{p \in \mathcal{P}_t} R_t(p) < 2t + \frac{d-2}{2} \log t + \beta_t.
  \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem-deterministic-representation of arXiv:2411.12623, 'Random signed measures'] Any $\mu\in\mathsf{M}_S$ has the following decomposition
	\begin{equation}
		\mu=\alpha_+-\alpha_-+\sum_{k\leq\kappa_+}\beta_{+,k}\delta_{\sigma_{+,k}}-\sum_{k\leq\kappa_-}\beta_{-,k}\delta_{\sigma_{-,k}}
	\end{equation}
	where $\alpha_+,\alpha_-\in\mathcal{M}_S$ and they are atomless, $\kappa_+,\kappa_-\in\mathbb{N}\cup\{0\}\cup\{\infty\}$, $\beta_{+,1},\beta_{-,1},\beta_{+,2},\beta_{-,2},...>0$, and distinct $\sigma_{+,1},\sigma_{-,1},\sigma_{+,2},\sigma_{-,2},...\in S$. Moreover, the Jordan decomposition of $\mu$ is given by the measures
	\begin{equation*}
		\mu_+=\alpha_+\sum_{k\leq\kappa_+}\beta_{+,k}\delta_{\sigma_{+,k}}\quad\text{and}\quad \mu_-=\alpha_-+\sum_{k\leq\kappa_-}\beta_{-,k}\delta_{\sigma_{-,k}}.
	\end{equation*}
	The representations for $\mu$, $\mu_+$, and $\mu_-$ are unique up to the order of terms, and we may choose $\alpha_+$, $\alpha_-$, $\kappa_+$, $\kappa_-$, and all $(\beta_{+,k},\sigma_{+,k})$ and  $(\beta_{-,k},\sigma_{-,k})$ to be measurable functions of $\mu$, $\mu_+$ and $\mu_-$. Conversely, any locally finite sum as in $((eq-measure of the paper))$, involving measurable functions $\alpha_+$, $\alpha_-$, $\kappa_+$, $\kappa_-$, $(\beta_{+,k},\sigma_{+,k})$, $(\beta_{-,k},\sigma_{-,k})$ as above, defined on some measurable space $(A,\mathcal{B})$, uniquely determine $\mu$, $\mu_+$, and $\mu_-$ as measurable functions on $A$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:SpectralComparison of arXiv:2511.10630, 'Cutoff for generalised Bernoulli--Laplace urn models'] There exists a constant $\tilde{C} > 0$ such that for all $r \in \mathbb{N}$ and $A \subseteq \mathrm{Centre}(C)$ with $r = R(2\ell)$ and $\ell = \left\lvertA\right\rvert \leqslant \delta \left\lvert\mathrm{Centre}(C)\right\rvert$ and $\delta \in (0, 1/2]$, we have
    \begin{equation}

        \sup_{f \colon \mathrm{Centre}(C) \rightarrow \mathbb{R},\, f\vert_{A^{\mathsf{c}}} = 0,\, f \neq 0} \frac{\langle (I-P^{\textup{aux}})f, f\rangle_{\pi_{\textup{aux}}}}{\langle (I-P^{\textup{res}})f, f\rangle_{\pi_{\textup{res}}}} \leqslant \tilde{C} r^2
    \end{equation}
    for all $n$ sufficiently large. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 15 of arXiv:2604.15226, '\bfseries Nonlinear Schrödinger equations with spatial white noise potential on full space'] Let $0<\mu\le 1$ and $\beta>\frac{1}{2}$. For $u_0\in e^X(H^1(\IR^2)\cap L_\mu^2(\IR^2))$, consider the unique solution $u_\eps$ to the regularized equation associated to \eqref{Hartree}. Then there exists a unique function $u\in\CC(\IR,e^X(H^1(\IR^2)\cap L_\mu^2(\IR^2)))$ such that
\begin{equation}
\lim_{\eps\to0}\ \sup_{t\in[-T,T]}\|e^{-X_\eps}u_\eps(t)-e^{-X}u(t)\|_{H^1(\IR^2)\cap L_\mu^2(\IR^2)}=0
\end{equation}
for any $T>0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem Th:simulation_stable of arXiv:2412.06374, 'Stable and tempered stable distributions and processes: an overview toward trajectory simu'] Let $\alpha \in (0,2)$ and  $U,V$ be two independent random variables such that $U\sim \mathcal{U}\left([-\frac\pi2, \frac\pi2] \right)$ and $V\sim \mathcal{E}(1).$
Let $\theta = \alpha^{-1}\arctan\left(\beta \tan\left(\frac{\pi\alpha}{2} \right) \right)$ for  $\beta \in [-1,1]$  and $\alpha \neq 1$ then
 \begin{align}
     X \sim \begin{cases}
\frac{\sin(\alpha(\theta + U))}{\left(\cos(\alpha \theta)\cos(U)\right)^{1/\alpha}} \left(\frac{\cos(\alpha \theta + (\alpha-1)U)}{V}\right)^{(1-\alpha)/\alpha} & \text{ if } \alpha \neq 1, \\
  \frac{2}{\pi} \left[\left( \frac{\pi}{2} + \beta U\right)\tan(U) - \beta \log\left( \frac{\frac{\pi}{2}V\cos(U)}{\frac{\pi}{2}+ \beta U} \right) \right]       & \text { if } \alpha=1,
     \end{cases}
 \end{align}
 is distributed as $S_\alpha (1,\beta, 0).$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[The 25 (Alexandrov's theorem) of arXiv:2609.02879, 'On the cut locus of Hamilton--Jacobi equations I: structure and propagation via the touchi'] Let $\phi\in\text{\rm SCL}\,(\T^n)$. Then we have
