[Proposition 13 of arXiv:2608.12947, 'Branch-stationary max-stable fields on rooted trees'] Let \(Z\) be an \(\alpha\)-spectral representer satisfying
(equation 2 of the paper), and let \(\eta\) be given by
(equation 3 of the paper). The following statements are
equivalent:
\begin{enumerate}[(i)]
\item \(\eta\) is branch-stationary;
\item \(B^aZ\sim_\alpha Z\) for every \(a\in\mathcal T\);
\item the punctured tail measure is branch-invariant, i.e.,
\begin{equation}
  \nu_Z^\circ\bigl((B^a)^{-1}A\bigr)
  =
  \nu_Z^\circ(A),
  \qquad
  A\in\mathcal B(\mathcal F^\circ),\quad a\in\mathcal T,

\end{equation}
where
\[
  (B^a)^{-1}A
  =
  \{f\in\mathcal F^\circ:B^af\in A\};
\]
\item the local spectral tail fields satisfy
\begin{equation}
  B^a\Theta^{[au]}\stackrel{\mathrm d}{=}\Theta^{[u]},
  \qquad a,u\in\mathcal T;

\end{equation}
\item for every \(a,u\in\mathcal T\) and every \(F\in\mathfrak H_0\),
\begin{equation}
  \E*{
    Z_{au}^{\alpha}F(B^aZ)
  }
  =
  \E*{
    Z_u^{\alpha}F(Z)
  }.

\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 27 of arXiv:2604.07370, 'Probabilistic Weyl law for twisted Toeplitz matrices with rough symbols'] Let $\widetilde{m}$ be  an order function satisfying \eqref{Hypothèse fonction d'ordre Mildred} with $\alpha$ replaced by $t$. Let $\psi\in \mathscr{C}^\infty_c(\R)$ and consider $0<h^{1-2\eta}\ll\alpha\leq t\leq \beta$ with notations \eqref{Scaling en fonction de t}, \eqref{Scaling de q atchek en fonction de t}, \eqref{Scaling de q_0 atchek en fonction de t} and \eqref{Fonction d'ordre théorème central - version en t}. Then, under the assumptions of Theorem \ref{Théorème central}, for $a\in \{0,1\}$ the following decomposition holds:
        \begin{equation}
        \mathrm{tr}\pr{\frac{1}{t^a}\psi\pr{\frac{\atc{q}_{N,t_1,t_2}}{t}}}=N^d\Bigl(I^a_t+II^a_t+III^a_t+IV^a_t\Bigl)

    \end{equation}
    where for $k\geq 1$,
    \begin{equation}
        \begin{split}
            I^a_t &:=\frac{(h^\eta t)^d}{t^a}\int_{\mc{T}_{t_1,t_2}}\psi\pr{\frac{\atc{q}_0(\widetilde{\rho})}{t}}d\widetilde{\rho}\\
            II^a_t &:=\mc{O}_M(1)\frac{(h^\eta t)^d}{t^a}\Tilde{h}\int_{\mc{T}_{t_1,t_2}}\widetilde{\chi}\pr{\frac{\atc{q}_0(\widetilde{\rho})}{t}}d\widetilde{\rho}\\
            III^a_t &:= \mc{O}_M(1)\frac{(h^\eta t)^d}{t^a}\Tilde{h}^M\int_{\mc{T}_{t_1,t_2}}\widetilde{m}(\widetilde{\rho})d\widetilde{\rho}\\
            IV^a_t &:= \mc{O}_k(1)\frac{(h^\eta t)^d}{t^a}\pr{Nh^\eta t^{1/2}}^{-k}\int_{\mc{T}_{t_1,t_2}}\widetilde{m}(\widetilde{\rho})d\widetilde{\rho}.
        \end{split}

    \end{equation}
    and where $\widetilde{\chi}\in \mathscr{C}^{\infty}_c(\R;[0,1])$ is such that $\widetilde{\chi}\equiv 1$ on a neighborhood of $[0,\sup\mathrm{supp}(\psi)]$.

