[Definition def:first-second-functionals-fg of arXiv:2607.22156, 'A random matrix approach to lamplighter groups'] Let $x,y\in\mathbb{C}[G]$. The first and second order distributions are defined by
    \begin{align*}
        \Phi^{(1)}(x) &:=\lim_{N\rightarrow\infty}\frac{1}{N}\mathbb{E}\left[\mathrm{Tr}(x_{N})\right],\\
        \Phi^{(2)}(x,y)&:=\lim_{N\rightarrow\infty}\frac{1}{N}\mathbb{E}\left[\left(\mathrm{Tr}(x_{N})-\mathbb{E}[\mathrm{Tr}(x_{N})]\right)\left(\mathrm{Tr}(y_{N})-\mathbb{E}[\mathrm{Tr}(y_{N})]\right)\right].
    \end{align*}

[Lemma lem:latala-iid-centered-sum of arXiv:2608.11084, 'Sharp Frobenius-Norm Concentration for Sample Moment Tensors'] {latala1997estimation}}]

Let \(Y_1,\ldots,Y_N\) be independent copies of a centered real-valued
random variable \(Y\). Then, for every \(q\ge2\) such that \(Y\in L_q\),
\begin{equation}
\bigg\|
\sum_{i=1}^N Y_i
\bigg\|_{L_q}
\asymp
\sup_{\max\{2,q/N\}\le s\le q}
\frac qs
\mathopen{}\mathclose\bgroup\originalleft(\frac Nq\aftergroup\egroup\originalright)^{1/s}
\|Y\|_{L_s}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 11 ({cf.~\cite{bhatt2022Prismatic}*{Remark 2.5.5}}) of arXiv:2609.00567, 'Hodge--Tate splitting and Akizuki--Nakano vanishing in positive characteristic'] Let \(A\) be a commutative ring, let \(\mcalG\) be a flat affine group scheme over \(U\defeq\Spec(A)\), and let
  \begin{equation*}
    f\colon B_U\mcalG\to U
  \end{equation*}
  be the structure morphism.
  Let \(q\colon U\to B_U\mcalG\) be the canonical fpqc cover, let \(q_\bullet\colon U^\bullet\to B_U\mcalG\) be its \v{C}ech nerve, and let \(p_n\colon U^n\to U\) be the structure morphism, which can be identified with the projection \(\mcalG^n \to U\).

  For \(\mcalF\in\mcalD^+_{\qcoh}(B_U\mcalG)\), put
  \begin{equation*}
    \mcalF_n\defeq Lq_n^*\mcalF \in \mcalD_{\qcoh}(U^n),\qquad K_{\mcalF}^n\defeq R(p_n)_{*}\mcalF_n \in \mcalD_{\qcoh}(U) \cong \mcalD(A).
  \end{equation*}
  Then the following assertions hold.
  \begin{enumerate}
    \item There is a canonical equivalence
    \begin{equation}

      Rf_*\mcalF\xrightarrow{\sim}\Tot(K_{\mcalF}^\bullet)
    \end{equation}
    in \(\mcalD_{\qcoh}(U)\simeq\mcalD(A)\).
    \item If \(\mcalF\in\mcalD^{\geq c}_{\qcoh}(B_U\mcalG)\), then \(K_{\mcalF}^n\in\mcalD^{\geq c}(A)\) for every integer \(n\geq0\).
    \item For every flat ring homomorphism \(A\to A'\), write \(g\colon U'\defeq\Spec(A')\to U\) for the induced morphism, put \(\mcalG_{U'}\defeq\mcalG\times_UU'\), and write \(f'\colon B_{U'}\mcalG_{U'}\to U'\) for the structure morphism, and \(g'\colon B_{U'}\mcalG_{U'}\to B_U\mcalG\) for the projection. Then the base change morphism
    \begin{equation}

      A'\otimes_A^LRf_*\mcalF\to Rf'_*L(g')^*\mcalF
    \end{equation}
    is an equivalence in \(\mcalD_{\qcoh}(U')\simeq\mcalD(A')\).
  \end{enumerate}

