body:
[Theorem thm1 of arXiv:2510.17257, 'Rigidity of One-Dimensional Point Processes via Optimal Transport'] In dimension $d=1$, let $\mathsf{P}\in\mathscr{P}_s(\Gamma)$ be the law of a stationary point process. Under the assumption 
	\eq{\mathsf{Wass}_1(\mathsf{P},\mathsf{P}^{\mathbb{Z}})<+\infty,} 
	the point process $\mathsf{P}$ is Number-Rigid and has a Cyclic-Factor. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem le:limit_theorem_L2 of arXiv:2506.17168, '{\bf Scaling limits for sample autocovariance operators of Hilbert space-valued linear pro'] Let $\{X_{n}\}_{n \in \mathbb Z}$ be an $L^2(\mathbb{Y})$-valued linear process (equation eq:XninL2 of the paper) and consider its autocovariance operators $(\widehat \gamma_{N,h}, h = 0,\dots,H)$ given in (equation eq:gammars of the paper). Suppose $ d(s) \in \left(\frac{1}{4},\frac{1}{2}\right)$, 
\begin{equation} 
  \operatorname{E} \| \varepsilon_{0} \|^4_{L^4(\mathbb{Y})} < \infty. 
\end{equation}
and
\begin{equation} 
\int_{\mathbb{Y}} \frac{\sigma^2(r)}{(1-2d(r))(2d(r)-1/2)}	\mu(dr)  < \infty.
\end{equation}
Then, 
\begin{equation*}
\Xi_N \begin{pmatrix}
    \widehat{\gamma}_{N,0}-\gamma_{0} \\
    \vdots 
    \\
    \widehat{\gamma}_{N,H}-\gamma_{H}
\end{pmatrix} 
\overset{\operatorname{d}}{\to}
\begin{pmatrix}
    \mathfrak{R} \\
    \vdots \\
     \mathfrak{R}
\end{pmatrix}
 \in L^2(\mathbb{Y}^2:\mathbb R^{(H+1)}),
\end{equation*}
where $\mathfrak{R}$ is given in (equation equality_f^(u,l)_t,(m,s) of the paper) below and $\Xi_N$ in (equation eq:Xi-def of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 23 of arXiv:2510.20492, 'Heterochromatic two-arm probabilities for metric graph Gaussian free fields'] For any $3\le d\le 5$ and $\epsilon>0$, there exist $\Cl(d,\epsilon),\cl(d,\epsilon)>0$ such that for any $n\ge \Cref{const_lemma_separation1}$, $N\ge \Cref{const_lemma_separation1}n$, $\psi\in \Psi(n,N)$, $\diamond\in \{\mathrm{in},\mathrm{out}\}$, $i\in \{ 1,2\}$, and any line segment $\widetilde{\eta}\subset \mathfrak{B}_{m_{\diamond},100}^{\diamond}$ satisfying $\mathrm{vol}(\widetilde{\eta})\le 100m_\diamond$ and $\mathrm{dist}(z_i^{\diamond},\widetilde{\eta})\ge \frac{m_\diamond}{100}$, 
	 \begin{equation}
	 	\mathbb{P}\big( \mathsf{R}_i^{\diamond}[\psi, \cref{const_lemma_separation2}, \widetilde{\eta}] \mid    \mathsf{C}[\psi] \big) \le \tfrac{1}{4} \epsilon. 
	 \end{equation}
	Particularly, by taking $\widetilde{\eta}=\{z_{3-i}^\diamond\}$, this implies 
\begin{equation}
		\mathbb{P}\big( \mathsf{S}[\psi,\cref{const_lemma_separation2}] \mid    \mathsf{C}[\psi] \big)\le   \epsilon.
	\end{equation}
	Consequently, there exists $\cl>0$ such that 
	\begin{equation}
		\mathbb{P}\big(     \widehat{\mathsf{C}}[\psi, \cref{const_lemma_separation3}] \big)\asymp  \mathbb{P}\big(  \mathsf{C}[\psi] \big), \ \forall \psi\in \Psi(n,N). 
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm hyc of arXiv:2507.02518, '{\bf Exponential Ergodicity in Relative Entropy and $L^2$-Wasserstein Distance for non-equ'] Assume  {\bf(B)} and $\sigma\sigma^\ast$ is invertible. Then (equation Degth1 of the paper) has a unique invariant probability measure $\bar{\mu}\in\mathscr P_2(\mathbb R^{2d})$ and there exists a constant $t_1>0$ such that $P_{t_1}^\ast $, the adjoint operator of $P_{t_1}$ in $L^2(\bar{\mu})$, is hypercontractive, in the sense that
\begin{align}
\|P_{t_1}^\ast\|_{L^{\frac{4}{3}}(\bar{\mu})\rightarrow L^{2}(\bar{\mu})}= 1.
\end{align}
Consequently, there exist constants $c,\tilde c,\lambda>0$ such that
\begin{align} \mathrm{Ent}(\mathscr L_{(X_t^{\mu_0},Y_t^{\mu_0})}|\bar{\mu})\leq c\text{\rm{e}}^{-2\lambda t}\mathrm{Ent}(\mu_0|\bar{\mu}),~ t\geq 0, \mu_0\in\mathscr P(\mathbb R^{2d}),
\end{align}
and
\begin{align}\mathbb W_2(\mathscr L_{(X_t^{\mu_0},Y_t^{\mu_0})},\bar{\mu})\leq \tilde c\text{\rm{e}}^{-\lambda t}\mathbb W_2(\mu_0,\bar{\mu}),\ \ t\geq 0, \mu_0\in\mathscr P_2(\mathbb R^{2d}).
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 15 (Harris--FKG--Inequality) of arXiv:2504.02435, 'Poisson-Voronoi percolation in higher rank'] In the above setting, $\omega_p^{(\lambda)}$ satisfies the Harris-FKG-Inequality, i.e.~
    \begin{equation*}
        \mathbb P_p^{(\lambda)} (A_1 \cap A_2) \geq \mathbb P_p^{(\lambda)} (A_1) \mathbb P_p^{(\lambda)} (A_2)
    \end{equation*}
    for every increasing events $A_1$ and $A_2$.

[Definition 9 of arXiv:2606.22964, 'Signature McKean--Vlasov stochastic differential equations'] Let $(p,\alpha)\in(1,\infty)\times(0,1)$ with $p\alpha<1$. We define $C^{\alpha,p}_o([0,T],G^{\lfloor 1/\alpha\rfloor}(\mathbb{R}^k))$ as the set of continuous paths $\mathbf{x}:[0,T]\rightarrow G^{\lfloor 1/\alpha\rfloor}(\mathbb{R}^k)$ such that $\mathbf{x}_0=(1,0,\dots,0)$ and
    \begin{equation*}
        \begin{aligned}
            &\lVert \mathbf{x} \rVert_{\textup{hom $p$-var};[0,T]} + \lVert \mathbf{x} \rVert_{\textup{hom $\alpha$-H\"{o}l};[0,T]} < \infty\\(\textit{equiv.}\; &\lVert \mathbf{x} \rVert_{\textup{inhom $p$-var}} + \lVert \mathbf{x} \rVert_{\textup{inhom $\alpha$-H\"{o}l};[0,T]} < \infty).
        \end{aligned}
    \end{equation*}
    Moreover, we define
    \begin{equation*}
        \begin{aligned}
            &\widehat{C}^{\alpha,p}_o=\widehat{C}^{\alpha,p}_o([0,T],G^{\lfloor 1/\alpha\rfloor}(\mathbb{R}^{k+1})) :=\\
            &:= \Big\{\widehat{\mathbf{x}}\in C_o^{\alpha,p}([0,T],G^{\lfloor 1/\alpha\rfloor}(\mathbb{R}^{k+1})) \,:\, \widehat{\mathbf{x}}^{(1)}=\left(t,\mathbf{x}^{(1)}\right)\;\forall\,t\in[0,T],\,\mathbf{x}\in C^{\alpha,p}_o([0,T],G^{\lfloor 1/\alpha\rfloor}(\mathbb{R}^k))\Big\}.
        \end{aligned}
    \end{equation*}

[Thm t:P0 of arXiv:2504.07255, 'A Tail-Respecting Splitting Numerical Scheme\\ for L\'evy-Driven SDEs With Superlinear Dri'] Let assumptions $\mathbf{H}^\mathrm{diss}_A$, $\mathbf{H}_{a,b,c}^{\mathrm{Lip}_b}$,
$\mathbf{H}_{\nu,p},$
$\mathbf{H}_A^{\mathrm{Lip}_+}$,
and
$\mathbf{H}_{A_x,A_{xx}}$ hold.
Then, for any $T\in[0,\infty)$, any
$p_X\in [p, p+\kappa-1)$
and any
\begin{equation}\begin{aligned}

\gamma
<\begin{cases}
\frac{p(p+\kappa-1 - p_X)}{(\chi+2)(\kappa-1)+\chi p},&\quad p\leq \chi+2, \\
\frac{p+\kappa-1 - p_X}{\kappa+\chi-1},  &\quad  p> \chi+2,
\end{cases}
\end{aligned}\end{equation}
we have
\begin{equation}\begin{aligned} \sup_{t\in[0,T]}
 \mathbf{E}\|X^n_t-X_t\|^{p_X}
\leq_C  h_n^{\gamma }(1+\|x\|^{p+\kappa-1}),\quad x\in\mathbb{R}^d.
\end{aligned}\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def-u-m of arXiv:2604.24914, 'SPDEs with time-independent\\ L\'evy colored noise'] {\rm The process $\{u(t,x);t\geq 0,x\in \mathbb{R}^d\}$ with $\mathbb{E}|u(t,x)|^2<\infty$ for all $(t,x) \in \mathbb{R}_{+} \times \mathbb{R}^d$ and the Poisson-chaos expansion:
\begin{equation}

u(t,x)=1+\sum_{n\geq 1}I_n\big(f_n^{*}(\cdot,x;t)\big),
\end{equation}
is the {\bf (Skorohod) solution} of equation (equation mult-eq of the paper), provided that $f_n^{*}(\cdot,x;t)\in \mathcal{H}^{\otimes n}$ for any $(t,x)\in \mathbb{R}_{+}\times \mathbb{R}^d$ and $n\geq 1$, and the series converges in $L^2(\Omega)$.
}

[Lemma 26 of arXiv:2511.07350, 'Decoupling of clusters in independent sets in a percolated hypercube'] For all $p > \f12 - \gamma$, where $\gamma > 0$ is defined as in Proposition \ref{prop:dimers},
\begin{equation}
	\P\left[\AS \text{ fails at step \ref{step:fail2_shatconstruct}} \middle| \AS \text{ does not fail at step \ref{step:fail1_s1construct}} \right] \pto 0
\end{equation}

[Lemma 43 (Useful identities for the first fundamental forms; \cite{abbrescia2022emergence}*{Lemma\,3.15}) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] Let $\smoothtorusproject$, 
$\gtorus$,
$g$,
and $X$ be as in Defs.\,\ref{D:FIRSTFUNDAMENTALFORMS},
\ref{D:PROJECTIONTENSORFIELDSANDTANGENCYTOHYPERSURFACES},
and\,\ref{D:COMVECTORFIELDS}.
Then the following identities hold relative to the geometric coordinates ($A,B = 2,3$):
\begin{subequations}
\begin{align}
\gtorus_{AB} & = \Speed^{-2} \updelta_{AB} +\Speed^{-2} \frac{X^AX^B}{(X^1)^2}, 

		\\ 
(\gtorus^{-1})^{AB}
& 
= \Speed^2 \updelta^{AB} - X^A X^B, 

		\\
\mydet \gtorus & = \frac{1}{\Speed^2 (X^1)^2}. 

\end{align}
\end{subequations}Moreover, the following identities hold relative to arbitrary coordinates:
\begin{subequations}
	\begin{align} 
		g_{\alpha \beta}
		& =
		\gfour_{\alpha \beta} 
		+
		\Transport_{\alpha} \Transport_{\beta},
			\\
		(g^{-1})^{\alpha \beta}
		& 
		=
		(\gfour^{-1})^{\alpha \beta} 
		+
		\Transport^{\alpha} \Transport^{\beta}.

	\end{align}
\end{subequations}Furthermore, the following identities hold relative to the Cartesian coordinates:
\begin{subequations}
	\begin{align}
		g
		& = \Speed^{-2} \sum_{a=1}^3 (\rmd x^a - v^a \rmd t)\otimes  (\rmd x^a - v^a \rmd t),

				\\
		g^{-1}
		& = \Speed^2 \sum_{a=1}^3 \p_a \otimes \p_a.

	\end{align}
\end{subequations}In addition, the following identities hold relative to arbitrary coordinates:
\begin{subequations}
	\begin{align}
			\gtorus_{\alpha \beta}
			& = 
			g_{\alpha \beta} 
			-
			X_{\alpha} X_{\beta}
			=
			\gfour_{\alpha \beta} 
			+
			\Transport_{\alpha} \Transport_{\beta}
			-
			X_{\alpha} X_{\beta}
			= \gfour_{\alpha \beta} 
				+
				\Lunit_{\alpha} \Lunit_{\beta}
				+
				\Lunit_{\alpha} X_{\beta}
				+
				X_{\alpha} \Lunit_{\beta},

				\\
		(\gtorus^{-1})^{\alpha \beta}
		& = 
			(g^{-1})^{\alpha \beta} 
			-
			X^{\alpha} X^{\beta}
			=
			(\gfour^{-1})^{\alpha \beta} 
			+
			\Transport^{\alpha} \Transport^{\beta}
			-
			X^{\alpha} X^{\beta}
			=
				(\gfour^{-1})^{\alpha \beta}
				+
				\Lunit^{\alpha} \Lunit^{\beta}
				+
				\Lunit^{\alpha} X^{\beta}
				+
				X^{\alpha} \Lunit^{\beta},

				\\
		\smoothtorusproject^{\ \alpha}_\beta 
		& = 
		\gfour_{\beta \gamma}
		(\gtorus^{-1})^{\alpha \gamma}
		=
		\gtorus_{\beta \gamma}
		(\gtorus^{-1})^{\alpha \gamma}.

	\end{align}
\end{subequations}Finally, relative to the Cartesian coordinates, the following identities hold for $\alpha, \beta = 0,1,2,3$:
\begin{subequations}
\begin{align} 
		(\gtorus^{-1})^{0 \alpha}
		& 
		=
		(\gtorus^{-1})^{\alpha 0}
		= 0,
			\\
		(g^{-1})^{0 \alpha}
		& 
		=
		(g^{-1})^{\alpha 0}
		= 0,

			\\
	\smoothtorusproject^{\ 0}_{\beta}
	& = 0.

\end{align}
\end{subequations} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 53 (Colored Newton lift) of arXiv:2608.29585, '2608.29585'] For every zero-framed knot $K$ and every $n\ge2$, the series
\begin{equation}
 \mathscr J_K^{(n)}(x,q)=\sum_{k=0}^{\infty}
 P_k^{(n)}(x,q)H_k^{(n)}(K;q)
\end{equation}
defines an element of $\widehat{\mathscr R}_n$.  For every $r\ge0$,
\begin{equation}
 \mathscr J_K^{(n)}(q^r,q)=J_r^{SU(n)}(K;q).
\end{equation}

