[Lemma L3 of arXiv:2608.22945, 'A Momentum-Based Variance-Reduced Algorithm for Federated Multiobjective Optimization'] Suppose that Assumptions (A1 of the paper)--(A2 of the paper) hold. If $\gamma L\leq\sqrt{\frac{\beta KM}{54}}$, then, for all $t\ge1$,
	\begin{align*}
	\mathcal{E}_s^t\leq(1-\beta)\mathcal{E}_s^{t-1}+\frac{4}{\beta}L^2U_s^t+\frac{3\beta^2\sigma^2}{KM}+\frac{2\beta}{9}\mathbb{E}[\|g^{t-1}\|^2].
	\end{align*}
and for $t=0$, 
\begin{align*}
	\mathcal{E}_s^0\leq(1-\beta)\mathcal{E}_s^{-1}+\frac4\beta L^2U_s^0+\frac{3\beta^2\sigma^2}{KM}.
\end{align*}

[Lem idlaw of arXiv:2602.21277, 'A Limit in Law for the Cover Time and Last Visited Vertex of Wired Planar Domains'] Given $T \in \mathbb N$, the random walk $\widetilde{X}^{[0,T]}$ satisfies:
\begin{itemize}
\item [\rm{i.}] For any $i=0,\dots,T-1$, $j=i,\dots,T-1$, $v \in \mathcal N_k$ and $m \in \mathbb{N}$, conditional on $T_{\widetilde{v}_k}(T-i)=m$, 

\begin{equation}
T_{\widetilde{v}_k}(T-j) \sim \Bigeo\left(m, \frac{1}{j-i+1},\frac{1}{j-i+1}\right)	.
\end{equation}
 	\item [\rm{ii.}] For any $i=1,\dots,T$ and $v \in \mathcal N_k$, 
	\begin{equation}
	\widetilde{L}_{(v)}(T-i) \sim \Biexp\left(\widetilde{v}_k,\frac{1}{i};\frac{1}{i}\right).
\end{equation}
	\item [\rm{iii.}] For any $i=0,\dots,T-1$, $j=i,\dots,T-1$ and $\theta >0$, conditional on $\sqrt{\widetilde{L}_{(v)}(T-i)}=\theta$, 
\begin{equation}
T_{\widetilde{v}_k}(T-j) \sim \Poigeo\left(\frac{\widetilde{\theta}_k}{j-i+1};\frac{1}{j-i+1}\right).
\end{equation}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

