[Definition 17 ({cf.\ \cite[Section~2.2) of arXiv:2608.30549, '\vspace{-1cm}Maximally Spread Out Measures and Implications\\{} for Phase Transitions in A'] {GrohsCartoonApproximation}
  and \cite[Definition~6.1]{VoigtlaenderPeinAnalysisVSSynthesisSparsityAlphaShearlets}}]

  Let $\nu \geq 1$ and fix ${0 < \varrho_0 \leq \frac{1}{4} < \frac{1}{2} \leq \varrho_1 < 1}$.
  Then the family of \emph{star-shaped subsets of $\R^2$ with $C^{2}$ smooth boundary}
  is defined as
  \[
    \mathrm{STAR}^{2} (\nu; \varrho_0, \varrho_1)
    := \biggl\{
         x_0 + S_{\varrho}
         \,\,:\,\,
         \begin{array}{l}
           x_0 \in \R^2 \text{ and } \varrho \in C^{2}_{2 \pi}(\R)
           \text{ with } \| \varrho'' \|_{L^\infty} \leq \nu , \\
           \varrho_0 \leq \varrho \leq \varrho_1 ,
           \text{ and } x_0 + S_{\varrho} \subset [0,1]^2
         \end{array}
       \biggr\}
    ,
  \]
  where $C_{2\pi}^{2}(\R)$ denotes the set of all $2 \pi$-periodic $C^2$ functions
  $\varrho : \R \to \R$, and where
  \begin{equation}
    S_{\varrho}
    := \biggl\{
         r \cdot \begin{pmatrix} \cos(\phi) \\ \sin(\phi) \end{pmatrix}
         \,\,:\,\,
         \phi \in [0,2\pi] \text{ and } 0 \leq r \leq \varrho(\phi)
       \biggr\}
    \subset \R^2
    .

  \end{equation}

[Defn leftconv of arXiv:2608.06500, 'Free energy of Ising models under a spectral condition'] Let $G=(\text{\boldmath $A$},\text{\boldmath $h$}_1,\ldots,\text{\boldmath $h$}_k)$ be a weighted graph on vertex set
    $[N]$ and $X=(\text{\boldmath $W$},\text{\boldmath $d$}_1,\ldots,\text{\boldmath $d$}_k)$ be a test graph on vertex
    set $[n]$. We define the \emph{weighted homomorphism density}
    $t(X,G)$ as the quantity

    \begin{align}
    t(X,G):=\frac1{N^{c(X)}} \sum_{f:[n]\rightarrow[N]} \left(
    \prod_{i\in[n]} \prod_{\ell=1}^k h_{\ell,f(i)}^{d_{\ell,i}}
    \right) \left( \prod_{i\le j\in[n]} a_{f(i)f(j)}^{w_{ij}}
    \right)\, .
    \end{align}

    We say that a sequence $G_1,G_2,\ldots$ of weighted graphs is
    \emph{left-convergent} if for all test graphs $X$, the sequence
    $t(X,G_1),t(X,G_2),\ldots$ converges to a finite value.

[Proposition 21 (Spike-profile bounded analytic LSS input) of arXiv:2608.07820, 'Linear Spectral Statistics for Entrywise-Transformed Spiked Wigner Matrices under Shifted '] Assume W3--W5 and the spike assumption \eqref{eq:spike-package}.  Let
\(H_N=H_N^{(4)}\) be the centered atomic array
\eqref{eq:R3-centered-array}, put
\(S_{ij}:=\E H_N(i,j)^2\), and let \(S_N^0\) be
\eqref{eq:R3-flat-S}.  Then
\begin{align}
 |\sqrt N H_N(i,j)|&\le C,\\
 \max_{i\ne j}|NS_{ij}-1|&\to0,\\
 \max_i\left|\sum_jS_{ij}-1\right|&=o(N^{-1/2}),
 \\
 \max_i\sum_j|S_{ij}-S_{ij}^0|&\to0,\\
 \norm{S_N-S_N^0}_{\HS}&\to0.
\end{align}
Let \(m_{i,N}(z)\) be the vector Dyson-equation solution
\begin{equation}
 -\frac1{m_{i,N}(z)}
 =z+\sum_jS_{ij}m_{j,N}(z),
 \qquad
 \overline m_N(z):=\frac1N\sum_i m_{i,N}(z),
\end{equation}
and let \(\overline m_N^0\) denote the corresponding scalar solution for
\(S_N^0\).  Moreover,
\begin{equation}
 \max_{i<j}\left|
 \cum_4(\sqrt N H_N(i,j))-\kappa_4^{f,\nu}
 \right|\to0.
\end{equation}
For a function \(\varphi\) analytic near \(\Gamma\), define the
zero-diagonal Dyson-density correction
\begin{equation}
 d_{\varphi,\Gamma,N}^{0,\rm Dyson}
 :=-\frac{N}{2\pi\ii}\oint_\Gamma
 \varphi(z)\bigl(\overline m_N^0(z)-m(z)\bigr)\,\dd z.
\end{equation}
Then, for every finite family of such functions, there are deterministic
bounded-endpoint biases \(m_{\varphi,\Gamma,N}^{\rm fluc}\) such that
\begin{equation}
 \left(
 \Tr\varphi_\ell(H_N)
 +\frac{N}{2\pi\ii}\oint_\Gamma
       \varphi_\ell(z)\overline m_N(z)\,\dd z
 -m_{\varphi_\ell,\Gamma,N}^{\rm fluc}
 \right)_\ell
 \Longrightarrow (G_{\varphi_\ell})_\ell .
\end{equation}
The bias not contained in the exact Dyson density satisfies
\begin{equation}
 m_{\varphi,\Gamma,N}^{\rm fluc}
 +d_{\varphi,\Gamma,N}^{0,\rm Dyson}
 \longrightarrow m_{\varphi,\Gamma}^{\rm base}(\kappa_4^{f,\nu}),
\end{equation}
and the limiting covariance is
\(\mathcal V_{\kappa_4^{f,\nu}}^\Gamma\).  No convergence or homogeneity of
the edgewise third cumulants is assumed.

[Lemma l.R,A_rel of arXiv:2411.14105, 'Simultaneous replica-symmetry breaking \\ for vector spin glasses'] Let $\Phi$ and $X$ be associated with some decomposition $(L,\alpha)$.
For $t\in [0,T]$, define
\begin{gather}
    R(t) = \mathbb{E} \left[\nabla\Phi\nabla\Phi^\intercal(t,X_t)\right];
    \qquad
    A_t= \nabla^2\Phi(t,X_t). 
\end{gather}
Then, the following holds for every $t\in[0,T]$:
\begin{gather}
    R(t) = R(0)+ 2 \int_0^t \mathbb{E} \left[A_r^\intercal \accentset{\mbox{\large\bfseries .}}{L}(r) A_r\right]\mathrm{d} r; 
    \\
    \mathbb{E} \left[A_t\right] = \mathbb{E} \left[A_T\right] + \int_t^T \alpha(r)\accentset{\mbox{\large\bfseries .}}{R}(r)\mathrm{d} r.
\end{gather} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 4 (Cumulant expansion) of arXiv:2605.14630, '2605.14630'] Let $X$ be a random variable such that $\expec{\e^{tX}}$ exists for all $t$ 
in an open interval $(-\delta,\delta)$, and write 
\begin{equation}

 \expec{\e^{tX}} = \sum_{n\geqs0} \mu_n\frac{t^n}{n!}\;, 
 \qquad 
 \mu_n = \expec{X^n}\;.
\end{equation} 
Then the \emph{cumulant expansion} of $X$ is given by 
\begin{equation}

 K_X(t) = \log\expec{\e^{tX}}
 = \sum_{n\geqs0} \kappa_n \frac{t^n}{n!}\;.
\end{equation} 
The coefficients $\mu_n$ are called \emph{moments} of $X$, while the 
$\kappa_n$ are called \emph{cumulants}.

[Theorem 14 (generalized moving-subspace bound) of arXiv:2609.03736, '2609.03736'] Let $(\rho,\Lambda)$ be a positive survival datum for
$(\mathsf G,\mathsf H,E,\ell,\Omega)$, and let $\tau<\Lambda$.  Write
\begin{equation}
 D_\rho=\dim\ran\rho,
 \qquad
 r_\rho=\rank K_\rho(o,o).

\end{equation}
Then
\begin{equation}
 \vartheta'(\mathfrak G_t(\tau))\leq
 \frac{1-\tau}{\Lambda-\tau}\frac{D_\rho}{r_\rho}.

\end{equation}

[Prop constant maps general fivefold of arXiv:2609.02409, 'Membranes and Maps'] (conj:index of the paper) is equivalent to the claim that for all Calabi--Yau fivefolds $Z$ with the action of a torus $\mathsf{T}$ fixing the Calabi--Yau form we have
    \begin{equation}

        \GWargs{Z}{\mathsf{T}}{0}
        =
        \frac{1}{2}
        \sum_{g>1}
        \frac{B_{2g-2}}{2g-2}
        \left[
            \ch[\mathsf{T}]\,\chi_{\mathsf{T}}\big(Z,T_{Z}-T_{Z}^\vee\big)
        \right]_{2g-2}
        u^{2g-2} \,,
    \end{equation}
    where $\left[\cdot\right]_{2g-2}$ denotes the cohomological degree $(2g-2)$-part.

