body:
[Thm 61 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] Fix $t>0,\;x,y\in F,$ and $x_n,y_n\in F_n$.
Suppose that $(F,R,\mu)$ satisfies $\rm{(A1)}$
for $s_0,s_1>0$ with $s_0<s_1+1$,
and that
\begin{align*}
  h:=d_{\rm{H}}(F,F_n)^{\kappa}+d_{\BL^{\kappa}}(\mu,\mu_n)+d(x,x_n)+d(y,y_n)
\end{align*}
is less than $1/2$.
\begin{itemize}
  \item [$\mathrm{(i)}$]For each $\kappa\in [1/2,2/3)$, it holds that
\begin{align*}
  |p(t,x,y)-p_n(t,x_n,y_n)|\lesssim h^E,
\end{align*}
where
\begin{align*}
  E=\frac{2(s_1-s_0+1)}{\left\{ (2\kappa+5)s_0+2\kappa+4 \right\}(s_1+2)+2(s_1-s_0+1)}.
\end{align*}
Moreover, the time-dependence of the constant in $\lesssim$ is $t^{-2},\;t\in (0,1]$.
\item[$\mathrm{(ii)}$]If $(F,R,\mu)$ satisfies the assumption $\mathrm{(A2)}$, then it holds for $\kappa\in [1/2,1]$ that
\begin{align*}
  |p(t,x,y)-p_n(t,x_n,y_n)|\lesssim h^E,
\end{align*}
where
\begin{align*}
  E=\frac{s_1-s_0+1}{(\kappa+2)(1+s_0)(s_1+2)+\frac{s_0}{2}+(s_1-s_0+1)}.
\end{align*}
Moreover, the time-dependence of the constant in $\lesssim$ is $t^{-2},\;t\in (0,1]$.
\item[$\rm{(iii)}$]If $(F,R,\mu)$ satisfies the assumption $\mathrm{(A3)}$, then it holds for $\kappa\in [1/2,1]$ that
\begin{align*}
  |p(t,x,y)-p_n(t,x_n,y_n)|\lesssim  h^{E_1}(\log(1/h))^{E_2},
\end{align*}
where
\begin{align*}
  E_1=\frac{s_1-s_0+1}{(2+\kappa)(1+s_0)\Theta+\frac{s_0}{2}+(s_1-s_0+1)},
  \quad E_2=\frac{(2+\kappa)\{s_1+2(2+s_0)(s_0-s_1)\}}{1-(2+s_0)(s_0-s_1)},
\end{align*}
and $\Theta=\frac{1+s_0-s_1}{1-(s_0-s_1)(2+s_0)}$.
Moreover, the time-dependence of the constant in $\lesssim$ is $t^{-2},\;t\in (0,1]$.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 7 (Exponential stability) of arXiv:2608.22636, 'Q-Learning with Stable Infinite-Dimensional \\Linear Function Approximation'] For $\theta\in\Theta$, there exists a unique solution $\vartheta_{\mrm U}(t;\theta)\in\Theta$ for all $t\ge 0$ to 
\begin{equation}
        \vartheta_{\mrm U}(t;\theta)
        =
        \theta+
        \int_0^t\cH_{\mrm U}\vartheta_{\mrm U}(s;\theta)ds        
\end{equation}
such that
\begin{equation}
        \norm{\vartheta_{\mrm U}(t;\theta)-\theta^*}
        \le
        e^{-c_\wedge(1-\gamma)t}\norm{\theta-\theta^*}.

\end{equation}

