 \begin{cases}
    C\left\{\left|x_0-\tilde{x}_0\right|^{\alpha-1}+ \max\left\{B_\infty^{(\alpha\tilde{\eta}-1)/(\alpha\tilde{\eta}-\alpha+1)}, S_\infty^{\alpha-1/\tilde{\eta}}\right\}\right\}& \textrm{if~~}\tilde{\eta} \in(1/\alp

