body:
[Proposition prop:shmp of arXiv:2411.09516, 'Sharp Matrix Empirical Bernstein Inequalities\footnote{NeurIPS 2025 Poster}'] Let $X_1,\dots, X_n$ be $[0,1]$-bounded independent random scalars with common mean $\mu$ and variance $\sigma^2$. We denote by $\overline{X}_n$ their sample average and $\hat \sigma_n^2$ the Bessel-corrected sample variance. Then, for any $\alpha\in(0,1)$, $
      \mathbb P \left(  \overline X_n  - \mu  \geqslant \rho_n   \right) \leqslant \alpha$,
where
\begin{equation}
    \rho_n = \frac{ \log\frac{n}{(n-1)\alpha}  }{3n} + \sqrt{\frac{2 \hat \sigma^2_n \log\frac{n}{(n-1)\alpha} }{n}}  + 2 \sqrt{\frac{\left( \log\frac{n}{(n-1)\alpha}  \right) \left( \log \frac n\alpha  \right)}{n(n-1)}}.
\end{equation}
Further, with i.i.d.\ $X_1,\dots, X_n$,
\begin{equation}
    \lim_{n \to \infty} \sqrt{n} \rho_n =  \sqrt{2 \sigma^2 \log(1/\alpha)}, \quad \text{almost surely}.
\end{equation}

