[Maintheorem 2 (Navier--Stokes endpoint atoms force local pressure concentration) of arXiv:2608.30715, 'Endpoint Energy Atoms Force Local Pressure Concentration in Three-Dimensional Navier--Stok'] Let \(u\) be a Leray--Hopf solution of \eqref{eq:NS-intro} that is smooth
on every compact subinterval of \([t_b,T_*)\). Suppose that for some sequence
\(t_k\uparrow T_*\),
\begin{equation}
 \abs{u(t_k,x)}^2\dd x\weakstarto\mu_*,
 \qquad \mu_*(\{a\})=m>0.

\end{equation}
For \(\tau\in(t_b,T_*)\), let
\begin{equation}
 z_\tau=S(t,\tau)u(\tau),\qquad
 g_\tau=\Qq z_\tau,\qquad
 r_\tau=u-z_\tau.

\end{equation}
Then, for every fixed \(\tau\in(t_b,T_*)\) and every \(t\in(\tau,T_*)\),
\begin{equation}
 \frac12\norm{r_\tau(t)}_2^2
 +\nu\int_\tau^t\norm{\nabla r_\tau(\rho)}_2^2\dd\rho
 =\int_\tau^t\ip{\nabla p(\rho)}{g_\tau(\rho)}\dd\rho,

\end{equation}
and
\begin{equation}
 \limsup_{t\uparrow T_*}
 \int_\tau^t\ip{\nabla p}{g_\tau}\dd\rho\ge\frac m2.

\end{equation}
More quantitatively, fix \(s\in(t_b,T_*)\) and let \(R_n\downarrow0\).
There are \(\tau_n\uparrow T_*\), with \(\tau_n>s\), such that
\begin{equation}
 \frac{A(\tau_n)}{R_n}
 +\frac{\sqrt{\nu(T_*-\tau_n)}}{R_n}\longrightarrow0,

\end{equation}
\begin{equation}
 \liminf_{n\to\infty}
 \operatorname{Osc}_2\!\left(
 p;(\tau_n,T_*)\times B_{2R_n}(a)\right)
 \ge c_\Omega\frac{m\sqrt\nu}{\norm{u(s)}_2},

\end{equation}
and
\begin{equation}
 \liminf_{n\to\infty}
 R_n^2\int_{\tau_n}^{T_*}\int_{B_{2R_n}(a)}
 \abs{\nabla p}^2\dd x\dd t
 \ge c_\Omega\frac{m^2\nu}{\norm{u(s)}_2^2}.

\end{equation}
In particular, for every \(t_0\in(t_b,T_*)\) and every sufficiently small
\(r>0\),
\begin{equation}
 \operatorname{Osc}_2
 \bigl(p;(t_0,T_*)\times B_r(a)\bigr)=+\infty

\end{equation}
and
\begin{equation}
 \int_{t_0}^{T_*}\int_{B_r(a)}\abs{\nabla p}^2\dd x\dd t=+\infty.

\end{equation}
Thus local square integrability of either the pressure modulo functions of
time or its gradient on one terminal neighborhood excludes a point atom of
the endpoint kinetic-energy measure at its center. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 3 of arXiv:2605.30091, 'Computing lower expectations with respect to total variation distance and chi-squared dive'] With $r\in\{\ell,\ldots,n\}$ defined as above, we have that
\begin{equation}
    \underline{E}^{\chi^2}_{p,\delta}(f)
    =
    \begin{cases}
    \mu_r-\sigma_r\sqrt{m_r\delta-(1-m_r)} & \text{if } r>\ell,\\
    f(x_1) & \text{if } r=\ell.
    \end{cases}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 13 of arXiv:2604.10244, 'Ergodicity for regime-switching neutral stochastic functional differential equations with '] Let assumption (\hyperlink{A0}{A0}), (\hyperlink{H1}{H1}), and (\hyperlink{H2}{H2}) hold. Suppose that there exist a function \( V \in C^{2}\left(\mathbb{R}^{n} \times \mathbb{S} ; \mathbb{R}_{+}\right) \) and positive constants $ p$, $ c_{1} $, $ c_{2} $, $\lambda_0$, $\lambda_{1} $, $ \lambda_{2} $  such that \( \lambda_{1}>\frac{\lambda_{2}}{(1-\kappa_1)^{p}}\),
		\begin{equation}
			c_{1}|x|^{p} \leq V(x, k) \leq c_{2}|x|^{p}
		\end{equation}
		for \( (x, k) \in \mathbb{R}^{n} \times \mathbb{S} \) and
		\begin{equation}
			(\mathcal{L} V)(\varphi, k) \leq \lambda_0-\lambda_{1}|\varphi(0)-G(\varphi,k)|^{p}+\lambda_{2} \int_{-\infty}^{0} |\varphi(\theta)|^{p} \rho(\d \theta)
		\end{equation}
		for \( (\varphi,  k) \in C_r \times \mathbb{S} \). Then there exists a constant $C>0$  such that for any   $(\xi,i)\in C_r\times\S$ and  $t\geq 0 $,
		\begin{equation}
			\mbb{E}\left|Y^{\xi, i}(t)\right|^{p}\leq  C(1+\|\xi\|_{r}^{p}).
		\end{equation}

