[Lemma opt2prefix of arXiv:2604.20660, 'The Legendre structure of the TAP complexity\\ for the Ising spin glass'] Let $f\in \mathbb{R}$, $q\in (0,1)$ and $u\in (0,1)$. Let $\zeta\in \mathrm{Prefix}_2(u,q)$ satisfy the assumptions of Proposition (prop:annealed 0 of the paper). Let $(X_t)_{t\in [0,1]}$ be the Auffinger--Chen process
		\begin{equation*}
			\begin{cases}
				\mathrm{d} X_t=\xi''(t)\zeta([0,t])\partial_x \Phi_\zeta(t,X_t)\mathrm{d} t+\sqrt{\xi''(t)} \mathrm{d} B_t\\
				X_0=0.
			\end{cases}
		\end{equation*}
		For every $s\in [0,1]$, set
		\begin{equation*}
			H_\zeta(s):=\frac{1}{2}\int_s^1 \xi''(r)\Bigl(\mathbb{E}[(\partial_x\Phi_\zeta(r,X_r))^2]-r\Bigr)\mathrm{d} r.
		\end{equation*}
		Then, the following hold:
		\begin{enumerate}[label=(\roman*)]
			\item \begin{equation}
				-\mathbb{E}[\Phi_\zeta(q,X_q)]+\int_0^q t\xi''(t)\zeta([0,t])\mathrm{d} t +\frac{1}{2}\int_q^1 t\xi''(t)\zeta([0,t])\mathrm{d} t=-f,
			\end{equation}
			\item \begin{equation}
				\mathbb{E}[(\partial_x\Phi_\zeta(q,X_q))^2]=q,
			\end{equation}
			\item  \begin{equation}
				\mathrm{supp}(\zeta)\cap [q,1]\subset \underset{[q,1]}{\mathrm{arg\,min}}(H_\zeta).
			\end{equation}
		\end{enumerate}

[Lem 21 of arXiv:2609.01358, 'Regularized spectral expansion of a Rankin--Selberg period and moments'] Let $d\ge 2$ and for $\lambda:=(\lambda_1,\lambda_2)\in\a^\ast_{\Q_{d-1},\C}$ let $\varphi_\lambda\in\1_{d-1}\cdot|\det|^{\lambda_1}\boxplus\1_1\cdot|\cdot|^{\lambda_2}$ be a normalized factorizable vector. If $\varphi_\lambda$ is holomorphic in a sufficiently small neighbourhood of the hyperplane $\lambda_1-\lambda_2=\tfrac{d}{2}$ then $\Eis(\varphi_\lambda)$ has at most a simple polar divisor along the same hyperplane, where the residue is given by
		\begin{equation*}
			|\det|^{\lambda_1-\frac{1}{2}} \Delta^{-\frac{d-1}{2}}\frac{\xi^\ast(1)}{\xi(d)}\int_{K_d}\varphi_\lambda(k)\, dk\in\1_d\cdot|\det|^{\frac{(d-1)\lambda_1+\lambda_2}{d}},
		\end{equation*}
		for $\lambda_1-\lambda_2=\tfrac{d}{2}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 7 of arXiv:2608.25772, 'Propagation of Chaos and Gaussian Fluctuations for Mean-field Coupled Maps'] Fix $T\in\N$ and $m\in\N$. Assume $\Delta<\Delta_0$, where $\Delta_0$ is the constant in Theorem~\ref{thm:main}. Under the assumptions \textup{\textbf{(A1.3)}}, \textup{\textbf{(A2)}} and \textup{\textbf{(A3)}}, given any $m$ test functions $\varphi_1,\dots,\varphi_m\in C^2(\T)$ and a function $\Psi\in C_b^3(\R^m)$, we have
    \begin{equation}
        \left|\mathbb{E}\Psi\left(\langle\varphi_1,\eta_t^N\rangle,\dots,\langle\varphi_m,\eta_t^N\rangle\right)-\mathbb{E}\Psi\left(\langle\varphi_1,\eta_t\rangle,\dots,\langle\varphi_m,\eta_t\rangle\right)\right|\leq\frac{C\mathrm{e}^{Ct}}{\sqrt{N}},\quad t=0,\dots,T,
    \end{equation}
    where the constant $C>0$ depends on $\Delta,m,\|\Psi\|_{C_b^3},\|F\|_{C^2},\|h\|_{C^2}$ and $\|\varphi_i\|_{C^2}(1\leq i\leq m)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 19 of arXiv:2609.00183, '2609.00183'] There exist $(C,R_1)(\Lambda,n,M,\sigma_j,X)>0$ with the following property: If $r\leq R_1$ and $x_1,x_2\in B_{r/8}(0)$, then for all $y,z$ on the line segment between $x_1$ and $x_2$, we have
    \begin{equation}
    |\BDOrd_{\phi,v}(y,r)-\BDOrd_{\phi,v}(z,r)|\leq C(W(x_1)+W(x_2)+r)^{1/2}\frac{|y-z|}{|x_1-x_2|}.
\end{equation}

