[Lemma lem:intersection-homogeneity of arXiv:2609.03532, 'Airy limit for the Jack process and topological expansion'] For $r\geq m-1$ and $a>0$,
\begin{equation}
  \mathbf L_{0,r}^{\mathrm{conn}}[a\boldsymbol x]
  =
  a^{3r-\frac32m}
  \mathbf L_{0,r}^{\mathrm{conn}}[\boldsymbol x].

\end{equation}

[Lemma unimodular-extension-of-splitting-Gibbs-measure of arXiv:2603.01322, 'Gibbs conditioning, atypical consensus and splitting Gibbs measures on random regular grap'] For any $\TIS$ Gibbs measure $\pmb{\rho}$ on $T^\k$ with some given specification    
we have 
\begin{equation}
    \pmb{\rho}_1=\mu^{(\pi_{\pmb\rho_1})},
\end{equation}
with $\mu^{(\pi_{\pmb\rho_1})}$ as defined in (equation eqn:1MRF of the paper), and 
\begin{equation}
    \pmb{\rho}=\UGW_1(\pmb{\rho}_1),
\end{equation}
where $\UGW_1$ is the map given by Definition (\oldref{defn:UniExt}). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem variance exit time identity of arXiv:2512.12796, 'Symmetrization and the Planar Skorokhod Embedding Problem'] If 
\[
f(z)=\sum^{+\infty}_{n=1}c_{n}z^{n}
\]
is a univalent function mapping the unit disc onto a domain $U$ then
\begin{equation}
\mathbf{E}(\tau_{U})=\frac{1}{2}\sum^{+\infty}_{n=1}\vert c_{n}\vert^{2}=\mathbf{Var}(\mu_{U}).
\end{equation}

[Theorem thm:tailrl-weight-form of arXiv:2609.02987, 'Tail Likelihood Reinforcement Learning'] For an input $x$, the population-level gradient of TailRL{} is estimable as,
\begin{equation}
\nabla_\theta J_{\mathrm{TailRL{}}}(\theta;x)
=\mathbb{E}_{z\sim\pi_\theta(\cdot\mid x)}
\left[
\left(
\int_0^{r(x,z)}
\frac{d\tau}{p_\theta(x,\tau)}
\right)
S(x,z)
\right].

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem OptimalPWConcentration of arXiv:2609.02541, 'A note on the norm of the embedding of $\text{PW}^2$ into $\text{PW}^q$'] Let $S \subset \mathbb{R}$ be a measurable set with $0 < |S| < \infty$ and $g$ be any function of $PW^2$ with $\|g\|_{2}=1$. Then
\begin{align*}
     \int_{0}^{|S|}u^{*}(x) dx \leq \sup_{\substack{f\in PW^2\\ \|f\|_2=1}} \int_{-|S|/2}^{|S|/2}|f(x)|^2 dx = \lambda(|S|).
\end{align*}
Here $u^{*}$ denotes the decreasing rearrangement of $|g|^2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 (Finite-entropy criterion for the entropic CCLT) of arXiv:2608.30579, '2608.30579'] Let $(\xi,\eta )$ be a pair of random variables. 
    Let $\{(\xi_i,\eta_i)\}_{i\geq 1}$ be independent copies of $(\xi,\eta)$.
	  Define
	  \begin{equation}
					W_n = \frac{\xi_1 + \xi_2 + \cdots + \xi_n}{\sqrt{n}}, 
			\quad \boldsymbol{\eta}_{n}= (\eta_1, \ldots, \eta_n).	
	  \end{equation}
			Assume that
\begin{equation}
			\sigma^{2} \triangleq\mathbb{E}\,\operatorname{Var}(\xi  \vert \eta) < \infty, 
		\quad (\xi \vert \eta) \ll \mathcal{L}, \ P_{\eta} \text{-a.s.},
\end{equation}
			where $\mathcal{L} $ denotes Lebesgue measure and the notation $\nu \ll \mathcal{L}$ indicates that $\nu$ is 
			absolutely continuous with respect to  $\mathcal{L}$. Define
	\begin{equation}
	h_{n}= \mathbb{E}\, h\!\left(W_{n} \vert \boldsymbol{\eta}_{n}\right).		
	\end{equation}		
			Then the convergence
\begin{equation}
			\lim_{n \to \infty} h_n = \frac{1}{2} \log (2\pi e \sigma^2)
\end{equation}
holds if and only if there exists $n_0 \geq 1$ such that
\begin{equation}
	h_{n_{0}}= \mathbb{E}\, h\!\left(W_{n_0} \vert \boldsymbol{\eta}_{n_{0}}\right) > -\infty.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 22 of arXiv:2605.03851, 'The Relay Random Tree:\\A stochastic geometry approach of multihop relay in an urban visib'] \textbf{Reverse Shade the in finite range case.}

Let $\landsc$ be a landscape and $(a, b)\in \landsc$ a building. We define the reverse shade of $(a, b)$ as \textit{the intersection of all the shades of $(a, b)$ from buildings visible from $(a, b)$, cut off at distance $R$ from $a$}:
\begin{align*}
\rs (a, b) := \displaystyle\bigcap_{\substack{(a_1, b_1) \in \landsc \\ a_1\in ]a, a+R]}} \Biggl(\{(x, y) \in \Half: (x\geq a_1-R &\text{ and } \frac{b-y}{a-x} \geq \frac{b_1-b}{a_1-a}\}\\&  \cup\{(x, y)\in \Half:a-Rx <a_1-R\}\Biggl).
\end{align*}

\begin{figure}[h]
            \centering
            \includegraphics[width=0.75\textwidth]{Figures/reverse_shade_fini_horiz.ipe.png}
            \caption{The reverse shade is characterized by a succession of upwards jumps and then increasing slopes.}
\end{figure}

[Lemma lem:critical-window-mean-advantage of arXiv:2608.06159, 'Majority Dynamics on Resampled Sparse Erd\H{o}s--R\'enyi Graphs:\\[0.5ex] Gaussian Winner '] For every fixed \(C_0<\infty\), uniformly over deterministic initial
configurations satisfying (equation eq:critical-window-condition of the paper),
we have
\begin{align}
\frac{\E[\Delta_1\mid\rvy_0]}{\sqrt N}
=
x_0
+O\left(\frac1{\sqrt{\log N}}\right).

\end{align}
The implicit constant depends only on \(b\) and \(C_0\). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 19 of arXiv:2604.05138, 'Convergence rate of $H$-property for step-graphons'] The following two items hold:
\begin{enumerate}
\item If $W$ satisfies Condition $A$ and $B'$, but not $B$, then there exist a nonzero $p^*\in (0,1)$ and a positive constant $c$ such that
\begin{equation}
|P_n(W) - p^*| \leq \frac{c}{\sqrt{n}}.  
\end{equation}
\item If $W$ satisfies Condition $B'$, but not $A$, then there exist a positive constant $c$ such that 
\begin{equation}
P_n(W) \leq \frac{c}{\sqrt{n}}.
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

