[Theorem BerryEsseen of arXiv:2411.14876, 'Limit theorems for stochastic exponentials of matrix-valued L\'evy processes \\'] Let $L$ be a L\'evy process in $\mathbb{R}^{d\times d}$ fulfilling (equation eq-nonsingular of the paper) and let $X$ be the corresponding stochastic exponential.
	Assume that $G_X$ satisfies  (i-p) and $\mathds{E} \big[ \sup_{0 \le s \le 1} (\log M(X_s))^4 \big]<\infty$. Then there is a constant $C>0$ such that for all $n \ge 1$, $y \in \R^d$ with $\|y \|=1$ and $z \in \R$,
\begin{equation}
	\bigg| \mathds{P} \bigg(\frac{\log \|Y_t^y \|-t\lambda}{\sigma \sqrt{t}} \le z\bigg) -  \Phi(z)  \bigg| ~\le~\frac{C}{\sqrt{t}}. 
\end{equation}
Under the additional assumption that $\mathds{E} \big[ M(X_1)^\delta\big]<\infty$ for some $\delta>0$,  there exist $C>0$ and $\gamma>0$ such that for all $n \ge 1$, $y \in \R^d$ with $\|y \|=1$, $z \in \R$ and $\varphi \in \mathcal{B}_\gamma$,
	\begin{equation}
		\bigg| \mathds{E} \bigg[ \varphi(Z_t^{\hat{y}}) \mathds{1}\bigg\{\frac{\log \|Y_t^y \|-t\lambda}{\sigma \sqrt{t}} \le z\bigg\}\bigg] - \pi(\varphi) \Phi(z)  \bigg| ~\le~\frac{C}{\sqrt{t}} \|\varphi \|_\gamma .
	\end{equation}

[Theorem thm:j fixed of arXiv:2607.01946, 'Second-order fluctuations for a phase transition in random partitions'] Under the notations above,
\begin{multline}
\pp{\frac{C_{j}(\floor{nt})-{\mathbb E}\pp{C_j(\floor{nt})\;\middle\vert\;{\mathcal P}}}{n^{\alpha/2}}, \frac{{\mathbb E}\pp{C_j(\floor{nt})\;\middle\vert\;{\mathcal P}} - \floor{nt}^\alpha p_j\topp\alpha S_\alpha}{n^{\alpha/2}}}_{t\in[0,1],j\in{\mathbb N}}\\
\Rightarrow\pp{\pp{\frac {S_\alpha}{\Gamma(1-\alpha)}}^{1/2}\zeta_{\alpha,j}\topp1(t),
\pp{\frac {S_\alpha}{\Gamma(1-\alpha)}}^{1/2}\zeta_{\alpha,j}\topp2(t)}_{t\in[0,1],j\in{\mathbb N}},
\end{multline}
in $(D[0,1]\times D[0,1])^{\mathbb N}$ with
\begin{align*}
\zeta\topp1_{\alpha,j}(t)&:=
\int_{{\mathbb R}_+\times\Omega'}\pp{\inddd{N'(tr) = j} - \mathbb P(N'(tr) = j)}{\rm d} M_\alpha({\rm d} r{\rm d}\omega'),\\
\zeta\topp2_{\alpha,j}(t)&:=\int_{{\mathbb R}_+\times\Omega'}\mathbb P(N'(tr) = j){\rm d} M_\alpha({\rm d} r{\rm d}\omega'),
\end{align*}
where $M_\alpha$ is a Gaussian random measure on $(0,\infty)\times\Omega'$ with control measure $\alpha r^{-\alpha-1}{\rm d} r{\rm d}\mathbb P'$ and $N'$ on $(\Omega',\mathbb P')$ is a standard Poisson process, and $M_\alpha$ is independent of $S_\alpha$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prp 25 of arXiv:2608.13976, 'Boundary Harnack principle for diffusion with jumps on metric measure spaces'] Let $D$ be an  open subset in $\R^d (d\geq 3)$ and  $R_0>0$.
Assume for each $x\in\R^d,$ $z\mapsto j(x, z)$ is positive and for each  $R\in (0, R_0)$ and $x_0\in\R^d,$
\begin{equation}
\inf_{z\in \R^d:  R/16\leq |z|<R/2} j(x_0, z)>0.
\end{equation}
Suppose  for each  $x_0\in\R^d, R\in (0, R_0)$ and $0<p<q\leq 1,$ there exists $c_1=c_1(x_0, R, p, q)>1$  such that  for any $x\in B(x_0, pR)$ and $y\in B(x_0, qR)^c,$
\begin{equation}
c_1^{-1}J(x_0, y)\leq J(x, y) \leq c_1J(x_0, y).
\end{equation}
Then  for each $z_0\in \partial D$ and $R\in (0, \tfrac{1}{16}R_0),$
there exists a constant  $C=C(z_0, R)\geq 1$   independent of the geometry of $D$ such that   for   any  nonnegative  regular harmonic functions $f$ and $g$
on $D\cap B(z_0, R)$   vanishing  on  $(D^c)^r\cap B(z_0, R),$
\begin{equation}
f(x)g(y)\leq Cf(y)g(x)  \quad \hbox{for } x, y\in D\cap B(z_0, R/32).
\end{equation}
Furthermore, if \eqref{e:4.27} and \eqref{e:4J} hold uniformly for $x_0\in\R^d,$
then BHP \eqref{e:Xb} holds with $C=C(R)\geq 1$ uniformly for $z_0\in \partial D$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma TSP-E-L-A-1 of arXiv:2608.30582, 'The flexible part of intermittent Onsager theorem for the two-dimensional stochastic incom'] Suppose $\left| {t - {t_0}} \right|{\left\| u \right\|_1} \lesssim 1$. Let $w{\left( t ,x \right)}$ be the solution of the transport equation
\begin{equation*}
\left\{ {\begin{array}{*{20}{l}}
{\partial _t}w + \left( {v \cdot \nabla } \right)w = u ,   &\mbox{on}\ \left[ {{t_0}, T } \right]  \times  \mathbb{T}^2, \\
w\left( {{t_0}} \right) = {w_0} ,
\end{array}} \right.
\end{equation*}
where $v\left( t, x \right)$ and $u\left( t, x \right)$ are the vector functions on $\left[ {{t_0}, T } \right]  \times   \mathbb{T}^2$. Then, for any $\alpha \in \left[ {0,1} \right)$ and $N \in {\mathbb{Z}^ + } $, we have
\begin{equation}
{\left\| {w\left( t \right)} \right\|_\alpha } \lesssim {\left\| {{w_0}} \right\|_\alpha } + \int_{{t_0}}^t {{{\left\| {u\left( s  \right)} \right\|}_\alpha }} \mathrm{d}s  ,
\end{equation}
and
\begin{equation}
{\left[ {w\left( t \right)} \right]_{N + \alpha }} \lesssim  {\left[ {{w_0}} \right]_{N + \alpha }} + \left| {t - {t_0}} \right|{\left[ v \right]_{N + \alpha }}{\left[ {{w_0}} \right]_1}  + \int_{{t_0}}^t {{{\left[ {u\left( s  \right)} \right]}_{N + \alpha }} + \left| {t - s } \right|{{\left[ v \right]}_{N + \alpha }}{{\left[ {u\left( s  \right)} \right]}_1}} \mathrm{d}s  .
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 12 (Local $C^0$ estimate) of arXiv:2608.29736, '2608.29736'] There exists a constant \(C>0\), independent of \(t\), such that
\begin{equation}
u_t\geq\rho-C\qquad\text{on }M\setminus Z.
\end{equation}
Consequently, for every \(K\Subset M\setminus Z\), there exists
\(C_K>0\), independent of \(t\), such that
\begin{equation}
-C_K\leq u_t\leq0\qquad\text{on }K.
\end{equation}

[Cor 158 of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] For all $\ell\leq \ubl$, we have 
  \begin{equation}

  \lim_{\eta\downarrow 0}
  \bbE\big[
  \hat{b}^{\chaos,\ell}(\hat X^{\ell,\eta})
  \big]
  =
  \lim_{\eta\downarrow 0}
  \bbE\big[
  \hat{b}^{\chaos,\ell}(\hat{\prxX}^{\ell,\eta}) \big]
  =
  0\,.
  \end{equation}

[Theorem 9 of arXiv:2604.05234, 'Quantitative propagation of chaos and universality for asymmetric Langevin spin glass dyna'] {\cite[Theorem 1.1]{Bobkov-Nayar-Tetali-2017-nonLip}}

Suppose $\nu \in \mP(\R^d)$ satisfies a T$_2$ inequality with constant $\sigma^2$. For a Borel set $A\subseteq \R^d$ with $\nu(A)>0$, define  $\nu_A(S):=\nu(A\cap S)/\nu(A)$. Then $\nu_A$ satisfies a T$_2$ inequality with constant $\sigma^2_A$, and
\begin{align*}
    \sigma_A^2\leq c\log\Big(\frac{e}{\nu(A)}\Big)\sigma^2,
\end{align*}
where $c$ is a universal constant. In particular for every $L \in (0, \infty)$ and each $L$-Lipschitz function $f:\R^d\to \R$ with $\int f\,d\nu_A=0,$ the following hold:
\begin{enumerate}
    \item For each $\lambda\in \R$ we have
\begin{align}
    \int_{\R^d} e^{\lambda f(x)}d\nu_A(x)\leq e^{L^2\lambda^2\sigma^2_A/2}.

    \end{align}
    \item For each $\lambda < \frac{1}{2\sigma_AL}$, we have
    \begin{equation}
    \int_{\R^d} e^{\lambda^2 f(x)^2/2} d\nu_A(x)\leq 2.

    \end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

