[Corollary cor:o1 of arXiv:2605.26048, 'Classification of the eternal solutions and multiple coalescing shocks in the KPZ fixed po'] For any $\varphi\in\Phi_\omega$,
             \begin{equation}
                 (W\star\varphi\,)(x,t)=f_\xi(x,t), \qquad \forall \;  \xi\in\pmb{\xi}^{W\star \varphi}\text{ and } (x,t) \in \mathfrak{C}^{W\star\varphi\,}(\xi).
             \end{equation}

[Theorem 5 of arXiv:2506.18313, 'A stochastic model for the diffusion of competing opinions with trend-following, oppositio'] Assume $\theta> 1/2$. Then, as $n \to \infty$, the following results hold:

\begin{enumerate}


\item [(i)] (Strong convergence to a random vector)
\begin{equation}

\lim\limits_{n\to\infty}  n^{1-\theta}\left(\hat{N}_n, \hat{M}_n\right) =  (W,-W) \ \text{a.s.} \ \text{and in } L^2.
\end{equation}
where $W$ is a non-degenerated random variable such that
\begin{equation*}
\mathbb{E}[W]=\frac{\Gamma(T_0)}{\Gamma(\theta+T_0)}\left(N_0-\frac{a}{1-\theta}T_0\right),
\end{equation*}
and
\begin{eqnarray}

\dE[W^2]&=&\frac{\Gamma(T_0)}{\Gamma(2\theta+T_0)}\Bigg[ N_0^2+ \frac{a}{1-\theta}T_0\left(\frac{(1-2a)}{(2\theta-1)}- \frac{a}{(1-\theta)}(T_0+1) \right)\notag \\
&+ &  \frac{1}{(2\theta+T_0)}\left( N_0 - \frac{a}{1-\theta}T_0\right) \left[ (2a-1)T_0+(\theta+T_0)\left(\frac{2a(2\theta+T_0)}{(\theta-1)} \right) \right] \notag \Bigg].
\end{eqnarray}

\item [(ii)] (The Gaussian fluctuations)
\begin{equation}

    \sqrt{n^{2\theta-1}}\left( n^{1-\theta}\left(\hat{N}_n, \hat{M}_n\right)-(W,-W) \right) 
\overset{d}{\longrightarrow} \mathcal{N}  \left(0,\Sigma\right),
\end{equation}
where
$$\Sigma =\dfrac{a(1-a-\theta)}{(1-\theta)^2(2\theta-1)} \left(\begin{array}{cc}
1 & -1 \\
-1 & 1 
\end{array}
\right)$$
\item [(iii)] (Law of the iterated logarithms)
    \begin{equation}

        \limsup_{n \to \infty} \pm \frac{\sqrt{n^{2\theta-1}}\left( n^{1-\theta}\left(\hat{N}_n, \hat{M}_n\right)-(W,-W) \right)}{\sqrt{2 \log \log n}} = \sqrt{\dfrac{a(1-a-\theta)}{(1-\theta)^2(2\theta-1)}} (1,1)\ \text{ a.s. }
    \end{equation}

\item [(iv)] (Asymptotics of the average difference process)
    \begin{equation}
    \lim_{n \to \infty} n^{1 - \theta} \left( \frac{C_n}{n} -\left(\frac{a}{(1-\theta)}-\frac12\right) \right) = \frac{2W}{1 + \theta} \quad \text{a.s.}
    \end{equation}
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 168 (Coercive spacetime integrals) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] Let $\upxi$ be a scalar function or an $\ell_{t,u}$-tangent one form defined on $\characteristicdiamondtwoarg{[\leftubar,\ubar)}{[\moreinterestingu_1,u]}$. Then we define the following spacetime integral:
	\begin{equation}
		\spacetimecoercive{q}[\upxi](\ubar,u) \eqdef - \int_{\characteristicdiamondtwoarg{[\leftubar,\ubar)}{[\moreinterestingu_1,u]}}  ( \newL \upmu) |\upxi|^2 \mathbf{1}_{\characteristicdiamondtwoarg{[\leftubar,\ubar)}{[\moreinterestingu_1,u]} \cap \smallneighborhoodofcreasearg{[\leftubar,\ubarboot]}}
 \, \weight^{q}  \voldiamond, 
	\end{equation}
	where $\smallneighborhoodofcreasearg{[\leftubar,\ubarboot]}$ is the spacetime region from \eqref{E:SMALLNEIGHBORHOOD}. In the case that $\upxi$ is an $\ell_{t,u}$-tangent one form, $|\xi|^2$ is understood to be $|\xi|_{\gtorus}^2$ in \eqref{E:SPACETIMECOERCIVEINTEGRALS}.

	Next, let $\upxi$ be a scalar function or a $\doublenulltoritwoarg{\ubar}{u}$-tangent one form  defined on $\characteristicdiamondtwoarg{[\leftubar,\ubar)}{[\moreinterestingu_1,u]}$.  Then we define the following spacetime integral:
	\begin{equation}
		\newspacetimecoercive{q}[\upxi](\ubar,u) \eqdef - \int_{\characteristicdiamondtwoarg{[\leftubar,\ubar)}{[\moreinterestingu_1,u]}}   \newL \weight \, |\upxi|^2 \, \weight^{q}  \voldiamond. 
	\end{equation}
	In the case that $\upxi$ is an $\doublenulltoritwoarg{\ubar}{u}$-tangent one form , $|\upxi|^2$ is understood to be $|\upxi|_{\gnulltori}^2$ in \eqref{E:NEWSPACETIMECOERCIVEINTEGRALS}.

[Definition eq:epsilon_def of arXiv:2607.18011, 'From local giants to locality in long-range percolation'] \thlabel{def:biskup_good}
    For $C_{\mathrm{vor}}{}\ge 1$ from \thref{prop:tile_and_cell_volume_bounds}, let

    \begin{equation}

        \varepsilon_0
        = 
        1 - r_0^{- \delta / 4},
        \quad
        \varepsilon_i 
        = 
        \frac{
            1
        }{
            C_{\mathrm{vor}}^2
            (i+1)^2
        }.
    \end{equation}  

    For $\delta \in (\max(0, 1-\alpha),2-\alpha)$, $c_{\mathrm{vor}}{}$ as in \thref{prop:tile_and_cell_volume_bounds}, and for $i \geq 1$, let

    \begin{equation}

        \rho_0 
        =
        \theta
        r_0^{- d \delta/4}/c_{\mathrm{vor}}{},
        \quad
        \rho_i 
        =
        \theta
        r_0^{- \delta/4} 
        \prod_{j=2}^{i+1} 
        (1 - j^{-2}),
        \quad 
        \rho_\infty
        = 
        \lim_{j \to \infty} \rho_j.
    \end{equation}

    Let $((\Tile{i}{j})_{j \geq 0})_{i \geq 0}$ be the renormalisation scheme in \thref{def:renorm_scheme_2}. 


    We say that a tile $\Tile{0}{j}$ is \textbf{good} if $B(x_{0,j}, r_0/4)$ contains a cluster $\goodcluster{0}{j}$ satisfying

    \begin{equation}

        \# 
        \goodcluster{0}{j} 
        \geq 
        \rho_0 
        \# \Tile{0}{j}.
    \end{equation}

    We call the cluster $\goodcluster{0}{j}$ the \textbf{good cluster}.

    For $i \geq 1$, we say that a level-$i$ tile $\Tile{i}{j}$ is \textbf{good} if at least a $(1-\varepsilon_i)$ proportion of its subtiles are good and their good clusters are connected to each other inside $\Tile{i}{j}$ to form the \textbf{good cluster} $\goodcluster{i}{j}$.

    When the good cluster is not unique, we choose one arbitrarily.

[Lemma lem:LRPcycle of arXiv:2608.25279, 'Provable Non-Acceleration of Standard Strang\\ Splittings of Kinetic Langevin Dynamics'] The deterministic recurrence
\begin{equation*}
 x_{k+1}=\frac{13}{9}x_k-\frac49x_{k-1}-\frac19U'(x_k)
\end{equation*}
has the period-three orbit $(p_k)$. Consider the perturbed recurrence
\begin{equation*}
 x_{k+1}
 =\frac{13}{9}x_k-\frac49x_{k-1}-\frac19U'(x_k)+\varepsilon_{k+1},
 \qquad x_{-1}=p_{-1},\quad x_0=p_0,
\end{equation*}
and set $e_k=x_k-p_k$. Suppose that $x_k$ and $p_k$ lie in the same
interval of (equation eq:Upieces of the paper) for every $0\le k\le n-1$. Then, for
$0\le k\le n-1$,
\begin{equation}
 e_{k+1}=-\frac43e_k-\frac49e_{k-1}+\varepsilon_{k+1},
\end{equation}
and
\begin{equation}
 \max_{0\le k\le n}\lvert e_k\rvert
 \le9\max_{1\le j\le n}\lvert \varepsilon_j\rvert.
\end{equation}
In particular, if
$\max_{1\le j\le n}\lvert \varepsilon_j\rvert\le1/180$, then
$\lvert e_k\rvert\le1/20$ for every $0\le k\le n$, and $x_k$ and $p_k$
lie in the same interval of (equation eq:Upieces of the paper) at every such step.

