[Theorem T:LND_x of arXiv:2602.05317, 'Strong local nondeterminism for stochastic time-fractional\\ slow and fast diffusion equat'] \index{conditional variance}
  Assume $\alpha > 0$, $\beta \in (0, 2]$, $\gamma \ge 0$, $H \in (0, 1)$, and
  $\ell \in (0, 2d)$. Assume the Dalang condition (equation E:main of the paper), namely, $\rho >
    0$ and $\ell < 2\alpha$. Then, for all $0 < S < T < \infty$ and $1 \le M <
    \infty$, there exist positive finite constants $C = C(S,T,M, \alpha, \beta,
    \gamma, H, d, \ell)$ and $C' = C'(S,T,M, \alpha, \beta, \gamma, H, d, \ell)$
  such that the following statements hold.

  \begin{enumerate}[\rm (i)]

    \item If either $\beta \in (0, 2)$ or $(\beta, \gamma) \in \{2\} \times [1,
            \infty)$, then for all $t \in [S, T]$, for all integers $n \ge 1$, and for
          all $x, x_1, \dots, x_n \in B(0, M) \subset \mathbb{R}^d$, we have
          \begin{align}
            \ensuremath{\mathrm{Var} }\left(u(t, x)\big|u(t, x_1), \dots, u(t, x_n)\right)
            \ge C \min_{1 \le j \le n}|x-x_j|^{2\tilde\rho_1},
          \end{align}
          and for all $t \in [S, T]$, for all $x, y \in B(0, M)$, we have
          \begin{align}
            \mathbb{E}\left[\left(u(t, x) - u(t, y)\right)^2\right] \ge
            \begin{cases}
              C'|x-y|^{2\tilde\rho_1} & \text{if } \tilde\rho_1 \in (0, 1), \\
              C'|x-y|^2 (1+|\log|x-y||)                            & \text{if } \tilde\rho_1 = 1,        \\
              C'|x-y|^2                                            & \text{if } \tilde\rho_1 > 1.
            \end{cases}
          \end{align}

    \item If $\beta = 2$ and $\gamma \in [0,1)$, then for all $t \in [S, T]$,
          for all integers $n \ge 1$, for all $x, x_1, \dots, x_n \in B(0, M)
            \subset \mathbb{R}^d$, we have
          \begin{align}
            \ensuremath{\mathrm{Var} }\left( u(t, x) \big| u(t, x_1), \dots, u(t, x_n) \right) \ge C \min_{1\le j \le n}|x-x_j|^{2\tilde\rho_2},
          \end{align}
          and for all $t \in [S, T]$, for all $x, y \in B(0, M)$, we have
          \begin{align}
            \mathbb{E}\left[ \left( u(t, x) - u(t, y) \right)^2\right] \ge
            \begin{cases}
              C' |x-y|^{2\tilde\rho_2} & \text{if } \tilde\rho_2 \in (0, 1), \\
              C' |x-y|^2 (1+|\log|x-y||)           & \text{if } \tilde\rho_2 = 1,        \\
              C' |x-y|^2                           & \text{if } \tilde\rho_2 > 1.
            \end{cases}
          \end{align}

  \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 5. lem: pcpt of aging functions near diagonal of arXiv:2412.08236, 'Aging and sub-aging for Bouchaud trap models on resistance metric spaces'] For every $l \in \mathbb{N}$ and $\eta > 0$,
  \begin{equation}
    \lim_{\eta \to 0} 
    \limsup_{n \to \infty} 
    \sup_{(s,t) \in T_{1}(l, \eta)} 
    |\Phi_{n}^{\nu_{n}}(s,t) - 1| 
    = 0.
  \end{equation}

[Lemma 26 (sharp half-disk Dirichlet-to-Neumann profile) of arXiv:2609.03736, '2609.03736'] There is a continuous function $q$ on the unit circle such that, uniformly
in $\theta$,
\begin{equation}
 \frac{\mathcal B(re^{\iu\theta})}{\log r}
 \longrightarrow q(e^{\iu\theta})
 \qquad(r\uparrow1).

\end{equation}
Because $\log r\sim r-1$, the function $q$ is the outward normal derivative
of $\mathcal B$ along the circular boundary.
On the open right semicircle, put
\begin{equation}
 a=\tan\!\left(\frac\pi4-\frac\theta2\right).
\end{equation}
Then
\begin{equation}
 q(e^{\iu\theta})=D(a),
 \qquad
 D(a)=\frac12-\frac{2a\log a}{\pi(a^2-1)},

\end{equation}
where $D$ is extended continuously at $a=1$.  The function $D$ has its
unique minimum at $a=1$, with $D(1)=\delta_\pi$.  At the two corners
$q(\pm\iu)=1/2$, and $q(-z)=q(z)$.  Consequently,
\begin{equation}
 \min_{|z|=1}q(z)=\delta_\pi,

\end{equation}
with equality exactly at $z=\pm1$.

[Theorem 10 (SGD scaling law \citep{li2026functional}) of arXiv:2609.02728, 'Momentum in large-batch training: Polyak enlarges the critical batch size, Nesterov improv'] Under Assumptions~\ref{ass:diagonal-covariance} and~\ref{ass:power-law}, if the stability condition \(\eta\lesssim1\) holds, then for $k \gtrsim 1/\eta$, the expected excess risk satisfies:
\begin{equation}

\EE[\cE(\btheta_k)]
\eqsim
\left(\eta k\right)^{-s}
+
\frac{\eta\sigma^2}{B}.
\end{equation}

[Prop 5 of arXiv:2609.03777, '2609.03777'] The following statements are equivalent.
\begin{enumerate}
\item The map $\bar\delta$ preserves $\ker(G)$ and therefore induces a well-defined derivation on $\mes$, again denoted by $\delta$.
\item The evaluation map
\begin{align}
\operatorname{ev}_{G_2}:\mesadm[T]&\longrightarrow\mes,\\
T&\longmapsto G_2
\end{align}
is injective.
\item The Eisenstein series $G_2$ is transcendental over $\mesadm$.
\end{enumerate}
If these statements hold, then
\begin{align}
\mes=\mesadm[G_2]
\end{align}
freely and
\begin{align}
\delta=-\frac12\frac{\partial}{\partial G_2}\,.
\end{align}

