body:
[Theorem 16 (\cite{MR2778606} Theorem 5.1.3) of arXiv:2606.26496, 'Homeomorphism of the Revuz correspondence under Dynkin class assumptions'] The quotient space of $\mathbf{A}_c^+$ under the equivalence relation and the family ${\sf S}$ are in one-to-one correspondence under the following relation: For $\mu \in {\sf S}$ and ${\sf A}\in\mathbf{A}_c^+$,
		 \begin{equation}
		 	\lim_{t \downarrow 0} \frac{1}{t}\int_E \mathbb{E}_x\left[  \int_{0}^{t} f(X_s)\ {\rm d}{\sf A}_s  \right]h(x)\mathfrak{m}({\rm d}x)=\int_E f(x) h(x)\mu({\rm d}x)
		 \end{equation}
		 where $h$ is any $\gamma$-excessive function and $f \in \mathscr{B}_+(E)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 6 of arXiv:2506.22040, '\vspace{-3em} Khinchin inequalities for uniforms on spheres with a deficit'] Let $p \geq 2$. Suppose that  $a_1 \geq b_1 \geq b_2 \geq a_2 > 0$ with $a_1^2 + a_2^2 = b_1^2 + b_2^2 = \sigma^2$ for some $\sigma > 0$. For every vector $v$ in $\R^d$, $d \geq 2$, we have
\begin{align}\notag
&\E\left|b_1\xi_1 + b_2\xi_2 + v\right|^p - \E\left|a_1\xi_1 + a_2\xi_2 + v\right|^p \\
&\qquad\qquad\geq \frac{1}{d}(a_1^4+a_2^4 - b_1^4-b_2^4)\cdot \begin{cases}\beta_{p,d}(|v|^2+\sigma^2)^{\frac{p-4}{2}}, & 2 \leq p \leq 4, \\ \frac{p(p-2)}{8}\E|v+\sigma\xi|^{p-4}, & p > 4, \end{cases}
\end{align}
with $\beta_{p,d}$ defined in \eqref{eq:beta-def}.

[Theorem 2 of arXiv:2511.14757, 'A weak convergence approach to the large deviations of the dynamic Schr\"odinger problem'] The sequence of Schr\"odinger bridges $\{\pi_\eta\}_{\eta > 0}$ satisfies an LDP on $\calC_1$ with the rate function $I_D$ given by
    \begin{equation}
    \begin{split}
        I_D(\varphi) &= I_S(\varphi_0, \varphi_1) + I_B^{\varphi_0 \varphi_1}(\varphi) \\
        &= (c - (-\psi \oplus \phi))(\varphi_0, \varphi_1) + \inf_{\nu \in U^{\varphi_0 \varphi_1}_\varphi} \frac{1}{2} \int_0^1 |\nu(t)|^2 dt,
    \end{split}
    \end{equation}
    where $U^{xy}_\varphi \coloneq \{\nu \in L^2([0,1]:\bR^d): \varphi(\cdot) = \int_0^{\cdot} (b(s, \varphi(s) + \sigma(s, \varphi(s))\nu_s)ds\}$, and $(\psi, \phi)$ are a pair Kantorovich potentials. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 15 of arXiv:2604.26549, 'Existence and uniqueness results of a stochastic nonlinear heat equation with a constraint'] Suppose $(\mathcal{Z}_T$, $\mathcal{T})$ be fixed as in \eqref{def-zt}. Then, a set $\wtilde{\K}\subset\mathcal{Z}_T$ is $\mathcal{T} - $relatively compact if the following three conditions hold:
		\begin{itemize}
			\item[(i)] \begin{equation}
				\sup_{u\in\wtilde{\K}}\sup_{t\in[0,T]}\|u(t)\|_{\Vp}<\infty.
			\end{equation}
			\item[(ii)] $\wtilde{\K}$ is bounded in the space  $L^2(0,T;D(A))$, i.e., 
			\begin{equation}
				\sup_{u\in\wtilde{\K}}\bigg(\int_0^T\|\Delta u(t)\|_{L^2(\bO)}^2dt \bigg) < \infty.
			\end{equation}
			\item[(iii)] \begin{equation}
				\lim_{\delta\to 0}\sup_{u\in\wtilde{\K}}\sup_{s,t\in[0,T],|t-s|\leq\delta}\|u(t) -u(s)\|_{L^2(\bO)} = 0.
			\end{equation}
		\end{itemize}

[Definition 56 of arXiv:2607.18104, '2607.18104'] Suppose that $(\eta_t)_{t \geq 0}$ is an ASEP on $\Z$, and that $(\bar{\eta}^{\per}_t)_{t \geq 0}$ is an unwrapped periodic ASEP. Fix some $\rho \in [0,1]$ and $\theta \in \R$, which are allowed to depend on $N$. Set
\begin{equation}
    E_t := \left\{ \{ x, x+1 \} \colon x \in \mathcal{I}^{\rho}_{N}(\theta,\theta+1) \right\}  
\end{equation} for all $t\geq 0$. We define the $\boldsymbol{(\rho,\theta,1,N)}$\textbf{-reference frame basic coupling} as follows. 
For all edges, we place independent rate $(1+q)$ Poisson clocks. 
Whenever the clock of an edge $e=\{ x,x+1\}$ rings, and the exclusion processes are in states $\eta$ and $\eta^{\prime}$, respectively, we sample an independent Bernoulli-$(1+q)^{-1}$-distributed random variable $B$. If
\begin{itemize}
\item $B=1$ and $e\in E_t$. Then, if $\eta(x)=1-\eta(x+1)=1$ holds, we move the particle at site $x$ to site $x+1$ in configuration $\eta$. Similarly, if $\bar{\eta}^{\per}(x)=1-\bar{\eta}^{\per}(x+1)=1$ holds, we move for all $j\in \Z$ the particle at site $x+jN$ to site $x+jN+1$ in $\bar{\eta}^{\per}$. 
\item $B=0$ and $e\in E_t$. Then, if $\eta(x)=1-\eta(x+1)=0$ holds, we move the particle at site $x+1$ to site $x$ in configuration $\eta$. Similarly, if $\bar{\eta}^{\per}(x)=1-\bar{\eta}^{\per}(x+1)=0$ holds, we move for all $j\in \Z$ the particle at site $x+jN+1$ to site $x+jN$ in  $\bar{\eta}^{\per}$. 
\item $B=1$ and $e \notin E_t$. Then, if $\eta(x)=1-\eta(x+1)=1$ holds, we move the particle at site $x$ to site $x+1$ in configuration $\eta$.
\item $B=0$ and $e\notin E_t$. Then, if $\eta(x)=1-\eta(x+1)=0$ holds, we move the particle at site $x+1$ to site $x$ in configuration $\eta$.
\end{itemize}
In all other cases, the configuration remains unchanged.

