[Lemma 10 of arXiv:2609.01965, 'A logarithmic Bogomolov--Sommese vanishing theorem on compact K\"ahler manifolds'] Let $(X,\omega)$ be a compact K\"ahler manifold of dimension $n$ and $L$ a pseudo-effective line bundle over $X$ with $\nd(L)=k>p$.
    Let $D$ be a reduced simple normal crossing divisor on $X$.
    There exist constants $c_0,C_0>0$ such that for every $\varepsilon$ sufficiently small, we have the following properties.
    \begin{enumerate}
        \item There exists a log resolution 
        $$\pi_\varepsilon:\widetilde{X}_\varepsilon\longrightarrow X$$
        and a reduced simple normal crossing divisor $B_\varepsilon$ such that $B_\varepsilon$ contains the total transform of $D$ and the exceptional divisor.
        Moreover, $\pi_\varepsilon$ induces a natural morphism from $\Omega^p_X(\log D)$ to $\Omega^p_{\widetilde{X}_\varepsilon}(\log B_\varepsilon)$.
        \item There exists a singular Hermitian metric $\widetilde{h}_\varepsilon$ on line bundle $\pi^*_\varepsilon L$ 
        with divisorial singularities supported on $B_\varepsilon$ and smooth on $$Y_\varepsilon:=\widetilde{X}_\varepsilon\setminus B_\varepsilon.$$
        \item There exist K\"ahler forms $\gamma_\varepsilon$ and $\Omega_\varepsilon$ on $\widetilde{X}_\varepsilon$ such that, on $Y_\varepsilon$,
        \begin{equation}
            \image\Theta_{\pi^*_\varepsilon L,\widetilde{h}_\varepsilon}=\gamma_\varepsilon-3\varepsilon\pi^*_\varepsilon\omega 
            \quad \text{and} \quad \Omega_\varepsilon\geq \pi^*_\varepsilon\omega.
        \end{equation}
        \item The following uniform estimates hold:
        \begin{equation}
            V_\varepsilon:=\int_{\widetilde{X}_\varepsilon}\gamma_\varepsilon^n\geq c_0\varepsilon^{n-k} 
            \quad \text{and} \quad
            \int_{\widetilde{X}_\varepsilon}\gamma_\varepsilon^{p}\wedge\Omega_\varepsilon^{n-p}\leq C_0.
        \end{equation}
    \end{enumerate}

