[Theorem thm: Heat Kernel Bound of arXiv:2411.09614, 'Moment estimates for the stochastic heat equation on Cartan-Hadamard manifolds'] Let $M$ be a Hadamard manifold.

    Suppose $t>0,x,y\in M$. If $\sec_M\leq -K_1<0$, the heat kernel $P_t(x,y)$ satisfies \begin{equation}
      P_t(x,y)\leq C h(K_1t,\sqrt{K_1}d(x,y))
    \end{equation}
    where $C>0$ depends on $n$ and $K_1$. Similarly, if $\sec_M\geq-K_2>-\infty$, we have \begin{equation}
        P_t(x,y)\geq ch(K_2t,\sqrt{K_2}d(x,y))
    \end{equation}
    where $c>0$ depends on $n$ and $K_2$.

[Lem lemma:M-contraction-map of arXiv:2411.11676, 'Surface sums for lattice Yang--Mills in the large-$N$ limit'] Let $K_* : \mathcal{P}_{\mathbb{Z}^d} \rightarrow \mathbb{N}$ be a plaquette assignment and $M_* \geq 1$ an integer.
For any $\lambda \in (0, 1/2)$ and $\gamma \in (0, \infty)$, we have that
\begin{align}
	\|M f\|_{\lambda, \gamma} &\leq \frac{\lambda}{1-2\lambda} + (4\lambda + 4d \upbeta \gamma \lambda^{-4}) \|f\|_{\lambda, \gamma},\qquad\forall f \in \Theta_{K_*, M_*}, 
\end{align}
where we recall that the norm $\|\cdot\|_{\lambda, \gamma}$ is defined using the parameters $K_*, M_*$, which we fixed. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:pureweak-nonstrong2 of arXiv:2507.14676, 'On the critical parameters of branching random walks'] {cf:BZ17}}]  
Let $(X,K)$ and $(X,K^*)$ two irreducible continuous-time BRWs such that $k_{xy}=k^*_{xy}$ for all $x \in X \setminus A$
where $A$ is a finite nonempty set.  Suppose that $\lambda^*_w<\lambda_w < \lambda_s$, and let $B\subseteq X$ be nonempty.

Then, for the BRW $(X,K^*)$
\begin{enumerate} 
\item if $\lambda \le \lambda_w^*$ there is a.s.~extinction in $B$;

\item if $\lambda \in (\lambda_w^*, \lambda_w)$ there is strong survival in $B$; 

\item if $\lambda =\lambda_w$ and $(X,K)$ dies out globally, then there is strong survival in $B$;

conversely, if $(X,K)$ survives globally and $B$ is finite; there is non-strong survival in $B$;

\item if $\lambda \in (\lambda_w, \lambda_s]$ and $B$ is finite, then

there is non-strong survival in $B$;

\item if $\lambda > \lambda_s$ and $B$ is finite, then survival is strong (resp.~non-strong) in $B$

if and only if 
the same holds for $(X,K)$.  
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 1 of arXiv:2608.30549, '\vspace{-1cm}Maximally Spread Out Measures and Implications\\{} for Phase Transitions in A'] Let $\XX$ be a quasi-normed space and let $\emptyset\ne\SC\subset \XX$.
  We then say that $\SC$ satisfies {\ConditionZetaText}
  if there exist constants $C, \alpha > 0$ satisfying
  \begin{equation}
    \sum_{n=1}^{\infty} \frac{x_n}{C \cdot n^\alpha}
    \in \SC
    \quad \text{whenever} \quad x_1,x_2,\dots \in \SC
    .

    \tag{$\zeta$}
  \end{equation}
  More precisely, we then say that $\SC$ satisfies \ConditionZetaTextAlphaC{(\alpha,C)}.

[Lemma 8 of arXiv:2608.21014, 'The stochastic Cahn--Hilliard equation in critical spaces'] Let $1<q<\infty$ and $-2\leq s\leq 2$. For $f\in \Bpsn{s,q}$, the mapping
\begin{align}
    \bigl[h\mapsto \langle h,f(\cdot)\rangle_{\ell^2}\bigr] \in \sL(\ell^2,\bpsn{s,q})
\end{align}
induces a conjugate-linear isomorphism from $\Bpsn{s,q}$ onto  $\gamma(\ell^2, \bpsn{s,q}) $.

