[Theorem thm:LASS of arXiv:2606.02003, 'Higher-Order Multifractional Stable Motion:\\ Definition and Fundamental Properties'] Let $X^{(n)}_H$ be an $n$-MFSM satisfying Assumption~(ass:params of the paper)
with $H \in \mathcal{C}^n(\mathbb{R})$ (i.e., $H$ is $n$-times continuously
differentiable; for $n=1$ this is equivalent to $\beta > 1$).
Then for each $t_0 \in \mathbb{R}$:
\begin{equation}

\left\{
\frac{X^{(n)}_H(t_0 + \varepsilon\tau)
  - \displaystyle\sum_{k=0}^{n-1}\frac{X^{(n,k)}_H(t_0)}{k!}\,
  (\varepsilon\tau)^k}
{\varepsilon^{H(t_0)}}
\right\}_{\tau \in \mathbb{R}}
\overset{\mathrm{f.d.d.}}{\longrightarrow}
\bigl\{Y^{(n)}_{H(t_0)}(\tau)\bigr\}_{\tau \in \mathbb{R}}
\quad \text{as } \varepsilon \to 0^+,
\end{equation}
where $Y^{(n)}_{H(t_0)}$ is an $n$-FSM (in the sense of [Kawai2016])
with constant Hurst parameter $H(t_0)$ and stability index $\alpha$,
whose moving-average representation is
\begin{equation}

Y^{(n)}_{H(t_0)}(\tau)
= \int_\mathbb{R}
\frac{(\tau-u)_+^{H(t_0)-1/\alpha}}{\Gamma(H(t_0)+1-1/\alpha)}
\,dM_\alpha(u).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 6 of arXiv:2510.20492, 'Heterochromatic two-arm probabilities for metric graph Gaussian free fields'] For $d\ge 3$, $n\ge 1$, $D\subset \widetilde{\mathbb{Z}}^d$ and $v,w\in \widetilde{\mathbb{Z}}^d\setminus D$,
	\begin{equation}
  \big|  \mathbb{P} (v\xleftrightarrow{\ge 0} w  ) -\mathbb{P}^{D}(v\xleftrightarrow{\ge 0} w ) \big|  \lesssim  \widetilde{G}(v,w)-\widetilde{G}_D(v,w). 
\end{equation}

