[Lemma lem:G1 of arXiv:2605.15545, 'Crossover from subcritical to critical decay: \\ random walk, self-avoiding walk, percolat'] For $d \ge 1$ and $\phi \ge 0$,
\begin{equation}
    \int_{{\mathbb R^d}} |y|^\phi  \mathbb{G}_{1}(y) \mathrm{d} y
      =
    2^{\phi+1}
    \frac{\Gamma( \frac{\phi+2}{2})\Gamma( \frac{\phi+d}{2} )}{\Gamma(\frac d2)}
    .
\end{equation}

