[Lemma eq:2s5c-bar-appendix of arXiv:2411.00930, '\bf \Large Asymptotic Product-form Steady-state for Multiclass Queueing Networks: A Reentr'] Let the random vector $X$ in~(equation eq:2s5c-state of the paper) denote the pre-jump state and $\Delta$ represent the increments corresponding to different jump events, i.e., external job arrival or service completion,
\begin{align*}
    &\Delta_{e,1}\equiv\Big(e^{(1)},e^{(1)}T_{e,1}/\alpha_1,0\Big)\\
    \text{and}\quad&\Delta_{s,k}\equiv\Big(-e^{(k)}+e^{(k+1)}\mathbbm1\{k<5\},0,e^{(k)}T_{s,k}/\mu_k\Big),\quad k=1,\ldots,5.
\end{align*} 
Together, these random vectors satisfy the following BAR with some ``nice'' functions $f$.
\begin{equation}

    -\mathbb{E}[{\mathcal A} f(X)] = \alpha_1\Big(\mathbb{E}_{e,1}[f(X+\Delta_{e,1})-f(X)]+\sum_{k=1}^5\mathbb{E}_{s,k}[f(X+\Delta_{s,k})-f(X)]\Big),
\end{equation}
where $\mathbb{E}_{e,1}[\cdot]$ and $\mathbb{E}_{s,k}[\cdot]$ are Palm expectations.
For $x=(z,u_1,v)$ and function $f$, the operator ${\mathcal A}$ is defined as
\begin{align*}
    {\mathcal A} f(x)=
    -\frac{\partial f}{\partial u_1}(x)&-\frac{\partial f}{\partial v_1}(x)\mathbbm{1}\{z_1>0, z_3=z_5=0\}-\frac{\partial f}{\partial v_3}(x)\mathbbm{1}\{z_3>0, z_5=0\}-\frac{\partial f}{\partial v_5}(x)\\
    &-\frac{\partial f}{\partial v_2}(x)-\frac{\partial f}{\partial v_4}(x)\mathbbm{1}\{z_4>0, z_2=0\}.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 21 of arXiv:2604.20435, 'Stochastic Extinction with Relaxed Boundedness Conditions'] There is some $\wdt h_2(\eps)$, $\wdt h_2(\eps)\to0$ as $\eps\to0$ such that
	\begin{equation}
		\PP\bigg\{\sup_{t\leq \wdt\xi_\delta}e^{\frac{p^*t}2}|\BX_1(t)-\wdt \BX_1(t)|\big(K_{U,\BX,\wdt\BX}(t)\big)^{\wdt d_0}\geq \frac{|\by_1-\wdt \by_1|+\delta}{\eps}\bigg\}\leq\wdt h_2(\eps).
	\end{equation}

