[Proposition 3 (Coefficient convergence) of arXiv:2608.16256, 'Error Distribution of the Local Linearization Method for Stochastic Differential Equations'] \label[proposition]{prop:ll_coefficients}
For every \(1\le i,j\le d\), the sequence
\[
    \sup_{t\le1}
    |f^i_j(\hat X_{\varphi_n(t)}^n)|
\]
is tight.  Moreover,
\begin{equation}
    \int_0^\cdot
    f^i_j(\hat X_{\varphi_n(s)}^n)\,ds
    \xrightarrow{\mathrm{ucp}}
    \int_0^\cdot
    f^i_j(X_s)\,ds .
\end{equation}

[Lemma lem.tau-k-decomp of arXiv:2605.26082, 'Quantitative Einstein relation for reversible diffusions in a random environment'] For every $k\ge 1$ and $n\ge 2k$, there exists an event
		\[
			\Gamma_{k,n}\in\sigma\bigl(X^\lambda_s:0\le s\le n\Delta-\Delta\bigr)\vee\sigma\bigl(Y_0,\ldots,Y_{n-2}\bigr)
		\]
		such that the following statements hold $\widehat{\mathbb P}_0^\lambda$-a.s.:
		\begin{equation}
			\{\tau_k=n\Delta\}=\Gamma_{k,n}\cap\{Y_{n-1}=1\}\cap\{D\circ\theta_{n\Delta}=\infty\}\, ,
		\end{equation}
		\begin{equation}
			\Gamma_{k,n}\subseteq
			\left\{\sup_{0\le s\le n\Delta-\Delta} e_1\cdot X^\lambda(s)
			\le e_1\cdot X^\lambda(n\Delta-\Delta)+R\right\}\, .
		\end{equation}
		Consequently, also $\widehat{\mathbb P}_0^\lambda$-a.s., for every $y\in\mathbb{R}^d$,
		\begin{equation}
			\Gamma_{k,n}\cap\{y\in B^{X^\lambda(n\Delta-\Delta)}\}\subseteq\left\{\sup_{0\le s\le n\Delta-\Delta}e_1\cdot X^\lambda(s)\le e_1\cdot y-7R\right\}\, ,
		\end{equation}
		and
		\begin{equation}
			\Gamma_{k,n}\cap\{Y_{n-1}=1\}\subseteq\Bigl\{\sup_{0\le s\le n\Delta-\Delta}e_1\cdot X^\lambda(s)\le e_1\cdot X^\lambda(n\Delta)-7R\Bigr\}\, .
		\end{equation}

