[Lemma 63 of arXiv:2608.30549, '\vspace{-1cm}Maximally Spread Out Measures and Implications\\{} for Phase Transitions in A'] Let $U,V$ be quasi-Banach spaces and let $T\colon U\to V$ be a compact linear map and let $t\in(0,\infty)$.
    Assume that 
    \begin{equation*}
       \liminf_{k\to \infty} \bigl( k^{t} \cdot \en_k(T)\bigr) >0.
    \end{equation*}
    Then $\bigl(T(\ball_U), \norm{\cdot \mid V}\bigr)$ is totally bounded and we have $\lmd\bigl(T(\ball_U)\bigr) \ge \frac{1}{t}$.

[Lemma lem:kpz-red-derivative-identities of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] Under the hypotheses of
Proposition~(thm:kpz-red-Darboux of the paper), the dressed
observable $\mathcal A=z\Phi R\Psi$ satisfies
\begin{align}
\mathcal A_a
&=\mathcal F_{1,0}-\mathcal A^2+\mathcal F_{0,1},
 \\
\mathcal A_{aa}
&=\mathcal F_{2,0}+\mathcal F_{0,2}
+2\mathcal F_{1,1}
-\mathcal F_{1,0}\mathcal A
-\mathcal A\mathcal F_{0,1}
-\mathcal A_a\mathcal A
-\mathcal A\mathcal A_a,
 \\
\mathcal A_x
&=\mathcal F_{0,2}-\mathcal F_{2,0}
+\mathcal A\mathcal F_{1,0}
-\mathcal F_{0,1}\mathcal A
+2C\mathcal A-2\mathcal A C,
 \\
\mathcal A_t
&=-\tfrac13\mathcal F_{3,0}
  -\tfrac13\mathcal F_{0,3}
  +\tfrac13(\mathcal F_{0,2}\mathcal A
  -\mathcal F_{0,1}\mathcal F_{1,0}
  +\mathcal A\mathcal F_{2,0})
\notag \\
&\quad
  +C\mathcal F_{1,0}+\mathcal F_{0,1}C
  -\mathcal A C\mathcal A
  +(\Lambda+C_a)\mathcal A
  -\mathcal A\Lambda.

\end{align}

[Lem 5 of arXiv:2609.00598, 'Supercritical mean--field limit for magnetized Hamiltonian dynamics'] Let $v$ be a smooth vector field on $\mathbb{T}^{2}$, 
and let $\omega $ be a smooth scalar field on $\mathbb{T}^{2}$ 
such that $\int_{\mathbb{T}^{2}}\omega(x)\ \dd x=0$ and 
\begin{align*}
\omega=\mathrm{curl}_{x}(v)=-\mathrm{div}_{x}(v^{\perp}).     
\end{align*}
Then there is a constant vector $m\in \mathbb{R}^{2}$ and smooth scalar functions $\phi$ and $\psi$
such that 
\begin{equation}
v=m+\nabla_{x}\phi+\nabla_{x}^{\perp}\psi, \quad \omega=\Delta_{x}\psi,
\quad \int_{\mathbb{T}^{2}}\psi(x)\, \dd x=0.  
\end{equation}

