[Thm 1 (Microscopic fluctuations) of arXiv:2607.28865, 'First-Passage Percolation on Spread-out line graphs: Microscopic Regime'] Assume that $\ell\ge2$ is fixed and $\go$ is not deterministic.
\begin{enumeratei}
	\item If $\E\go<\infty$ or $\go$ satisfies condition~A.\ref{ass:A2} with $\gc>1/{\lc}$, then the weak law of large numbers holds, \ie\
\begin{align*}
    \frac{1}{n}T^{(\ell)}(0,n)
    \stackrel{\pr}{\to}
    \mu_{\mathrm{FPP}} \text{ as } n\to\infty
\end{align*}
for some constant $\mu_{\mathrm{FPP}}\in (0,\infty).$

\item If $\E\go^2<\infty$ or $\go$ satisfies condition~A.\ref{ass:A2} with $\gc>2/{\lc}$, then the following Gaussian central limit theorem holds
\begin{align*}
    n^{-1/2}\cdot (T^{(\ell)}(0,n)-n\cdot \mu_{\mathrm{FPP}})
    \Longrightarrow
    \N(0,\gs_{\mathrm{FPP}}^2),
\end{align*}
where $\mu_{\mathrm{FPP}}$ is as in~\eqref{thm:mean}, and
$\gs_{\mathrm{FPP}}^2$ is a positive constant given in~\eqref{eq:var-CLT-def}.

\item Finally, if condition~A.\ref{ass:A2} holds with $0<\gc<2/{\lc}$, then
\begin{align*}
    \frac1{a_n}\cdot (T^{(\ell)}(0,n)-b_n)
    \Longrightarrow
    Z_\alpha,
\end{align*}
where $\alpha=\gc\lc$ and $Z_\alpha$ is the totally right-skewed $\alpha$-stable law associated with the normalization $a_n=n^{1/(\gc \lc) +o(1)},b_n$ explicitly given in~\eqref{eq:stable-law-const}. 
\end{enumeratei} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 23 (Prediction Range \citep{hamman2024quantifying,watson2023predictive}) of arXiv:2609.01397, 'Measuring consistency via ensemble margin and local prediction variability: Auditing decis'] The prediction range of $\emprashomonset$ is the range of predicted probabilities of models for a given test instance $x$, and is defined as,
\begin{align}
    \predrange(x) =  \max_{f_k \in  \emprashomonset}f_{k}(x) -  \min_{f_k \in  \emprashomonset}f_{k}(x).
\end{align}

[Lemma lem:sep3 of arXiv:2606.02472, 'Correlated uniform attachment trees'] For all $\varepsilon>0$ there exist $m,k,K \in \N$ such that for all $n \geq m$, whenever $\left( T_n^1, T_n^2 \right)$ is distributed according to $\alpha{\text -}\mathrm{CUA}$, then
    \ba{
        \mathbb{P} \left( \left| \min_{u_1 \in A_K^1(n), u_2 \in A_K^2(n)} \frac{1}{k^3} \sum_{j=1}^{k} \left( \widehat{U}_{jk^2,(j+1)k^2}^{T_n^1}(u_1) - \widehat{U}_{jk^2,(j+1)k^2}^{T_n^2}(u_2) \right)^2 - 2(1-\alpha) \right| \leq \varepsilon  \right) > 1-\varepsilon.
    } (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma eq:wpsle_ub of arXiv:2507.15589, 'Tightness of approximations to metrics on non-simple conformal loop ensemble gaskets'] There exists $c>0$ such that if $\eta$ denotes a two-sided whole-plane ${\rm SLE}_\kappa$ in $\mathbf{C}$ from $\infty$ to $\infty$ through $0$, parameterized according to the natural parameterization with $\eta(0) = 0$, then
\begin{align}
\mathbf{P}[\mathrm{diam}(\eta[0,t]) \ge rt^{1/d_{\rm SLE}}] &\le c^{-1}\exp(-cr^{d_{\rm SLE}/(d_{\rm SLE}-1)}) , \\
\mathbf{P}[\mathrm{diam}(\eta[0,t]) \le r^{-1}t^{1/d_{\rm SLE}}] &= o^\infty(r^{-1}) 
\end{align}
as $r\to\infty$.

[Prop cormain of arXiv:2411.18359, 'Large systems of symmetrized trapped Brownian Bridges and Schr\"odinger processes'] Fix $ \beta \in (0,\infty) $ and assume that $ {\mathfrak m} $ is either a positive finite measure on $\mathbb{R}^d$, or a $\sigma-$ finite measure which is absolutely continuous with respect to the Lebesgue measure, with continuous and bounded density. Fix some continuous and bounded function $g\colon\mathbb{R}^d\times \mathbb{R}^d\to(0,\infty)$ and replace $\mathbb{P}_{x,y}^\beta$ by $g(x,y)\mathbb{P}_{x,y}^\beta$ in the definition (equation Psymdef of the paper) of $\mathbb{P}_{{\mathfrak m},N}^{\ssup{{\rm sym}}}$. Then 
\begin{enumerate}
\item[(i)] Proposition~(main of the paper) remains true. The corresponding rate function is
\begin{equation}
    \mu\mapsto I^{{\scriptscriptstyle{({\rm sym}})}}_{W,{\mathfrak m},g}(\mu)-\langle \mu_{0,\beta},\log g\rangle-\inf_{\mu \in {\mathcal M }_1({\mathcal C }_\beta)}\Bigl\{I^{{\scriptscriptstyle{({\rm sym}})}}_{W,{\mathfrak m}}(\mu)-\langle \mu_{0,\beta},\log g\rangle\Bigr\}.
\end{equation}

\item[(ii)] Corollary~(main2 of the paper) remains true. The corresponding rate function is
\begin{equation}
J^{{\scriptscriptstyle{({\rm sym}})}}_{{\mathfrak m},W,g}(p)=\widetilde{J}_{g,W,N}(p)-\inf_{p\in {\mathcal M }_1(\mathbb{R} ^ d)}\{\widetilde{J}_{g,W,N}(p)\},\qquad p\in{\mathcal M }_1(\mathbb{R}^d),
\end{equation}
where 
\[\widetilde{J}_{g,W,N}(p)=\inf\limits_{q\in{\mathcal M }_1^{\ssup{{\rm s}}}(\mathbb{R}^d\times\mathbb{R}^d)}\Big\{H(q|\overline{q}\otimes{\mathfrak m})+J^{{\scriptscriptstyle{({q}})}}(p)+\langle W, p\rangle-\langle q,\log g\rangle\Big\}.\]
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

