[Lem lem_rauchToponogovComparisonEstimate of arXiv:2608.17463, 'Persistence probabilities of fractional L\'evy fields indexed by hyperbolic space and othe'] Under the above assumptions on the manifold $\mathcal{M}$ there exists $r'>0$ and $\kappa', \mathcal{K}' \in\mathbb{R}$ with $\kappa'\leq\mathcal{K}'$, such that for any $\kappa\leq\kappa'$, any $\mathcal{K}'\leq\mathcal{K}$, any $0<r\leq\min\left\{r', \inj(\mathcal{M}_\mathcal{K})\right\}$, and any $\eta,\zeta\in\mathcal{B}_r^{\mathcal{M}}(O)$ we have
    \begin{align*}
        d_\mathcal{K}(\Psi_\mathcal{K}(\eta), \Psi_\mathcal{K}(\zeta)) \leq d(\eta, \zeta) \leq d_\kappa(\Psi_\kappa(\eta), \Psi_\kappa(\zeta)),
    \end{align*}
    where $d_\mathcal{K}(.,.)$ and $d_\kappa(.,.)$ are the shortest distance functions in the respective model spaces $\mathcal{M}_\mathcal{K}$ and $\mathcal{M}_\kappa$ and $\Psi_\mathcal{K}, \Psi_\kappa$ are the diffeomorphisms defined in (equation eq_exponentialTransferMap of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition of arXiv:2411.05534, 'Inverse problems for stochastic partial differential equations'] We say the strongly measurable function $ f(\cdot) : \Omega \rightarrow \mathcal{X} $ is Bochner integrable with respect to $ \mu $ if there exists a sequence of Bochner integrable simple  functions $ \{ f_{i}(\cdot) \}_{i=1}^{\infty}    $ converging to $ f(\cdot) $ in $ X $, $ \mu $-a.e., such that 
    \begin{align*}
        \lim _{i, j \rightarrow \infty} \int_{\Omega}\left|f_i(s)-f_j(s)\right|_{\mathcal{X}} d \mu=0
        .
    \end{align*}
    For  $ E \in \mathcal{F} $, the Bochner integral of $ f(\cdot) $ over $ E $ is defined by 
    \begin{align*}
        \int_E f(s) d \mu=\lim _{i \rightarrow \infty} \int_{\Omega} \chi_E(s) f_i(s) d \mu(s) \quad \text { in } \mathcal{X} \text {. }
    \end{align*}

[Proposition 47 ({\cite[Theorem~6.4) of arXiv:2609.04139, 'The conformally invariant metric on CLE$_4$ II:\\ existence of geodesics'] {zhan2019two}}]

Let $v_-, w_-, w_+, v_+ \in \BR$ with $v_- < w_- < w_+ < v_+$ be such that $0 \in [v_-, v_+]$. Let $(\eta_w,\eta_v)$ be a bichordal SLE$_4$ in $\BH$ with link pattern $\{\{w_+, w_-\}, \{v_+, v_-\}\}$. Then, there exists a universal constant $C \in (0,\infty)$ such that
\begin{align*}
\BP[\eta_w \text{ exits } B_L(0)] \leq C L^{-4} G_2(w_-, w_+; v_-, v_+) \left(1 + C((v_+ - v_-) / L)^{5/6}\right)
\end{align*}
for all $L > 0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 11 of arXiv:2608.25772, 'Propagation of Chaos and Gaussian Fluctuations for Mean-field Coupled Maps'] Let $f:\T^d\to\T^d$ be a $C^1$ diffeomorphism and $\mu\in L^1(\T^d)\cap\mathcal{P}(\T^d)$ be an absolutely continuous Borel probability measure on $\T^d$. Then we have the formula
    \begin{equation}
        (f_{\ast}\mu)(x)=\frac{\mu(f^{-1}(x))}{|Df|(f^{-1}(x))},\quad x\in\T^d,
    \end{equation}
    where $|Df|$ denotes the absolute value of the Jacobian of $f$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 21 of arXiv:2608.27307, '2608.27307'] Under Assumption~\ref{ass:basic}, uniformly for $z\in\mb D(\tau,\eta_0)$,
        \begin{align}
                \|\partial_z\Pi(z)\|              & \lesssim\frac1{(\Im m(z))^6},   \\
                |\partial_zm(z)|+|\partial_zg(z)| & \lesssim\frac1{(\Im m(z))^2}. 
        \end{align}

