body:
[Cor 6 (Large deviation principle for the normalised mass function) of arXiv:2604.00635, 'Large deviations of the periodic Toda chain'] The normalised mass function of the unconstrained model $\Pi_{N}$ obeys a large deviation principle
at speed $N$ and rate function $I - \!\! \underset{\mu \in \mathcal{M}_1(\mathbb{R})}{\inf}\!\! I[\mu ]$.
That is, for any open set $O \subset \mathcal{M}_1(\mathbb{R})$,

\begin{align}

\liminf_{N \to +\infty} \frac{1}{N}\ln \Pi_{N}[O] \geq

- \Big\{ \inf_{\mu \in O}I[\mu] - \inf_{\mu \in \mathcal{M}_1(\mathbb{R})} \hspace{-3mm} I[\mu] \Big\}

\end{align}

and, for any closed set $F \subset \mathcal{M}_1(\mathbb{R})$,

\begin{align}
    \limsup_{N \to +\infty} \frac{1}{N}\ln \Pi_{N}[F] \leq

- \Big\{ \inf_{\mu \in F}I[\mu]-\inf_{\mu \in \mathcal{M}_1(\mathbb{R})} \hspace{-3mm} I[\mu] \Big\} \, .

\end{align}

Likewise the normalised mass function of the constrained model $\Pi_{N,\mathsf{c}}$ also obeys a large deviation principle
on  $ \mathcal{M}_{1,\mathsf{c} }(\mathbb{R})$  at speed $N$ and rate function $I- \underset{ \mu \in \mathcal{M}_{1,\mathsf{c}}(\mathbb{R})}{\inf}\hspace{-3mm}I[\mu]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lemma_RS_gft of arXiv:2411.16572, 'Optimal decay of eigenvector overlap for non-Hermitian random matrices'] Fix small constant $\epsilon,\tau>0$ and  any integer $m\geq 1$.
	 For any  $|z_i| \leq 1+\tau$ and $\eta_i \in {\mathbb R }$ satisfying $ \min_{i=1}^2 \{|\eta_i| \rho_i\} \geq n^{-1+\epsilon}$ and $\gamma \gtrsim \eta_*/ \rho^* $, 	
	assuming\footnote{We remark that stochastic domination $\prec$ 
	and upper bounds of arbitrarily high moments of a random variable 
	are equivalent for random variables bounded by some $n^C$
	 which is always true in our case, \emph{i.e., }  for $|X|\le n^C$ we have
	 that $X \prec \Psi$ if and only if  ${\boldsymbol{E} }|X|^{2m} \le n^\xi \Psi^{2m}$ for any $m\geq 1$ and $\xi>0$.
	  We frequently use this fact  in the proof without mentioning it. \normalcolor}
	that for some $0\leq b<1$, 
	\begin{align}  
		&{\boldsymbol{E} }|R_t^{xy}|^{2m} \prec (\mathcal{E}_b)^{2m}, \quad \qquad  R_t^{xy}=\big(G_1 A G_2-M^{A}_{12}\big)_{{\bm x} {\bm y}}, \nonumber\\
		&{\boldsymbol{E} }|S_t^{xy}|^{2m} \prec (\widetilde{\mathcal{E}}_b)^{2m},  \quad \qquad  S_t^{xy}=\big(G_{1}A_1G_{2}A_2G_{1}-M^{A_1,A_2}_{121}\big)_{{\bm x} {\bm y}},   \nonumber
	\end{align}
	  uniformly for any $t\geq 0$, any deterministic bounded  matrices $A_i~(i=1,2)$ and unit vectors ${\bm x}, {\bm y}$,  then  the following hold for $b'=\min\big\{b+\theta,~1\big\}$, $0<\theta\leq \epsilon/10$, and the prefactor $C_n:=1+\frac{1}{\sqrt{n} \eta_*^{1+\frac{\epsilon}{2}}}$,
	\begin{align}
		\Big|\frac{\mathrm{d} {\boldsymbol{E} } |R^{xy}_t|^{2m}}{\mathrm{d} t}\Big| \lesssim & C_n
		\Big(  {\boldsymbol{E} } \big|R^{xy}_t\big|^{2m} +O_\prec\big(\mathcal{E}_{b'}\big)^{2m}\Big),
	\end{align}
	\begin{align}
		\Big|\frac{\mathrm{d} {\boldsymbol{E} } \big|\mathcal{S}^{xy}_t\big|^{2m}}{\mathrm{d} t}\Big| \lesssim & C_n
		\Big(  {\boldsymbol{E} } \big|\mathcal{S}^{xy}_t\big|^{2m} +O_\prec\big(\widetilde{\mathcal{E}}_{b'}\big)^{2m}\Big),
	\end{align}
	 uniformly for any $t\geq 0$, any deterministic bounded  matrices $A_i~(i=1,2)$ and unit vectors ${\bm x}, {\bm y}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

