[Theorem 15 of arXiv:2609.02426, 'Deformations of the $\osp(n|2)$-action on the superspace\\ of symbols of differential oper'] Let $n\geq3$ and $2d=m\in\N$, and consider the general infinitesimal deformation \eqref{eq:28},
$$L_1=\sum_{k=-\infty}^{m}\tau_kf_{\frac k2}+\sum_{k=1}^m\bigl(t_kh_k+\widetilde{t}_k\widetilde{h}_k\bigr).$$
Then
\begin{equation}

\tfrac12(L_1\vee L_1)=\sum_{k=1}^m\Bigl(\tau_{2-n-k}\bigl(t_k-\widetilde{t}_k\bigr)+\tau_k\widetilde{t}_k\Bigr)\,\Omega_k ,
\end{equation}
and consequently:
\begin{itemize}
\item[i)] the quadratic integrability conditions are exactly the $m$ relations
\begin{equation}

\tau_{2-n-k}\bigl(t_k-\widetilde{t}_k\bigr)+\tau_k\widetilde{t}_k=0,\qquad 1\leq k\leq m ;
\end{equation}
\item[ii)] these conditions are also sufficient: if \eqref{eq:52} holds, then $L+L_1$ itself, with no term of
order $\geq2$, satisfies \eqref{eq:18}. In particular no integrability condition of order $\geq3$ occurs.
\end{itemize}
Therefore the versal deformation of the $\osp(n|2)$-module $\Sc^n_d$ is
\begin{equation}

\widetilde{L}=L+\sum_{k=-\infty}^{m}\tau_kf_{\frac k2}+\sum_{k=1}^m\bigl(t_kh_k+\widetilde{t}_k\widetilde{h}_k\bigr)
\end{equation}
over the base
$\mathcal{A}=\Cc\bigl[[\{\tau_k\},\{t_k\},\{\widetilde{t}_k\}]\bigr]/R$, where $R$ is the ideal generated
by the $m$ quadratic relations \eqref{eq:52}; and every integrable formal deformation of $L$ is equivalent to its
infinitesimal part.

[Prop subpolynomialconc of arXiv:2604.14122, 'The scaling limit of random walk and\\ the intrinsic metric on planar critical percolation'] There exist $\varepsilon_0>0$, $\beta>0$, $R_0 > 0$, and a function $p_0(R)$ such that the following holds for each $R \ge R_0$ and $p < p_0(R)$. Assume that 
for some $\alpha>\frac{3}{4}-\varepsilon_0$, there exists $C_0=C_0(\alpha,R,p)$ such that for all $k\in\mathbf N$ and $n> R^k$, we have
\begin{equation}
    \mathbf{P}(X_{R^{\kappa-k}}> \mathbf{q}_n)\leq C_0R^{-\alpha k}.
\end{equation}
Then 
there exists $C_1=C_1(\alpha,R,p)$ such that for all $k\in\mathbf N$ and $n> R^k$, we have
\begin{equation}
    \mathbf{P}(X_{R^{\kappa-k}}> \mathbf{q}_n)\leq C_1R^{-(\alpha+\beta) k}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:ZIMsurvival of arXiv:2607.29409, 'The Zombie Infection Model'] The following statements are equivalent:
		\begin{enumerate}
			\item $\exists \lambda_{*}^{\ZIM}\in [1,\infty)$ such that $\BP^{\ZIM}_{\lambda,G,\Delta}
				( \lim_{t\rightarrow \infty}{\mathcal{Z}}_{t}= \infty ) >0$ for all $\lambda
				>\lambda_{*}^{\ZIM}$ and $\Delta \Subset V$.


			\item $\exists \lambda_{c}^{\SIR}\in (0,\infty)$ such that $\BP_{\lambda,G,\Delta}
				^{\SIR}( \lim_{t\rightarrow \infty}{\mathcal{I}}_{t} = \infty ) >0$ for
				all $\lambda>\lambda_{c}^{\SIR}$ and $\Delta \Subset V$.


			\item $p_{c}^{\siteperc}(G)<1$. 
		\end{enumerate}
		In particular, if $p_{c}=p_{c}^{\siteperc}(G)<1$, we may set
		$\lambda_{*}^{\ZIM}= \frac{\sqrt[d]{p_{c}}}{1-\sqrt[d]{p_{c}}}$ with
		$d=\mathrm{deg}(G)-1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition it:boundary_conditions of arXiv:2609.04140, 'The conformally invariant metric on $\CLE_4$ III:\\ uniqueness'] Let $a,b>0$ and let $h$ be a GFF in a proper simply connected domain $G \subseteq \BC$. We say that a local set $A$ of $h$ is a \emph{two-valued local set} of $h$ of levels $-a$ and $b$ if it satisfies the following properties.
	\begin{enumerate}
		\item 
		If $h_{A}$ denotes the harmonic extension to $G\setminus A$ of the boundary values of $h$ on $A$, then we have that $h_{A} \in \{-a,b\}$ a.s.
		\item 
		For any smooth test function $f \in C_0^{\infty}(G)$, a.s.,
		\begin{align*}
			(h,f) = (h-h_{A} , f) + \int_{G \setminus A} h_{A}(x) f(x) \mathrm{d}x.
		\end{align*}
		\item  The set $A \cup \partial G$ has a finite number of connected components.
	\end{enumerate}

[Definition eq8 of arXiv:2608.30592, 'Infinite Matrix Operators and $E$-Frames in Hilbert Spaces'] We say a sequence $\Psi=\lbrace \psi_k\rbrace_{k=1}^{\infty}$ is an $E$-sequence in $\mathcal{H}$ if, its $E$-transform, i.e. the sequence 
\begin{equation}
E\Psi=\left\lbrace\sum_{k=1}^{\infty}E_{n,k}\psi_k\right\rbrace_{n=1}^{\infty},
\end{equation}
is a well defined sequence in $\mathcal{H}$, that is, the series in (equation eq8 of the paper) converges for all
 $n\in\mathbb{N}$.

[Proposition prop:pathwise-cluster-product-green-energy of arXiv:2608.02459, 'Response Calculus for Spectral Simplicity\\ and Joint Eigenvalue Densities'] Fix $x\in\Omega_{\rm Fr}\cap\Omega_{\rm op}$, and let
$(\Lambda_i^x,\phi_i)$ and $(\Lambda_j^x,\phi_j)$ be positive eigenpairs of
$A_x$ with real $L^2(M_x)$-normalized eigenfunctions.  Then
\begin{equation}
 \phi_i\phi_jM_x\in\mathcal M_{\rm fe}(D),

\end{equation}
and
\begin{equation}
 I_D(|\phi_i\phi_j|M_x)
 \le M_x(D)^{1/2}K_G(x)^{3/2}
      \min\{(\Lambda_i^x)^2,(\Lambda_j^x)^2\}<\infty.

\end{equation}
Consequently, for every $g\inH$,
\begin{equation}
 \big\langleU_D(\phi_i\phi_jM_x),g\big\rangle_{H}
 =\int_D\widetilde g\,\phi_i\phi_j\,dM_x.

\end{equation}

