[Corollary 12 (Jiang--Lee--Vempala conjecture) of arXiv:2608.27657, '\bfseries Stein Kernels and Normal Approximation\\ for Log-Concave Bilinear Forms'] Assume the estimates in \cref{thm:letwin}.  If \(X,Y\in\R^n\) are
independent isotropic log-concave random vectors and \(G\sim N(0,1)\), then
\begin{equation}
  \boxed{
  W_2^2\!\left(
    \Law\!\left(\frac{\langle X,Y\rangle}{\sqrt n}\right),
    \Law(G)
  \right)
  \leq\frac{20}{n}.}
  \tag{5.12}
\end{equation}
Equivalently, if \(G_n\sim N(0,n)\), then
\begin{equation}
  W_2^2\!\left(\Law(\langle X,Y\rangle),\Law(G_n)\right)\leq20.
  \tag{5.13}
\end{equation}
Thus the dimension-free central limit conjecture of
Jiang, Lee, and Vempala \cite{JLV} follows from the cited estimates.

[Lem 39 of arXiv:2510.22783, 'Universality of Cutoff for Riffle Shuffling'] If $\delta$, $\chi$, $\varepsilon$ are as in \eqref{eq:small-params}, the following properties hold for each $y\in \mathcal A$.
        \begin{enumerate}[label=(\alph*)]
            \item 

            If $x \in A_{y,z}^{\stable}$, then we have
            \begin{equation}
                4 c_L(x)- c_F(x)+2c_E( x)+\sum_{0\leq i\leq z}c_{\tot}^{(i)}H(\{c_l^{(i)}\}_{(i,l)\in T})\leq-\Omega(\varepsilon).
            \end{equation}
            \item 

            If $x\in A_{y,z}^{\stable}$ and $A_{y,z}^{\stable}\neq\{y\vee z\}$, then we have
            \begin{equation}
                - c_F(x)+2c_E( x)+\sum_{0\leq i\leq z}c_{\tot}^{(i)}H(\{c_l^{(i)}\}_{(i,l)\in T})\leq-\Omega(\varepsilon).
            \end{equation}
            \item 

            If $A_{y,z}^{\stable}=\{y\vee z\}$, we have 
            \begin{equation}
                c_E(y\vee z)+c_L(y\vee z)\leq -\Omega(\varepsilon).
            \end{equation}
        \end{enumerate}

