[Definition 10 (Two-parameter rough integral over the simplex) of arXiv:2605.08844, 'Signature Kernel and Schwinger-Dyson Kernel Equations as Two-Parameter Rough Differential '] Let $Z \in \mathcal{D}^{p}_{\mathbf{X}}\!\left(\Delta_{[a,b]},\,\mathrm{Hom}(V \boxtimes V, F)\right)$ and let $\widehat{Z}$ be its symmetrisation, defined as above. We define the two-parameter rough integral of $Z$ over the simplex $\Delta_{[a,b]}$ by
\begin{equation}
\int_{\Delta_{[a,b]}} Z_{s,u}\, d\left(\mathbf{X}_s,\mathbf{X}_u\right)
:= \frac{1}{2}\int_{[a,b]\times[a,b]} \widehat{Z}_{s,u}\, d\left(\mathbf{X}_s,\mathbf{X}_u\right).
\end{equation}

[Theorem t: independent avsets of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Let $m \in \N_0$, and let $\mu$ be a random finite signed measure on $\R^d$. Suppose that $\Phi$ is a locally square-integrable invariant point process that is $2m$-uniform, and suppose that $K$ is a transport kernel such that $(K_x^\ast)_{x\in\Phi}$, conditioned on $\Phi$, is a sequence of independent random finite measures distributed like $\mu$. Further, assume that
    \begin{align}
        \BE\bigg[\bigg(&\int \|x\|^m+1\, |\mu|(dx)\bigg)^2\bigg] < \infty, \\
        &\int x^{\otimes q}\, \mu(dx) \textnormal{ is deterministic for } q\in\N_0, q<m,\\
        &\int x^{\otimes m}\, \mu(dx) \textnormal{ is not deterministic}.
    \end{align}
    Then $K\Phi$ is a locally square-integrable invariant random measure and solely $2m$-uniform.

    \begin{proof}
        If $\mu$ was a random probability measure,~[Klatt_Last_Lotz_Yogeshwaran_2025] would yield that $K\Phi$ is a locally square-integrable random measure and that
        \begin{equation}
            \hat\beta_{K\Phi} = \big|\BE[\hat\mu]\big|^2 \cdot \hat\beta_\Phi + \alpha_\Phi(\{0\}) \BV[\hat\mu]\cdot \lambda_d.
        \end{equation}
        Similarly, this formula was also derived in [Lachièze-Rey_2025a], where $\mu$ is assumed to be a random finite counting measure. Here, we show this formula in the slightly more general setting that $\mu$ is a random finite signed measure.

        First, since $\Phi$ and $K$ are invariant, $K\Phi$ is also invariant. Further, it is locally square-integrable because of independence and $\BE\big[\|\mu\|^2\big]<\infty$, as
        \begin{align}
            \BE\big[|K\Phi(B_1)|^2\big] &= \iint \BE_{0,y}^\Phi\big[K(0, B_1-x), \overline{K(y, B_1-x)}\big]\,dx \,\alpha_\Phi(dy)\nonumber\\
            &= \iint \BE\big[\mu(B_1-x)\big]\BE\big[\overline{\mu(B_1-x-y)}\big]\,dx \,\alpha_\Phi(dy)\nonumber\\
            &\qquad + \alpha_\Phi(\{0\})\int\BV[\mu(B_1-x)]\,dx\nonumber\\
            &= \BE\big[|L\Phi(B_1)|^2\big] + \alpha_\Phi(\{0\})\int\BV[\mu(B_1-x)]\,dx\nonumber\\
            &< \infty,
        \end{align}
        where $L$ is an invariant deterministic transport kernel from $\R^d$ to $\R^d$ with $L^\ast(y)=\BE[\mu], y\in\R^d$. The fact that $L\Phi$ is locally square-integrable can be derived analogously to~[Klatt_Last_Lotz_Yogeshwaran_2025]. Additionally, we can derive from~(equation e:alpha independent avsets of the paper) and $\BE[L\Phi]=\BE[K\Phi]$ that
        \begin{equation}
            \beta_{K\Phi} = \beta_{L\Phi} + \alpha_\Phi(\{0\}) (\BE[\mu\star\mu]-\BE[\mu]\star\BE[\mu]).
        \end{equation}
        Hence,
        \begin{align}
            \hat\beta_{K\Phi} &= \hat\beta_{L\Phi} + \alpha_\Phi(\{0\}) \BV[\hat\mu]\cdot \lambda_d\nonumber\\
            &= \big|\BE[\hat\mu]\big|^2 \cdot \hat\beta_\Phi + \alpha_\Phi(\{0\}) \BV[\hat\mu]\cdot \lambda_d, 
        \end{align}
        which proves~(equation e: spectral measure cluster process of the paper) in this more general setting. Further,
        \begin{equation}
            \hat\mu(k) = \int e^{-i\langle k,x\rangle}\, \mu(dx) = \sum_{q=0}^m \frac{(-ik)^{\otimes q}}{q!} \int x^{\otimes q} \, \mu(dx) + \int g(\langle k ,x\rangle)\, \mu(dx), \quad k\in\R^d,
        \end{equation}
        where
        \begin{equation}
            g(z) := e^{-iz} - \sum_{q=0}^m \frac{(-iz)^q}{q!} = \sum_{q=m+1}^\infty \frac{(-iz)^q}{q!},\quad z\in\R.
        \end{equation}
        Thus, there is some $c>0$ such that
        \begin{equation*}
            |g(z)| \leq c\min(|z|^{m}, |z|^{m+1}),\quad z\in\R.
        \end{equation*}
        This bound allows us to apply~(equation e: ind avsets moment of the paper) and the dominated convergence theorem to obtain that, for $k\in\R^d$,
        \begin{equation*}
            \frac{1}{\|k\|^{2m}}\BE\bigg[\bigg|\int g(\langle k,x\rangle)\, \mu(dx)\bigg|^2\bigg] = \BE\bigg[\bigg|\int \underbrace{\frac{g(\langle k,x\rangle)}{\|k\|^m}}_{|\cdot|\leq c \min(\|x\|^m, \|k\|\|x\|^{m+1})}\, \mu(dx)\bigg|^2\bigg] \xrightarrow{k\to 0} 0.
        \end{equation (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop Delta1 of arXiv:2506.07158, 'The diffusivity of supercritical Bernoulli percolation is infinitely differentiable'] \zhaocomment{We wish to use uniform bound for (equation e:derivative_formula_modified of the paper) to give a uniform bound for (equation e:derivative_formula of the paper) (without-boundary version), but we need to be careful.}
