[Proposition 12 of arXiv:2604.08127, 'Asymptotics of Brownian occupation measures \\ with unusually large intersections'] Suppose $p \ge 2$ and $d(p-1) < 2p$. The distributions $t^{-p} \widetilde{\ell}_t^{\otimes p}$ satisfies an LDP in $(\widetilde{\mathcal{X}}(\mathbb{R}^d), \mathbf{D})$ defined in \eqref{eq:MV-set}, \eqref{eq:MV-metric} with good rate function
    \begin{equation}

        \mathcal{I}^{\ell} (\zeta) = \begin{cases}
            \mathcal{I}(\xi^{\otimes p}) & \text{if } \mathcal{I}(\xi^{\otimes p}) < \infty \text{ and }\prod\limits_{j=1}^p \psi_i^j = \sqrt{\frac{d\gamma_i}{d x}} \\
            \infty & \text{otherwise},
        \end{cases}
    \end{equation}
    where $\zeta = \{ \widetilde{\gamma}_i\}_{i \in I} \in \widetilde{\mathcal{X}}(\mathbb{R}^d)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 67 of arXiv:2605.03236, 'Stochastic It\^o Equations and Parabolic Second-Order Equations with singular Drift'] Under Assumption \ref{assumption 8.24.1}
for any $\lambda\geq \varkappa_{0}^{2}\rho_{b}^{-2}$ and   Borel nonnegative $f(x)$  
we have on $\{\tau<\infty\}$
\begin{equation}

 E_{\cF_{\tau}}\int_{0}^{\infty}e^{- \lambda s}
f( x_{\tau+s}-x_{\tau}) \,dt\leq 
N(\sfp_{0})\ell\lambda^{-\alpha-1/q} \|\Psi_{\lambda}  f\|_{L_{p}(\bR^{d})},
\end{equation}
where $\Psi _{\lambda}( x)=\exp(- \sqrt{\lambda}  |x|\sfp_{0}/16)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 15 (Integrated Davies trick) of arXiv:2609.01098, 'Gaussian upper bounds for averaged heat semigroups on graphs'] For any $q\in[1,\infty]$, denote by $q'$ its H\"older conjugate and let $0\leq V,W\in\ell^\infty(X),$ $I\subset \RR$. Then, for any $q$-norm with respect to any measure on $X$, we have 
\begin{multline*}
\left(
\fint_I \|VP_{2\tau}W\|_{q',q}^\frac{q}{2}\drm \tau 
\right)^\frac{2}{q}
=
\left(
\fint_I \|WP_\tau V\|_{q',q}^\frac{q}{2}\drm \tau 
\right)^{\frac{2}{q}}
\\
\leq 
\inf_{\omega\in\ell^\infty(X)}
\sup_{\supp V}\euler^{-\omega}
\sup_{\supp W}\euler^{\omega}
\left(
\fint_I
\|V P_\tau^\omega\|_{2,q}^q
\drm \tau
\right)^\frac{1}{q}
\left(
\fint_I
\|W P_\tau^{-\omega}\|_{2,q}^q
\drm \tau
\right)^\frac{1}{q}.
\end{multline*}

[Theorem 47 (Fixed-rank Laurent integrality) of arXiv:2608.29585, '2608.29585'] For every zero-framed knot $K$, every fixed $n\ge2$, and every $k\ge0$,
the formal Newton coefficient in \eqref{eq:formal-SU} satisfies
\begin{equation}
 H_k^{(n)}(K;q)\in\Z[q^{\pm1}].
\end{equation}
Equivalently, for every $r\ge0$,
\begin{equation}
 J_r^{SU(n)}(K;q)=\sum_{k=0}^{r}
 \left(\prod_{i=0}^{k-1}\{r-i\}\{r+n+i\}\right)
 H_k^{(n)}(K;q),
\end{equation}
with unique Laurent-polynomial coefficients.

[Lemma jointsources of arXiv:2606.30475, 'Ancestries in random $d$-DAGs'] Let $1\leq i_1 < \dots < i_r \leq n$ for some $r\in\mathbb{N}$. Then
 \begin{equation}
  \mathbb{P}\big(a_{i_1}(n)=\dots=a_{i_r}(n)=1) = \prod_{j=1}^r \left(\frac{i_j-j}{n-j}\right)^d.
 \end{equation}

