[Theorem 74 of arXiv:2609.03875, 'Measure theory without infinities'] {$ $}
  \begin{enumerate}
  \item [(i)] Let $\mu$ be a positive measure and $\eta = \as[\mf R]\mu$. Then $\eta$ is a $\sigma$-finite $\mf R$-valued measure, $\eta$ is an extension of $\mu$, $D_\eta = \q\eta = \q\mu$, and $\mu = \mf F\eta$.
  \item [(ii)] Let $\eta$ be a $\sigma$-finite $\mf R$-valued measure and $\mu = \mf F\eta$. Then $\mu$ is a positive measure and $\eta = \as[\mf R]\mu$.
  \end{enumerate}

