[Theorem thm:stat.dist.alpha>0.beta=lambda0.exp of arXiv:2607.10708, 'A class of Markov processes with resetting and applications to cybersecurity'] \addcontentsline{toc}{subsection}{Theorem \thetheorem\ {case \texorpdfstring{$\beta=\lambda_o$}{Theorem β=λₒ}} and \texorpdfstring{$\alpha>0$}{α>0}  and exponential jumps}
    Under Assumption (ass_ex of the paper), the invariant measure $\Pi$ for $\Lambda$ is given by the following:

\begin{equation} 
    \Pi(d\lambda) = \frac{K_0}{\beta} \delta_{\beta}(d\lambda) + \pi(\lambda) d\lambda

\end{equation}
    where the density is given by 

\begin{equation} 
    \pi(\lambda)
    = \frac{K_0}{\beta} \frac{\beta\theta}{\alpha(\lambda-\beta)} \int_\lambda^A \left(\frac{u-\beta}{\lambda-\beta}\right)^{-\frac{\beta}{\alpha}} e^{-(\frac{1}{\alpha}-\theta)(u-\lambda)} du \ ,

\end{equation}
    with $K_0/\beta = \frac{\alpha}{\alpha+ \beta \theta K_3}$ and 

\begin{equation}
  K_3 =
  \begin{cases}
    -{_1F_1}^{(1,0,0)}\left(0,\frac{\beta }{\alpha },\frac{(\alpha  \theta -1) (A-\beta )}{\alpha }\right), & \alpha \not= 1/\theta \\
    \frac{\alpha}{\beta}  \left( A -\beta\right) & \alpha = 1/\theta
  \end{cases}

\end{equation}
  where ${_1F_1}^{(1,0,0)}$ is the Kummer’s confluent hypergeometric function.

[Lemma lem:bounded first moments of arXiv:2606.02472, 'Correlated uniform attachment trees'] Let $T_n \sim \mathrm{UA}(n)$, let $u \in \{0,\ldots,n\}$ and let $r \in \left[1,n\right]$. Then
    \begin{equation}
        \sum_{v=r}^{n} \mathbb{P} \left( v \sim u, F_{T_n}(v) > \frac{n}{r} \right) \leq 2,
    \end{equation}
    and
    \begin{equation}
        \sum_{v=u+1}^{r-1} \mathbb{P} \left( v \sim u, F_{T_n}(v) \leq \frac{n}{r} \right) \leq 1 .
    \end{equation}

