[Lemma lem:perturbation_mat_bd_ii of arXiv:2506.23062, 'Shifted Composition IV\@: \\ Toward Ballistic Acceleration for Log-Concave Sampling'] If $h\lesssim \gamma^{-1} \wedge {\gamma/\beta}$ and $c_0\lesssim A$ for sufficiently small absolute constants, then
    \begin{align*}
        \norm{\mathcal{M}_t}_{\rm op} + \norm{\mathcal{M}_t^{\rm skew}}_{\rm op} + \norm{\mathcal{N}_t}_{\rm op}
        &\lesssim \frac{\beta}{\gamma_t} + \eta_t^\mathsf{p}\,.
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma eloge-derivative of arXiv:2603.01322, 'Gibbs conditioning, atypical consensus and splitting Gibbs measures on random regular grap'] Fix $\nu\in \P(\X)$ and $\k\geq 2$. Given $\pi\in \Psym{\X}$, for any $\xi\in \Psym{\X}$, define
\begin{equation*}
    \pi_\varepsilon=\pi_\varepsilon[\xi]\coloneqq (1-\varepsilon)\pi+\varepsilon\xi,\quad \forall \varepsilon\in [0,1].
\end{equation*}
Then
\begin{equation}
    \lim_{\varepsilon\rightarrow 0^+}\frac{1}{|\varepsilon\log \varepsilon|}\cpr{J_\k^\nu(\pi_\varepsilon)-J_\k^\nu(\pi)}=(\k-1)\sum_{x\in \X}\xi^o(x)\indf_{\pr{\pi^o(x)=0}}-\frac{\k}{2}\sum_{x,z\in \X}\xi(x,z)\indf_{\pr{\pi(x,z)=0}}.
\end{equation}

[Theorem SSRR of arXiv:2411.04590, 'Singular stochastic delay equations driven by fractional Brownian motion: Dynamics, longti'] Assume \((\Omega, \mathcal{F}, \mathbb{P}, \theta)\), \(\frac{1}{3} < \beta \leq \gamma < H\), and let \(\mathbf{B}\) be the delayed \(\gamma\)-rough path cocycle constructed in Theorem (thm:B_delayed_cocycle of the paper). Assume \(\xi \in \mathscr{D}_{\mathbf{B}(\omega)}^{\beta}([-r,0])\) and consider the following equation:
			\begin{align}
				\begin{split}
					\mathrm{d}y_{t} &= A\left(y_t, \int_{-r}^{0} y_{\theta+t} \pi(\mathrm{d}\theta)\right) \mathrm{d}t + G \left(y_{t}, y_{t-r}\right) \mathrm{d}\mathbf{B}_{t}(\omega), \\
					y_{s} &= \xi_{s} \quad \text{for} \quad -r \leq s \leq 0,
				\end{split}
			\end{align}
			with the same conditions as in Theorem (SSS of the paper). Then this equation admits a unique solution globally in time. Assume \((\phi^{t}_{\mathbf{B}(\omega)}(\xi))_{t \geq 0}\) is this solution. For \(m \in \mathbb{N}\), define
			\[
			\varphi^{m}_{\omega}(\xi) := \left(\phi^{(m-1)r+t}_{\mathbf{B}(\omega)}(\xi)\right)_{0 \leq t \leq r}.
			\]
			In this case, we indeed have \(\varphi^{m}_{\omega}(\xi) \in \mathscr{D}_{\mathbf{B}(\theta_{mr}\omega)}^{\beta}([-r,0])\). Moreover, the following map
			\begin{align}
				\begin{split}
					&\varphi^{m}_{\omega}: \mathscr{D}_{\mathbf{B}(\omega)}^{\beta}([-r,0]) \rightarrow \mathscr{D}_{\mathbf{B}(\theta_{mr}\omega)}^{\beta}([-r,0]), \\
					& \xi \longrightarrow \varphi^{m}_{\omega}(\xi),
				\end{split}
			\end{align}
			is continuous and satisfies the cocycle property, i.e.,
			\begin{align}
				\varphi^{p+q}_{\omega} = \varphi^{p}_{\theta_{qr} \omega} \circ \varphi^{q}_{\omega},
			\end{align}
			for all \(p, q \in \mathbb{N}\).

