    \begin{align*}
        &\tau_s^{(1)}=\inf\{t>0 \ : \ |m_t| \leq\frac12(\mathsf{m}_{2}+\mathsf{m}_{3})\}\,,\\
        &\tau_l^{(i)}=\inf\{t>\tau_s^{(i)} \ : \ |m_t| \geq \mathsf{m}_{3}\}\,,&&i=1,2,...\nonumber\\
        &\tau_s^{(i)}=\inf\{t > \tau_l^{(i-1)} \ : \ |m_t|\leq \frac12(\mathsf{m}_{2}+\mathsf{m}_{3})\}\,,&&i=2,3,...
    \end{align*}
