&
\dfrac{1}{\sqrt{2\pi}}
\sum_{k=0}^{N} 
\dfrac{(-1)^{k}}{2^{k} k! (k+1/2)}
\dfrac{1}{\big(\frac{1}{2\pi}\vert\log\varepsilon\vert\big)^{k+1/2}}
\sum_{j=0}^{k} \dfrac{(-1)^{j}(2k+1)!}{2^{j} j! (2(k-j)+1)!}
\,\widetilde{F}^{\text{SLE}_{4}}_{j}\,\psi_{2(k-j)+1,A}
\\&+o(\vert \log\varepsilon\vert^{-(N+1/2)}).
\end{align*} (Verbatim from the paper's TeX; symbols are the source paper's. Stated as open/conjectural; no resolution of it was found in the paper's own text by the rules of problem_index.py - a paper may still prove special cases of a conjecture it states.)

[Cor non of arXiv:2411.00663, 'Ergodicity and Mixing of invariant capacities and applications'] Suppose exactly the same conditions as that of Corollary (cor;non of the paper), then 
	\begin{equation}
		\lim_{n\to\infty}\frac{1}{n}\sum_{i=0}^{n-1}P(B\cap T^{-i}C)=P(B)Q(C)\text{ for any }B,C\in\mathcal{F}.
	\end{equation}
	In particular, 
	\begin{equation}
		\lim_{n\to\infty}\frac{1}{n}\sum_{i=0}^{n-1}P\circ T^{-i}=Q.
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm-LSI-3 of arXiv:2411.13788, '\bf Gradient bounds and Liouville property for a class of hypoelliptic diffusion via coupl'] Let $f$ be a   positive, globally Lipschitz and bounded $C^2\left(\mathbb{R}^{m_0}\times\cdots\times\mathbb{R}^{m_r}\right)$ function. Then for any fixed $t\ge0$, $x=(x^{(1)},\cdots,x^{(r+1)})\in \mathbb{R}^{m_0}\times\cdots\times\mathbb{R}^{m_r}$,  we have
\begin{align}
\hskip0ptP_t(f\ln f)-(P_tf)\ln P_tf&\le \frac12P_t\left(f\left\langle \int_0^tE(-(t-s))AE^*(-(t-s))ds\nabla \ln f,\nabla \ln f\right\rangle\right).
\end{align}
For $t>0$, the following reverse Logarithmic Sobolev inequality  holds for any positive bounded function $f$:
\begin{align}
P_t(f\ln f)-P_tf\ln P_tf&\ge \frac12P_tf\left\langle \mathcal{C}(t)\nabla\ln P_tf,\nabla \ln P_tf\right\rangle,
\end{align}
where $\mathcal{C}(t)$ defined in (equation C-M of the paper) is a positive matrix.

