[Defn 3 of arXiv:2608.13976, 'Boundary Harnack principle for diffusion with jumps on metric measure spaces'] \begin{enumerate}
 \item[\rm (i)]
 We say condition   ${\bf (ED)} _{\leq, x_0, R}$ holds
  if for the  ball $B=B(x_0, R)$ with $\overline B \subsetneq \sX$,
  there is a constant $C_1=C_1(x_0, R)>0$  so that   for
      any  open subset $ U\subset 2^{-1}B$ and every $  x\in B_U(x_0,  R/64)$,
\begin{equation}
\P_x  \big( X^{B}_{\tau_{B_U(x_0, R/32)}} \in U \big)
\leq   C_1\E_x[\tau_{B_U(x_0,  R/32)}]  .
 \end{equation}

  \item[\rm (ii)]
We say condition  ${\bf {(\wh{ED})}} _{\leq, x_0, R}$ holds
 if for the  ball $B=B(x_0, R)$ with $\overline B \subsetneq \sX$,
there is a constant $C_2=C_2(x_0, R)>0$  so that  for
 any  open subset $  U\subset 2^{-1}B$ and
every $x\in  U \cap A(x_0, 3R/8, R/2)$,
\begin{equation}
\P_x  \Big( \wh X^{B}_{\wh\tau^B_{U\cap  A(x_0, R/4, R/2)}}  \in U \Big)
\leq   C_2\E_x \left[ \wh\tau^{B}_{U\cap  A(x_0, R/4, R/2)} \right] .
 \end{equation}

\item[\rm (iii)] We say condition  ${\bf (ED)}^s _{\leq, R}$
  (resp. ${\bf (\wh {ED} ) }^s_{\leq, R}$) holds
 if  \eqref{e:ED1} holds  with $C_1=C_1 (R)$ (resp.  \eqref{e:ED2} holds with constant $C_2=C_2(R)$)
for any ball $B$ with radius $R$  and  $\overline B \subsetneq \sX$.

 \end{enumerate}

[Theorem 7 (Critical rescaled power variation) of arXiv:2606.11994, 'Sample Path Properties of the\\ Fractional Wiener--Weierstrass Bridge II'] Assume $H=K$.  Then, $\Pp$-a.s.~for every $t\in[0,1]$,
\begin{equation}
\lim_{n\uparrow\infty}
\frac1{n^{1/(2H)}}
\sum_{k=0}^{\floor{tb^n}-1}
\abs{Y((k+1)b^{-n})-Y(kb^{-n})}^{1/H}
=
\frac{2^{1/(2H)}\Gamma\big(\frac{H+1}{2H}\big)}{\sqrt\pi}\,t.
\end{equation}
In particular, almost all sample paths of $Y$ have infinite $b$-adic $(1/H)^{\text{th}}$ variation:
\begin{equation}
 V_n^{(1/H)}(Y,t)  \longrightarrow+\infty\qquad\text{for every $t\in(0,1]$ $\Pp$-a.s.}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 22 of arXiv:2604.19220, 'Split merge dynamics for expanding intervals and point processes on the real line.'] Let $(U_{i,k})_{ k\in \ZZ, \;  i \in \NN} $ be a sequence of i.i.d. uniform  random variables on $[0,1]$ independent of $(E_{1,i}, \; E_{2,i})_{ i \in \NN} $ be a pair of independent sequences of i.i.d. exponential  random variables with parameter $1.$ Both sequences are assumed to be independent. Let us define a $ {\cal S}_{l,m} $ valued Markov chain with the following procedure. 

 For $ i \ge 0 $ let $ \X_i = \{ \X_{i}^{1}< l < \X_{i}^{2}< \ldots < \X_{i}^{n-1} < m < \X_{i}^{n} \}.$
 \begin{itemize}
 \item  If   $ n > 2.$ Then for $ k = 2 $ to $ n $ let 
 $$ \tilde{\X}_i^k = U_{i+1,k} \X_{i}^{k-1} + (1-  U_{i+1,k}) \X_{i}^{k}.$$
 \begin{itemize}
 \item  If $ \tilde{\X}_i^2 < l,$ we set $ \X_{i+1}^1 = \tilde{\X}_i^2,$ and for $ k = 2 $ to $ n-1 $ $ \X_{i+1}^{k} =  \tilde{\X}_i^{k+1}.$ 
 \item  If  $ \tilde{\X}_i^2  > l,$ we take $ \X_{i+1}^1 =  \X_{i}^1 - E_{1,i}  $ and for  $ k = 2$ to $ n-1 $  $ \X_{i+1}^{k} =  \tilde{\X}_i^k.$ 
 \item  If $ \tilde{\X}_i^n < m , \; \X_{i+1}^n=\tilde{\X}_i^n $ and $ \X_{i+1}^{n+1}= \X_i^n +  E_{2,i}.$      \item If $ m < \tilde{\X}_i^n, \;  \X_{i+1}^n= \tilde{\X}_i^n.$
 \end{itemize}
 \item If $ n = 2,$ 
 $$ \tilde{\X}_i^2 = U_{i+1,2} \X_{i}^{1} + (1-  U_{i+1,2}) \X_{i}^{2}.$$
 \begin{itemize}
 \item  If $ \tilde{\X}_i^2 < l,$ we set $ \X_{i+1}^1 = \tilde{\X}_i^2,$ and $ \X_{i+1}^2 = \X_i^2+ E_{2,i}.$
 \item  If $ l < \tilde{\X}_i^2 < m,$ we set 
 $$   \X_{i+1}^1 =  \X_{i}^1 - E_{1,i}, \;  \X_{i+1}^2 =  \tilde{\X}_i^2, \; \X_{i+1}^3 = \X_i^2 +  E_{2,i}. $$
 \item  If $ m < \tilde{\X}_i^2,$ we set $ \X_{i+1}^1 = \tilde{\X}_i^1 - E_{1,i},$ and $ \X_{i+1}^2 = \tilde{\X}_i^2.$
 \end{itemize}
 \end{itemize}

[Proposition prop:T=Gamma of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] With the same assumption and notation as in Proposition (prop:ribbon of the paper), 
let \begin{equation}
    b'_{n}=\begin{cases}
        -\frac{1}{2},&n=0,\\
        1,&n=2,\\
        0,&\text{otherwise},
    \end{cases}
\end{equation} then  for any  non-negative integers $n_1,\dots ,n_s$ we have 
    \begin{equation}
        \mathbb{E}\big[\prod_{j=1}^s \mathrm{Tr} (\widetilde{T}_{n_j}(X)+b'_{n_j}\mathbf{I})\big]=\sum_{\Gamma\in \mathscr{D}_{s;\beta}} \mathfrak{F}_{\Gamma}(\{n_j\}).
    \end{equation}

