[Prop 5 of arXiv:2506.10650, 'Admitted symmetries of Backward Stochastic Differential Equations'] \begin{equation}
     \zeta:=\bar{Z}=\frac{\varphi_y Z+\sigma\varphi_x}{\eta}.
 \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop lebowitz of arXiv:2608.18045, 'Supercritical sharpness for the random cluster representation of real-valued spin models'] Fix a finite graph $G = (V,E)$. Consider two sets of coupling constants $\{J_{xy}\}_{xy\in E}$ and $\{J'_{xy}\}_{xy\in E}$ satisfying $|J'_{xy}| \le J_{xy}$ for every $xy\in E$, and two external magnetic fields $\mathsf{h}$ and $\mathsf{h}'$ satisfying $|\mathsf{h}'_x|\le \mathsf{h}_x$ for every $x\in V$. Consider a family of single-site measures $(\rho_x)_{x\in V}$ such that for every $x\in V$, $\rho_x$ is either an even measure over $\mathbb{R}$ or $\rho_x$ is supported on $\mathbb{R}^+$. For every pair of moment functions $A, B:V\to\mathbb{N}$, one has
\begin{equation}
\langle \tau_A \tau_B \rangle - \langle \tau_A \tau_B \rangle' \ge |\langle \tau_A \rangle \langle\tau_B \rangle' - \langle \tau_A \rangle' \langle \tau_B \rangle|,
\end{equation}
where $\langle \cdot \rangle$ and $\langle \cdot \rangle'$ stand for the expectations under the measures $\nu_{G,\rho,J, \mathsf{h}}$ and $\nu_{G,\rho,J',\mathsf{h}'}$ respectively\footnote{Note that $\beta$ has been chosen equal to $1$ here which explains why it disappeared from the notation.}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition attractor of arXiv:2603.12774, 'Synchronization by noise for stochastic differential equations driven by fractional Browni'] A random compact set $\mathcal{A} = \{ \mathcal{A}(\omega^-) \}_{\omega^- \in \mathcal{B}}$ is called a \(\mathrm{P}\)-pullback attractor for the SDS \(\varphi\) if the following conditions are satisfied.
	\begin{enumerate}
		\item For every $\omega^-, \omega^+ \in \mathcal{B}$, we have
		\[
		\Phi^{t}_{(\omega^-,\omega^+)}(\mathcal{A}(\omega^-)) = \mathcal{A}(P_t(\omega^-,\omega^+)).
		\]

		\item For every compact set 
		\( K \subset \mathbb{R}^d \)
		\[
		\lim_{t \to \infty} \sup_{x \in K} d(\varphi^{t}_{\omega^-}(x), {\mathcal{A}}(\omega^-)) = 0 \quad \mathbf{P}\text{-a.s.}
		\]
	\end{enumerate}
	\begin{comment}
		\textcolor{red}{
			This statement must not be difficult to show:
			The Weak \(\mathrm{P}\)-pullback attractor  is unique up to set with full measure.
		}
	\end{comment}

[Lem e:Phixx of arXiv:2504.07255, 'A Tail-Respecting Splitting Numerical Scheme\\ for L\'evy-Driven SDEs With Superlinear Dri'] Let assumptions $\mathbf{H}^{\mathrm{Lip}_+}_A$ and
$\mathbf{H}_{A_x,A_{xx}}$ hold. Then, for all $x\in\mathbb{R}^d$, $t\in [0,1]$,
\begin{align}

\|\Phi_{xx}(t,x)\|&\leq_C 1,\\

\|\Phi_{xx}(t,x)\|&\leq_C   t (1+\|x\|^\chi).
\end{align}

