body:
[Corollary cor:GLPP-scalar of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] The one-point Fredholm determinant
$F_{n, m, a} = \det(I - K_{n, m, a})$ satisfies
\begin{equation}
F_{n, m+1, a}F_{n-1, m, a-2}
- qF_{n-1, m, a-1}F_{n, m+1, a-1}
- (1{-}q)F_{n, m, a-1}F_{n-1, m+1, a-1}
= 0,
\end{equation}
at every $(n, m, a)$ with $n \ge 2$ and
$a > x_{m+1} + n + 1$.

[Cor 135 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] Let $\md,\me\lesssim1$ be positive numbers. There exists a constant
    $C>1$ such that the following holds. 
	Fix $(x', y') = (x', \gamma_{x'})$ on the arctic boundary $\mathfrak A_{q;a,b,c}$ with $x' \in [1/4, 5/4]$, and denote $f = f_{x'} (\gamma_{x'})$; $\gamma = \gamma_{x'}$; $\gamma' = \gamma_{x'}'$; and $\gamma'' = \gamma_{x'}''$. 
	 Let $z=(x,y)$ with 
	\begin{flalign}

		x = x' + (\mathfrak{d} \mathfrak{e})^{1/2} \hat{x} - \gamma' \mathfrak{d} \mathfrak{e} \hat{y}; \qquad y = \gamma_{x'} + \gamma' (\mathfrak{d} \mathfrak{e})^{1/2} \hat{x} + \mathfrak{d} \mathfrak{e} \hat{y}
	\end{flalign}
        and assume that
        \begin{equation}

       \frac{ \md}{|\gamma'|},\frac{\me_{z;q}}{\me},\frac{\md_{z}}\md\in   [C^{-1},C].
        \end{equation}

	\noindent Denoting  
	\begin{flalign}

		\hat{f}(\hat{x}, \hat{y}) = (\mathfrak{d} \mathfrak{e})^{-1/2} ( f(x,y) - f); \qquad \Gamma =  \gamma''- \gamma'(1 - \gamma') \log \mathfrak{q}, 
	\end{flalign}
	\noindent we have 
	\begin{flalign}

		\hat{f} (\hat{x}, \hat{y}) =  \displaystyle\frac{\mathrm{i} \Gamma^{1/2}}{(\gamma'-1)^2}   \big( 2 (\gamma'^2 + 1) \hat{y} - \gamma'' \hat{x}^2 \big)^{1/2}  - \displaystyle\frac{\gamma'' \hat{x}}{(\gamma'-1)^2} + \mathcal{O} ( (\mathfrak{d} \mathfrak{e})^{1/2}).
	\end{flalign} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 4 (Global reciprocal bounds) of arXiv:2609.03958, '2609.03958'] Let $n\geq 2$ and $K\geq 0$. Suppose that $\lambda\in \Gamma_2$ satisfies $\lambda_1\ge\cdots\ge\lambda_n\geq -K$ and $\sigma_2(\lambda)=f$ with $f_0\leq f\leq f_1$ for two constants $f_1\geq f_0>0$.  Then there exists  $C >0$ depending only on $n$, $K$, $f_0$ and $f_1$ such that
\begin{equation}
 \sum_{i=1}^n \frac{1}{\sigma_{1;i}(\lambda)}\leq C(\sigma_1(\lambda)+1),
 \qquad
 \sum_{i=1}^n \frac{1}{\sigma_1^2(\lambda)\sigma_{1;i}(\lambda)}\leq C.
\end{equation}

[Lemma lem:CT-TASEP-WF of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] The product-graph wave functions satisfy the dual
semi-discrete linear problem
(equation eq:sc-dual-linear-1 of the paper)--(equation eq:sc-dual-linear-j of the paper)
and its adjoint
(equation eq:sc-dual-adjoint-1 of the paper)--(equation eq:sc-dual-adjoint-j of the paper)
with the shifts and edge weights above.
Explicitly:
\begin{align}
\partial_t \Psi^{t,\mathbf{a}+\mathbf{1},\mathbf{n}}
&= -\tfrac{1}{2}\bigl(\Psi^{t,\mathbf{a}+\mathbf{1},\mathbf{n}}
   - \Psi^{t,\mathbf{a},\mathbf{n}}\bigr),
 \\
\Psi^{t,\mathbf{a},\mathbf{n}+\mathbf{1}}
&= 2\Psi^{t,\mathbf{a}+\mathbf{1},\mathbf{n}}
   - \Psi^{t,\mathbf{a},\mathbf{n}},

\end{align}
and
\begin{align}
\partial_t \Phi^{t,\mathbf{a}+\mathbf{1},\mathbf{n}}
&= -\tfrac{1}{2}\bigl(\Phi^{t,\mathbf{a}+\mathbf{2},\mathbf{n}}
   - \Phi^{t,\mathbf{a}+\mathbf{1},\mathbf{n}}\bigr),
 \\
\Phi^{t,\mathbf{a}+\mathbf{1},\mathbf{n}}
&= 2\Phi^{t,\mathbf{a},\mathbf{n}+\mathbf{1}}
   - \Phi^{t,\mathbf{a}+\mathbf{1},\mathbf{n}+\mathbf{1}}.

\end{align}

[Definition 8 of arXiv:2608.30875, 'A Decomposition Theorem for Topological Semi-small Maps'] We define a \textbf{topologically stratified space} inductively on dimension. A 0-dimensional topologically stratified space $X$ is a countable set with the discrete topology. For $m > 0$ an \textbf{$m$-dimensional topologically stratified space} is a paracompact Hausdorff topological space $X$ equipped with a filtration
	\begin{align*}
		X=X_{m} \supseteq X_{m-1} \supseteq \dots \supseteq X_{1} \supseteq X_{0} \supseteq X_{-1}= \emptyset
	\end{align*}
	by closed subsets $X_{j}$ such that if $x \in X_{j}-X_{j-1}$ there exists a neighborhood $\mathcal{N}_{x}$ of $x$ in $X$, a compact $(m-j-1)$-dimensional topologically stratified space $L$ with filtration
	\begin{align*}
		L=L_{m-j-1} \supseteq \dots \supseteq L_{1} \supseteq  L_{0} \supseteq L_{-1} = \emptyset,
	\end{align*}  
	and a homeomorphism $\phi : \mathcal{N}_{x} \longrightarrow \mathbb{R}^{j} \times \mathcal{C}(L),$
	where $\mathcal{C}(L)$ is the open cone on $\mathcal{L}$, such that $\phi$ takes $\mathcal{N}_{x} \cap X_{j+i+1}$ homeomorphically onto
	\begin{align*}
		\mathbb{R}^{j} \times \mathcal{C}(L_{i}) \subseteq \mathbb{R}^{j} \times \mathcal{C}(L)
	\end{align*}
	for $m-j-1 \geq i \geq 0$, and $\phi$ takes $\mathcal{N}_{x} \cap X_{j}$ homeomorphically onto
	\begin{align*}
		\mathbb{R}^{j} \times \{ \text{vertex of }\; \mathcal{C}(L) \}.
	\end{align*}

[Lem 134 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] {Let $C>1$ be a constant.}
		Letting $x \in [1/4, 5/4]$, the following two statements hold. 

		\begin{enumerate} 
			\item Recalling $\Gamma_{x;2}$ from \eqref{gammax12}, we have for $\gamma_x \le y$ that
		\begin{flalign}

			f_x (y) = f_x (\gamma_x) + \mathrm{i} ( f_x (\gamma_x) - 1 )^2 \cdot ( 2 \Gamma_{x;2} (y - \gamma_x) )^{1/2} + (y-\gamma_x) \cdot \varsigma_1 ( x, (y-\gamma_x)^{1/2}),  
		\end{flalign}

		\noindent where $\varsigma_1: [1/4,5/4] \times \mathbb{R}_{\ge 0} \rightarrow \mathbb{C}$ is a function dependent on $(a,b,c,q)$ that satisfies the following. For any derivative $\partial_{\ell}$ in $(x,z,a,b,c,q)$, there exists a constant $C_{\ell} > 1$ such that $|\partial_{\ell} \varsigma_1 (x,z)| \le C_{\ell}$, for all $(x,z) \in [1/4,5/4] \times [0, C]$; $q \in [-\varepsilon, \varepsilon]$; and $a,b,c \in [1-\varepsilon, 1+ \varepsilon]$. 

		\item  The asymptotics can be refined close to $p^{SW}_{q;a,b,c}$. That is, assume that $\gamma_x \le y \le C \mathfrak{d}^2$ and denote
		\begin{flalign}
			D' & = f_0' (0) = \displaystyle\frac{\log \mathfrak{q}}{\mathfrak{q}^x - 1}; \\ 
			A' & = f_0'' (0) + \displaystyle\frac{\mathfrak{q}^{x} + 1}{(\mathfrak{q}^{x} - 1)^2} (\log \mathfrak{q})^2; \\
			B' & = \displaystyle\frac{1}{3} \cdot \Bigg( f_0''' (0) + \displaystyle\frac{2 (\mathfrak{q}^{2x} + \mathfrak{q}^{x}+1)}{(\mathfrak{q}^{x}-1)^3} (\log \mathfrak{q})^3 +  3 f_0'' (0)   \cdot \displaystyle\frac{ (\mathfrak{q}^{x} + 1)}{\mathfrak{q}^{x} - 1} \log \mathfrak{q} \Bigg).
		\end{flalign}
		Then, we have 
		\begin{flalign}
			\begin{aligned} 
                  f_x (y) - f_x (\gamma_x)  & = \mathrm{i}  (f_x (\gamma_x) - 1)^2 \cdot ( 2 \Gamma_{x;2}  (y-\gamma_x) )^{1/2} \\ 
                 	& \qquad + \mathfrak{q}^x A'^{-1} D' (A'^{-1} B' D' - f_0'' (0)) \cdot (y - \gamma_x) + \mathfrak{d}^3 \cdot \varsigma_2 ( x, (y-\gamma_x)^{1/2}), 

                 \end{aligned} 
		\end{flalign}

		\noindent where $\varsigma_2: \mathbb{R}_{\ge 0} \rightarrow \mathbb{C}$ is a function dependent on $(a,b,c,q)$ that satisfies the following. For any derivative $\partial_{\ell}$ in $(x,z,a,b,c,q)$, there exists a constant $C_{\ell} > 1$ such that $|\partial_{\ell} \varsigma_2 (x, z)| \le C_{\ell}$, for all $(x,z) \in [1/4,5/4] \times [0, C \mathfrak{d}]$; $q \in [-\varepsilon, \varepsilon]$; and $a,b,c \in [1-\varepsilon, 1+ \varepsilon]$. 

	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 28 (Uniform-in-time fixed-marginal chaos in $W_2$) of arXiv:2608.28827, 'Quantitative Target Convergence and Uniform-in-Time\\ Propagation of Chaos for Langevin-Re'] Under Assumptions~\ref{ass:core-target}, \ref{ass:W2}, and \ref{ass:concentration}, for fixed \(k\) and \(N\ge2k\),
\begin{equation}
    \sup_{t\ge0}
    W_2^2(P_{N,t}^{(k)},\mu_t^{\otimes k})
    \le C_k\left\{
       N^{-\frac{2\varepsilon\alpha}
          {L_\mathrm{cpl}+2\varepsilon\alpha}}
       +N^{-1}\right\},
\end{equation}
where \(P^{N,k}\) denotes the \(k\)-coordinate marginal of
\(P^N\).

