[Lemma cint of arXiv:2603.28936, 'Composition of random functions and word reconstruction'] For all $x,y\in[n]$ with $x\neq y$  and uniformly over $u\in [0,1]$, we have
\begin{align}
\mathbb E\bigl[u^{d(x)+d(y)}\mathbf{1}_{x,y\in\mathcal{Q}_n\cap \mathcal{T}_n}  \mathbf{1}_{B_{\omega}(x)\cap B_{\omega}(y)\neq  \varnothing}\bigr]  = \frac{c_{\textrm{int}}(w,u)}{n}+ O\Bigl(\frac{1}{n^2}\Bigr),
\end{align}
where 
\begin{equation}
c_{\textrm{int}}(w,u) :=  2\sum_{(i,j)\in \mathcal{M}} \mathbb E^{i,j,\ell_{i,j}}_{\mathbf{Y},\mathbf{Y}'} \bigl[u^{Y_k+Y_k'}\mathbf{1}_{Y_{2k}=Y_{2k}'=0}\bigr].
\end{equation}
where $\mathbb E^{i,j,\ell_{i,j}}_{\mathbf{Y},\mathbf{Y}'} \bigl[u^{Y_k+Y_k'}\mathbf{1}_{Y_{2k}=Y_{2k}'=0}\bigr]$ is explicitly given by Proposition~(prop:cross_monster of the paper), 
	and where $\mathcal{M}=\mathcal{M}(w^2)$, $\ell_{i,j}=\ell_{i,j}(w^2)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 40 of arXiv:2604.07370, 'Probabilistic Weyl law for twisted Toeplitz matrices with rough symbols'] Let $p=p(x,\xi)$ be of the form
    \begin{equation}
        p(x,\xi)=\sum_{k\in \Lambda}p_k(x)e^{2i\pi \ps{k}{\xi}}, \quad(x,\xi)\in [0,1]^d\times \T^d,
    \end{equation}
    where $\Lambda=\prod_{j=1}^d\disc{-n_j}{m_j}$, $n_j,m_j\geq 0$, and $p_k:[0,1]^d\to \C$, $k\in \Lambda$ is measurable. Let us denote 
    \begin{equation*}
        S:=\sum_{j=1}^d (n_j+m_j)>0\mm\m\m\text{and}\mm\m\m \Xi:=\prod_{j=1}^d(n_j+m_j+1).
    \end{equation*}
    We assume that: there exists $m>0$ such that for almost every $x\in [0,1]^d$, 
    \begin{equation}
        \sum_{\substack{k\in \Lambda\\k\neq 0}}^{N_+}\bb{p_k(x)}\geq m>0.
    \end{equation}
    Then, for all $z\in \C$, $t\geq 0$, 
    \begin{equation}
        \mathrm{L}\pr{\acc{(x,\xi)\in [0,1]^d\times \T^d\m;\m \bb{p(x,\xi)-z}^2\leq t}}\leq Ct^\kappa
    \end{equation}
    where
    \begin{equation}
        \kappa=\frac{1}{2S}\mm\text{and}\mm C= 14d\pr{\frac{\sqrt{\Xi}}{m}}^{\frac{1}{S}}.
    \end{equation}

