[Definition 42 (Balanced comparison structure) of arXiv:2606.16636, 'Free energy of non-convex multi-species spin glasses with centered Ising spins'] We say that $\xi$ is \textbf{balanced} with respect to $\lambda$ if there exists a one-species covariance function $\xi_\star:\R_+\to\R$ such that, for every $r\in\R_+$,
\begin{equation}

    \xi(r\lambda)=\xi_\star(r),
\end{equation}
and, for every $a=(a_s)_{s\in\sS}\in\R_+^\sS$,
\begin{equation}

    \xi(a)\leq \sum_{s\in\sS}\lambda_s\xi_\star\left(\frac{a_s}{\lambda_s}\right).
\end{equation}

[Lemma eq:auxiliary-control-problem:verification of arXiv:2605.14149, 'The mean-field limit of online stochastic vector balancing'] Fix $p \in [2,\infty)$ and $\delta > 0$, and let $\lambda$ and $\gamma$ be as defined in (equation eq:primal-optimizers-finite-p:def-lambda of the paper) and (equation def.gammalambda of the paper). Define a function $u : [0,1] \times {\mathbb R} \to {\mathbb R}$ via
    \begin{align*}
    u(t_0,x_0) = \inf_{\beta} {\mathbb E}\bigg[ \int_{t_0}^1 \frac{1}{2 \lambda(t)} \beta(t)^2 \, dt + \gamma |X(1)|^p \bigg],
\end{align*}
where the infimum is taken over all progressively measurable processes $\beta$ satisfying
\begin{align*}
    {\mathbb E}\bigg[ \int_{t_0}^1 \frac{1}{\lambda(t)} \beta(t)^2 \, dt  \bigg] < \infty,
\end{align*}
and
\begin{align*}
    X(t) = x_0 + \int_{t_0}^t \beta(s) \, ds + (B(t)  - B(t_0)).
\end{align*}
Then, the following assertions hold:
\begin{enumerate}
    \item $u$ is convex and even in $x$, and there is a constant $C$ such that
    \begin{align*}
        |u(t,x)| \leq C(1 + |x|^p)
    \end{align*}
    for all $(t,x) \in [0,1] \times {\mathbb R}$.
    \item $u$ is a classical solution to (equation eq:auxiliary-control-problem:hjb of the paper).
    \item the unique optimizer for the problem (equation eq:auxiliary-control-problem:def of the paper)  (and hence for the problem $V_{p,\delta}^{\infty}$, thanks to Lemma (lemma:auxiliary-control-problem:optimality of the paper)) is give in feedback form by
    \begin{align*}
        \beta(t,x) = - \lambda(t) \partial_x u(t,x),
    \end{align*}
    and in particular is odd and points inwards.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 14 (Continuation-side trace condition) of arXiv:2606.17517, 'Killed resolvents and measure-valued stopping gains for reflected optimal stopping with ma'] Assume the hypotheses of Theorem~\ref{thm:killed-resolvent-representation} and
the free-boundary regularity needed for the following trace to exist. Then, for
every boundary point at which the trace is well-defined,
\begin{equation}

   \lim_{\substack{x\to z_b(x_1)\\ x\in\mathcal C}}
   R_r^{\mathcal C}\Gamma(x)
   =0.
\end{equation}
If non-tangential traces are used, \eqref{eq:boundary-trace} is interpreted as
$\lim_{x\to z_b(x_1),\,x\in\mathcal C\ \mathrm{n.t.}}R_r^{\mathcal C}\Gamma(x)=0$.

[Lemma 27 of arXiv:2510.20492, 'Heterochromatic two-arm probabilities for metric graph Gaussian free fields'] For any $d\ge 3$, there exist $C,c>0$ such for any $T>0$, any distinct $v_1,v_2,w_1,w_2\in \widetilde{\mathbb{Z}}^d$ with $|v_1-w_1|\land |v_2-w_2|\ge d$, and any $z\in \{v_1,v_2,w_1,w_2\}$, 
 	 	\begin{equation}
 		\begin{split}
 			\mathbb{P}\big(  \widehat{\mathcal{L}}_{1/2}^{z} \ge T  \mid \{v_1\xleftrightarrow{} w_1\Vert v_2\xleftrightarrow{} w_2 \} \big)\le Ce^{-cT}. 
 		\end{split}
 	\end{equation}

[Thm 2 of arXiv:2506.16873, 'Optimal matchings of randomly perturbed lattices'] Fix $d=1$ and $\alpha\in(0,1)$. Suppose that the distribution of the perturbation $\xi$ is symmetric around the origin and satisfies 
    \begin{equation}
       cr^{-\alpha } \le  \mathbb P (|\xi | \ge r) \le Cr^{-\alpha }
    \end{equation}
    for two constants $C,c>0$ and all $r \ge 1$. Then:
    \begin{enumerate}
        \item 
        There is a perfect matching $M:\mathbb Z \to \Pi$ such that $$\mathbb P (|M(0)|>r)\le Cr^{-\frac{1+\alpha }{2}} \, .$$
        \item 
        Any invariant perfect matching $M:\mathbb Z \to \Pi $ has $$\E \big[ |M(0)|^{\frac{1+\alpha}{2}} \big] = \infty \, .$$
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma Bramson-converges-to-1 of arXiv:2608.23202, 'Locally finite Fixed points of Branching Brownian Motion'] \footnote{This claim can also be verified in the modern language of extremal point processes $\widetilde{\mathcal{E}}_\infty^\lambda$. Notably, the underlying reason for (equation other-main-input-from-Bramson of the paper) to hold is that the number of particles of $\widetilde{\mathcal{E}}_\infty^\lambda$ at a bounded distance from $x$ blows up as $x\to -\infty$: it grows like $ e^{-\mu x}$ for $\lambda >\sqrt{2}$ and $\approx (-x)e^{-\sqrt{2}x}$ for $\lambda = \sqrt{2}$.}
    Let $\phi:\mathbb{R}\to [0,1]$ be a measurable function such that $\phi(x) \geq \eta$ for all $x\in (a,b)$ \textcolor{black}{with} some $a,b \in \mathbb{R}$ and $\eta >0$. Let $u_\phi(t,x)$ be the solution to F-KPP equation with initial condition $\phi$. Then, for any $\delta >0$, as $t \to \infty$,
\begin{equation}
u_\phi\left(t, x\right) \to 1
\end{equation}
uniformly in $x$ such that $|x| \le \sqrt{2}t - \bigl(\frac{3}{2\sqrt{2}} + \delta\bigr)\log t$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 18 of arXiv:2604.00190, '2604.00190'] For $\bfb \in \Xi^\nu$, there exists a measurable function $p_\bfb$ from $E$ to $[0, 1]$ such that for $y\in E$, 
\begin{align}
\varrho^{\nu, \bfb}_{p_\bfb}( \bfb (y), y) =1,\qquad 
\rho^{\nu, \bfb}_{p_\bfb}(  x, y)
\begin{cases}
\geq 1,\qquad &x <\bfb(y),\\
\leq 1 ,\qquad &x>\bfb(y). 
\end{cases}

\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

