[Pro Jordan of arXiv:2606.19583, 'Power-law hypothesis and (un)fairness of PageRank on undirected multi-type PAMs'] {AnBaBhPi26}} and {[HevHLi25a]}]
~
\begin{enumerate}[(a)]
    \item The sequence of random vectors $(\boldsymbol{\tilde{Y}}^{\boldsymbol{m},(n)})_{n \in \mathbb{N}}$ converges almost surely to $\boldsymbol{\eta}^{\boldsymbol{m}}$ in (equation eq: LyapunovFunction of the paper).
    \item For $k \in S$, recall $\varphi_k^{\boldsymbol{m}}$ in (equation eq: varphik of the paper). 

    Then, for any $d \in \mathbb{N}_0$ and color $k \in S$, and for $\phi_n$ chosen uniformly at random from $V(G_n)$,  \begin{equation}\mathbb{P}(d_{\phi_n}(G_n)=d \mid X_{\phi_n}=k) \stackrel{n \rightarrow \infty}{\longrightarrow} \frac{2\Gamma(m_k+\frac{2}{\varphi_k^{\boldsymbol{m}}})}{\varphi_k^{\boldsymbol{m}} \Gamma(m_k)}\frac{\Gamma(d)}{\Gamma(d+\frac{2}{\varphi_k^{\boldsymbol{m}}}+1)}.\end{equation}
    \item For any $r \geq 0$ and color $k \in S$,
    \begin{equation*}
     \limsup_{n \rightarrow \infty}\mathbb{P}(R_{\phi_n}(G_n)>r \mid X_{\phi_n}=k) \leq  \sum_{s=\lceil r \rceil}^\infty\frac{2\Gamma(m_k+\frac{2}{\varphi_k^{\boldsymbol{m}}})}{\varphi_k^{\boldsymbol{m}} \Gamma(m_k)}\frac{\Gamma(s)}{\Gamma(s+\frac{2}{\varphi_k^{\boldsymbol{m}}}+1)}.
    \end{equation*}
\end{enumerate}

