[Maintheorem 3 (Relative pressure-work principle for a common drift) of arXiv:2608.30715, 'Endpoint Energy Atoms Force Local Pressure Concentration in Three-Dimensional Navier--Stok'] Let \(u,w\) satisfy \eqref{eq:A-finite}--\eqref{eq:Oseen}, and suppose
\begin{equation}
 \Aa_a[w]\ge m>0

\end{equation}
for some \(a\in\Omega\). Then the following statements hold for every fixed
\(\tau\in(s,T_*)\).

\begin{enumerate}[label=\textup{(\roman*)},leftmargin=2.4em]
\item The passive field \(z_\tau\) and its Hodge components
\(v_\tau,g_\tau\) are
terminally non-atomic, whereas
\begin{equation}
 \Aa_a[r_\tau]\ge m,
 \qquad
 \Aa_a[c_\tau]\ge m.

\end{equation}

\item For every \(\tau<t<T_*\),
\begin{equation}
 \begin{aligned}
 \frac12\norm{r_\tau(t)}_2^2
 +\nu\int_\tau^t\norm{\nabla r_\tau(\rho)}_2^2\dd\rho
 &=\int_\tau^t\ip{\nabla\pi_w(\rho)}{g_\tau(\rho)}\dd\rho\\
 &=-\int_\tau^t\int_\Omega
 \pi_w\,\nabla\cdot z_\tau\dd x\dd\rho\\
 &=\int_\tau^t\int_\Omega
 u_iw_j\partial_j(g_\tau)_i\dd x\dd\rho.
 \end{aligned}

\end{equation}

\item The accumulated work and its product majorant satisfy
\begin{equation}
 \limsup_{t\uparrow T_*}
 \int_\tau^t\ip{\nabla\pi_w}{g_\tau}\dd\rho
 \ge\frac m2,

\end{equation}
and
\begin{equation}
 \int_\tau^{T_*}
 \norm{u(t)}_\infty\norm{\nabla g_\tau(t)}_2\dd t
 \ge\frac{m}{2F_\tau}
 \ge\frac{m}{2\norm{f}_2}.

\end{equation}
The first integral in \eqref{eq:main-product-lower} is understood in
\([0,+\infty]\).

\item For the tail function \(A\) in \eqref{eq:A-finite} and
\(q_\tau\in\{r_\tau,g_\tau,c_\tau\}\),
\begin{equation}
 \sup_{\tau<t<T_*}\norm{q_\tau(t)}_{\dot H^{-1}}
 \le C_\Omega F_\tau A(\tau)

\end{equation}
and
\begin{equation}
 \norm{q_\tau}_{L^4((\tau,T_*);L^2)}
 \le C_\Omega\nu^{-1/4}F_\tau A(\tau)^{1/2}.

\end{equation}
In particular, the quantities in \eqref{eq:main-Hminus} and
\eqref{eq:main-L4} tend to zero as \(\tau\uparrow T_*\).

\item The vector field
\begin{equation}
 \mathfrak h_{\tau,i}=w\cdot\nabla(g_\tau)_i

\end{equation}
belongs to the periodic real Hardy space for almost every time, has zero
mean componentwise, and obeys
\begin{equation}
 \norm{\mathfrak h_\tau(t)}_{\Hh^1}
 \le C_\Omega\norm{w(t)}_2\norm{\nabla g_\tau(t)}_2,
 \qquad
 \norm{\mathfrak h_\tau}_{L^2((\tau,T_*);\Hh^1)}
 \le C_\Omega\nu^{-1/2}F_\tau^2.

\end{equation}
Moreover, the last line of \eqref{eq:main-ledger} is
\begin{equation}
 \int_\tau^t
 \ip{u}{\mathfrak h_\tau}_{\BMO,\Hh^1}\dd\rho.

\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 3 of arXiv:2607.08129, '2607.08129'] Under \eqref{eq:MDP-scale}, the sequence $(\widehat Y_n)_{n\ge1}$ satisfies an MDP in $C[0,1]$, equipped with the uniform norm, with speed $b_n^2$ and good rate function
\begin{equation}
 J_\theta(f)
 :=\begin{cases}
 \dfrac12\norm{f}_{\cH_\theta}^2,
 &f\in\cH_\theta,\\[1ex]
 +\infty,&f\notin\cH_\theta.
 \end{cases}
\end{equation}
The step processes $(Y_n)_{n\ge1}$ satisfy the same MDP in $D[0,1]$ with the $J_1$-topology. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem compound of arXiv:2602.21277, 'A Limit in Law for the Cover Time and Last Visited Vertex of Wired Planar Domains'] Let $n \in \mathbb{N}$, $p,q \in (0,1]$ and $\lambda,\mu > 0$ be fixed parameters. Then:
\begin{itemize}
\item [\rm{i.}] If $S \sim \Bigeo(n,p;q)$, then $\begin{cases}\mathbb{P}( S \leq \theta ) \leq {\rm e}^{-(\sqrt{np}-\sqrt{\theta q})^2}  \quad \text{ if $\theta \leq \frac{np}{q}$,} \\ \\ \mathbb{P}(  S  \geq \theta ) \leq {\rm e}^{-(\sqrt{\theta q}-\sqrt{np})^2} \quad \text{ if $\theta \geq \frac{np}{q}$}.\end{cases}$ 
\item [\rm{ii.}] If $S \sim \Biexp(n,p;\lambda)$, then $\begin{cases}
\mathbb{P}( S \leq \theta ) \leq {\rm e}^{-(\sqrt{np}-\sqrt{\theta \lambda})^2} \quad \text{ if $\theta \leq \frac{np}{\lambda}$,}\\ \\
\mathbb{P}(  S  \geq \theta ) \leq {\rm e}^{-(\sqrt{\theta \lambda}-\sqrt{np})^2} \quad \text{ if $\theta \geq \frac{np}{\lambda}$}.\end{cases}$
\item[\rm{iii.}] If $S \sim \Poigeo(\mu;q)$, then $\begin{cases}
\mathbb{P}(S \leq \theta) \leq {\rm e}^{-(\sqrt{\mu}-\sqrt{\theta p})^2} \quad \text{ if $\theta \leq \frac{\mu}{p}$,} \\ \\ 
\mathbb{P}(S \geq \theta) \leq {\rm e}^{-(\sqrt{\mu}-\sqrt{\theta p})^2} \quad \text{ if $\theta \geq \frac{\mu}{p}$}.\end{cases}$
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

